internal fun postRelativeTime(createdAt: String, nowMillis: Long): String {
    val timestamp = try {
        java.time.Instant.parse(createdAt).toEpochMilli()
    } catch (_: Exception) {
        try {
            java.time.OffsetDateTime.parse(createdAt.replace(" ", "T")).toInstant().toEpochMilli()
        } catch (_: Exception) { return "Data indisponível" }
    }
    val seconds = ((nowMillis - timestamp) / 1000).coerceAtLeast(0)
    return when {
        seconds < 60 -> "Agora"
        seconds < 3600 -> "Há ${seconds / 60} min"
        seconds < 86400 -> "Há ${seconds / 3600} h"
        seconds < 604800 -> "Há ${seconds / 86400} d"
        else -> java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy", java.util.Locale("pt", "BR"))
            .withZone(java.time.ZoneId.systemDefault()).format(java.time.Instant.ofEpochMilli(timestamp))
    }
}

@androidx.compose.runtime.Composable
private fun LivePostTime(createdAt: String, color: androidx.compose.ui.graphics.Color, suffix: String = "", short: Boolean = false) {
    var nowMillis by androidx.compose.runtime.remember { androidx.compose.runtime.mutableLongStateOf(System.currentTimeMillis()) }
    androidx.compose.runtime.LaunchedEffect(createdAt) {
        while (true) {
            nowMillis = System.currentTimeMillis()
            kotlinx.coroutines.delay(15_000L)
        }
    }
    androidx.compose.material3.Text((postRelativeTime(createdAt, nowMillis).let { if (short) it.removePrefix("Há ") else it }) + suffix, color = color, fontSize = androidx.compose.ui.unit.TextUnit(12f, androidx.compose.ui.unit.TextUnitType.Sp))
}


/** Paleta do QINBLY (azul). Para mudar a cor da marca inteira, troque só estes valores. */
/** Guarda a proporção de cada foto já carregada: ao voltar para um post, a altura já está certa e a lista não pula. */
private object QinblyImageRatioCache { val map = java.util.concurrent.ConcurrentHashMap<String, Float>() }

internal object QinblyBrand {
    /** Nome do app mostrado nas telas. Para renomear a rede, troque só este valor (e app_name em res/values/strings.xml). */
    const val Name = "QINBLY"
    /** Roxo original: só o logotipo e o botão + do Criar continuam com ele. */
    val Logo = Color(0xFF7C4DFF)
    /** Cor padrão do app (azul #2F68E0). */
    val Accent: Color get() = Color(0xFF565BF0)
    val AccentDeep: Color get() = if (QiblyTheme.dark) Color(0xFF6A6FF3) else Color(0xFF4A4FD6)
    /** Letreiros (PERGUNTA DO DIA, DESAFIO) e hashtags: azul padrão. */
    val Lavender = Color(0xFF565BF0)
    val AccentLight = Color(0xFF9A9EF7)
    /** Cor dos letreiros que antes eram roxos (branco no escuro). Logo e botão Criar continuam roxos. */
    val TextAccent: Color get() = if (QiblyTheme.dark) Color.White else Accent
    /** Hashtags e @menções: índigo mais claro (#2F68E0); os botões continuam #2F68E0. */
