@androidx.compose.runtime.Composable
private fun RepostVerifiedIcon(verified: Boolean, tint: Color = Color.White) {
    // Repostar: duas setas em círculo (redondinho), grade 24x24, contorno arredondado.
    // Ao tocar, as setas dão uma volta inteira e o "verificado" aparece (ou some) dentro delas, na mesma cor.
    val spin = remember { androidx.compose.animation.core.Animatable(360f) }
    var firstFrame by remember { mutableStateOf(true) }
    LaunchedEffect(verified) {
        if (firstFrame) { firstFrame = false; return@LaunchedEffect }
        spin.snapTo(0f)
        spin.animateTo(360f, androidx.compose.animation.core.tween(700, easing = androidx.compose.animation.core.FastOutSlowInEasing))
    }
    val p = spin.value / 360f
    val checkAlpha = if (p >= 1f) (if (verified) 1f else 0f)
        else if (verified) ((p - 0.39f) / 0.3f).coerceIn(0f, 1f)
        else (1f - p / 0.35f).coerceIn(0f, 1f)
    androidx.compose.foundation.Canvas(modifier = Modifier.size(LocalQinblyActionIconSize.current).graphicsLayer { rotationZ = spin.value }) {
        val stroke = androidx.compose.ui.graphics.drawscope.Stroke(
            width = 2.1f,
            cap = androidx.compose.ui.graphics.StrokeCap.Round,
            join = androidx.compose.ui.graphics.StrokeJoin.Round
        )
        val arrows = androidx.compose.ui.graphics.vector.PathParser()
            .parsePathString("M20 11a8.1 8.1 0 0 0 -15.5 -2m-.5 -4v4h4M4 13a8.1 8.1 0 0 0 15.5 2m.5 4v-4h-4")
            .toPath()
        withTransform({ scale(size.width / 24f, size.width / 24f, pivot = androidx.compose.ui.geometry.Offset.Zero) }) {
            drawPath(arrows, tint, style = stroke)
            if (checkAlpha > 0f) {
                val check = androidx.compose.ui.graphics.Path().apply {
                    moveTo(9f, 12.4f); lineTo(11.2f, 14.6f); lineTo(15f, 10.4f)
                }
                drawPath(check, tint.copy(alpha = tint.alpha * checkAlpha), style = stroke)
            }
        }
    }
}

@androidx.compose.runtime.Composable
private fun QinblyCommentIcon(tint: Color, iconSize: Dp = 24.dp, flip: Boolean = false) {
    // Balão redondo com 2 tracinhos dentro. Grade 24x24, contorno arredondado.
    androidx.compose.foundation.Canvas(modifier = Modifier.size(iconSize)) {
        val k = size.width / 24f
        val bubble = androidx.compose.ui.graphics.vector.PathParser()
            .parsePathString("M3 20l1.3-3.9C2 12.7 2.9 8.2 6.4 5.7c3.5-2.5 8.6-2.3 11.8.5 3.3 2.8 3.7 7.3 1 10.5-2.7 3.2-7.6 4.2-11.6 2.3L3 20")
            .toPath()
        val lines = androidx.compose.ui.graphics.vector.PathParser().parsePathString("M8 10h8M8 13.5h5").toPath()
        val stroke = androidx.compose.ui.graphics.drawscope.Stroke(
            width = 1.7f,
            cap = androidx.compose.ui.graphics.StrokeCap.Round,
            join = androidx.compose.ui.graphics.StrokeJoin.Round
        )
        withTransform({
            if (flip) { translate(size.width, 0f); scale(-k, k, pivot = androidx.compose.ui.geometry.Offset.Zero) }
            else scale(k, k, pivot = androidx.compose.ui.geometry.Offset.Zero)
        }) { drawPath(bubble, tint, style = stroke) }
        withTransform({ scale(k, k, pivot = androidx.compose.ui.geometry.Offset.Zero) }) { drawPath(lines, tint, style = stroke) }
    }
}

@androidx.compose.runtime.Composable
private fun QinblyShareArrowIcon(tint: Color = Color.White, iconSize: Dp = 26.dp, outline: Boolean = false) {
    // Seta de enviar dos vídeos: cheia, curva, curta e gorda (ponta grande). Grade 34x34.
    androidx.compose.foundation.Canvas(modifier = Modifier.size(iconSize)) {
        val arrow = androidx.compose.ui.graphics.vector.PathParser()
            .parsePathString("M18 4L31 16L18 28V22C12 22 8 24 4 29C4 18 8 11 18 10Z")
            .toPath()
        withTransform({ scale(size.width / 34f, size.width / 34f, pivot = androidx.compose.ui.geometry.Offset.Zero) }) {
            if (outline) {
                drawPath(arrow, tint, style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2.6f, join = androidx.compose.ui.graphics.StrokeJoin.Round))
            } else {
                drawPath(arrow, tint)
                drawPath(arrow, tint, style = androidx.compose.ui.graphics.drawscope.Stroke(width = 3.5f, join = androidx.compose.ui.graphics.StrokeJoin.Round))
            }
        }
    }
}

@androidx.compose.runtime.Composable
private fun RoundedPaperPlaneIcon(tint: Color = Color.White) {
    // Avião de papel do QINBLY: asas largas e todas as pontas arredondadas (bico e as duas asas). Grade 26x24, contorno 2.
    val planeSize = LocalQinblyActionIconSize.current
    androidx.compose.foundation.Canvas(modifier = Modifier.size(width = planeSize * 26f / 24f, height = planeSize)) {
        val outline = androidx.compose.ui.graphics.Path().apply {
            moveTo(6.14f, 8.94f)
            lineTo(19.49f, 4.0f)
            quadraticTo(23.8f, 2.4f, 22.49f, 6.81f)
            lineTo(19.19f, 17.97f)
            quadraticTo(18.0f, 22.0f, 15.6f, 18.56f)
            lineTo(13.83f, 16.02f)
            quadraticTo(12.0f, 13.4f, 8.94f, 12.46f)
            lineTo(6.22f, 11.63f)
            quadraticTo(2.2f, 10.4f, 6.14f, 8.94f)
            close()
        }
        val fold = androidx.compose.ui.graphics.Path().apply {
            moveTo(12.6f, 13.9f)
            lineTo(20.8f, 5.2f)
        }
        val stroke = androidx.compose.ui.graphics.drawscope.Stroke(
            width = 2f,
            cap = androidx.compose.ui.graphics.StrokeCap.Round,
            join = androidx.compose.ui.graphics.StrokeJoin.Round
        )
        withTransform({ scale(size.width / 26f, size.width / 26f, pivot = androidx.compose.ui.geometry.Offset.Zero) }) {
            drawPath(outline, tint, style = stroke)
            drawPath(fold, tint, style = stroke)
        }
    }
}

class MainActivity : ComponentActivity() {
    // Segundo plano: tudo que toca (vídeo, música, áudio) pausa quando o app sai da tela e retoma ao voltar.
    override fun onStop() { QinblyPlayback.pauseAll(); super.onStop() }
    override fun onStart() { super.onStart(); QinblyPlayback.resumeAll(); QinblyNotifyService.start(applicationContext) }
    /** Como nas outras redes: ao abrir/voltar pro app, os avisos de curtida, comentário e mensagem saem da barra. */
    override fun onResume() { super.onResume(); qinblyClearSocialNotifications(applicationContext) }
    // Teclas de volume (aumentar ou diminuir): avisam os vídeos mudos para ligarem o som (o sistema continua tratando a tecla normalmente).
    override fun dispatchKeyEvent(event: android.view.KeyEvent): Boolean {
        if (QinblyCameraKeys.active && (event.keyCode == android.view.KeyEvent.KEYCODE_VOLUME_UP || event.keyCode == android.view.KeyEvent.KEYCODE_VOLUME_DOWN)) {
            if (event.action == android.view.KeyEvent.ACTION_DOWN && event.repeatCount == 0) QinblyCameraKeys.shutterTicks++
            return true
        }
        if ((event.keyCode == android.view.KeyEvent.KEYCODE_VOLUME_UP || event.keyCode == android.view.KeyEvent.KEYCODE_VOLUME_DOWN) && event.action == android.view.KeyEvent.ACTION_DOWN) QinblyVolumeKey.upTicks++
        return super.dispatchKeyEvent(event)
    }
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // Tema salvo já no primeiro quadro: antes ele só era lido depois de a tela aparecer (ficava escuro e depois clareava).
        getSharedPreferences("qinbly_session", MODE_PRIVATE).byAccount().let { sp ->
            QiblyTheme.dark = qinblySavedDark(sp, this)
            qinblySetSplashTheme(this, QiblyTheme.dark)
            QiblyTheme.largeText = sp.getBoolean("setting_large_text", false)
            QiblyTheme.reduceMotion = sp.getBoolean("setting_reduce_motion", false)
        }
        QinblyEngagement.init(getSharedPreferences("qinbly_session", MODE_PRIVATE).byAccount())
        QinblyHidden.load(getSharedPreferences("qinbly_session", MODE_PRIVATE).byAccount())
        QinblyAvatarCache.init(applicationContext)
        QinblyNotifyWorker.schedule(applicationContext)
        // Janela clara desde o primeiro quadro: qualquer vão entre telas mostra a cor do app, não preto.
        window.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(QiblyTheme.background.toArgb()))
        // Imagens: cache em memória (25% da RAM disponível) e em disco (256 MB); reabrir telas não baixa de novo.
        coil.Coil.setImageLoader(
            coil.ImageLoader.Builder(this)
                .crossfade(120)
                .respectCacheHeaders(false)
                // Fotos vindas da internet vinham "deitadas" (o giro do EXIF só era aplicado em arquivos locais): agora sempre respeita o EXIF.
                .components { add(coil.decode.BitmapFactoryDecoder.Factory(exifOrientationPolicy = coil.decode.ExifOrientationPolicy.RESPECT_ALL)) }
                .memoryCache { coil.memory.MemoryCache.Builder(this).maxSizePercent(0.25).build() }
                .diskCache { coil.disk.DiskCache.Builder().directory(cacheDir.resolve("qinbly_images")).maxSizeBytes(256L * 1024 * 1024).build() }
                .build()
        )
        QinblyDeepLink.handle(intent)
        setContent {
            // Ícones da barra de cima/de baixo (hora, bateria, sinal) escuros quando o fundo do app é claro, claros quando é escuro.
            val barView = androidx.compose.ui.platform.LocalView.current
            val lightBackground = QiblyTheme.background.luminance() > 0.5f && !QinblyVideoChrome.active
            SideEffect {
                val controller = androidx.core.view.WindowCompat.getInsetsController(window, barView)
                controller.isAppearanceLightStatusBars = lightBackground
                controller.isAppearanceLightNavigationBars = lightBackground
            }
            QinblyClearFocusWhenKeyboardCloses()
            QinblyApp()
        }
    }

    override fun onNewIntent(intent: android.content.Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        QinblyDeepLink.handle(intent)
    }
}

/** Links de publicação (https://qinbly.com/post/<id> ou qinbly://post/<id>) abrem a publicação dentro do app. */
/** Puxar para atualizar em todo o app: recarrega a tela atual (refaz o carregamento de dados da página). */
@androidx.compose.runtime.Composable
@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
private fun QinblyPullRefresh(enabled: Boolean = true, content: @androidx.compose.runtime.Composable () -> Unit) {
    if (!enabled) { content(); return }
    var nonce by androidx.compose.runtime.remember { androidx.compose.runtime.mutableIntStateOf(0) }
    var refreshing by androidx.compose.runtime.remember { androidx.compose.runtime.mutableStateOf(false) }
    LaunchedEffect(refreshing) { if (refreshing) { kotlinx.coroutines.delay(900); refreshing = false } }
    androidx.compose.material3.pulltorefresh.PullToRefreshBox(
        isRefreshing = refreshing,
        onRefresh = { refreshing = true; nonce++ },
        modifier = Modifier.fillMaxSize()
    ) {
        androidx.compose.runtime.key(nonce) { content() }
    }
}

/** Cartão "Selo de verificado" (Configurações → Conta): mostra o estado do pedido e deixa pedir a verificação (aprovação manual). */
@androidx.compose.runtime.Composable
private fun QinblyVerificationCard(token: String, onNotice: (String) -> Unit) {
    var verified by remember { mutableStateOf(false) }
    var status by remember { mutableStateOf("") }
    var note by remember { mutableStateOf("") }
    var loaded by remember { mutableStateOf(false) }
    var dialog by remember { mutableStateOf(false) }
    var reason by remember { mutableStateOf("") }
    var sending by remember { mutableStateOf(false) }
    val reload = remember { mutableIntStateOf(0) }
    LaunchedEffect(token, reload.intValue) {
        if (token.isBlank()) return@LaunchedEffect
        Thread {
            try {
                val r = QinblyApi.getVerificationStatus(token)
                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    verified = r.optBoolean("verified")
                    val req = r.optJSONObject("request")
                    status = req?.optString("status").orEmpty()
                    note = req?.optString("review_note").orEmpty().takeUnless { it == "null" }.orEmpty()
                    loaded = true
                }
            } catch (_: Exception) { android.os.Handler(android.os.Looper.getMainLooper()).post { loaded = true } }
        }.start()
    }
    if (token.isBlank() || !loaded) return
    Column(
        Modifier.fillMaxWidth().clip(RoundedCornerShape(14.dp)).background(QiblyTheme.card).border(1.dp, QiblyTheme.border, RoundedCornerShape(14.dp)).padding(14.dp),
        verticalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            QinblyVerifiedBadge(20.dp)
            Text("Selo de verificado", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold)
        }
        when {
            verified -> Text("Sua conta é verificada.", color = QiblyTheme.secondary, style = MaterialTheme.typography.bodySmall)
            status == "pending" -> Text("Seu pedido está em análise. Avisaremos você por notificação.", color = QiblyTheme.secondary, style = MaterialTheme.typography.bodySmall)
            else -> {
                if (status == "rejected") Text("Seu último pedido não foi aprovado." + if (note.isNotBlank()) " Motivo: $note" else "", color = QiblyTheme.secondary, style = MaterialTheme.typography.bodySmall)
                else Text("Peça o selo para mostrar que sua conta é autêntica. Não há número mínimo de seguidores: cada pedido é analisado por nós.", color = QiblyTheme.secondary, style = MaterialTheme.typography.bodySmall)
                QinblyGradientButton(onClick = { dialog = true }, colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)) {
                    Text(if (status == "rejected") "Pedir de novo" else "Pedir verificação")
                }
            }
        }
    }
    if (dialog) {
        AlertDialog(
            onDismissRequest = { if (!sending) dialog = false },
            title = { Text("Pedir verificação") },
            text = { QinblyClearFocusWhenKeyboardCloses();
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("Conte quem você é e por que sua conta deve ser verificada. Você precisa ter foto, bio e ao menos uma publicação.", style = MaterialTheme.typography.bodySmall)
                    OutlinedTextField(value = reason, onValueChange = { reason = it.take(1000) }, modifier = Modifier.fillMaxWidth(), minLines = 3, maxLines = 6, label = { Text("Motivo") })
                }
            },
            confirmButton = {
                TextButton(enabled = !sending && reason.trim().length >= 10, onClick = {
                    sending = true
                    Thread {
                        try {
                            QinblyApi.requestVerification(token, reason)
                            android.os.Handler(android.os.Looper.getMainLooper()).post { sending = false; dialog = false; reason = ""; reload.intValue++; onNotice("Pedido enviado. Vamos analisar.") }
                        } catch (e: Exception) {
                            android.os.Handler(android.os.Looper.getMainLooper()).post { sending = false; onNotice(e.message ?: "Não foi possível enviar o pedido.") }
                        }
                    }.start()
                }) { Text(if (sending) "Enviando…" else "Enviar") }
            },
            dismissButton = { TextButton(enabled = !sending, onClick = { dialog = false }) { Text("Cancelar") } }
        )
    }
}

/** Selo de conta verificada (aparece ao lado do nome): selo ondulado azul com check branco. */
@androidx.compose.runtime.Composable
internal fun QinblyVerifiedBadge(size: Dp = 16.dp) {
    androidx.compose.foundation.Canvas(Modifier.size(size)) {
        val w = this.size.minDimension
        val c = androidx.compose.ui.geometry.Offset(w / 2f, w / 2f)
        val lobes = 8
        val base = w * 0.45f
        val amp = w * 0.055f
        val path = androidx.compose.ui.graphics.Path()
        val steps = 96
        for (i in 0..steps) {
            val t = (i.toFloat() / steps) * (2f * Math.PI.toFloat())
            val r = base + amp * kotlin.math.cos(lobes * t)
            val x = c.x + r * kotlin.math.cos(t)
            val y = c.y + r * kotlin.math.sin(t)
            if (i == 0) path.moveTo(x, y) else path.lineTo(x, y)
        }
        path.close()
        drawPath(path, Color(0xFF1D9BF0))
        val check = androidx.compose.ui.graphics.Path().apply {
            moveTo(w * 0.30f, w * 0.52f); lineTo(w * 0.44f, w * 0.66f); lineTo(w * 0.71f, w * 0.36f)
        }
        drawPath(check, Color.White, style = androidx.compose.ui.graphics.drawscope.Stroke(width = w * 0.11f, cap = androidx.compose.ui.graphics.StrokeCap.Round, join = androidx.compose.ui.graphics.StrokeJoin.Round))
    }
}

