/** Notificação do sistema para novidades (aparece enquanto o app está aberto ou ainda em memória). */
/** Tira da barra os avisos do QINBLY (curtidas, comentários, mensagens...). Mantém o aviso fixo do serviço e o de atualização. */
internal fun qinblyClearSocialNotifications(context: android.content.Context) {
    try {
        val manager = context.getSystemService(android.content.Context.NOTIFICATION_SERVICE) as android.app.NotificationManager
        if (android.os.Build.VERSION.SDK_INT >= 23) {
            for (n in manager.activeNotifications) {
                if (n.id != 7010 && n.id != 7001 && n.id != 7002) manager.cancel(n.id)
            }
        }
    } catch (_: Exception) { }
}

/** Baixa a foto de perfil e recorta em círculo para ser o ícone grande da notificação. Precisa rodar fora da thread principal. */
internal fun qinblyNotificationAvatar(url: String): android.graphics.Bitmap? {
    if (!url.startsWith("http")) return null
    return try {
        val connection = (java.net.URL(url).openConnection() as java.net.HttpURLConnection).apply { connectTimeout = 6000; readTimeout = 6000 }
        val source: android.graphics.Bitmap? = try {
            connection.inputStream.use { android.graphics.BitmapFactory.decodeStream(it) }
        } finally {
            connection.disconnect()
        }
        if (source == null) return null
        val size = 192
        val side = minOf(source.width, source.height)
        val square = android.graphics.Bitmap.createBitmap(source, (source.width - side) / 2, (source.height - side) / 2, side, side)
        val scaled = android.graphics.Bitmap.createScaledBitmap(square, size, size, true)
        val out = android.graphics.Bitmap.createBitmap(size, size, android.graphics.Bitmap.Config.ARGB_8888)
        val canvas = android.graphics.Canvas(out)
        val paint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG)
        canvas.drawCircle(size / 2f, size / 2f, size / 2f, paint)
        paint.xfermode = android.graphics.PorterDuffXfermode(android.graphics.PorterDuff.Mode.SRC_IN)
        canvas.drawBitmap(scaled, 0f, 0f, paint)
        out
    } catch (_: Exception) { null }
}

internal fun qinblyNotify(context: android.content.Context, title: String, text: String, id: Int, kind: String = "", entityId: String = "", actor: String = "", avatarUrl: String = "") {
    try {
        val manager = context.getSystemService(android.content.Context.NOTIFICATION_SERVICE) as android.app.NotificationManager
        val soundUri = android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_NOTIFICATION)
        if (android.os.Build.VERSION.SDK_INT >= 26) {
            // Canal novo (v2): importância alta, com som e vibração explícitos. Um canal antigo mudo não pode ser alterado pelo app.
            val channel = android.app.NotificationChannel("qinbly_social_v2", "Novidades e mensagens", android.app.NotificationManager.IMPORTANCE_HIGH).apply {
                description = "Curtidas, comentários, seguidores e mensagens"
                enableVibration(true)
                vibrationPattern = longArrayOf(0, 250, 150, 250)
                enableLights(true)
                setSound(soundUri, android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_NOTIFICATION).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SONIFICATION).build())
            }
            manager.createNotificationChannel(channel)
        }
        if (android.os.Build.VERSION.SDK_INT >= 33 &&
            androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.POST_NOTIFICATIONS) != android.content.pm.PackageManager.PERMISSION_GRANTED
        ) return
        // Ao tocar, o app abre direto no assunto da notificação (mensagem, publicação, perfil...). Código único por aviso para um não sobrescrever o outro.
        val tapIntent = android.content.Intent(context, MainActivity::class.java)
            .addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK or android.content.Intent.FLAG_ACTIVITY_SINGLE_TOP)
            .putExtra("qinbly_kind", kind).putExtra("qinbly_entity", entityId).putExtra("qinbly_actor", actor)
        val open = android.app.PendingIntent.getActivity(
            context, id, tapIntent,
            android.app.PendingIntent.FLAG_IMMUTABLE or android.app.PendingIntent.FLAG_UPDATE_CURRENT
        )
        val builder = androidx.core.app.NotificationCompat.Builder(context, "qinbly_social_v2")
            .setSmallIcon(R.drawable.ic_stat_qinbly)
            .setContentTitle(title)
            .setContentText(text)
            .setStyle(androidx.core.app.NotificationCompat.BigTextStyle().bigText(text))
            .setContentIntent(open)
            .setAutoCancel(true)
            .setPriority(androidx.core.app.NotificationCompat.PRIORITY_HIGH)
            .setCategory(androidx.core.app.NotificationCompat.CATEGORY_SOCIAL)
            .setDefaults(androidx.core.app.NotificationCompat.DEFAULT_ALL)
            .setSound(soundUri)
            .setOnlyAlertOnce(false)
        // Foto de perfil de quem enviou (mensagens).
        if (avatarUrl.isNotBlank()) qinblyNotificationAvatar(avatarUrl)?.let { builder.setLargeIcon(it) }
        manager.notify(id, builder.build())
    } catch (_: Exception) { }
}

