/** Barra "Escrever algo..." no início: lápis + atalho para Enquete (Texto abre ao tocar na barra; saíram da câmera). */
@Composable
private fun QinblyHomeComposer(onCreateWith: (String, String) -> Unit) {
    Row(
        Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 6.dp)
            .clip(RoundedCornerShape(16.dp)).background(QiblyTheme.soft)
            .clickable { onCreateWith("text", "") }
            .padding(horizontal = 12.dp, vertical = 10.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        Icon(Icons.Default.Edit, contentDescription = "Escrever", tint = RemoteAppearance.feedTextColor, modifier = Modifier.size(22.dp))
        Text("Escrever algo...", color = RemoteAppearance.feedTextColor, fontSize = 14.sp, modifier = Modifier.weight(1f), maxLines = 1)
        Row(
            Modifier.clip(RoundedCornerShape(18.dp)).background(QiblyTheme.background.copy(alpha = 0.55f))
                .clickable { onCreateWith("poll", "") }.padding(horizontal = 10.dp, vertical = 7.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            Icon(QinblyCreateIcons.poll, contentDescription = null, tint = RemoteAppearance.feedTextColor, modifier = Modifier.size(15.dp))
            Text("Enquete", color = RemoteAppearance.feedTextColor, fontSize = 12.sp, fontWeight = FontWeight.Medium, maxLines = 1)
        }
    }
}

/** Desafio da semana no topo do Descobrir (sem saudação nem novidades). */
@Composable
private fun QinblyHomeHeader(
    posts: List<QinblyApi.PostSummary>, prefs: android.content.SharedPreferences,
    onCreateWith: (String, String) -> Unit
) {
    val today = java.time.LocalDate.now()
    val challenge = qinblyWeeklyChallenges[(today.dayOfYear / 7) % qinblyWeeklyChallenges.size]
    val participants = posts.filter { it.caption.contains("#" + challenge.first, ignoreCase = true) }.map { it.username.lowercase() }.distinct().size
    Column(Modifier.fillMaxWidth().padding(top = 10.dp, bottom = 10.dp).padding(horizontal = 14.dp)) {
        Row(
            Modifier.fillMaxWidth().height(76.dp).clip(RoundedCornerShape(16.dp)).border(1.dp, RemoteAppearance.feedDividerColor, RoundedCornerShape(16.dp))
                .clickable { QinblyTagNav.tag = challenge.first }.padding(horizontal = 14.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Icon(androidx.compose.material.icons.Icons.Default.PhotoCamera, contentDescription = null, tint = QinblyBrand.Lavender, modifier = Modifier.size(24.dp))
            Column(Modifier.weight(1f)) {
                Text("DESAFIO DA SEMANA", color = QinblyBrand.Lavender, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, letterSpacing = 0.8.sp, maxLines = 1)
                Text(challenge.second, color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 15.sp, maxLines = 1,
                    overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                if (participants > 0) Text(if (participants == 1) "1 participante" else "$participants participantes", color = RemoteAppearance.feedSecondaryTextColor, fontSize = 12.sp, maxLines = 1)
            }
            Text("Participar", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 14.sp,
                modifier = Modifier.clip(RoundedCornerShape(18.dp)).background(QinblyBrand.Lavender)
                    .clickable { onCreateWith("camera", "#" + challenge.first + " ") }.padding(horizontal = 14.dp, vertical = 7.dp))
        }
    }
    Box(Modifier.fillMaxWidth().height(1.dp).background(RemoteAppearance.feedDividerColor.copy(alpha = 0.45f)))
}

private fun qinblyHotScore(post: QinblyApi.PostSummary): Int = QinblyEngagement.likeCount(post) + post.comments * 2 + QinblyEngagement.repostCount(post) * 2

private fun qinblyInPeriod(post: QinblyApi.PostSummary, period: String): Boolean {
    val limit = when (period) { "Semana" -> 24L * 7; "Mês" -> 24L * 30; else -> 24L }
    return (qinblyPostAgeHours(post.createdAt) ?: 0L) <= limit
}

/** Em alta mostra só publicações com vídeo ou foto (texto e enquete ficam de fora). */
private fun qinblyEmAltaMedia(post: QinblyApi.PostSummary): Boolean =
    post.mediaUrl.isNotBlank() && (post.mediaType.equals("video", ignoreCase = true) || post.mediaType.equals("image", ignoreCase = true))

private fun qinblyTopHashtags(posts: List<QinblyApi.PostSummary>): List<String> =
    posts.flatMap { p -> Regex("#([\\p{L}\\p{N}_]+)").findAll(p.caption).map { it.groupValues[1].lowercase() }.toList() }
        .groupingBy { it }.eachCount().entries.sortedByDescending { it.value }.take(8).map { it.key }

/** Uma live no ar. A lista vem do servidor (ainda não existe): enquanto vazia, a tela mostra o estado "ninguém ao vivo". */
internal data class QinblyLive(val id: String, val host: String, val viewers: Int, val likes: Int, val displayName: String = "", val avatarUrl: String = "")

/** Uma linha de live: posição (coroa/medalha nos 5 primeiros, número depois), foto com aro vermelho, nome, @, números e AO VIVO. */
@Composable
private fun QinblyLiveRow(position: Int, live: QinblyLive, sort: String, showPosition: Boolean = true, highlight: String = "", onClick: () -> Unit) {
    val medal = listOf(Color(0xFFEF9F27), Color(0xFF98978F), Color(0xFFB8733A), QinblyBrand.Accent, Color(0xFF1D9E75)).getOrNull(position - 1)
    Row(
        Modifier.fillMaxWidth().clip(RoundedCornerShape(12.dp)).clickable { onClick() }.padding(vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        if (showPosition) Box(Modifier.width(26.dp), contentAlignment = Alignment.Center) {
            if (medal != null) Icon(if (position <= 3) QinblyCameraIcons.crown else QinblyCameraIcons.medal, contentDescription = "${position}º lugar", tint = medal, modifier = Modifier.size(if (position <= 3) 24.dp else 22.dp))
            else Text("$position", color = Muted, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
        }
        Box(Modifier.size(42.dp).border(2.dp, Color(0xFFE24B4A), CircleShape).padding(3.dp).clip(CircleShape).background(Color(0x1A808080)), contentAlignment = Alignment.Center) {
            if (live.avatarUrl.startsWith("http")) AsyncImage(model = live.avatarUrl, contentDescription = null, modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
            else Text((live.displayName.ifBlank { live.host }).take(2).uppercase(), color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
        }
        Column(Modifier.weight(1f)) {
            Text(qinblyHighlight(live.displayName.ifBlank { live.host }, highlight), color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, maxLines = 1)
        }
        Column(horizontalAlignment = Alignment.End) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(3.dp)) {
                Icon(if (sort == "Curtidas") Icons.Default.Favorite else QinblyCameraIcons.eye, contentDescription = null, tint = QiblyTheme.text, modifier = Modifier.size(15.dp))
                Text(if (sort == "Curtidas") "${live.likes}" else "${live.viewers}", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
            }
            Text("AO VIVO", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.SemiBold,
                modifier = Modifier.clip(RoundedCornerShape(4.dp)).background(Color(0xFFE24B4A)).padding(horizontal = 6.dp, vertical = 1.dp))
        }
    }
}

@Composable
private fun QinblySortChips(options: List<String>, sort: String, onSort: (String) -> Unit) {
    options.forEach { name ->
        val chosen = name == sort
        Text(name, fontSize = 11.sp, color = if (chosen) QiblyTheme.background else QiblyTheme.text,
            modifier = Modifier.padding(start = 5.dp).clip(RoundedCornerShape(14.dp))
                .background(if (chosen) QiblyTheme.text else Color.Transparent)
                .border(0.5.dp, Muted, RoundedCornerShape(14.dp))
                .clickable { onSort(name) }.padding(horizontal = 9.dp, vertical = 4.dp))
    }
}

/** Lives em alta: os 5 melhores (por telespectadores ou curtidas). Com mais de 5 no ar e `onSeeMore`, aparece "Ver mais lives". */
@Composable
private fun QinblyTopLives(
    lives: List<QinblyLive>, sort: String, onSort: (String) -> Unit, prefs: android.content.SharedPreferences,
    onOpen: (QinblyLive) -> Unit = {}, onSeeMore: (() -> Unit)? = null, title: String = "Top 5 lives em alta"
) {
    val ranked = (if (sort == "Curtidas") lives.sortedByDescending { it.likes } else lives.sortedByDescending { it.viewers }).take(5)
    Column(Modifier.fillMaxWidth().padding(top = 14.dp)) {
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            Text(title, color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 16.sp, modifier = Modifier.weight(1f))
            QinblySortChips(listOf("Telespectadores", "Curtidas"), sort, onSort)
        }
        if (ranked.isEmpty()) {
            Text("Ninguém ao vivo agora.", color = Muted, fontSize = 14.sp, modifier = Modifier.padding(vertical = 14.dp))
        } else ranked.forEachIndexed { index, live -> QinblyLiveRow(index + 1, live, sort) { onOpen(live) } }
        if (onSeeMore != null && lives.size > 5) {
            QinblyAccentText("Ver mais lives", fontWeight = FontWeight.SemiBold, fontSize = 14.sp,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                modifier = Modifier.fillMaxWidth().padding(top = 6.dp).clip(RoundedCornerShape(22.dp))
                    .border(0.5.dp, Muted, RoundedCornerShape(22.dp)).clickable { onSeeMore() }.padding(vertical = 9.dp))
        }
    }
}

/** Lista completa de quem está ao vivo (a partir do 6º), aberta por "Ver mais lives". */
@Composable
private fun QinblyAllLives(lives: List<QinblyLive>, onBack: () -> Unit, onOpen: (QinblyLive) -> Unit) {
    var sort by remember { mutableStateOf("Telespectadores") }
    BackHandler { onBack() }
    val ordered = when (sort) {
        "Curtidas" -> lives.sortedByDescending { it.likes }
        "Mais recentes" -> lives
        else -> lives.sortedByDescending { it.viewers }
    }
    val start = if (sort == "Mais recentes") 0 else 5
    Column(Modifier.fillMaxSize().padding(horizontal = 14.dp)) {
        Row(Modifier.fillMaxWidth().padding(top = 4.dp), verticalAlignment = Alignment.CenterVertically) {
            IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = RemoteAppearance.feedTextColor) }
            Text("Todas as lives ao vivo", fontWeight = FontWeight.SemiBold, fontSize = 18.sp, color = RemoteAppearance.feedTextColor)
        }
        Row(Modifier.fillMaxWidth().padding(bottom = 6.dp), verticalAlignment = Alignment.CenterVertically) {
            QinblySortChips(listOf("Telespectadores", "Curtidas", "Mais recentes"), sort) { sort = it }
        }
        LazyColumn(Modifier.fillMaxSize(), contentPadding = PaddingValues(bottom = 20.dp)) {
            items(ordered.size - start.coerceAtMost(ordered.size), key = { ordered[start + it].id }) { i ->
                QinblyLiveRow(start + i + 1, ordered[start + i], sort) { onOpen(ordered[start + i]) }
            }
        }
    }
}

/** Texto com o trecho digitado destacado em azul (ignora maiúsculas e acentos simples). */
private fun qinblyHighlight(text: String, query: String): androidx.compose.ui.text.AnnotatedString {
    val q = query.trim().removePrefix("@")
    val at = if (q.isBlank()) -1 else text.indexOf(q, ignoreCase = true)
    return androidx.compose.ui.text.buildAnnotatedString {
        append(text)
        if (at >= 0) addStyle(androidx.compose.ui.text.SpanStyle(color = QinblyBrand.Accent, fontWeight = FontWeight.SemiBold), at, at + q.length)
    }
}

/** Pesquisa dentro da aba Lives: campo com histórico (campo vazio) e lista de quem está ao vivo filtrada pelo nome ou @. */
@Composable
private fun QinblyLiveSearch(lives: List<QinblyLive>, onBack: () -> Unit, onOpen: (QinblyLive) -> Unit) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    var query by remember { mutableStateOf("") }
    var history by remember { mutableStateOf((prefs.getString("qinbly_live_search_history", "") ?: "").split("\n").filter { it.isNotBlank() }) }
    val save: (String) -> Unit = { term ->
        val t = term.trim()
        if (t.length >= 2) {
            history = (listOf(t) + history.filterNot { it.equals(t, true) }).take(8)
            prefs.edit().putString("qinbly_live_search_history", history.joinToString("\n")).apply()
        }
    }
    val focus = remember { FocusRequester() }
    LaunchedEffect(Unit) { focus.requestFocus() }
    BackHandler { onBack() }
    val q = query.trim().removePrefix("@").lowercase()
    val results = if (q.isBlank()) emptyList() else lives.filter { it.host.lowercase().contains(q) || it.displayName.lowercase().contains(q) }.sortedByDescending { it.viewers }
    Column(Modifier.fillMaxSize().padding(horizontal = 14.dp)) {
        Row(Modifier.fillMaxWidth().padding(top = 4.dp, bottom = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, contentDescription = "Fechar pesquisa", tint = RemoteAppearance.feedTextColor) }
            OutlinedTextField(
                value = query, onValueChange = { query = it.take(40) },
                modifier = Modifier.weight(1f).focusRequester(focus), singleLine = true,
                placeholder = { Text("Pesquisar quem está ao vivo") },
                leadingIcon = { Icon(Icons.Default.Search, contentDescription = null, tint = Muted) },
                trailingIcon = { if (query.isNotEmpty()) IconButton(onClick = { query = "" }) { Icon(Icons.Default.Close, contentDescription = "Limpar", tint = Muted) } },
                shape = RoundedCornerShape(28.dp),
                keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(imeAction = androidx.compose.ui.text.input.ImeAction.Search),
                keyboardActions = androidx.compose.foundation.text.KeyboardActions(onSearch = { save(query) })
            )
        }
        if (q.isBlank()) {
            if (history.isNotEmpty()) {
                Text("Pesquisados recentemente", fontWeight = FontWeight.SemiBold, fontSize = 16.sp, color = RemoteAppearance.feedTextColor, modifier = Modifier.padding(vertical = 4.dp))
                history.forEach { term ->
                    Row(Modifier.fillMaxWidth().clip(RoundedCornerShape(12.dp)).clickable { query = term }.padding(vertical = 8.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                        Icon(QinblyCameraIcons.clock, contentDescription = null, tint = Muted, modifier = Modifier.size(20.dp))
                        Text(term, color = RemoteAppearance.feedTextColor, modifier = Modifier.weight(1f), maxLines = 1)
                        IconButton(onClick = { history = history.filterNot { it == term }; prefs.edit().putString("qinbly_live_search_history", history.joinToString("\n")).apply() }, modifier = Modifier.size(32.dp)) {
                            Icon(Icons.Default.Close, contentDescription = "Remover", tint = Muted, modifier = Modifier.size(16.dp))
                        }
                    }
                }
            }
            Text("Ao vivo agora", fontWeight = FontWeight.SemiBold, fontSize = 16.sp, color = RemoteAppearance.feedTextColor, modifier = Modifier.padding(top = 14.dp, bottom = 4.dp))
            Text(if (lives.isEmpty()) "Ninguém ao vivo agora." else "Digite um nome ou @ para encontrar quem está transmitindo.", color = Muted, fontSize = 14.sp)
        } else {
            Text("Resultados (${results.size})", fontWeight = FontWeight.SemiBold, fontSize = 16.sp, color = RemoteAppearance.feedTextColor, modifier = Modifier.padding(vertical = 4.dp))
            if (results.isEmpty()) Text("Nenhuma live encontrada com esse nome.", color = Muted, fontSize = 14.sp, modifier = Modifier.padding(vertical = 20.dp).fillMaxWidth(), textAlign = androidx.compose.ui.text.style.TextAlign.Center)
            LazyColumn(Modifier.fillMaxSize(), contentPadding = PaddingValues(bottom = 20.dp)) {
                items(results, key = { it.id }) { live ->
                    QinblyLiveRow(0, live, "Telespectadores", showPosition = false, highlight = query) { save(query); onOpen(live) }
                }
            }
        }
    }
}

/** Janela de tela cheia da live: cobre barra de cima, abas e menu de baixo. O botão voltar chama o que a tela registrar em [backHook]. */
@Composable
private fun QinblyLiveWindow(backHook: MutableState<(() -> Unit)?>, content: @Composable () -> Unit) {
    QinblyDialog(
        onDismissRequest = { backHook.value?.invoke() },
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false, dismissOnClickOutside = false),
        lift = false
    ) { Box(Modifier.fillMaxSize().background(Color.Black)) { content() } }
}

/** Aba Lives: barra fina "Começar uma live", "Ao vivo agora" e "Agendadas". */
@Composable
private fun QinblyLivesPage(initialLives: List<QinblyLive>, onNotice: (String) -> Unit) {
    val listContext = androidx.compose.ui.platform.LocalContext.current
    var lives by remember { mutableStateOf(initialLives) }
    LaunchedEffect(Unit) {
        // Atualiza quem está ao vivo a cada poucos segundos enquanto a aba está aberta.
        while (true) {
            val token = QinblyLiveNet.userToken(listContext)
            if (token.isNotBlank()) QinblyLiveNet.list(token)?.let { lives = it }
            kotlinx.coroutines.delay(8000)
        }
    }
    var openLive by remember { mutableStateOf<QinblyLive?>(null) }
    var hostOpen by remember { mutableStateOf(false) }
    if (hostOpen) {
        val hostBack = remember { mutableStateOf<(() -> Unit)?>(null) }
        QinblyLiveWindow(hostBack) { QinblyLiveHost(onClose = { hostOpen = false }, onNotice = onNotice, backHook = hostBack) }
        return
    }
    openLive?.let { live ->
        val roomBack = remember { mutableStateOf<(() -> Unit)?>(null) }
        QinblyLiveWindow(roomBack) { QinblyLiveRoom(live, onClose = { openLive = null }, onNotice = onNotice, backHook = roomBack) }
        return
    }
    var allOpen by remember { mutableStateOf(false) }
    var liveSort by remember { mutableStateOf("Telespectadores") }
    var searchOpen by remember { mutableStateOf(false) }
    if (searchOpen) {
        QinblyLiveSearch(lives, onBack = { searchOpen = false }, onOpen = { openLive = it })
        return
    }
    if (allOpen) {
        QinblyAllLives(lives, onBack = { allOpen = false }, onOpen = { openLive = it })
        return
    }
    val livesPrefs = androidx.compose.ui.platform.LocalContext.current.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount()
    LazyColumn(Modifier.fillMaxSize(), contentPadding = PaddingValues(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
        item {
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text("Lives", fontWeight = FontWeight.SemiBold, fontSize = 20.sp, color = RemoteAppearance.feedTextColor, modifier = Modifier.weight(1f))
                IconButton(onClick = { searchOpen = true }) { Icon(Icons.Default.Search, contentDescription = "Pesquisar lives", tint = RemoteAppearance.feedTextColor) }
            }
        }
        item {
            Row(
                Modifier.fillMaxWidth().clip(RoundedCornerShape(12.dp)).background(qinblyAccentBrush())
                    .clickable { hostOpen = true }.padding(horizontal = 12.dp, vertical = 8.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Icon(QinblyIcon.Videocam, null, tint = Color.White, modifier = Modifier.size(18.dp))
                Text("Começar uma live", color = Color.White, fontWeight = FontWeight.Medium, fontSize = 14.sp, modifier = Modifier.weight(1f))
                Icon(QinblyIcon.ChevronRight, null, tint = Color.White, modifier = Modifier.size(18.dp))
            }
        }
        item { QinblyTopLives(lives, liveSort, { liveSort = it }, livesPrefs, onOpen = { openLive = it }, onSeeMore = { allOpen = true }, title = "Lives em alta") }
        item { Text("Agendadas", fontWeight = FontWeight.SemiBold, fontSize = 16.sp, color = RemoteAppearance.feedTextColor) }
        item { Text("Nenhuma live agendada.", color = RemoteAppearance.feedSecondaryTextColor, fontSize = 14.sp) }
    }
}

/** Quem transmite: "Antes de começar" (título, O que mostrar: Câmera ou Jogos, quem assiste, comentários, presentes) → contagem 5-4-3-2-1 → "No ar".
 *  Jogos transmite a tela do celular (permissão de gravação do Android) em vez da câmera; sem virar câmera.
 *  Na barra de baixo: comentário, virar câmera, microfone, pausa e X vermelho (encerrar, com confirmação).
 *  A bolinha vermelha fica acesa só enquanto transmite: some (cinza) ao pausar e acende ao retomar.
 *  A transmissão usa o LiveKit (veja Live.kt e functions/api/live.js). */
@Composable
private fun QinblyLiveHost(onClose: () -> Unit, onNotice: (String) -> Unit, backHook: MutableState<(() -> Unit)?>) {
    var stage by remember { mutableStateOf("setup") } // setup, count, live
    var count by remember { mutableStateOf(5) }
    var seconds by remember { mutableStateOf(0) }
    var paused by remember { mutableStateOf(false) }
    var micOn by remember { mutableStateOf(true) }
    var title by remember { mutableStateOf("") }
    var mode by remember { mutableStateOf("camera") } // camera ou game (tela do celular para jogos)
    var screenData by remember { mutableStateOf<Intent?>(null) }
    var audienceAll by remember { mutableStateOf(true) }
    var commentsOn by remember { mutableStateOf(true) }
    var giftsOn by remember { mutableStateOf(true) }
    var comment by remember { mutableStateOf("") }
    var confirmEnd by remember { mutableStateOf(false) }
    var summary by remember { mutableStateOf(false) }
    val liveContext = androidx.compose.ui.platform.LocalContext.current
    var hostCommentRefresh by remember { mutableIntStateOf(0) }
    val hostHandle = remember { liveContext.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount().getString("username", "").orEmpty().removePrefix("@") }
    var liveCamOk by remember { mutableStateOf(androidx.core.content.ContextCompat.checkSelfPermission(liveContext, android.Manifest.permission.CAMERA) == android.content.pm.PackageManager.PERMISSION_GRANTED) }
    val liveCamPermission = androidx.activity.compose.rememberLauncherForActivityResult(androidx.activity.result.contract.ActivityResultContracts.RequestPermission()) { liveCamOk = it }
    var liveMicOk by remember { mutableStateOf(androidx.core.content.ContextCompat.checkSelfPermission(liveContext, android.Manifest.permission.RECORD_AUDIO) == android.content.pm.PackageManager.PERMISSION_GRANTED) }
    val liveScreenPermission = androidx.activity.compose.rememberLauncherForActivityResult(androidx.activity.result.contract.ActivityResultContracts.StartActivityForResult()) { res ->
        val data = res.data
        if (res.resultCode == android.app.Activity.RESULT_OK && data != null) { screenData = data; stage = "count" }
        else onNotice("Sem a permissão do Android não dá para mostrar a tela.")
    }
    val liveStartScreen = {
        val mpm = liveContext.getSystemService(android.content.Context.MEDIA_PROJECTION_SERVICE) as android.media.projection.MediaProjectionManager
        liveScreenPermission.launch(mpm.createScreenCaptureIntent())
    }
    val liveMicPermission = androidx.activity.compose.rememberLauncherForActivityResult(androidx.activity.result.contract.ActivityResultContracts.RequestPermission()) {
        liveMicOk = it
        if (!it) onNotice("Sem o microfone não dá para transmitir.")
        else if (mode == "game") liveStartScreen()
        else if (liveCamOk) stage = "count"
    }
    var viewersNow by remember { mutableIntStateOf(0) }
    var viewersPeak by remember { mutableIntStateOf(0) }
    var streamError by remember { mutableStateOf<String?>(null) }
    var liveFront by remember { mutableStateOf(true) }
    var liveFace by remember { mutableStateOf("Nenhum") }
    var liveColor by remember { mutableStateOf("Original") }
    var hostLikes by remember { mutableIntStateOf(0) }
    var hostViewerNames by remember { mutableStateOf<List<String>>(emptyList()) }
    var hostJoin by remember { mutableStateOf("") }
    val hostHearts = remember { QinblyLiveHearts() }
    var hostBoxW by remember { mutableIntStateOf(0) }
    var hostBoxH by remember { mutableIntStateOf(0) }
    LaunchedEffect(hostJoin) { if (hostJoin.isNotBlank()) { kotlinx.coroutines.delay(4000); hostJoin = "" } }
    val hostInputPad = qinblyInputBottomPadding()
    androidx.compose.runtime.SideEffect { backHook.value = { if (stage == "live") confirmEnd = true else if (stage == "count") { screenData = null; stage = "setup" } else onClose() } }
    LaunchedEffect(stage) {
        if (stage == "count") {
            count = 5
            while (count > 0) { kotlinx.coroutines.delay(1000); count-- }
            seconds = 0; paused = false; viewersNow = 0; viewersPeak = 0; hostLikes = 0; hostViewerNames = emptyList(); streamError = null; stage = "live"
        }
    }
    LaunchedEffect(stage, paused) {
        while (stage == "live" && !paused) { kotlinx.coroutines.delay(1000); seconds++ }
    }
    val glass = Color(0x24FFFFFF)
    Box(Modifier.fillMaxSize().onSizeChanged { hostBoxW = it.width; hostBoxH = it.height }.background(Brush.verticalGradient(listOf(Color(0xFF4A586D), Color(0xFF222B3A), Color(0xFF12161E))))) {
        if (mode == "game") {
            if (stage == "live" && screenData != null) {
                QinblyLiveHostStream(
                    paused = paused, front = liveFront, micOn = micOn, username = hostHandle, modifier = Modifier.fillMaxSize(), screenData = screenData,
                    onViewers = { viewersNow = it; if (it > viewersPeak) viewersPeak = it },
                    onViewerNames = { hostViewerNames = it.filter { n -> n.isNotBlank() } },
                    onLikes = { hostLikes = it },
                    onHeart = { n -> repeat(n.coerceAtMost(6)) { hostHearts.add(hostBoxW * (0.55f + 0.35f * Math.random().toFloat()), hostBoxH * 0.78f) } },
                    onJoin = { hostJoin = "$it entrou na live" },
                    onError = { streamError = it }
                )
            }
            Column(Modifier.align(Alignment.TopCenter).fillMaxWidth().statusBarsPadding().padding(top = 110.dp, start = 36.dp, end = 36.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                Box(Modifier.size(64.dp).clip(CircleShape).background(Color(0x408B5CF6)), contentAlignment = Alignment.Center) {
                    Icon(androidx.compose.material.icons.Icons.Outlined.SportsEsports, null, tint = Color(0xFFC9B8FF), modifier = Modifier.size(32.dp))
                }
                Spacer(Modifier.height(10.dp))
                Text(if (stage == "live") "Seu jogo está ao vivo" else "Seu jogo vai ao vivo", color = Color.White, fontSize = 14.sp)
                Spacer(Modifier.height(4.dp))
                Text(
                    if (stage == "live") "Volte para o jogo. Para encerrar, abra o QINBLY e toque no X vermelho."
                    else "Ao tocar em Iniciar live, abra o jogo. Quem assiste vê tudo que aparecer na tela, inclusive avisos.",
                    color = Color(0xFF9A9AA8), fontSize = 12.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center
                )
            }
        } else if (liveCamOk && stage == "live") {
            QinblyLiveHostStream(
                paused = paused, front = liveFront, micOn = micOn, username = hostHandle, modifier = Modifier.fillMaxSize(), screenData = null,
                onViewers = { viewersNow = it; if (it > viewersPeak) viewersPeak = it },
                onViewerNames = { hostViewerNames = it.filter { n -> n.isNotBlank() } },
                onLikes = { hostLikes = it },
                onHeart = { n -> repeat(n.coerceAtMost(6)) { hostHearts.add(hostBoxW * (0.55f + 0.35f * Math.random().toFloat()), hostBoxH * 0.78f) } },
                onJoin = { hostJoin = "$it entrou na live" },
                onError = { streamError = it }
            )
        } else if (liveCamOk) {
            QinblyFaceCameraPreview(liveFace, if (liveColor == "Original") null else qinblyFilterMatrix(liveColor, 1f).array, liveFront, Modifier.fillMaxSize())
        } else {
            Column(Modifier.align(Alignment.Center), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text("A câmera aparece aqui", color = Color(0x80FFFFFF), fontSize = 14.sp)
                Button(onClick = { liveCamPermission.launch(android.Manifest.permission.CAMERA) }) { Text("Permitir câmera") }
            }
        }
        when (stage) {
            "setup" -> {
                Row(Modifier.fillMaxWidth().statusBarsPadding().padding(10.dp), verticalAlignment = Alignment.CenterVertically) {
                    Box(Modifier.size(34.dp).clip(CircleShape).background(glass).clickable { onClose() }, contentAlignment = Alignment.Center) {
                        Icon(QinblyIcon.Close, "Fechar", tint = Color.White, modifier = Modifier.size(18.dp))
                    }
                    Spacer(Modifier.weight(1f))
                    Text("Prévia", color = Color.White, fontWeight = FontWeight.Medium, fontSize = 14.sp, modifier = Modifier.clip(RoundedCornerShape(14.dp)).background(glass).padding(horizontal = 12.dp, vertical = 5.dp))
                    Spacer(Modifier.weight(1f))
                    if (mode == "camera") Box(Modifier.size(34.dp).clip(CircleShape).background(glass).clickable { liveFront = !liveFront }, contentAlignment = Alignment.Center) {
                        Icon(QinblyIcon.Cameraswitch, "Virar câmera", tint = Color.White, modifier = Modifier.size(18.dp))
                    } else Spacer(Modifier.size(34.dp))
                }
                val sheetLine = Color(0x1AFFFFFF)
                val sheetLabel = Color(0xFF9A9AA8)
                Column(
                    Modifier.align(Alignment.BottomCenter).fillMaxWidth().imePadding().padding(bottom = hostInputPad)
                        .clip(RoundedCornerShape(topStart = 22.dp, topEnd = 22.dp)).background(Color(0xD60E0E16)).padding(start = 16.dp, end = 16.dp, top = 14.dp, bottom = 12.dp)
                ) {
                    Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                        QinblyLiveAvatar(hostHandle.ifBlank { "Você" }, "", 32.dp, Color(0xFFD4537E))
                        TextField(
                            value = title, onValueChange = { title = it.take(80) }, singleLine = true,
                            placeholder = { Text("Título da live (opcional)", color = Color(0x99FFFFFF), fontSize = 14.sp) },
                            modifier = Modifier.weight(1f),
                            colors = TextFieldDefaults.colors(focusedContainerColor = Color.Transparent, unfocusedContainerColor = Color.Transparent, focusedIndicatorColor = Color.Transparent, unfocusedIndicatorColor = Color.Transparent, focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                        )
                        Icon(androidx.compose.material.icons.Icons.Filled.Edit, null, tint = Color(0x99FFFFFF), modifier = Modifier.size(17.dp))
                    }
                    Box(Modifier.fillMaxWidth().height(0.5.dp).background(sheetLine))
                    Text("O que mostrar", color = sheetLabel, fontSize = 11.sp, modifier = Modifier.padding(top = 12.dp, bottom = 6.dp))
                    Row(Modifier.fillMaxWidth().clip(RoundedCornerShape(14.dp)).background(Color(0x1AFFFFFF)).padding(3.dp)) {
                        listOf("camera" to "Câmera", "game" to "Jogos").forEach { (key, label) ->
                            Row(
                                Modifier.weight(1f).clip(RoundedCornerShape(11.dp)).background(if (mode == key) QinblyBrand.Accent else Color.Transparent)
                                    .clickable { mode = key }.padding(vertical = 7.dp),
                                horizontalArrangement = Arrangement.Center, verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(if (key == "camera") androidx.compose.material.icons.Icons.Filled.CameraAlt else androidx.compose.material.icons.Icons.Outlined.SportsEsports, null, tint = Color.White, modifier = Modifier.size(15.dp))
                                Spacer(Modifier.width(6.dp))
                                Text(label, color = Color.White, fontWeight = if (mode == key) FontWeight.Medium else FontWeight.Normal, fontSize = 14.sp)
                            }
                        }
                    }
                    Text("Quem pode assistir", color = sheetLabel, fontSize = 11.sp, modifier = Modifier.padding(top = 12.dp, bottom = 6.dp))
                    Row(Modifier.fillMaxWidth().clip(RoundedCornerShape(14.dp)).background(Color(0x1AFFFFFF)).padding(3.dp)) {
                        listOf(true to "Todos", false to "Seguidores").forEach { (all, label) ->
                            Row(
                                Modifier.weight(1f).clip(RoundedCornerShape(11.dp)).background(if (audienceAll == all) QinblyBrand.Accent else Color.Transparent)
                                    .clickable { audienceAll = all }.padding(vertical = 7.dp),
                                horizontalArrangement = Arrangement.Center, verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(if (all) androidx.compose.material.icons.Icons.Filled.Language else androidx.compose.material.icons.Icons.Filled.People, null, tint = Color.White, modifier = Modifier.size(15.dp))
                                Spacer(Modifier.width(6.dp))
                                Text(label, color = Color.White, fontWeight = if (audienceAll == all) FontWeight.Medium else FontWeight.Normal, fontSize = 14.sp)
                            }
                        }
                    }
                    Row(Modifier.fillMaxWidth().padding(top = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                        Icon(androidx.compose.material.icons.Icons.Filled.ChatBubbleOutline, null, tint = Color(0xFFDDDDDD), modifier = Modifier.size(19.dp))
                        Text("Comentários", color = Color.White, fontSize = 14.sp, modifier = Modifier.weight(1f).padding(start = 10.dp))
                        Switch(checked = commentsOn, onCheckedChange = { commentsOn = it })
                    }
                    Box(Modifier.fillMaxWidth().height(0.5.dp).background(sheetLine))
                    Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                        Icon(androidx.compose.material.icons.Icons.Filled.CardGiftcard, null, tint = Color(0xFFDDDDDD), modifier = Modifier.size(19.dp))
                        Text("Presentes", color = Color.White, fontSize = 14.sp, modifier = Modifier.weight(1f).padding(start = 10.dp))
                        Switch(checked = giftsOn, onCheckedChange = { giftsOn = it })
                    }
                    Row(
                        Modifier.fillMaxWidth().padding(top = 6.dp).clip(RoundedCornerShape(26.dp)).background(qinblyAccentBrush()).clickable {
                            if (mode == "game") {
                                if (!liveMicOk) liveMicPermission.launch(android.Manifest.permission.RECORD_AUDIO)
                                else liveStartScreen()
                            } else if (!liveCamOk) liveCamPermission.launch(android.Manifest.permission.CAMERA)
                            else if (!liveMicOk) liveMicPermission.launch(android.Manifest.permission.RECORD_AUDIO)
                            else stage = "count"
                        }.padding(vertical = 13.dp),
                        horizontalArrangement = Arrangement.Center, verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(Modifier.size(9.dp).clip(CircleShape).background(Color.White))
                        Spacer(Modifier.width(8.dp))
                        Text("Iniciar live", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 16.sp)
                    }
                }
            }
            "count" -> Text(if (count > 0) "$count" else "", color = Color.White, fontSize = 96.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.align(Alignment.Center))
            else -> {
                if (paused) Column(Modifier.align(Alignment.Center).fillMaxWidth().background(Color(0xB30B0E14)).padding(vertical = 28.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text("Live pausada", color = Color.White, fontWeight = FontWeight.Medium, fontSize = 16.sp)
                    Row(Modifier.clip(RoundedCornerShape(20.dp)).background(qinblyAccentBrush()).clickable { paused = false }.padding(horizontal = 22.dp, vertical = 9.dp), verticalAlignment = Alignment.CenterVertically) {
                        Icon(Icons.Default.PlayArrow, null, tint = Color.White, modifier = Modifier.size(20.dp))
                        Spacer(Modifier.width(4.dp))
                        Text("Retomar", color = Color.White, fontWeight = FontWeight.SemiBold)
                    }
                }
                Row(Modifier.fillMaxWidth().statusBarsPadding().padding(horizontal = 10.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                    QinblyLiveCapsule("Você", "", hostLikes, null, {})
                    Spacer(Modifier.weight(1f))
                    QinblyLiveViewersPill(hostViewerNames, viewersNow)
                    Spacer(Modifier.width(6.dp))
                    Row(Modifier.clip(RoundedCornerShape(14.dp)).background(if (paused) Color(0xB3666B75) else Color(0xD9E24B4A)).padding(horizontal = 10.dp, vertical = 6.dp), verticalAlignment = Alignment.CenterVertically) {
                        Box(Modifier.size(7.dp).clip(CircleShape).background(if (paused) Color(0xFFC9CDD4) else Color.White))
                        Spacer(Modifier.width(5.dp))
                        Text("%02d:%02d".format(seconds / 60, seconds % 60), color = Color.White, fontSize = 12.sp)
                    }
                }
                QinblyHeartsLayer(hostHearts, Modifier.fillMaxSize())
                Column(
                    Modifier.align(Alignment.BottomStart).imePadding().padding(start = 10.dp, end = 60.dp, bottom = hostInputPad + 64.dp),
                    verticalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    QinblyLiveJoinNotice(hostJoin, Modifier.padding(start = 4.dp))
                    if (commentsOn && hostHandle.isNotBlank()) QinblyLiveCommentsList(hostHandle, hostCommentRefresh)
                }
                Row(
                    Modifier.align(Alignment.BottomCenter).fillMaxWidth().imePadding().padding(start = 10.dp, end = 10.dp, top = 8.dp, bottom = hostInputPad),
                    verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(7.dp)
                ) {
                    TextField(
                        value = comment, onValueChange = { comment = it }, singleLine = true, visualTransformation = QinblyTagTransformation,
                        placeholder = { Text("Comente…", color = Color(0xB3FFFFFF)) },
                        modifier = Modifier.weight(1f), shape = RoundedCornerShape(24.dp),
                        colors = TextFieldDefaults.colors(focusedContainerColor = Color(0x8C14141C), unfocusedContainerColor = Color(0x8C14141C), focusedIndicatorColor = Color.Transparent, unfocusedIndicatorColor = Color.Transparent, focusedTextColor = Color.White, unfocusedTextColor = Color.White),
                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(imeAction = androidx.compose.ui.text.input.ImeAction.Send),
                        keyboardActions = androidx.compose.foundation.text.KeyboardActions(onSend = {
                            val text = comment.trim()
                            comment = ""
                            if (text.isNotEmpty()) {
                                if (hostHandle.isBlank()) onNotice("Entre na sua conta para comentar.")
                                else qinblySendLiveComment(liveContext, hostHandle, text, { hostCommentRefresh++ }, onNotice)
                            }
                        })
                    )
                    if (mode == "camera") QinblyLiveRoundButton(40.dp, onClick = { liveFront = !liveFront }) { Icon(QinblyIcon.Cameraswitch, "Virar câmera", tint = Color.White, modifier = Modifier.size(19.dp)) }
                    QinblyLiveRoundButton(40.dp, onClick = { micOn = !micOn }) { Icon(if (micOn) Icons.Default.Mic else QinblyIcon.MicOff, if (micOn) "Silenciar" else "Ligar microfone", tint = Color.White, modifier = Modifier.size(19.dp)) }
                    QinblyLiveRoundButton(40.dp, onClick = { paused = !paused }) { Icon(Icons.Default.Pause, "Pausar", tint = Color.White, modifier = Modifier.size(19.dp)) }
                    QinblyLiveRoundButton(40.dp, Color(0xFFE24B4A), onClick = { confirmEnd = true }) { Icon(Icons.Default.Close, "Encerrar", tint = Color.White, modifier = Modifier.size(19.dp)) }
                }
            }
        }
    }
    streamError?.let { why ->
        AlertDialog(
            onDismissRequest = { streamError = null; onClose() },
            shape = RoundedCornerShape(28.dp),
            title = { Text("Live não iniciada") },
            text = { Text(why) },
            confirmButton = { TextButton(onClick = { streamError = null; onClose() }) { Text("Fechar") } }
        )
    }
    if (confirmEnd) {
        AlertDialog(
            onDismissRequest = { confirmEnd = false },
            shape = RoundedCornerShape(28.dp),
            title = { Text("Encerrar a live?") },
            text = { Text("A transmissão será finalizada.") },
            confirmButton = { TextButton(onClick = { confirmEnd = false; summary = true }) { Text("Encerrar", color = Color(0xFFE24B4A)) } },
            dismissButton = { TextButton(onClick = { confirmEnd = false }) { Text("Continuar") } }
        )
    }
    if (summary) {
        AlertDialog(
            onDismissRequest = { summary = false; onClose() },
            shape = RoundedCornerShape(28.dp),
            title = { Text("Live encerrada") },
            text = { Text("Tempo no ar: %02d:%02d\nMáximo de espectadores: %d\nCurtidas: %d".format(seconds / 60, seconds % 60, viewersPeak, hostLikes)) },
            confirmButton = { TextButton(onClick = { summary = false; onClose() }) { Text("Concluir") } }
        )
    }
}

/** Sala ao vivo (quem assiste), em tela cheia: cápsula com foto, nome, curtidas e Seguir; fotinhas de quem assiste;
 *  curtir é tocar na tela (cada toque solta um coração); comentários em balão, campo "Diga algo…" e compartilhar. */
@Composable
private fun QinblyLiveRoom(live: QinblyLive, onClose: () -> Unit, onNotice: (String) -> Unit, backHook: MutableState<(() -> Unit)?>) {
    val shareContext = androidx.compose.ui.platform.LocalContext.current
    var commentRefresh by remember { mutableIntStateOf(0) }
    var likes by remember { mutableIntStateOf(live.likes) }
    var comment by remember { mutableStateOf("") }
    var viewersLive by remember { mutableIntStateOf(live.viewers) }
    var viewerNames by remember { mutableStateOf<List<String>>(emptyList()) }
    var joinNotice by remember { mutableStateOf("") }
    var pending by remember { mutableIntStateOf(0) }
    var boxW by remember { mutableIntStateOf(0) }
    var boxH by remember { mutableIntStateOf(0) }
    var hostId by remember { mutableStateOf("") }
    var hostAvatar by remember { mutableStateOf("") }
    var following by remember { mutableStateOf(false) }
    val hearts = remember { QinblyLiveHearts() }
    val outbox = remember { kotlinx.coroutines.channels.Channel<Int>(kotlinx.coroutines.channels.Channel.UNLIMITED) }
    val scope = rememberCoroutineScope()
    val inputPad = qinblyInputBottomPadding()
    val viewerHandle = remember { shareContext.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount().getString("username", "").orEmpty().removePrefix("@") }
    androidx.compose.runtime.SideEffect { backHook.value = onClose }
    DisposableEffect(Unit) { onDispose { outbox.close() } }
    LaunchedEffect(live.host) {
        try {
            val u = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getPublicProfile(live.host) }.optJSONObject("user")
            if (u != null) {
                hostId = u.optString("id")
                hostAvatar = u.optString("avatarUrl")
                following = u.optBoolean("isFollowing")
            }
        } catch (_: Exception) { }
    }
    LaunchedEffect(joinNotice) { if (joinNotice.isNotBlank()) { kotlinx.coroutines.delay(4000); joinNotice = "" } }
    LaunchedEffect(Unit) {
        // Os toques viram um lote a cada 0,4 s para não encher a conexão.
        while (true) {
            kotlinx.coroutines.delay(400)
            if (pending > 0) { outbox.trySend(pending); pending = 0 }
        }
    }
    Box(
        Modifier.fillMaxSize().background(Color(0xFF14181F)).onSizeChanged { boxW = it.width; boxH = it.height }
            .pointerInput(Unit) { detectTapGestures(onTap = { off -> likes++; pending++; hearts.add(off.x, off.y) }) }
    ) {
        QinblyLiveViewerStream(
            roomName = live.id, username = viewerHandle, modifier = Modifier.fillMaxSize(), outbox = outbox,
            onViewers = { viewersLive = it },
            onViewerNames = { list -> viewerNames = list.filter { n -> n.isNotBlank() && !n.equals(live.host, true) } },
            onLikes = { total -> if (total > likes) likes = total },
            onHeart = { n -> repeat(n.coerceAtMost(5)) { hearts.add(boxW * (0.5f + 0.4f * Math.random().toFloat()), boxH * 0.8f) } },
            onJoin = { joinNotice = "$it entrou na live" },
            onEnded = { onNotice(it); onClose() }
        )
        Row(Modifier.fillMaxWidth().statusBarsPadding().padding(horizontal = 10.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            QinblyLiveCapsule(
                live.host, hostAvatar, likes,
                if (viewerHandle.equals(live.host, true)) null else if (following) "Seguindo" else "Seguir",
                {
                    if (hostId.isBlank()) onNotice("Aguarde um instante.")
                    else scope.launch {
                        try {
                            val token = QinblyLiveNet.userToken(shareContext)
                            following = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.toggleFollow(token, hostId) }
                        } catch (e: QinblyApi.FollowRequestException) {
                            onNotice(e.message ?: "Pedido enviado.")
                        } catch (_: Exception) { onNotice("Não foi possível seguir agora.") }
                    }
                }
            )
            Spacer(Modifier.weight(1f))
            QinblyLiveViewersPill(viewerNames, viewersLive)
            Spacer(Modifier.width(6.dp))
            QinblyLiveRoundButton(30.dp, onClick = onClose) { Icon(QinblyIcon.Close, "Sair da live", tint = Color.White, modifier = Modifier.size(16.dp)) }
        }
        QinblyHeartsLayer(hearts, Modifier.fillMaxSize())
        Column(
            Modifier.align(Alignment.BottomStart).imePadding().padding(start = 10.dp, end = 60.dp, bottom = inputPad + 64.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            QinblyLiveJoinNotice(joinNotice, Modifier.padding(start = 4.dp))
            QinblyLiveCommentsList(live.host, commentRefresh)
        }
        Row(
            Modifier.align(Alignment.BottomCenter).fillMaxWidth().imePadding().padding(start = 10.dp, end = 10.dp, top = 8.dp, bottom = inputPad),
            verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            TextField(
                value = comment, onValueChange = { comment = it }, visualTransformation = QinblyTagTransformation,
                placeholder = { Text("Diga algo…", color = Color(0xB3FFFFFF)) },
                modifier = Modifier.weight(1f), singleLine = true, shape = RoundedCornerShape(24.dp),
                colors = TextFieldDefaults.colors(focusedContainerColor = Color(0x8C14141C), unfocusedContainerColor = Color(0x8C14141C), focusedIndicatorColor = Color.Transparent, unfocusedIndicatorColor = Color.Transparent, focusedTextColor = Color.White, unfocusedTextColor = Color.White),
                keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(imeAction = androidx.compose.ui.text.input.ImeAction.Send),
                keyboardActions = androidx.compose.foundation.text.KeyboardActions(onSend = {
                    val text = comment.trim()
                    comment = ""
                    if (text.isNotEmpty()) qinblySendLiveComment(shareContext, live.host, text, { commentRefresh++ }, onNotice)
                })
            )
            QinblyLiveRoundButton(42.dp, onClick = {
                try {
                    val send = android.content.Intent(android.content.Intent.ACTION_SEND).setType("text/plain")
                        .putExtra(android.content.Intent.EXTRA_TEXT, "Assista à live de @${live.host} no QINBLY!")
                    shareContext.startActivity(android.content.Intent.createChooser(send, "Compartilhar live").addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK))
                } catch (_: Exception) { onNotice("Não foi possível abrir o compartilhamento.") }
            }) { Icon(QinblyIcon.Share, "Compartilhar", tint = Color.White, modifier = Modifier.size(20.dp)) }
        }
    }
}

private val EmAltaGold = Color(0xFFEF9F27)
private val EmAltaSilver = Color(0xFFB4B2A9)
private val EmAltaBronze = Color(0xFFD85A30)
private fun qinblyRankColor(rank: Int): Color = when (rank) { 1 -> EmAltaGold; 2 -> EmAltaSilver; 3 -> EmAltaBronze; else -> RemoteAppearance.feedSecondaryTextColor }

/** Miniatura de uma publicação (quadro do vídeo, foto ou ícone de texto). */
@Composable
private fun QinblyPostThumb(post: QinblyApi.PostSummary, modifier: Modifier) {
    when {
        post.mediaType.equals("video", ignoreCase = true) && post.mediaUrl.isNotBlank() -> QinblyVideoPoster(post.mediaUrl, modifier, androidx.compose.ui.layout.ContentScale.Crop)
        post.mediaType.equals("image", ignoreCase = true) && post.mediaUrl.isNotBlank() -> AsyncImage(model = post.mediaUrl, contentDescription = null, modifier = modifier, contentScale = androidx.compose.ui.layout.ContentScale.Crop)
        else -> Box(modifier, contentAlignment = Alignment.Center) { QinblyAccentIcon(Icons.Default.Edit, contentDescription = null) }
    }
}

/** Um cartão do carrossel do Em alta: o mais curtido, o mais comentado ou uma live em alta. */
private data class EmAltaCard(val kind: String, val post: QinblyApi.PostSummary? = null, val live: QinblyLive? = null)

/** Em alta: carrossel de cartões (um por vez, de canto a canto), período, assuntos, top criadores e o início do ranking de vídeos. */
@Composable
private fun QinblyEmAltaHeader(
    period: String, onPeriod: (String) -> Unit, cards: List<EmAltaCard>,
    creators: List<Pair<QinblyApi.PostSummary, Int>>, hasVideos: Boolean, empty: Boolean,
    onOpenCard: (EmAltaCard) -> Unit, onProfile: (String) -> Unit, onSeeAll: () -> Unit
) {
    Column(Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
        if (cards.isNotEmpty()) {
            val pager = androidx.compose.foundation.pager.rememberPagerState(pageCount = { cards.size })
            Box(Modifier.fillMaxWidth().height(180.dp).clip(RoundedCornerShape(20.dp))) {
            androidx.compose.foundation.pager.HorizontalPager(state = pager, modifier = Modifier.fillMaxSize()) { page ->
                val card = cards[page]
                val isLive = card.live != null
                Box(
                    Modifier.fillMaxSize()
                        .background(androidx.compose.ui.graphics.Brush.linearGradient(if (isLive) listOf(Color(0xFF5C2C3A), Color(0xFFC0392B)) else listOf(QinblyBrand.Accent, QinblyBrand.Pink)))
                        .clickable { onOpenCard(card) }
                ) {
                    card.post?.let { if (it.mediaUrl.isNotBlank()) QinblyPostThumb(it, Modifier.fillMaxSize()) }
                    Box(Modifier.fillMaxSize().background(androidx.compose.ui.graphics.Brush.verticalGradient(listOf(Color(0x33000000), Color(0xCC000000)))))
                    if (isLive) Row(
                        Modifier.align(Alignment.TopStart).padding(12.dp).clip(RoundedCornerShape(6.dp)).background(Color(0xFFE0245E)).padding(horizontal = 8.dp, vertical = 3.dp),
                        verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(5.dp)
                    ) {
                        Box(Modifier.size(6.dp).clip(CircleShape).background(Color.White))
                        Text("AO VIVO", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                    }
                    Column(Modifier.align(Alignment.BottomStart).padding(start = 16.dp, end = 16.dp, bottom = if (cards.size > 1) 30.dp else 14.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        Row(
                            Modifier.clip(RoundedCornerShape(12.dp)).background(Color(0x66000000)).padding(horizontal = 10.dp, vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            when (card.kind) {
                                "likes" -> QinblyIconOf(QinblyIcon.Favorite, Color(0xFFFF6B8A), 14.dp)
                                "comments" -> QinblyIconOf(QinblyIcon.ChatBubble, Color.White, 14.dp)
                                else -> Icon(Icons.Filled.LocalFireDepartment, contentDescription = null, tint = Color.White, modifier = Modifier.size(14.dp))
                            }
                            Text(when (card.kind) { "likes" -> "Mais curtido"; "comments" -> "Mais comentado"; else -> "Live em alta" }, color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Medium)
                        }
                        val post = card.post; val live = card.live
                        val title = when {
                            live != null -> live.displayName.ifBlank { live.host }
                            card.kind == "likes" -> "EM ALTA"
                            else -> {
                                val first = post?.caption?.lineSequence()?.firstOrNull().orEmpty().trim()
                                if (first.isNotBlank()) first else (post?.displayName.orEmpty().ifBlank { post?.username.orEmpty() })
                            }
                        }
                        Text(title, color = Color.White, fontSize = if (card.kind == "likes" && live == null) 30.sp else 24.sp, fontWeight = FontWeight.ExtraBold,
                            letterSpacing = if (card.kind == "likes") 1.sp else 0.sp, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                        val sub = when {
                            live != null -> "@${live.host} · ${qinblyCount(live.viewers)} assistindo"
                            card.kind == "comments" && post != null -> "@${post.username} · ${qinblyCount(post.comments)} comentários"
                            post != null -> "@${post.username} · ${qinblyCount(QinblyEngagement.likeCount(post))} curtidas"
                            else -> ""
                        }
                        Text(sub, color = Color(0xCCFFFFFF), fontSize = 13.sp, maxLines = 1)
                    }
                }
            }
            // As bolinhas ficam dentro da imagem (sobrepostas ao rodapé do cartão).
            if (cards.size > 1) Row(Modifier.align(Alignment.BottomCenter).padding(bottom = 10.dp), verticalAlignment = Alignment.CenterVertically) {
                repeat(cards.size) { i ->
                    val on = pager.currentPage == i
                    Box(Modifier.padding(horizontal = 2.5.dp).height(5.dp).width(if (on) 16.dp else 5.dp).clip(RoundedCornerShape(3.dp)).background(if (on) Color.White else Color(0x80FFFFFF)))
                }
            }
            }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            listOf("Hoje", "Semana", "Mês").forEach { label ->
                val on = period == label
                Text(label, color = if (on) Color.White else RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 14.sp,
                    modifier = Modifier.clip(RoundedCornerShape(18.dp)).background(if (on) QinblyBrand.Accent else QinblyBrand.Accent.copy(alpha = 0.10f))
                        .clickable { onPeriod(label) }.padding(horizontal = 16.dp, vertical = 8.dp))
            }
        }
        if (creators.isNotEmpty()) {
            val whenLabel = when (period) { "Semana" -> "da semana"; "Mês" -> "do mês"; else -> "de hoje" }
            Text("Top criadores $whenLabel", color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 17.sp)
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                creators.forEachIndexed { i, (post, likes) ->
                    Column(
                        Modifier.weight(1f).clip(RoundedCornerShape(16.dp)).background(qinblyAccentBrush(0.08f)).clickable { onProfile(post.username) }.padding(vertical = 12.dp, horizontal = 6.dp),
                        horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Box(Modifier.size(62.dp)) {
                            QiblyAccountAvatar(post.username, post.avatarUrl, 58.dp) { onProfile(post.username) }
                            Box(Modifier.align(Alignment.BottomEnd).size(22.dp).clip(CircleShape).background(qinblyRankColor(i + 1)), contentAlignment = Alignment.Center) {
                                Text("${i + 1}", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                        Text(post.displayName.ifBlank { post.username }, color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 13.sp, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                        Text("${qinblyCount(likes)} curtidas", color = RemoteAppearance.feedSecondaryTextColor, fontSize = 12.sp, maxLines = 1)
                    }
                }
            }
        }
        if (empty) {
            Text("Nada em alta neste período", color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 16.sp)
        } else if (hasVideos) {
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text("Vídeos em alta", color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 17.sp, modifier = Modifier.weight(1f))
                QinblyAccentText("Ver todos", fontWeight = FontWeight.SemiBold, fontSize = 14.sp,
                    modifier = Modifier.clip(RoundedCornerShape(12.dp)).clickable { onSeeAll() }.padding(horizontal = 8.dp, vertical = 6.dp))
            }
        } else {
            Text("Mais curtidas", color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 17.sp)
        }
    }
}

@Composable
private fun QinblyRankRow(rank: Int, post: QinblyApi.PostSummary, onMore: (() -> Unit)? = null, onClick: () -> Unit) {
    Row(Modifier.fillMaxWidth().clickable(onClick = onClick).padding(horizontal = 14.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
        Text(rank.toString(), color = qinblyRankColor(rank), fontWeight = FontWeight.SemiBold, fontSize = 18.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center, modifier = Modifier.width(22.dp))
        QinblyPostThumb(post, Modifier.size(width = 84.dp, height = 58.dp).clip(RoundedCornerShape(10.dp)).background(qinblyAccentBrush(0.10f)))
        Column(Modifier.weight(1f)) {
            val title = post.caption.lineSequence().firstOrNull().orEmpty().trim().ifBlank { post.displayName.ifBlank { post.username } }
            Text(title, color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 15.sp, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
            Text("${qinblyCount(QinblyEngagement.likeCount(post))} curtidas · ${qinblyCount(post.comments)} comentários", color = RemoteAppearance.feedSecondaryTextColor, fontSize = 12.sp, maxLines = 1)
        }
        if (onMore != null) IconButton(onClick = onMore, modifier = Modifier.size(36.dp)) { Icon(Icons.Default.MoreVert, contentDescription = "Mais opções", tint = RemoteAppearance.feedSecondaryTextColor) }
    }
}

/** "Ver todos" do Em alta: lista completa de vídeos em alta, com período, ordem e busca. */
@Composable
private fun QinblyTrendingAllScreen(
    posts: List<QinblyApi.PostSummary>, initialPeriod: String, onDismiss: () -> Unit,
    onOpen: (QinblyApi.PostSummary) -> Unit, onProfile: (String) -> Unit, onShare: (QinblyApi.PostSummary) -> Unit
) {
    var period by remember { mutableStateOf(initialPeriod) }
    var sort by remember { mutableStateOf("Mais curtidos") }
    var searching by remember { mutableStateOf(false) }
    var query by remember { mutableStateOf("") }
    var menuFor by remember { mutableStateOf<String?>(null) }
    val list = remember(posts, period, sort, query) {
        val q = query.trim().removePrefix("@").lowercase()
        posts.filter { it.mediaType.equals("video", ignoreCase = true) && it.mediaUrl.isNotBlank() && qinblyInPeriod(it, period) }
            .filter { q.isEmpty() || it.caption.lowercase().contains(q) || it.username.lowercase().contains(q) || it.displayName.lowercase().contains(q) }
            .let { l ->
                when (sort) {
                    "Mais comentados" -> l.sortedByDescending { it.comments }
                    "Recentes" -> l.sortedByDescending { it.createdAt }
                    else -> l.sortedByDescending { QinblyEngagement.likeCount(it) }
                }
            }.take(50)
    }
    QinblyDialog(onDismissRequest = onDismiss, properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false)) {
        Column(Modifier.fillMaxSize().background(QiblyTheme.background).statusBarsPadding()) {
            Row(Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                IconButton(onClick = onDismiss) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = RemoteAppearance.screenTextColor) }
                Text("Vídeos em alta", color = RemoteAppearance.screenTextColor, fontSize = 20.sp, fontWeight = FontWeight.Medium, modifier = Modifier.weight(1f))
                IconButton(onClick = { searching = !searching; if (!searching) query = "" }) {
                    Icon(if (searching) Icons.Default.Close else Icons.Default.Search, contentDescription = "Buscar", tint = RemoteAppearance.screenTextColor)
                }
            }
            if (searching) {
                TextField(
                    value = query, onValueChange = { query = it }, singleLine = true, shape = RoundedCornerShape(24.dp),
                    placeholder = { Text("Buscar vídeo ou @usuário", color = RemoteAppearance.screenSecondaryTextColor) },
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 4.dp),
                    colors = TextFieldDefaults.colors(
                        focusedContainerColor = QinblyBrand.Accent.copy(alpha = 0.10f), unfocusedContainerColor = QinblyBrand.Accent.copy(alpha = 0.10f),
                        focusedIndicatorColor = Color.Transparent, unfocusedIndicatorColor = Color.Transparent,
                        focusedTextColor = RemoteAppearance.screenTextColor, unfocusedTextColor = RemoteAppearance.screenTextColor
                    )
                )
            }
            Row(Modifier.padding(horizontal = 14.dp, vertical = 6.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                listOf("Hoje", "Semana", "Mês").forEach { label ->
                    val on = period == label
                    Text(label, color = if (on) Color.White else RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold, fontSize = 14.sp,
                        modifier = Modifier.clip(RoundedCornerShape(18.dp)).background(if (on) QinblyBrand.Accent else QinblyBrand.Accent.copy(alpha = 0.10f))
                            .clickable { period = label }.padding(horizontal = 16.dp, vertical = 8.dp))
                }
            }
            Row(Modifier.horizontalScroll(rememberScrollState()).padding(horizontal = 14.dp, vertical = 4.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                listOf("Mais curtidos", "Mais comentados", "Recentes").forEach { label ->
                    val on = sort == label
                    Text(label, color = if (on) QinblyBrand.Accent else RemoteAppearance.screenSecondaryTextColor, fontWeight = if (on) FontWeight.SemiBold else FontWeight.Normal, fontSize = 13.sp,
                        modifier = Modifier.clip(RoundedCornerShape(16.dp)).border(1.dp, if (on) QinblyBrand.Accent else RemoteAppearance.screenSecondaryTextColor.copy(alpha = 0.4f), RoundedCornerShape(16.dp))
                            .clickable { sort = label }.padding(horizontal = 12.dp, vertical = 6.dp))
                }
            }
            if (list.isEmpty()) {
                Box(Modifier.fillMaxWidth().weight(1f), contentAlignment = Alignment.Center) {
                    Text(if (query.isNotBlank()) "Nenhum vídeo encontrado" else "Nenhum vídeo em alta neste período", color = RemoteAppearance.screenSecondaryTextColor, fontSize = 15.sp)
                }
            } else LazyColumn(Modifier.weight(1f).fillMaxWidth(), contentPadding = PaddingValues(top = 4.dp, bottom = 16.dp + qinblyNavBarPadding())) {
                items(list.size, key = { "all-" + list[it].id }) { i ->
                    val p = list[i]
                    Box(Modifier.fillMaxWidth()) {
                        QinblyRankRow(i + 1, p, onMore = { menuFor = p.id }) { onOpen(p) }
                        Box(Modifier.align(Alignment.CenterEnd)) {
                            DropdownMenu(expanded = menuFor == p.id, onDismissRequest = { menuFor = null }) {
                                DropdownMenuItem(text = { Text("Ver perfil") }, onClick = { menuFor = null; onProfile(p.username) })
                                DropdownMenuItem(text = { Text("Compartilhar") }, onClick = { menuFor = null; onShare(p) })
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
private fun FeedPage(scrollToTopRequest: Int, onlineUsers: Int, currentUsername: String, photoRefreshKey: Int, nameFontStyle: String, onNotice: (String) -> Unit, onOpenProfile: (String) -> Unit, onAddStory: () -> Unit, onSearch: () -> Unit, onNotifications: () -> Unit, onCreateWith: (String, String) -> Unit = { _, _ -> }, onOpenConversation: (String) -> Unit = {}, onGoTab: (Int) -> Unit = {}, onSettings: () -> Unit = {}) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    var posts by remember { mutableStateOf(QinblyCache.feed.ifEmpty { QinblyApi.getCachedPosts(context) }) }
    var loading by remember { mutableStateOf(posts.isEmpty()) }
    var refreshKey by remember { mutableIntStateOf(0) }
    var refreshingFeed by remember { mutableStateOf(false) }
    // Atualização "silenciosa" (voltou ao app depois de um tempo): busca o feed novo sem rolar a lista para o topo.
    var silentKey by remember { mutableIntStateOf(0) }
    val feedListState = rememberKeptListState("feed.list")
    val firstPhotoKey = remember { photoRefreshKey }
    val feedLifecycle = androidx.lifecycle.compose.LocalLifecycleOwner.current
    DisposableEffect(feedLifecycle) {
        var stoppedAt = 0L
        val observer = androidx.lifecycle.LifecycleEventObserver { _, event ->
            if (event == androidx.lifecycle.Lifecycle.Event.ON_STOP) stoppedAt = System.currentTimeMillis()
            else if (event == androidx.lifecycle.Lifecycle.Event.ON_START && stoppedAt > 0L) {
                if (System.currentTimeMillis() - stoppedAt >= 60_000L) silentKey++
                stoppedAt = 0L
            }
        }
        feedLifecycle.lifecycle.addObserver(observer)
        onDispose { feedLifecycle.lifecycle.removeObserver(observer) }
    }
    var commentPost by remember { mutableStateOf<QinblyApi.PostSummary?>(null) }
    var sharePost by remember { mutableStateOf<QinblyApi.PostSummary?>(null) }
    var selectedAudioPost by remember { mutableStateOf<QinblyApi.PostSummary?>(null) }
    var showTrendingAll by remember { mutableStateOf(false) }
    var emAltaLives by remember { mutableStateOf<List<QinblyLive>>(emptyList()) }
    var openEmAltaLive by remember { mutableStateOf<QinblyLive?>(null) }
    val openFeedComments: (QinblyApi.PostSummary) -> Unit = { target -> commentPost = target }
    var fullscreenVideoId by remember { mutableStateOf<String?>(null) }
    val resumeFeedFullscreen = remember { QinblyKeep.state<String?>("feed.resumeFullscreen", null) }
    val resumeFeedReels = remember { QinblyKeep.state("feed.resumeReels", false) }
    var selectedStory by remember { mutableStateOf<Pair<String, String>?>(null) }
    var unreadNotifications by remember { mutableIntStateOf(0) }
    // Primeira abertura: pede de uma vez as permissões que o app usa (câmera, microfone, mídia, localização, notificações).
    // Isso só pede a permissão; a câmera continua sendo ligada apenas na tela Criar.
    val startupPermissions = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { }
    LaunchedEffect(Unit) {
        if (!prefs.getBoolean("permissions_asked_v2", false)) {
            val wanted = mutableListOf(
                android.Manifest.permission.CAMERA, android.Manifest.permission.RECORD_AUDIO,
                android.Manifest.permission.ACCESS_COARSE_LOCATION, android.Manifest.permission.ACCESS_FINE_LOCATION,
                android.Manifest.permission.READ_CONTACTS
            )
            if (android.os.Build.VERSION.SDK_INT >= 33) {
                wanted += android.Manifest.permission.READ_MEDIA_IMAGES
                wanted += android.Manifest.permission.READ_MEDIA_VIDEO
                wanted += android.Manifest.permission.READ_MEDIA_AUDIO
                wanted += android.Manifest.permission.POST_NOTIFICATIONS
            } else wanted += android.Manifest.permission.READ_EXTERNAL_STORAGE
            if (android.os.Build.VERSION.SDK_INT >= 34) wanted += "android.permission.READ_MEDIA_VISUAL_USER_SELECTED"
            if (android.os.Build.VERSION.SDK_INT >= 31) wanted += android.Manifest.permission.BLUETOOTH_CONNECT
            val missing = wanted.filter { androidx.core.content.ContextCompat.checkSelfPermission(context, it) != android.content.pm.PackageManager.PERMISSION_GRANTED }
            prefs.edit().putBoolean("permissions_asked_v2", true).apply()
            if (missing.isNotEmpty()) startupPermissions.launch(missing.toTypedArray())
        }
    }
    val notifPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { }
    LaunchedEffect(Unit) {
        if (android.os.Build.VERSION.SDK_INT >= 33 && androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.POST_NOTIFICATIONS) != android.content.pm.PackageManager.PERMISSION_GRANTED) {
            val last = prefs.getLong("notif_perm_asked_at", 0L)
            if (System.currentTimeMillis() - last > 24L * 60 * 60 * 1000) {
                prefs.edit().putLong("notif_perm_asked_at", System.currentTimeMillis()).apply()
                kotlinx.coroutines.delay(1500)
                notifPermission.launch(android.Manifest.permission.POST_NOTIFICATIONS)
            }
        }
    }
    var selectedFeedTab by rememberKept("feed.tab", "Descobrir")
    var emAltaPeriod by rememberKept("feed.period", "Hoje")
    var reelsOpen by remember { mutableStateOf(resumeFeedReels.value.also { resumeFeedReels.value = false }) }
    LaunchedEffect(Unit) { resumeFeedFullscreen.value?.let { fullscreenVideoId = it; resumeFeedFullscreen.value = null } }
    LaunchedEffect(prefs.getString("token", null)) {
        val token = prefs.getString("token", null)
        if (token.isNullOrBlank()) {
            unreadNotifications = 0
        } else {
            var firstLoad = true
            while (true) {
                try {
                    val loaded = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getNotifications(token) }
                    val seenIds = context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount().getStringSet("notif_seen_ids", emptySet()).orEmpty()
                    val newUnread = loaded.count { it.readAt.isBlank() && it.kind != "message" && it.id !in seenIds }
                    // Com o app aberto não cria aviso na barra (o contador do sino já mostra); quem avisa é o serviço com o app fechado.
                    firstLoad = false
                    unreadNotifications = newUnread
                } catch (_: Exception) {
                    // Mantém o último contador confirmado se a rede estiver indisponível.
                }
                kotlinx.coroutines.delay(15_000)
            }
        }
    }
    // Perfis/publicações demonstrativas locais para testar a interface sem tocar no banco.
    var demoComments by remember { mutableStateOf<Map<String, List<QinblyApi.CommentSummary>>>(emptyMap()) }
    // O feed usa somente publicações reais retornadas pela API.
    val allFeedPosts = posts.sortedByDescending { it.createdAt }.distinctBy { it.id }
    // Bolinha vermelha na aba Seguindo: alguém que você segue postou depois da última vez que você abriu essa aba.
    var followingSeenAt by remember { mutableStateOf(prefs.getString("following_tab_seen_at", null) ?: java.time.Instant.now().toString().also { prefs.edit().putString("following_tab_seen_at", it).apply() }) }
    val hasNewFollowing = remember(allFeedPosts, followingSeenAt) {
        val seen = try { java.time.Instant.parse(followingSeenAt) } catch (_: Exception) { java.time.Instant.now() }
        allFeedPosts.any { post ->
            !post.username.equals(currentUsername.removePrefix("@"), ignoreCase = true) &&
                QinblyEngagement.isFollowing(prefs, post.username, post.isFollowing) &&
                (try { java.time.Instant.parse(post.createdAt).isAfter(seen) } catch (_: Exception) { false })
        }
    }
    LaunchedEffect(selectedFeedTab, allFeedPosts.size) {
        if (selectedFeedTab == "Seguindo") {
            val now = java.time.Instant.now().toString()
            followingSeenAt = now
            prefs.edit().putString("following_tab_seen_at", now).apply()
        }
    }
    val feedTabPosts = when (selectedFeedTab) {
        "Seguindo" -> allFeedPosts.filter { QinblyEngagement.isFollowing(prefs, it.username, it.isFollowing) }
        "Comunidade" -> allFeedPosts.filter { it.comments > 0 }
        else -> allFeedPosts
    }
    val displayedPosts = when (selectedFeedTab) {
        "Vídeos" -> allFeedPosts.filter { it.mediaType.equals("video", ignoreCase = true) }
        "Em alta" -> allFeedPosts.filter { qinblyEmAltaMedia(it) && qinblyInPeriod(it, emAltaPeriod) }.sortedByDescending { qinblyHotScore(it) }.take(20)
        else -> feedTabPosts
    }
    // Vídeos para a faixa "Vídeos sugeridos": os mais curtidos que não são seus e não estão nas primeiras publicações do feed.
    val suggestedVideos = remember(allFeedPosts, currentUsername, displayedPosts) {
        val firstIds = displayedPosts.take(3).map { it.id }.toSet()
        allFeedPosts.filter { it.mediaType.equals("video", ignoreCase = true) && it.mediaUrl.isNotBlank() && it.id !in firstIds && !it.username.equals(currentUsername.removePrefix("@"), ignoreCase = true) }
            .sortedByDescending { qinblyHotScore(it) }.take(8)
    }
    // Como o Instagram: o feed é buscado ao entrar no app, ao voltar depois de um tempo e ao puxar para atualizar. Nunca fica consultando enquanto a pessoa usa.
    // Se a pessoa já começou a rolar quando o feed novo chega, ele não troca a tela por cima (fica guardado para a próxima vez).
    val loadGate = remember { booleanArrayOf(true) }
    LaunchedEffect(refreshKey, silentKey, photoRefreshKey) {
        val force = refreshingFeed || photoRefreshKey != firstPhotoKey
        val isFirst = loadGate[0]; loadGate[0] = false
        if (isFirst && !force && posts.isNotEmpty() && System.currentTimeMillis() - QinblyCache.feedAt < 60_000L) { loading = false; return@LaunchedEffect }
        loading = posts.isEmpty()
        Thread {
            try {
                val loaded = QinblyApi.getPosts(prefs.getString("token", null))
                QinblyCache.feed = loaded
                QinblyCache.feedAt = System.currentTimeMillis()
                if (!prefs.getString("token", null).isNullOrBlank()) android.os.Handler(android.os.Looper.getMainLooper()).post { QinblyEngagement.learnFromPosts(prefs, loaded) }
                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    val atTop = feedListState.firstVisibleItemIndex == 0 && feedListState.firstVisibleItemScrollOffset < 60
                    if (force || posts.isEmpty() || atTop) posts = loaded
                    loading = false; refreshingFeed = false
                }
            } catch (e: Exception) {
                val cached = QinblyApi.getCachedPosts(context)
                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    if (cached.isNotEmpty() && posts.isEmpty()) posts = cached
                    loading = false
                    refreshingFeed = false
                    onNotice(if (cached.isNotEmpty()) "Sem conexão: mostrando o último feed sincronizado." else (e.message ?: "Não foi possível carregar o feed."))
                }
            }
        }.start()
    }
    // Carrossel do Em alta: busca as lives no ar ao abrir a aba (sem ficar consultando).
    LaunchedEffect(selectedFeedTab) {
        if (selectedFeedTab == "Em alta") {
            val liveToken = QinblyLiveNet.userToken(context)
            if (liveToken.isNotBlank()) QinblyLiveNet.list(liveToken)?.let { emAltaLives = it }
        }
    }
    // "Ver original" de um vídeo de story: vai para a aba Vídeos; se o vídeo não estiver na lista, abre a publicação sozinha.
    LaunchedEffect(QinblyFeedJump.postId) { if (QinblyFeedJump.postId != null && selectedFeedTab != "Vídeos") selectedFeedTab = "Vídeos" }
    LaunchedEffect(QinblyFeedJump.postId, loading, displayedPosts.size, selectedFeedTab) {
        val id = QinblyFeedJump.postId ?: return@LaunchedEffect
        if (!loading && selectedFeedTab == "Vídeos" && displayedPosts.none { it.id == id }) {
            val back = QinblyFeedJump.returnEntry; val idx = QinblyFeedJump.returnIndex
            QinblyFeedJump.postId = null; QinblyFeedJump.returnEntry = null
            if (back != null) QinblyResume.backOnClose = { QinblyStoryReturn.index = idx; QinblyStoryReturn.entry = back }
            QinblyDeepLink.postId = id
        }
    }
    LaunchedEffect(selectedFeedTab) { if (selectedFeedTab != "Vídeos") QinblyFeedJump.returnEntry = null }
    BackHandler(enabled = QinblyFeedJump.returnEntry != null) {
        val back = QinblyFeedJump.returnEntry
        QinblyFeedJump.returnEntry = null
        if (back != null) { selectedFeedTab = "Descobrir"; QinblyStoryReturn.index = QinblyFeedJump.returnIndex; QinblyStoryReturn.entry = back }
    }
    // Deslizar para os lados troca as abas de cima (Descobrir, Seguindo, Em alta, Vídeos, Lives); a barra de baixo não muda por gesto.
    val feedTabOrder = listOf("Descobrir", "Vídeos", "Seguindo", "Em alta", "Lives")
    // Aba Vídeos: tela cheia, um vídeo por tela, com o cabeçalho transparente por cima.
    val onVideoTab = selectedFeedTab == "Vídeos"
    val hdrText = if (onVideoTab) Color.White else RemoteAppearance.headerTextColor
    val videoTabPosts = if (onVideoTab) displayedPosts.filter { it.mediaUrl.isNotBlank() } else emptyList()
    val videoPagerState = androidx.compose.foundation.pager.rememberPagerState(pageCount = { videoTabPosts.size })
    // Depois do primeiro vídeo, o logo e os ícones somem e ficam só as abas de letra.
    val hideTop = onVideoTab
    DisposableEffect(onVideoTab) { QinblyVideoChrome.on = onVideoTab; onDispose { QinblyVideoChrome.on = false } }
    // Tocar num vídeo em qualquer aba do Início (Explorar, Seguindo...) abre a mesma tela cheia da aba Vídeos, já nele; voltar retorna à aba de origem.
    var videoBackTab by remember { mutableStateOf<String?>(null) }
    val openPostMedia: (QinblyApi.PostSummary) -> Unit = { target ->
        if (target.mediaType.equals("video", ignoreCase = true) && target.mediaUrl.isNotBlank()) {
            videoBackTab = selectedFeedTab
            QinblyFeedJump.postId = target.id
            selectedFeedTab = "Vídeos"
        } else fullscreenVideoId = target.id
    }
    LaunchedEffect(selectedFeedTab) { if (selectedFeedTab != "Vídeos") videoBackTab = null }
    // Qualquer aba de cima que não seja a Explorar: 1 toque no voltar leva ao Explorar; 2 toques rápidos fecham o app.
    BackHandler(enabled = selectedFeedTab != "Descobrir" && (videoBackTab != null || QinblyFeedJump.returnEntry == null)) {
        QinblyQuickExit.at = android.os.SystemClock.elapsedRealtime()
        selectedFeedTab = videoBackTab ?: "Descobrir"
        videoBackTab = null
    }
    // O cabeçalho inteiro (QINBLY, busca, sino e as abas Descobrir/Seguindo/Em alta/...) sobe junto com a rolagem e volta ao rolar para cima.
    var headerPx by remember { mutableFloatStateOf(0f) }
    var headerOffset by remember { mutableFloatStateOf(0f) }
    val headerConnection = remember {
        object : androidx.compose.ui.input.nestedscroll.NestedScrollConnection {
            override fun onPreScroll(available: Offset, source: androidx.compose.ui.input.nestedscroll.NestedScrollSource): Offset {
                if (selectedFeedTab == "Vídeos" || headerPx <= 0f || available.y == 0f) return Offset.Zero
                val next = (headerOffset + available.y).coerceIn(-headerPx, 0f)
                val used = next - headerOffset
                headerOffset = next
                return Offset(0f, used)
            }
        }
    }
    LaunchedEffect(selectedFeedTab, scrollToTopRequest) { headerOffset = 0f }
    Column(
        Modifier.fillMaxSize().background(if (onVideoTab) Color.Black else RemoteAppearance.headerBackgroundColor).padding(0.dp)
            .nestedScroll(headerConnection)
            .pointerInput(Unit) {
                var dragged = 0f
                detectHorizontalDragGestures(
                    onHorizontalDrag = { _, amount -> dragged += amount },
                    onDragEnd = {
                        val threshold = 72.dp.toPx()
                        val index = feedTabOrder.indexOf(selectedFeedTab)
                        val target = when {
                            dragged <= -threshold -> feedTabOrder.getOrNull(index + 1)
                            dragged >= threshold -> feedTabOrder.getOrNull(index - 1)
                            else -> null
                        }
                        if (target != null) selectedFeedTab = target
                        dragged = 0f
                    },
                    onDragCancel = { dragged = 0f }
                )
            }
    ) {
        Box(Modifier.weight(1f).fillMaxWidth()) {
        if (onVideoTab) {
            LaunchedEffect(QinblyFeedJump.postId, videoTabPosts.size) {
                val id = QinblyFeedJump.postId
                if (id != null) {
                    val i = videoTabPosts.indexOfFirst { it.id == id }
                    if (i >= 0) { videoPagerState.scrollToPage(i); QinblyFeedJump.postId = null }
                }
            }
            LaunchedEffect(scrollToTopRequest) { if (scrollToTopRequest > 0) videoPagerState.animateScrollToPage(0) }
            if (videoTabPosts.isNotEmpty()) {
                QinblyVideoPager(
                    posts = videoTabPosts, pagerState = videoPagerState, prefs = prefs, currentUsername = currentUsername, onNotice = onNotice,
                    onComment = { openFeedComments(it) }, onShare = { sharePost = it }, onOpenProfile = onOpenProfile,
                    onOpenAudio = { selectedAudioPost = it },
                    modifier = Modifier.fillMaxSize().padding(top = with(androidx.compose.ui.platform.LocalDensity.current) { headerPx.toDp() }), bottomPad = 24.dp, embedded = true
                )
            } else if (loading) QinblyLoadingSpinner(Modifier.fillMaxSize())
        }
        Column(Modifier.fillMaxSize()) {
        Column(
            Modifier.fillMaxWidth().clipToBounds()
                .layout { measurable, constraints ->
                    val placeable = measurable.measure(constraints)
                    if (headerPx != placeable.height.toFloat()) headerPx = placeable.height.toFloat()
                    val shownHeight = (placeable.height + headerOffset).toInt().coerceAtLeast(0)
                    layout(placeable.width, shownHeight) { placeable.place(0, headerOffset.toInt()) }
                }
        ) {
        if (!hideTop) Box(Modifier.fillMaxWidth().padding(start = 16.dp, end = 8.dp, top = 6.dp).heightIn(min = 42.dp)) {
            Text(QinblyBrand.Name, style = androidx.compose.ui.text.TextStyle(brush = Brush.horizontalGradient(listOf(QinblyBrand.Logo, QinblyBrand.Pink))), fontSize = 24.sp, fontWeight = FontWeight.ExtraBold, letterSpacing = 1.sp, modifier = Modifier.align(Alignment.CenterStart))
            Row(Modifier.align(Alignment.CenterEnd), verticalAlignment = Alignment.CenterVertically) {
            IconButton(onClick = onSearch, modifier = Modifier.size(42.dp)) {
                Icon(Icons.Default.Search, contentDescription = "Buscar", tint = hdrText, modifier = Modifier.size(26.dp))
            }
            Box(Modifier.size(48.dp), contentAlignment = Alignment.Center) {
                IconButton(onClick = onNotifications, modifier = Modifier.size(48.dp)) {
                    Icon(androidx.compose.material.icons.Icons.Outlined.NotificationsNone, contentDescription = "Notificações", tint = hdrText, modifier = Modifier.size(32.dp))
                }
                if (unreadNotifications > 0) {
                    Box(
                        Modifier.align(Alignment.TopEnd).offset(x = 2.dp, y = 0.dp)
                            .sizeIn(minWidth = 20.dp, minHeight = 20.dp)
                            .border(2.dp, RemoteAppearance.screenBackgroundColor, CircleShape)
                            .clip(CircleShape).background(qinblyAccentBrush()).padding(horizontal = if (unreadNotifications > 9) 5.dp else 0.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(if (unreadNotifications > 99) "99+" else unreadNotifications.toString(), color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, maxLines = 1)
                    }
                }
            }
        }
        }
        Row(Modifier.fillMaxWidth().padding(top = 2.dp)) {
            listOf("Descobrir", "Vídeos", "Seguindo", "Em alta", "Lives").forEach { feedTab ->
                val selected = selectedFeedTab == feedTab
                val labelTint = if (selected) (if (onVideoTab) Color.White else QinblyBrand.TextAccent) else hdrText.copy(alpha = 0.62f)
                // Nomes na tela; os códigos internos (Descobrir, Lives) continuam os mesmos.
                val tabLabel = when (feedTab) { "Descobrir" -> "Explorar"; "Lives" -> "Ao vivo"; else -> feedTab }
                Column(
                    modifier = Modifier.weight(1f).clickable { selectedFeedTab = feedTab }.padding(top = 12.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Box {
                        Text(tabLabel, color = labelTint, fontSize = 13.sp, maxLines = 1, softWrap = false, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, fontWeight = if (selected) FontWeight.SemiBold else FontWeight.Normal)
                        if (feedTab == "Seguindo" && hasNewFollowing && !selected) Box(
                            Modifier.align(Alignment.TopEnd).offset(x = 7.dp, y = (-3).dp).size(8.dp).clip(CircleShape).background(Color(0xFFE53935))
                        )
                    }
                    Spacer(Modifier.height(10.dp))
                    Box(Modifier.fillMaxWidth().height(3.dp).background(if (selected) (if (onVideoTab) Color.White else QinblyBrand.TextAccent) else Color.Transparent))
                }
            }
        }
        Box(Modifier.fillMaxWidth().height(0.5.dp).background(if (onVideoTab) Color.Transparent else RemoteAppearance.feedDividerColor))
        }
        if (selectedFeedTab != "Descobrir" && selectedFeedTab != "Vídeos") QinblyStoriesRow(onNotice, onOpenProfile, onOpenConversation, onAddStory, hostOnly = true)
        if (selectedFeedTab == "Lives") {
            QinblyLivesPage(emptyList(), onNotice)
        } else if (selectedFeedTab == "Vídeos" && (videoTabPosts.isNotEmpty() || loading)) {
            // A aba Vídeos é desenhada na camada de baixo (tela cheia, atrás do cabeçalho transparente).
        } else if (!loading && displayedPosts.isEmpty() && selectedFeedTab != "Em alta" && selectedFeedTab != "Descobrir") {
            Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("Ainda não há publicações", fontWeight = FontWeight.SemiBold)
                    Text("Quando alguém publicar, as postagens públicas aparecerão aqui.", color = Muted, style = MaterialTheme.typography.bodySmall)
                }
            }
        } else {
            // Ao voltar de um perfil, a lista continua onde estava: só rola para o topo quando a aba/atualização muda de verdade.
            var feedFirstRun by remember { mutableStateOf(true) }
            LaunchedEffect(refreshKey, selectedFeedTab) { if (feedFirstRun) feedFirstRun = false else feedListState.scrollToItem(0) }
            LaunchedEffect(scrollToTopRequest) { if (scrollToTopRequest > 0) feedListState.animateScrollToItem(0) }
            LaunchedEffect(QinblyFeedJump.postId, selectedFeedTab, displayedPosts.size) {
                val id = QinblyFeedJump.postId
                if (id != null && selectedFeedTab == "Vídeos") {
                    val i = displayedPosts.indexOfFirst { it.id == id }
                    if (i >= 0) { feedListState.scrollToItem(i); QinblyFeedJump.postId = null }
                }
            }
            androidx.compose.material3.pulltorefresh.PullToRefreshBox(isRefreshing = refreshingFeed, onRefresh = { RemoteUiRefreshSignal.value++; if (!refreshingFeed) { refreshingFeed = true; refreshKey++ } }, modifier = Modifier.fillMaxSize()) {
            LazyColumn(
                state = feedListState,
                verticalArrangement = Arrangement.spacedBy(0.dp),
                contentPadding = PaddingValues(top = 0.dp, bottom = 18.dp)
            ) {
                if (selectedFeedTab == "Descobrir") item(key = "home-stories") {
                    QinblyStoriesRow(onNotice, onOpenProfile, onOpenConversation, onAddStory)
                }
                if (selectedFeedTab == "Descobrir") item(key = "home-composer") {
                    QinblyHomeComposer(onCreateWith)
                }
                if (selectedFeedTab == "Descobrir") item(key = "home-header") {
                    QinblyHomeHeader(allFeedPosts, prefs, onCreateWith)
                }
                if (selectedFeedTab == "Em alta") item(key = "alta-header") {
                    val periodPosts = allFeedPosts.filter { qinblyEmAltaMedia(it) && qinblyInPeriod(it, emAltaPeriod) }
                    val creators = periodPosts.groupBy { it.username.lowercase() }
                        .map { (_, ps) -> ps.first() to ps.sumOf { QinblyEngagement.likeCount(it) } }
                        .sortedByDescending { it.second }.take(3)
                    val cards = buildList {
                        periodPosts.maxByOrNull { QinblyEngagement.likeCount(it) }?.let { add(EmAltaCard("likes", post = it)) }
                        periodPosts.filter { it.comments > 0 }.maxByOrNull { it.comments }?.let { add(EmAltaCard("comments", post = it)) }
                        emAltaLives.maxByOrNull { it.viewers }?.let { add(EmAltaCard("live", live = it)) }
                    }
                    QinblyEmAltaHeader(
                        period = emAltaPeriod, onPeriod = { emAltaPeriod = it },
                        cards = cards, creators = creators,
                        hasVideos = displayedPosts.any { it.mediaType.equals("video", ignoreCase = true) && it.mediaUrl.isNotBlank() },
                        empty = displayedPosts.isEmpty(),
                        onOpenCard = { c -> val l = c.live; val pst = c.post; if (l != null) openEmAltaLive = l else if (pst != null) openPostMedia(pst) }, onProfile = onOpenProfile, onSeeAll = { showTrendingAll = true }
                    )
                }
                if (!loading && displayedPosts.isEmpty()) {
                    item {
                        Column(
                            Modifier.fillMaxWidth().padding(horizontal = 28.dp, vertical = 32.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text("Ainda não há publicações", color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 18.sp)
                            Text("Quando as pessoas publicarem, elas aparecerão aqui.", color = RemoteAppearance.feedSecondaryTextColor, fontSize = 14.sp)
                            OutlinedButton(onClick = { refreshKey++ }) {
                                Text("Atualizar feed")
                            }
                        }
                    }
                }
                if (selectedFeedTab == "Em alta") {
                    val altaVideos = displayedPosts.filter { it.mediaType.equals("video", ignoreCase = true) && it.mediaUrl.isNotBlank() }.take(3)
                    val altaOthers = displayedPosts.filter { p -> altaVideos.none { it.id == p.id } }.take(10)
                    items(altaVideos.size, key = { "rank-" + altaVideos[it].id }) { index ->
                        QinblyRankRow(index + 1, altaVideos[index]) { openPostMedia(altaVideos[index]) }
                    }
                    if (altaOthers.isNotEmpty() && altaVideos.isNotEmpty()) item(key = "alta-others") {
                        Text("Publicações em alta", color = RemoteAppearance.feedTextColor, fontWeight = FontWeight.SemiBold, fontSize = 17.sp,
                            modifier = Modifier.padding(horizontal = 14.dp, vertical = 12.dp))
                    }
                    items(altaOthers.size, key = { "rank2-" + altaOthers[it].id }) { index ->
                        QinblyRankRow(index + 1, altaOthers[index]) { openPostMedia(altaOthers[index]) }
                    }
                } else androidx.compose.foundation.lazy.itemsIndexed(displayedPosts, key = { _, p -> p.id }) { index, post ->
                    Column(Modifier.fillMaxWidth()) {
                    QinblyPostCard(
                        post = post,
                        prefs = prefs,
                        nameFontStyle = nameFontStyle,
                        onNotice = onNotice,
                        onOpenProfile = onOpenProfile,
                        onOpenViewer = { openPostMedia(it) },
                        onComment = { openFeedComments(it) },
                        onShare = { sharePost = it },
                        onPostsTransform = { change -> posts = change(posts) },
                        onRefresh = { refreshKey++ },
                        smallVideo = selectedFeedTab == "Descobrir"
                    )
                    if (selectedFeedTab == "Descobrir" && index == 2 && suggestedVideos.size >= 3) QinblySuggestedVideos(suggestedVideos) { openPostMedia(it) }
                    }
                }
            }
            }
        }
        }
        }
    openEmAltaLive?.let { live ->
        val roomBack = remember { mutableStateOf<(() -> Unit)?>(null) }
        QinblyLiveWindow(roomBack) { QinblyLiveRoom(live, onClose = { openEmAltaLive = null }, onNotice = onNotice, backHook = roomBack) }
    }
    if (showTrendingAll) {
        QinblyTrendingAllScreen(
            posts = allFeedPosts, initialPeriod = emAltaPeriod, onDismiss = { showTrendingAll = false },
            onOpen = { showTrendingAll = false; openPostMedia(it) },
            onProfile = { showTrendingAll = false; onOpenProfile(it) },
            onShare = { sharePost = it }
        )
    }
    sharePost?.let { selectedPost ->
        QiblyShareDialog(
            post = selectedPost,
            prefs = prefs,
            onDismiss = { sharePost = null },
            onNotice = onNotice
        )
    }
    if (reelsOpen) {
        // Clipes: vídeos do feed, um por tela, deslizando na vertical, com o mesmo visualizador, botões e comentários de todo o app.
        val reels = allFeedPosts.filter { it.mediaType == "video" && it.mediaUrl.isNotBlank() }
        if (reels.isEmpty()) {
            LaunchedEffect(Unit) { reelsOpen = false; onNotice("Ainda não há vídeos para mostrar em Clipes.") }
        } else {
            QinblyPostViewer(
                posts = reels, startPostId = reels.first().id, prefs = prefs, currentUsername = currentUsername, onNotice = onNotice,
                onDismiss = { reelsOpen = false }, onComment = { commentPost = it }, onShare = { sharePost = it },
                onOpenProfile = { QinblyResume.push { resumeFeedReels.value = true }; reelsOpen = false; onOpenProfile(it) }
            )
        }
    }
    val fullscreenStartId = fullscreenVideoId
    val fullscreenVideos = qinblyViewerList(displayedPosts.filter { (it.mediaType == "video" || it.mediaType == "image") && it.mediaUrl.isNotBlank() }, fullscreenStartId)
    if (fullscreenStartId != null && fullscreenVideos.any { it.id == fullscreenStartId }) {
        QinblyPostViewer(
            posts = fullscreenVideos,
            startPostId = fullscreenStartId,
            prefs = prefs,
            currentUsername = currentUsername,
            onNotice = onNotice,
            onDismiss = { fullscreenVideoId = null },
            onComment = { openFeedComments(it) },
            onShare = { sharePost = it },
            onOpenProfile = { val fv = fullscreenVideoId; QinblyResume.push { resumeFeedFullscreen.value = fv }; fullscreenVideoId = null; onOpenProfile(it) },
            onOpenAudio = { selectedAudioPost = it; fullscreenVideoId = null }
        )
    }
    if (selectedAudioPost != null) {
        val sourcePost = selectedAudioPost!!
        val originalSound = sourcePost.audioId.isBlank()
        val matchingPosts = allFeedPosts.filter { candidate ->
            candidate.mediaType.equals("video", ignoreCase = true) &&
                if (originalSound) candidate.id == sourcePost.id
                else candidate.audioId == sourcePost.audioId
        }.ifEmpty { listOf(sourcePost) }
        QinblyDialog(
            onDismissRequest = { selectedAudioPost = null },
            properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
        ) {
            Column(Modifier.fillMaxSize().background(Color(0xFF101010))) {
                Row(
                    Modifier.fillMaxWidth().padding(12.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(onClick = { selectedAudioPost = null }) {
                        Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = Color.White)
                    }
                    Spacer(Modifier.width(8.dp))
                    Text("Áudio", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.SemiBold)
                }
                Row(Modifier.fillMaxWidth().padding(18.dp), verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        Modifier.size(74.dp).clip(CircleShape).background(Color(0xFF252525)),
                        contentAlignment = Alignment.Center
                    ) {
                        if (originalSound && sourcePost.avatarUrl.isNotBlank()) {
                            AsyncImage(
                                model = sourcePost.avatarUrl, contentDescription = "Autor do som original",
                                modifier = Modifier.fillMaxSize(), contentScale = androidx.compose.ui.layout.ContentScale.Crop
                            )
                        } else Icon(Icons.Default.MusicNote, contentDescription = null, tint = Color.White, modifier = Modifier.size(34.dp))
                    }
                    Spacer(Modifier.width(16.dp))
                    Column {
                        Text(if (originalSound) "Som original" else sourcePost.audioTitle.ifBlank { "Áudio" },
                            color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.SemiBold)
                        Text(if (originalSound) "@${sourcePost.username}" else sourcePost.audioArtist.ifBlank { "@${sourcePost.username}" },
                            color = Color.LightGray, fontSize = 16.sp)
                        Text("${matchingPosts.size} publicação(ões) carregada(s) com este áudio",
                            color = Color.LightGray, fontSize = 12.sp)
                    }
                }
                Text("Publicações com este áudio", color = Color.White, fontWeight = FontWeight.SemiBold,
                    modifier = Modifier.padding(start = 18.dp, top = 12.dp, bottom = 10.dp))
                LazyColumn(
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(matchingPosts, key = { it.id }) { post ->
                        Row(
                            Modifier.fillMaxWidth().clip(RoundedCornerShape(10.dp))
                                .background(Color(0xFF202020))
                                .clickable { selectedAudioPost = null; fullscreenVideoId = post.id }
                                .padding(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            AsyncImage(
                                model = coil.request.ImageRequest.Builder(androidx.compose.ui.platform.LocalContext.current)
                                    .data(post.mediaUrl)
                                    .decoderFactory(coil.decode.VideoFrameDecoder.Factory())
                                    .build(),
                                contentDescription = "Vídeo de @${post.username}",
                                modifier = Modifier.size(width = 86.dp, height = 105.dp).clip(RoundedCornerShape(8.dp)),
                                contentScale = androidx.compose.ui.layout.ContentScale.Crop
                            )
                            Spacer(Modifier.width(12.dp))
                            Column(Modifier.weight(1f)) {
                                Text(post.displayName.ifBlank { post.username }, color = Color.White, fontWeight = FontWeight.SemiBold)
                                Text(post.caption, color = Color.LightGray, maxLines = 3)
                            }
                            Icon(Icons.Default.PlayCircle, contentDescription = "Assistir", tint = Color.White)
                        }
                    }
                }
            }
        }
    }
    if (selectedStory != null) {
        val story = selectedStory!!
        QinblyDialog(onDismissRequest = { selectedStory = null }, properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)) {
            Box(Modifier.fillMaxSize().background(Color.Black).clickable { selectedStory = null }) {
                AsyncImage(model = story.second.replace("w=240", "w=1200"), contentDescription = "Story de @" + story.first, modifier = Modifier.fillMaxSize(), contentScale = androidx.compose.ui.layout.ContentScale.Fit)
                Row(Modifier.align(Alignment.TopStart).fillMaxWidth().padding(20.dp), verticalAlignment = Alignment.CenterVertically) {
                    AsyncImage(model = story.second, contentDescription = null, modifier = Modifier.size(42.dp).clip(CircleShape), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
                    Text("@" + story.first, modifier = Modifier.padding(start = 10.dp).weight(1f), color = Color.White, fontWeight = FontWeight.SemiBold)
                    IconButton(onClick = { selectedStory = null }) { Icon(Icons.Default.Close, contentDescription = "Fechar story", tint = Color.White) }
                }
            }
        }
    }
    commentPost?.let { target ->
        QinblyCommentsDialog(
            post = target,
            prefs = prefs,
            currentUsername = currentUsername,
            onNotice = onNotice,
            onDismiss = { commentPost = null },
            onCountChanged = { postId, count ->
                posts = posts.map { if (it.id == postId && it.comments != count) it.copy(comments = count) else it }
                QinblyCache.feed = posts
            }
        )
    }

}

}

@Composable
private fun CommunitiesPage(onNotice: (String) -> Unit) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    val mainHandler = remember { android.os.Handler(android.os.Looper.getMainLooper()) }
    var selected by rememberKept("comm.selected", "Minhas")
    var list by remember { mutableStateOf(QinblyCache.communities[selected] ?: emptyList<QinblyApi.CommunitySummary>()) }
    var loading by remember { mutableStateOf(list.isEmpty()) }
    var showCreate by remember { mutableStateOf(false) }
    var openId by rememberKept<String?>("comm.openId", null)
    var reload by remember { mutableIntStateOf(0) }
    val filterKey = when (selected) { "Minhas" -> "mine"; "Em alta" -> "trending"; else -> "discover" }
    LaunchedEffect(Unit) { QinblyCache.communities["Minhas"]?.let { QinblyCommunitiesUi.hasMine = it.isNotEmpty() } }
    // Botão + do cabeçalho (aparece depois da primeira comunidade) abre a criação.
    var seenCreateRequest by remember { mutableIntStateOf(QinblyCommunitiesUi.createRequest) }
    LaunchedEffect(QinblyCommunitiesUi.createRequest) {
        if (QinblyCommunitiesUi.createRequest != seenCreateRequest) {
            seenCreateRequest = QinblyCommunitiesUi.createRequest
            if (!prefs.getString("token", null).isNullOrBlank()) showCreate = true else onNotice("Entre na sua conta para participar de comunidades.")
        }
    }

    LaunchedEffect(selected, reload) {
        list = QinblyCache.communities[selected] ?: emptyList()
        loading = list.isEmpty()
        val token = prefs.getString("token", null)
        Thread {
            try {
                val result = QinblyApi.getCommunities(filterKey, token)
                mainHandler.post { QinblyCache.communities[selected] = result; list = result; loading = false; if (filterKey == "mine") QinblyCommunitiesUi.hasMine = result.isNotEmpty() }
            } catch (e: Exception) {
                mainHandler.post { loading = false; onNotice(e.message ?: "Não foi possível carregar as comunidades.") }
            }
        }.start()
    }

    fun requireLogin(): String? {
        val t = prefs.getString("token", null)
        if (t.isNullOrBlank()) onNotice("Entre na sua conta para participar de comunidades.")
        return t?.takeIf { it.isNotBlank() }
    }

    fun toggleJoin(c: QinblyApi.CommunitySummary) {
        val token = requireLogin() ?: return
        val optimistic = !c.joined
        list = list.map { if (it.id == c.id) it.copy(joined = optimistic, members = (it.members + if (optimistic) 1 else -1).coerceAtLeast(0)) else it }
        Thread {
            try {
                val (joined, members, pending) = QinblyApi.toggleCommunityJoin(token, c.id)
                mainHandler.post {
                    if (pending) onNotice("Pedido enviado. O dono precisa aprovar.")
                    list = list.map { if (it.id == c.id) it.copy(joined = joined, members = members, pending = pending) else it }
                    QinblyCache.communities.clear()
                    if (selected == "Minhas" && !joined) list = list.filterNot { it.id == c.id }
                }
            } catch (e: Exception) {
                mainHandler.post { list = list.map { if (it.id == c.id) c else it }; onNotice(e.message ?: "Não foi possível atualizar.") }
            }
        }.start()
    }

    Column(Modifier.fillMaxSize().background(RemoteAppearance.screenBackgroundColor).padding(16.dp)) {
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            listOf("Minhas", "Em alta", "Descobrir").forEach { item ->
                Surface(
                    modifier = Modifier.weight(1f).clickable { selected = item },
                    shape = RoundedCornerShape(22.dp),
                    color = if (selected == item) QinblyBrand.Accent else QiblyTheme.card
                ) {
                    Text(item, modifier = Modifier.padding(vertical = 12.dp), textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                        color = if (selected == item) Color.White else RemoteAppearance.screenTextColor)
                }
            }
        }
        Spacer(Modifier.height(12.dp))
        if (!QinblyCommunitiesUi.hasMine) {
            QinblyGradientButton(
                onClick = { if (requireLogin() != null) showCreate = true },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(22.dp),
                colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)
            ) {
                Icon(Icons.Default.Add, contentDescription = null)
                Spacer(Modifier.width(8.dp))
                Text("Criar comunidade", fontWeight = FontWeight.SemiBold)
            }
            Spacer(Modifier.height(12.dp))
        }
        if (loading && list.isEmpty()) {
            Box(Modifier.fillMaxWidth().padding(24.dp), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = QinblyBrand.Accent) }
        } else if (list.isEmpty()) {
            Text(
                if (selected == "Minhas") "Você ainda não participa de comunidades." else "Ainda não há comunidades por aqui.",
                color = RemoteAppearance.screenSecondaryTextColor
            )
            Spacer(Modifier.height(8.dp))
            QinblyAccentText(if (selected == "Minhas") "Crie a sua ou descubra outras para participar." else "Seja a primeira pessoa a criar uma.",
                modifier = Modifier.clickable { if (selected == "Minhas") selected = "Descobrir" else if (requireLogin() != null) showCreate = true })
        } else {
            LazyColumn(Modifier.fillMaxSize()) {
                items(list, key = { it.id }) { c ->
                    Row(Modifier.fillMaxWidth().clickable { openId = c.id }.padding(vertical = 10.dp), verticalAlignment = Alignment.CenterVertically) {
                        QinblyCommunityAvatar(c.name, 48.dp, c.avatarUrl)
                        Column(Modifier.weight(1f).padding(horizontal = 12.dp)) {
                            Text(c.name, color = RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                            if (c.description.isNotBlank()) Text(c.description, color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodySmall, maxLines = 2, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                            Text(if (c.members == 1) "1 membro" else "${c.members} membros", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelSmall)
                        }
                        if (c.isOwner) {
                            QinblyAccentText("Sua", style = MaterialTheme.typography.labelMedium)
                        } else if (c.joined) {
                            OutlinedButton(onClick = { toggleJoin(c) }) { Text("Participando", color = RemoteAppearance.screenSecondaryTextColor) }
                        } else if (c.pending) {
                            OutlinedButton(onClick = { toggleJoin(c) }) { Text("Pedido enviado", color = RemoteAppearance.screenSecondaryTextColor) }
                        } else {
                            QinblyGradientButton(onClick = { toggleJoin(c) }, colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)) { Text(if (c.joinMode == "approval") "Pedir" else "Entrar") }
                        }
                    }
                    HorizontalDivider(color = RemoteAppearance.screenSecondaryTextColor.copy(alpha = 0.15f))
                }
            }
        }
    }

    if (showCreate) {
        QinblyCreateCommunityDialog(
            onDismiss = { showCreate = false },
            onCreate = { name, description, emoji, done ->
                val token = prefs.getString("token", null)
                if (token.isNullOrBlank()) { done("Entre na sua conta para criar uma comunidade."); return@QinblyCreateCommunityDialog }
                Thread {
                    try {
                        val created = QinblyApi.createCommunity(token, name, description, emoji)
                        mainHandler.post {
                            done(null); showCreate = false
                            QinblyCache.communities.clear()
                            selected = "Minhas"; reload++
                            openId = created.id
                            onNotice("Comunidade criada.")
                        }
                    } catch (e: Exception) {
                        mainHandler.post { done(e.message ?: "Não foi possível criar a comunidade. Confira se o servidor e o banco foram atualizados.") }
                    }
                }.start()
            }
        )
    }
    openId?.let { id ->
        QinblyCommunityDialog(
            communityId = id,
            onNotice = onNotice,
            onChanged = { QinblyCache.communities.clear(); reload++ },
            onDismiss = { openId = null }
        )
    }
}

@Composable
private fun QinblyCreateCommunityDialog(onDismiss: () -> Unit, onCreate: (String, String, String, (String?) -> Unit) -> Unit) {
    var errorText by remember { mutableStateOf<String?>(null) }
    var name by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    val emoji = "👥"
    var sending by remember { mutableStateOf(false) }
    val photoContext = androidx.compose.ui.platform.LocalContext.current
    var photoBitmap by remember { mutableStateOf<android.graphics.Bitmap?>(null) }
    val photoPicker = rememberQinblyPhotoLauncher { uri ->
        if (uri != null) photoBitmap = runCatching { photoContext.contentResolver.openInputStream(uri)?.use { android.graphics.BitmapFactory.decodeStream(it) }?.let { qinblyUpright(photoContext, uri, it) } }.getOrNull()
    }
    BackHandler(enabled = !sending) { onDismiss() }
    QinblyDialog(
        onDismissRequest = { if (!sending) onDismiss() },
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false, dismissOnClickOutside = false),
        lift = true
    ) {
        Surface(Modifier.fillMaxSize(), color = QiblyTheme.background) {
            Column(Modifier.fillMaxSize().statusBarsPadding().imePadding().padding(horizontal = 16.dp)) {
                Row(Modifier.fillMaxWidth().padding(vertical = 6.dp), verticalAlignment = Alignment.CenterVertically) {
                    IconButton(onClick = { if (!sending) onDismiss() }) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text) }
                    Text("Nova comunidade", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 20.sp)
                }
                Column(Modifier.weight(1f).verticalScroll(rememberScrollState()), horizontalAlignment = Alignment.CenterHorizontally) {
                    Spacer(Modifier.height(14.dp))
                    Box(Modifier.size(112.dp).clickable { photoPicker.launch("image/*") }, contentAlignment = Alignment.Center) {
                        Box(Modifier.fillMaxSize().clip(CircleShape).background(qinblyAccentBrush(0.10f)).border(1.5.dp, qinblyAccentBrush(), CircleShape), contentAlignment = Alignment.Center) {
                            val bmp = photoBitmap
                            if (bmp != null) androidx.compose.foundation.Image(bmp.asImageBitmap(), contentDescription = "Foto da comunidade", contentScale = androidx.compose.ui.layout.ContentScale.Crop, modifier = Modifier.fillMaxSize())
                            else QinblyAccentIcon(Icons.Outlined.CameraAlt, contentDescription = null, modifier = Modifier.size(40.dp))
                        }
                        Box(Modifier.align(Alignment.BottomEnd).size(32.dp).clip(CircleShape).background(qinblyAccentBrush()).border(2.dp, QiblyTheme.background, CircleShape), contentAlignment = Alignment.Center) {
                            Icon(Icons.Default.Add, contentDescription = null, tint = Color.White, modifier = Modifier.size(18.dp))
                        }
                    }
                    QinblyAccentText(if (photoBitmap == null) "Adicionar foto (opcional)" else "Trocar foto", fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(top = 8.dp, bottom = 14.dp))
                    Text("NOME", color = QiblyTheme.secondary, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.SemiBold, modifier = Modifier.fillMaxWidth().padding(bottom = 4.dp))
                    OutlinedTextField(
                        value = name, onValueChange = { name = it.take(40) }, singleLine = true,
                        placeholder = { Text("Ex.: Amantes de Música", color = QiblyTheme.secondary) },
                        supportingText = { Text("${name.length}/40", modifier = Modifier.fillMaxWidth(), textAlign = androidx.compose.ui.text.style.TextAlign.End) },
                        shape = RoundedCornerShape(14.dp), modifier = Modifier.fillMaxWidth()
                    )
                    Text("DESCRIÇÃO", color = QiblyTheme.secondary, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.SemiBold, modifier = Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 4.dp))
                    OutlinedTextField(
                        value = description, onValueChange = { description = it.take(300) }, minLines = 3, maxLines = 5,
                        placeholder = { Text("Sobre o que é a comunidade?", color = QiblyTheme.secondary) },
                        shape = RoundedCornerShape(14.dp), modifier = Modifier.fillMaxWidth()
                    )
                    errorText?.let { Text(it, color = Color(0xFFD33B3B), style = MaterialTheme.typography.bodySmall, modifier = Modifier.fillMaxWidth().padding(top = 8.dp)) }
                    Text("Qualquer pessoa poderá encontrar e entrar na comunidade.", color = QiblyTheme.secondary, style = MaterialTheme.typography.bodySmall, modifier = Modifier.fillMaxWidth().padding(top = 12.dp))
                    Spacer(Modifier.height(16.dp))
                }
                QinblyGradientButton(
                    enabled = !sending && name.trim().length >= 3,
                    onClick = {
                        sending = true
                        errorText = null
                        onCreate(name.trim(), description.trim(), emoji) { err -> sending = false; errorText = err }
                    },
                    shape = RoundedCornerShape(16.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent),
                    modifier = Modifier.fillMaxWidth().height(52.dp).padding(bottom = 0.dp)
                ) { Text(if (sending) "Criando..." else "Criar comunidade", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 16.sp) }
                Spacer(Modifier.height(12.dp))
            }
        }
    }
}

private fun qinblyDayLabel(createdAt: String): String {
    val d = runCatching { java.time.Instant.parse(createdAt).atZone(java.time.ZoneId.systemDefault()).toLocalDate() }.getOrNull() ?: return ""
    val today = java.time.LocalDate.now()
    return when (d) {
        today -> "Hoje"
        today.minusDays(1) -> "Ontem"
        else -> d.format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy"))
    }
}

private fun qinblyClockLabel(createdAt: String): String =
    runCatching { java.time.Instant.parse(createdAt).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("HH:mm")) }.getOrDefault("")

private fun qinblyNameColor(username: String): Color {
    val palette = listOf(Color(0xFFD9480F), Color(0xFF7C3AED), Color(0xFF0E9F6E), Color(0xFF0B7285), Color(0xFFC2255C), Color(0xFF5F3DC4), Color(0xFF2B8A3E), Color(0xFFE67700))
    return palette[(username.hashCode() and 0x7fffffff) % palette.size]
}

/** Foto da comunidade; enquanto não houver foto, círculo azul com a letra inicial do nome. */
/** Tela "Editar comunidade": abre na hora com os dados que o app já tem; só o Salvar fala com o servidor. */
@Composable
private fun QinblyEditCommunityScreen(
    community: QinblyApi.CommunitySummary,
    onBack: () -> Unit,
    onSave: (org.json.JSONObject, Uri?) -> Unit
) {
    var name by remember { mutableStateOf(community.name) }
    var description by remember { mutableStateOf(community.description) }
    var joinMode by remember { mutableStateOf(community.joinMode) }
    var writeMode by remember { mutableStateOf(community.writeMode) }
    var rules by remember { mutableStateOf(community.rules) }
    var showRulesField by remember { mutableStateOf(false) }
    var photoUri by remember { mutableStateOf<Uri?>(null) }
    val photoPicker = rememberQinblyPhotoLauncher { uri -> if (uri != null) photoUri = uri }
    val valid = name.trim().length >= 3
    @Composable
    fun ChoiceCard(title: String, subtitle: String, icon: androidx.compose.ui.graphics.vector.ImageVector, selected: Boolean, last: Boolean, onClick: () -> Unit) {
        Column {
            Row(Modifier.fillMaxWidth().clickable { onClick() }.padding(horizontal = 12.dp, vertical = 11.dp), verticalAlignment = Alignment.CenterVertically) {
                Box(Modifier.size(34.dp).clip(RoundedCornerShape(10.dp)).background(if (selected) QinblyBrand.Accent.copy(alpha = 0.18f) else QiblyTheme.soft), contentAlignment = Alignment.Center) {
                    Icon(icon, contentDescription = null, tint = if (selected) QinblyBrand.Accent else QiblyTheme.secondary, modifier = Modifier.size(19.dp))
                }
                Column(Modifier.weight(1f).padding(horizontal = 12.dp)) {
                    Text(title, color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 15.sp)
                    Text(subtitle, color = QiblyTheme.secondary, fontSize = 12.sp)
                }
                if (selected) Box(Modifier.size(22.dp).clip(CircleShape).background(qinblyAccentBrush()), contentAlignment = Alignment.Center) { Icon(Icons.Default.Check, contentDescription = "Selecionado", tint = Color.White, modifier = Modifier.size(15.dp)) }
                else Box(Modifier.size(22.dp).clip(CircleShape).border(1.5.dp, QiblyTheme.border, CircleShape))
            }
            if (!last) HorizontalDivider(color = QiblyTheme.border)
        }
    }
    Column(Modifier.fillMaxSize().statusBarsPadding().imePadding()) {
        Row(Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 6.dp), verticalAlignment = Alignment.CenterVertically) {
            IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text) }
            Text("Editar comunidade", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 18.sp)
        }
        Column(Modifier.weight(1f).verticalScroll(rememberScrollState()).padding(horizontal = 16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
            Spacer(Modifier.height(8.dp))
            Box(Modifier.size(96.dp).clickable { photoPicker.launch("image/*") }, contentAlignment = Alignment.Center) {
                Box(Modifier.fillMaxSize().clip(CircleShape).background(qinblyAccentBrush()), contentAlignment = Alignment.Center) {
                    if (photoUri != null) AsyncImage(model = photoUri, contentDescription = "Nova foto", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
                    else if (community.avatarUrl.isNotBlank()) AsyncImage(model = community.avatarUrl, contentDescription = "Foto da comunidade", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
                    else Text(name.trim().take(1).uppercase().ifBlank { "Q" }, color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 38.sp)
                }
                Box(Modifier.align(Alignment.BottomEnd).size(32.dp).clip(CircleShape).background(qinblyAccentBrush()).border(2.dp, QiblyTheme.background, CircleShape), contentAlignment = Alignment.Center) {
                    Icon(Icons.Outlined.PhotoCamera, contentDescription = null, tint = Color.White, modifier = Modifier.size(17.dp))
                }
            }
            QinblyAccentText("Trocar foto", fontSize = 14.sp, modifier = Modifier.padding(top = 8.dp).clickable { photoPicker.launch("image/*") })
            Text("NOME", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.fillMaxWidth().padding(top = 16.dp, bottom = 4.dp))
            OutlinedTextField(value = name, onValueChange = { name = it.take(40) }, singleLine = true, shape = RoundedCornerShape(14.dp), modifier = Modifier.fillMaxWidth(),
                supportingText = { Text("${name.length}/40", modifier = Modifier.fillMaxWidth(), textAlign = androidx.compose.ui.text.style.TextAlign.End) })
            Text("DESCRIÇÃO", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 4.dp))
            OutlinedTextField(value = description, onValueChange = { description = it.take(300) }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp), modifier = Modifier.fillMaxWidth(),
                placeholder = { Text("Sobre o que é a comunidade?") })
            Text("QUEM PODE ENTRAR", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.fillMaxWidth().padding(top = 18.dp, bottom = 6.dp))
            Column(Modifier.fillMaxWidth().clip(RoundedCornerShape(16.dp)).background(QiblyTheme.card)) {
                ChoiceCard("Qualquer um", "Entra direto", Icons.Outlined.Public, joinMode == "open", false) { joinMode = "open" }
                ChoiceCard("Com aprovação", "Você aceita cada pedido", Icons.Outlined.Lock, joinMode == "approval", true) { joinMode = "approval" }
            }
            Text("QUEM PODE ESCREVER", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.fillMaxWidth().padding(top = 18.dp, bottom = 6.dp))
            Column(Modifier.fillMaxWidth().clip(RoundedCornerShape(16.dp)).background(QiblyTheme.card)) {
                ChoiceCard("Todos", "Todo membro escreve", Icons.Outlined.Groups, writeMode == "all", false) { writeMode = "all" }
                ChoiceCard("Só admins", "Os outros só leem", Icons.Outlined.Shield, writeMode == "admins", true) { writeMode = "admins" }
            }
            Column(Modifier.fillMaxWidth().padding(top = 18.dp).clip(RoundedCornerShape(16.dp)).background(QiblyTheme.card)) {
                Row(Modifier.fillMaxWidth().clickable { showRulesField = !showRulesField }.padding(horizontal = 12.dp, vertical = 14.dp), verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Outlined.Description, contentDescription = null, tint = QiblyTheme.secondary)
                    Text("Regras da comunidade", color = QiblyTheme.text, modifier = Modifier.weight(1f).padding(start = 12.dp), fontSize = 15.sp)
                    Icon(if (showRulesField) Icons.Default.KeyboardArrowDown else Icons.Default.KeyboardArrowRight, contentDescription = null, tint = QiblyTheme.secondary)
                }
                if (showRulesField) OutlinedTextField(value = rules, onValueChange = { rules = it.take(2000) }, minLines = 4, maxLines = 8, shape = RoundedCornerShape(14.dp),
                    modifier = Modifier.fillMaxWidth().padding(start = 12.dp, end = 12.dp, bottom = 12.dp), placeholder = { Text("Escreva as regras para os membros") })
            }
            Spacer(Modifier.height(16.dp))
        }
        QinblyGradientButton(
            onClick = {
                val f = org.json.JSONObject().put("name", name.trim()).put("description", description.trim()).put("joinMode", joinMode).put("writeMode", writeMode).put("rules", rules.trim())
                onSave(f, photoUri)
            },
            enabled = valid,
            shape = RoundedCornerShape(16.dp),
            colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent),
            modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp).height(52.dp)
        ) { Text("Salvar", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 16.sp) }
        Spacer(Modifier.height(12.dp))
    }
}

/** Linha de membro: foto, nome, etiqueta Dono/Admin e três pontinhos; clicar e segurar abre o mesmo menu. */
@OptIn(androidx.compose.foundation.ExperimentalFoundationApi::class)
@Composable
private fun QinblyMemberRow(
    m: QinblyApi.CommunityMember, canManage: Boolean, menuOpen: Boolean, viewerIsOwner: Boolean,
    onOpenMenu: (QinblyApi.CommunityMember) -> Unit, onCloseMenu: () -> Unit,
    onProfile: (QinblyApi.CommunityMember) -> Unit, onAction: (QinblyApi.CommunityMember, String) -> Unit
) {
    Row(
        Modifier.fillMaxWidth()
            .background(if (menuOpen) QiblyTheme.soft else Color.Transparent)
            .combinedClickable(onClick = { onProfile(m) }, onLongClick = { if (canManage) onOpenMenu(m) })
            .padding(start = 16.dp, end = if (canManage) 4.dp else 16.dp, top = 4.dp, bottom = 4.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        QiblyAccountAvatar(m.username, m.avatarUrl, 40.dp) { onProfile(m) }
        Text(m.displayName.ifBlank { "@" + m.username }, color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(start = 12.dp, end = 8.dp).weight(1f), maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
        val badge = when (m.role) { "owner" -> "Dono"; "admin" -> "Admin"; else -> "" }
        if (badge.isNotEmpty()) QinblyAccentText(badge, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.border(1.dp, qinblyAccentBrush(), RoundedCornerShape(8.dp)).padding(horizontal = 7.dp, vertical = 2.dp))
        if (canManage) Box {
            IconButton(onClick = { onOpenMenu(m) }) { Icon(Icons.Default.MoreVert, contentDescription = "Opções", tint = QiblyTheme.secondary) }
            DropdownMenu(expanded = menuOpen, onDismissRequest = onCloseMenu) {
                DropdownMenuItem(text = { Text("Ver perfil") }, leadingIcon = { Icon(Icons.Outlined.Person, null) }, onClick = { onCloseMenu(); onProfile(m) })
                if (viewerIsOwner && m.role == "member") DropdownMenuItem(text = { Text("Tornar admin") }, leadingIcon = { Icon(Icons.Outlined.Shield, null) }, onClick = { onCloseMenu(); onAction(m, "admin") })
                if (viewerIsOwner && m.role == "admin") DropdownMenuItem(text = { Text("Remover de admin") }, leadingIcon = { Icon(Icons.Outlined.Shield, null) }, onClick = { onCloseMenu(); onAction(m, "member") })
                DropdownMenuItem(text = { Text("Remover da comunidade", color = Color(0xFFD92D20)) }, leadingIcon = { Icon(Icons.Outlined.PersonRemove, null, tint = Color(0xFFD92D20)) }, onClick = { onCloseMenu(); onAction(m, "remove") })
            }
        }
    }
}

@Composable
private fun QinblyCommunityAvatar(name: String, diameter: Dp, imageUrl: String = "") {
    Box(Modifier.size(diameter).clip(CircleShape).background(qinblyAccentBrush()), contentAlignment = Alignment.Center) {
        if (imageUrl.isNotBlank()) AsyncImage(model = imageUrl, contentDescription = "Foto da comunidade", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
        else Text(name.trim().take(1).uppercase().ifBlank { "Q" }, color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = (diameter.value * 0.42f).sp)
    }
}

@Composable
private fun QinblyCommunityDialog(communityId: String, onNotice: (String) -> Unit, onChanged: () -> Unit, onDismiss: () -> Unit) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    val mainHandler = remember { android.os.Handler(android.os.Looper.getMainLooper()) }
    var community by remember { mutableStateOf<QinblyApi.CommunitySummary?>(null) }
    var posts by remember { mutableStateOf<List<QinblyApi.CommunityPost>>(emptyList()) }
    var loading by remember { mutableStateOf(true) }
    var text by remember { mutableStateOf("") }
    var sending by remember { mutableStateOf(false) }
    var confirmDelete by remember { mutableStateOf(false) }
    var confirmLeave by remember { mutableStateOf(false) }
    var confirmClear by remember { mutableStateOf(false) }
    var showReport by remember { mutableStateOf(false) }
    var showMenu by remember { mutableStateOf(false) }
    var showInfo by remember { mutableStateOf(false) }
    var showEdit by remember { mutableStateOf(false) }
    var showInfoMenu by remember { mutableStateOf(false) }
    var showRules by remember { mutableStateOf(false) }
    var memberTarget by remember { mutableStateOf<QinblyApi.CommunityMember?>(null) }
    var memberSearch by remember { mutableStateOf("") }
    var showEmoji by remember { mutableStateOf(false) }
    BackHandler(enabled = showEmoji) { showEmoji = false }
    val cKb = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current
    val cFocus = androidx.compose.ui.platform.LocalFocusManager.current
    var showAttach by remember { mutableStateOf(false) }
    var refresh by remember { mutableIntStateOf(0) }
    var mutedFlag by remember { mutableStateOf(prefs.getBoolean("community_muted_$communityId", false)) }
    var clearedAt by remember { mutableStateOf(prefs.getString("community_cleared_$communityId", "") ?: "") }
    val listState = androidx.compose.foundation.lazy.rememberLazyListState()

    // A conversa atualiza sozinha a cada poucos segundos.
    LaunchedEffect(communityId) { while (true) { kotlinx.coroutines.delay(6_000L); refresh++ } }
    LaunchedEffect(communityId, refresh) {
        val token = prefs.getString("token", null)
        Thread {
            try {
                val (c, p) = QinblyApi.getCommunity(communityId, token)
                mainHandler.post { community = c; posts = p; loading = false }
            } catch (e: Exception) {
                mainHandler.post { loading = false; if (community == null) onNotice(e.message ?: "Não foi possível abrir a comunidade.") }
            }
        }.start()
    }
    val chat = remember(posts, clearedAt) { posts.sortedBy { it.createdAt }.filter { clearedAt.isBlank() || it.createdAt > clearedAt } }
    LaunchedEffect(chat.size) { if (chat.isNotEmpty()) listState.scrollToItem(chat.lastIndex + 0) }
    QinblyKeepChatAtBottom(listState, chat.lastIndex)

    var recordingVoiceC by remember { mutableStateOf(false) }
    fun sendCWith(action: (String, String) -> Unit) {
        val token = prefs.getString("token", null)
        val cid = community?.id
        if (token.isNullOrBlank() || cid == null) { onNotice("Entre na sua conta para enviar mensagens."); return }
        if (sending) return
        sending = true
        Thread {
            try {
                action(token, cid)
                mainHandler.post { sending = false; showAttach = false; refresh++ }
            } catch (e: Exception) { mainHandler.post { sending = false; onNotice(e.message ?: "Não foi possível enviar.") } }
        }.start()
    }
    var showCPoll by remember { mutableStateOf(false) }
    var showCStickerCreator by remember { mutableStateOf(false) }
    var cStickerRefresh by remember { mutableIntStateOf(0) }
    val cDocPicker = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        if (uri != null) sendCWith { token, cid -> QinblyApi.sendCommunityFile(context, token, cid, uri) }
    }
    // Câmera padrão do app (a mesma do Criar), em vez da câmera do celular.
    var showCAppCamera by remember { mutableStateOf(false) }
    // Foto da galeria passa pelo MESMO editor da câmera (padrão do app) antes de enviar.
    val cGalleryPicker = rememberQinblyPhotoLauncher(onCamera = { showCAppCamera = true }) { uri ->
        if (uri != null) { qinblySetPickedMedia(uri, false); showCAppCamera = true }
    }
    var pendingCPhoto by remember { mutableStateOf<java.io.File?>(null) }
    fun launchCCamera() { showCAppCamera = true }
    if (showCAppCamera) QinblyCameraCapture(
        onResult = { u ->
            showCAppCamera = false
            sendCWith { token, cid -> try { QinblyApi.sendCommunityImage(context, token, cid, u) } finally { u.path?.let { java.io.File(it).delete() } } }
        },
        onDismiss = { showCAppCamera = false }
    )
    val cCameraPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) launchCCamera() else onNotice("Permita a câmera para tirar a foto.")
    }
    fun cCameraShot() {
        if (androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.CAMERA) == android.content.pm.PackageManager.PERMISSION_GRANTED) launchCCamera()
        else cCameraPermission.launch(android.Manifest.permission.CAMERA)
    }
    val cContactPicker = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        val data = result.data?.data ?: return@rememberLauncherForActivityResult
        try {
            context.contentResolver.query(data, arrayOf(android.provider.ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME, android.provider.ContactsContract.CommonDataKinds.Phone.NUMBER), null, null, null)?.use { cur ->
                if (cur.moveToFirst()) {
                    val who = cur.getString(0).orEmpty()
                    val number = cur.getString(1).orEmpty()
                    sendCWith { token, cid -> QinblyApi.addCommunityPost(token, cid, "Contato: $who\n$number") }
                }
            }
        } catch (_: Exception) { onNotice("Não foi possível ler o contato escolhido.") }
    }
    fun sendCLocation() {
        try {
            val lm = context.getSystemService(android.content.Context.LOCATION_SERVICE) as android.location.LocationManager
            val best = lm.getProviders(true).mapNotNull { try { lm.getLastKnownLocation(it) } catch (_: SecurityException) { null } }.maxByOrNull { it.time }
            if (best == null) onNotice("Não consegui pegar sua localização. Ligue o GPS e tente de novo.")
            else sendCWith { token, cid -> QinblyApi.addCommunityPost(token, cid, "Minha localização:\nhttps://maps.google.com/?q=" + best.latitude + "," + best.longitude) }
        } catch (_: SecurityException) { onNotice("Permita a localização para enviar onde você está.") }
    }
    val cLocationPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { res ->
        if (res.values.any { it }) sendCLocation() else onNotice("Permita a localização para enviar onde você está.")
    }
    val cMicPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) recordingVoiceC = true else onNotice("Permita o microfone para gravar a mensagem de voz.")
    }
    fun startCVoice() {
        if (androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.RECORD_AUDIO) == android.content.pm.PackageManager.PERMISSION_GRANTED) recordingVoiceC = true
        else cMicPermission.launch(android.Manifest.permission.RECORD_AUDIO)
    }
    fun onCAttach(label: String) {
        when (label) {
            "Galeria" -> cGalleryPicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))
            "Contato" -> cContactPicker.launch(android.content.Intent(android.content.Intent.ACTION_PICK, android.provider.ContactsContract.CommonDataKinds.Phone.CONTENT_URI))
            "Localização" -> {
                val granted = androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.ACCESS_COARSE_LOCATION) == android.content.pm.PackageManager.PERMISSION_GRANTED ||
                    androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.ACCESS_FINE_LOCATION) == android.content.pm.PackageManager.PERMISSION_GRANTED
                if (granted) sendCLocation() else cLocationPermission.launch(arrayOf(android.Manifest.permission.ACCESS_COARSE_LOCATION, android.Manifest.permission.ACCESS_FINE_LOCATION))
            }
            "Áudio" -> startCVoice()
            "Documento" -> cDocPicker.launch(arrayOf("application/pdf", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/vnd.ms-excel", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/vnd.ms-powerpoint", "application/vnd.openxmlformats-officedocument.presentationml.presentation", "text/plain", "text/csv", "application/zip"))
            "Enquete" -> showCPoll = true
            else -> onNotice("$label: ainda não está disponível.")
        }
    }
    if (showCStickerCreator) {
        QinblyStickerCreateDialog(QinblyBrand.Accent, onNotice, onDismiss = { showCStickerCreator = false }, onCreated = { cStickerRefresh++ })
    }
    if (showCPoll) {
        QinblyPollCreateDialog(QinblyBrand.Accent, onDismiss = { showCPoll = false }) { question, options ->
            showCPoll = false
            sendCWith { token, cid -> QinblyApi.sendCommunityPoll(token, cid, question, options) }
        }
    }
    fun voteC(poll: QinblyApi.ChatPoll, index: Int) {
        val token = prefs.getString("token", null) ?: return
        Thread {
            try {
                val r = QinblyApi.voteChatPoll(token, poll.id, index)
                mainHandler.post { posts = posts.map { q -> if (q.poll?.id == poll.id) q.copy(poll = q.poll?.copy(votes = r.votes, myVote = r.myVote)) else q } }
            } catch (e: Exception) { mainHandler.post { onNotice(e.message ?: "Não foi possível votar.") } }
        }.start()
    }

    fun sendPost(c: QinblyApi.CommunitySummary) {
        val token = prefs.getString("token", null) ?: return
        val body = text.trim()
        if (body.isBlank() || sending) return
        sending = true
        Thread {
            try {
                QinblyApi.addCommunityPost(token, c.id, body)
                mainHandler.post { text = ""; sending = false; showEmoji = false; refresh++ }
            } catch (e: Exception) { mainHandler.post { sending = false; onNotice(e.message ?: "Não foi possível enviar.") } }
        }.start()
    }
    fun toggleJoin(c: QinblyApi.CommunitySummary) {
        val token = prefs.getString("token", null)
        if (token.isNullOrBlank()) { onNotice("Entre na sua conta para participar de comunidades."); return }
        Thread {
            try {
                val (joined, members, pending) = QinblyApi.toggleCommunityJoin(token, c.id)
                mainHandler.post { community = c.copy(joined = joined, members = members, pending = pending); if (pending) onNotice("Pedido enviado. O dono precisa aprovar."); onChanged() }
            } catch (e: Exception) { mainHandler.post { onNotice(e.message ?: "Não foi possível atualizar.") } }
        }.start()
    }
    fun shareCommunity(c: QinblyApi.CommunitySummary) {
        try {
            val share = Intent(Intent.ACTION_SEND).apply { type = "text/plain"; putExtra(Intent.EXTRA_TEXT, "Entre na comunidade ${c.name} no ${QinblyBrand.Name}!") }
            context.startActivity(Intent.createChooser(share, "Compartilhar comunidade"))
        } catch (_: Exception) { onNotice("Não foi possível abrir o compartilhamento neste aparelho.") }
    }
    fun memberAction(m: QinblyApi.CommunityMember, action: String) {
        val token = prefs.getString("token", null)
        if (token.isNullOrBlank()) { onNotice("Entre na sua conta."); return }
        Thread {
            try {
                QinblyApi.communityMemberAction(token, communityId, m.userId, action)
                mainHandler.post { refresh++; onChanged() }
            } catch (e: Exception) { mainHandler.post { onNotice(e.message ?: "Não foi possível concluir.") } }
        }.start()
    }
    fun copyCommunityLink(c: QinblyApi.CommunitySummary) {
        try {
            val cm = context.getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
            cm.setPrimaryClip(android.content.ClipData.newPlainText("Link da comunidade", "https://qinbly.pages.dev/#/community/" + c.id))
            onNotice("Link copiado.")
        } catch (_: Exception) { onNotice("Não foi possível copiar o link.") }
    }
    BackHandler { if (showEdit) showEdit = false else if (showInfo) showInfo = false else onDismiss() }

    QinblyDialog(onDismissRequest = onDismiss, properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false, dismissOnClickOutside = false), lift = true) {
        Surface(Modifier.fillMaxSize(), color = QiblyTheme.background) {
            val c = community
            if (c == null) {
                Column(Modifier.fillMaxSize().statusBarsPadding().padding(16.dp)) {
                    IconButton(onClick = onDismiss) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text) }
                    if (loading) Box(Modifier.fillMaxWidth().padding(32.dp), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = QinblyBrand.Accent) }
                    else Text("Comunidade não encontrada.", color = QiblyTheme.secondary, modifier = Modifier.padding(16.dp))
                }
            } else if (showEdit) {
                QinblyEditCommunityScreen(
                    community = c,
                    onBack = { showEdit = false },
                    onSave = { fields, photoUri ->
                        showEdit = false
                        val token = prefs.getString("token", null)
                        if (token.isNullOrBlank()) { onNotice("Entre na sua conta."); return@QinblyEditCommunityScreen }
                        // Aparece na hora; o servidor confirma em seguida.
                        community = c.copy(
                            name = fields.optString("name", c.name), description = fields.optString("description", c.description),
                            joinMode = fields.optString("joinMode", c.joinMode), writeMode = fields.optString("writeMode", c.writeMode), rules = fields.optString("rules", c.rules)
                        )
                        Thread {
                            try {
                                val f = org.json.JSONObject(fields.toString())
                                if (photoUri != null) f.put("avatarFileId", QinblyApi.uploadCommunityPhoto(context, token, photoUri))
                                val updated = QinblyApi.updateCommunity(token, c.id, f)
                                mainHandler.post { community = updated.copy(memberList = c.memberList); onChanged(); onNotice("Comunidade salva.") }
                            } catch (e: Exception) { mainHandler.post { refresh++; onNotice(e.message ?: "Não foi possível salvar a comunidade.") } }
                        }.start()
                    }
                )
            } else if (showInfo) {
                Column(Modifier.fillMaxSize().statusBarsPadding()) {
                    Row(Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 6.dp), verticalAlignment = Alignment.CenterVertically) {
                        IconButton(onClick = { showInfo = false }) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text) }
                        Text("Dados da comunidade", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 18.sp, modifier = Modifier.weight(1f))
                        Box {
                            IconButton(onClick = { showInfoMenu = true }) { Icon(Icons.Default.MoreVert, contentDescription = "Mais opções", tint = QiblyTheme.text) }
                            DropdownMenu(expanded = showInfoMenu, onDismissRequest = { showInfoMenu = false }) {
                                if (c.isOwner) DropdownMenuItem(text = { Text("Editar comunidade") }, leadingIcon = { Icon(Icons.Outlined.Edit, null) }, onClick = { showInfoMenu = false; showEdit = true })
                                DropdownMenuItem(text = { Text("Copiar link") }, leadingIcon = { Icon(Icons.Outlined.Link, null) }, onClick = { showInfoMenu = false; copyCommunityLink(c) })
                                DropdownMenuItem(text = { Text("Regras") }, leadingIcon = { Icon(Icons.Outlined.Description, null) }, onClick = { showInfoMenu = false; showRules = true })
                                DropdownMenuItem(text = { Text("Denunciar") }, leadingIcon = { Icon(Icons.Outlined.Flag, null) }, onClick = { showInfoMenu = false; showReport = true })
                                if (c.isOwner) DropdownMenuItem(text = { Text("Excluir comunidade", color = Color(0xFFD92D20)) }, leadingIcon = { Icon(Icons.Outlined.DeleteOutline, null, tint = Color(0xFFD92D20)) }, onClick = { showInfoMenu = false; confirmDelete = true })
                                else if (c.joined) DropdownMenuItem(text = { Text("Sair da comunidade", color = Color(0xFFD92D20)) }, leadingIcon = { Icon(Icons.Outlined.Logout, null, tint = Color(0xFFD92D20)) }, onClick = { showInfoMenu = false; confirmLeave = true })
                            }
                        }
                    }
                    androidx.compose.foundation.lazy.LazyColumn(Modifier.fillMaxSize(), contentPadding = PaddingValues(bottom = 24.dp)) {
                        item {
                            Column(Modifier.fillMaxWidth().padding(vertical = 10.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                                QinblyCommunityAvatar(c.name, 96.dp, c.avatarUrl)
                                Text(c.name, color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 20.sp, modifier = Modifier.padding(top = 10.dp))
                                Text("Comunidade · " + (if (c.members == 1) "1 membro" else "${c.members} membros"), color = QiblyTheme.secondary, fontSize = 14.sp)
                                Row(Modifier.padding(top = 14.dp), horizontalArrangement = Arrangement.spacedBy(22.dp)) {
                                    listOf(
                                        Triple(if (mutedFlag) "Reativar" else "Silenciar", if (mutedFlag) Icons.Outlined.NotificationsNone else Icons.Outlined.NotificationsOff, 0),
                                        Triple("Compartilhar", Icons.Outlined.Share, 1)
                                    ).forEach { (label, icon, kind) ->
                                        Column(
                                            Modifier.clip(RoundedCornerShape(14.dp)).clickable {
                                                if (kind == 0) { mutedFlag = !mutedFlag; prefs.edit().putBoolean("community_muted_$communityId", mutedFlag).apply() }
                                                else shareCommunity(c)
                                            }.padding(6.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(4.dp)
                                        ) {
                                            Box(Modifier.size(46.dp).clip(RoundedCornerShape(14.dp)).background(QiblyTheme.soft), contentAlignment = Alignment.Center) {
                                                Icon(icon, contentDescription = null, tint = QiblyTheme.text, modifier = Modifier.size(24.dp))
                                            }
                                            Text(label, color = QiblyTheme.text, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                                        }
                                    }
                                }
                            }
                        }
                        if (c.description.isNotBlank()) item {
                            Text("DESCRIÇÃO", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(start = 16.dp, top = 14.dp, bottom = 4.dp))
                            Text(c.description, color = QiblyTheme.text, modifier = Modifier.padding(horizontal = 16.dp))
                        }
                        val myUsername = prefs.getString("username", "").orEmpty()
                        item {
                            OutlinedTextField(
                                value = memberSearch, onValueChange = { memberSearch = it }, singleLine = true,
                                placeholder = { Text("Buscar membro", color = QiblyTheme.secondary) },
                                leadingIcon = { Icon(Icons.Outlined.Search, contentDescription = null, tint = QiblyTheme.secondary) },
                                shape = RoundedCornerShape(12.dp),
                                modifier = Modifier.fillMaxWidth().padding(start = 16.dp, end = 16.dp, top = 14.dp)
                            )
                        }
                        val pendingList = if (c.isAdmin) c.memberList.filter { it.role == "pending" } else emptyList()
                        if (pendingList.isNotEmpty()) {
                            item { Text("PEDIDOS PARA ENTRAR · ${pendingList.size}", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(start = 16.dp, top = 18.dp, bottom = 4.dp)) }
                            items(pendingList, key = { "p" + it.userId }) { m ->
                                Row(Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                                    QiblyAccountAvatar(m.username, m.avatarUrl, 40.dp) { QinblyTagNav.profile = m.username }
                                    Text(m.displayName.ifBlank { "@" + m.username }, color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(start = 12.dp).weight(1f), maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                                    TextButton(onClick = { memberAction(m, "reject") }) { Text("Recusar", color = QiblyTheme.secondary) }
                                    QinblyGradientButton(onClick = { memberAction(m, "approve") }, colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)) { Text("Aceitar") }
                                }
                            }
                        }
                        val q = memberSearch.trim().lowercase()
                        val visible = c.memberList.filter { it.role != "pending" && (q.isEmpty() || it.username.lowercase().contains(q) || it.displayName.lowercase().contains(q)) }
                        val staff = visible.filter { it.role == "owner" || it.role == "admin" }.sortedBy { if (it.role == "owner") 0 else 1 }
                        val regular = visible.filter { it.role != "owner" && it.role != "admin" }
                        fun canManage(m: QinblyApi.CommunityMember) = c.isAdmin && m.role != "owner" && !m.username.equals(myUsername, true) && (c.isOwner || m.role == "member")
                        if (staff.isNotEmpty()) {
                            item { Text("ADMINISTRADORES · ${staff.size}", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(start = 16.dp, top = 18.dp, bottom = 4.dp)) }
                            items(staff, key = { "s" + it.userId }) { m ->
                                QinblyMemberRow(m, canManage(m), memberTarget?.userId == m.userId, c.isOwner, { memberTarget = it }, { memberTarget = null }, { QinblyTagNav.profile = it.username }, { mm, a -> memberAction(mm, a) })
                            }
                        }
                        if (regular.isNotEmpty()) {
                            item { Text("MEMBROS · ${regular.size}", color = QiblyTheme.secondary, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(start = 16.dp, top = 18.dp, bottom = 4.dp)) }
                            items(regular, key = { "m" + it.userId }) { m ->
                                QinblyMemberRow(m, canManage(m), memberTarget?.userId == m.userId, c.isOwner, { memberTarget = it }, { memberTarget = null }, { QinblyTagNav.profile = it.username }, { mm, a -> memberAction(mm, a) })
                            }
                        }
                        if (visible.isEmpty()) item { Text("Ninguém encontrado.", color = QiblyTheme.secondary, modifier = Modifier.padding(16.dp)) }
                    }
                }
            } else {
                Column(Modifier.fillMaxSize().statusBarsPadding().imePadding()) {
                    // Topo: voltar, foto, nome, membros, menu
                    Row(Modifier.fillMaxWidth().background(QiblyTheme.card).padding(horizontal = 4.dp, vertical = 6.dp), verticalAlignment = Alignment.CenterVertically) {
                        IconButton(onClick = onDismiss) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text) }
                        Row(Modifier.weight(1f).clip(RoundedCornerShape(12.dp)).clickable { showInfo = true }.padding(vertical = 2.dp), verticalAlignment = Alignment.CenterVertically) {
                            QinblyCommunityAvatar(c.name, 40.dp, c.avatarUrl)
                            Column(Modifier.padding(start = 10.dp)) {
                                Text(c.name, color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 16.sp, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                                Text(if (c.members == 1) "1 membro" else "${c.members} membros", color = QiblyTheme.secondary, fontSize = 12.sp)
                            }
                        }
                        Box {
                            IconButton(onClick = { showMenu = true }) { Icon(Icons.Default.MoreVert, contentDescription = "Menu", tint = QiblyTheme.text) }
                            DropdownMenu(expanded = showMenu, onDismissRequest = { showMenu = false }) {
                                DropdownMenuItem(text = { Text("Dados da comunidade") }, leadingIcon = { Icon(Icons.Outlined.Info, null) }, onClick = { showMenu = false; showInfo = true })
                                DropdownMenuItem(text = { Text(if (mutedFlag) "Reativar avisos" else "Silenciar avisos") }, leadingIcon = { Icon(if (mutedFlag) Icons.Outlined.NotificationsNone else Icons.Outlined.NotificationsOff, null) }, onClick = { showMenu = false; mutedFlag = !mutedFlag; prefs.edit().putBoolean("community_muted_$communityId", mutedFlag).apply() })
                                DropdownMenuItem(text = { Text("Limpar conversa") }, leadingIcon = { Icon(Icons.Outlined.DeleteOutline, null) }, onClick = { showMenu = false; confirmClear = true })
                                DropdownMenuItem(text = { Text("Denunciar comunidade") }, leadingIcon = { Icon(Icons.Outlined.Flag, null) }, onClick = { showMenu = false; showReport = true })
                                if (c.isOwner) DropdownMenuItem(text = { Text("Excluir comunidade", color = Color(0xFFD92D20)) }, leadingIcon = { Icon(Icons.Outlined.DeleteOutline, null, tint = Color(0xFFD92D20)) }, onClick = { showMenu = false; confirmDelete = true })
                                else if (c.joined) DropdownMenuItem(text = { Text("Sair da comunidade", color = Color(0xFFD92D20)) }, leadingIcon = { Icon(Icons.Outlined.Logout, null, tint = Color(0xFFD92D20)) }, onClick = { showMenu = false; confirmLeave = true })
                            }
                        }
                    }
                    HorizontalDivider(color = QiblyTheme.border)
                    // Mensagem fixada: a descrição da comunidade
                    if (c.description.isNotBlank()) Row(Modifier.fillMaxWidth().background((if (QiblyTheme.dark) Color.Transparent else QinblyBrand.Accent.copy(alpha = 0.08f))).clickable { showInfo = true }.padding(horizontal = 14.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                        QinblyAccentIcon(Icons.Outlined.PushPin, contentDescription = null, modifier = Modifier.size(16.dp))
                        Text(c.description, color = QiblyTheme.text, fontSize = 12.sp, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, modifier = Modifier.padding(start = 8.dp))
                    }
                    // Conversa
                    Box(Modifier.weight(1f).fillMaxWidth().background(if (QiblyTheme.dark) Color(0xFF0D1119) else Color(0xFFEEF2F8))) {
                        if (chat.isEmpty()) {
                            Text(if (c.joined || c.isOwner) "Ainda não há mensagens. Comece a conversa!" else "Entre na comunidade para ver e enviar mensagens.", color = QiblyTheme.secondary, modifier = Modifier.align(Alignment.Center).padding(24.dp), textAlign = androidx.compose.ui.text.style.TextAlign.Center)
                        } else {
                            androidx.compose.foundation.lazy.LazyColumn(Modifier.fillMaxSize(), state = listState, contentPadding = PaddingValues(horizontal = 10.dp, vertical = 8.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                items(chat.size, key = { chat[it].id }) { idx ->
                                    val p = chat[idx]
                                    val day = qinblyDayLabel(p.createdAt)
                                    if (idx == 0 || day != qinblyDayLabel(chat[idx - 1].createdAt)) {
                                        Box(Modifier.fillMaxWidth().padding(vertical = 4.dp), contentAlignment = Alignment.Center) {
                                            Text(day, color = QiblyTheme.secondary, fontSize = 11.sp, modifier = Modifier.clip(RoundedCornerShape(10.dp)).background(QiblyTheme.card).padding(horizontal = 10.dp, vertical = 3.dp))
                                        }
                                    }
                                    val mine = p.mine
                                    Row(Modifier.fillMaxWidth(), horizontalArrangement = if (mine) Arrangement.End else Arrangement.Start, verticalAlignment = Alignment.Bottom) {
                                        if (!mine) { QiblyAccountAvatar(p.username, p.avatarUrl, 28.dp) { QinblyTagNav.profile = p.username }; Spacer(Modifier.width(6.dp)) }
                                        Column(
                                            Modifier.widthIn(max = 280.dp)
                                                .clip(RoundedCornerShape(topStart = if (mine) 14.dp else 4.dp, topEnd = if (mine) 4.dp else 14.dp, bottomStart = 14.dp, bottomEnd = 14.dp))
                                                .background(if (p.stickerUrl.isNotBlank() || QinblyStickers.idOf(p.body) != null) Color.Transparent else if (mine) QinblyBrand.Accent.copy(alpha = if (QiblyTheme.dark) 0.35f else 0.22f) else QiblyTheme.card)
                                                .padding(horizontal = 10.dp, vertical = 6.dp)
                                        ) {
                                            if (!mine) Text(p.displayName.ifBlank { p.username } + if (p.username == c.ownerUsername) " · dono" else "", color = qinblyNameColor(p.username), fontWeight = FontWeight.SemiBold, fontSize = 12.sp)
                                            val stickerId = QinblyStickers.idOf(p.body)
                                            if (p.poll != null) QinblyChatPollBubble(p.poll, QinblyBrand.Accent, QiblyTheme.text) { index -> voteC(p.poll, index) }
                                            else if (p.stickerUrl.isNotBlank()) AsyncImage(model = p.stickerUrl, contentDescription = "Figurinha", modifier = Modifier.size(120.dp))
                                            else if (p.fileUrl.isNotBlank()) QinblyFileBubble(p.fileUrl, p.fileName, QinblyBrand.Accent, QiblyTheme.text)
                                            else if (p.audioUrl.isNotBlank()) QinblyAudioBubble(p.audioUrl, p.audioSeconds, QinblyBrand.Accent, mine, QiblyTheme.text)
                                            else if (p.imageUrl.isNotBlank()) AsyncImage(model = p.imageUrl, contentDescription = "Foto enviada", modifier = Modifier.width(220.dp).heightIn(max = 320.dp).clip(RoundedCornerShape(12.dp)), contentScale = androidx.compose.ui.layout.ContentScale.Fit)
                                            else if (stickerId != null) QinblyStickerView(stickerId) else QinblyRichText(p.body, QiblyTheme.text)
                                            Row(Modifier.align(Alignment.End), verticalAlignment = Alignment.CenterVertically) {
                                                Text(qinblyClockLabel(p.createdAt), color = QiblyTheme.secondary, fontSize = 11.sp)
                                                if (mine || c.isOwner) Icon(Icons.Outlined.Delete, contentDescription = "Excluir mensagem", tint = QiblyTheme.secondary, modifier = Modifier.padding(start = 6.dp).size(14.dp).clickable {
                                                    val token = prefs.getString("token", null) ?: return@clickable
                                                    posts = posts.filterNot { it.id == p.id }
                                                    Thread {
                                                        try { QinblyApi.deleteCommunityPost(token, c.id, p.id) }
                                                        catch (e: Exception) { mainHandler.post { refresh++; onNotice(e.message ?: "Não foi possível excluir.") } }
                                                    }.start()
                                                })
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if ((c.joined || c.isOwner) && (c.writeMode != "admins" || c.isAdmin)) {
                        if (showAttach) {
                            val attachOptions = listOf(
                                Triple("Documento", Icons.Outlined.Description, Color(0xFF5B6CF0)),
                                Triple("Galeria", Icons.Outlined.Image, QinblyBrand.Accent),
                                Triple("Áudio", Icons.Outlined.Headphones, Color(0xFFF97316)),
                                Triple("Localização", Icons.Outlined.LocationOn, Color(0xFF16A34A)),
                                Triple("Contato", Icons.Outlined.PersonOutline, Color(0xFF0EA5E9)),
                                Triple("Enquete", QinblyCreateIcons.poll, Color(0xFFEAB308))
                            )
                            androidx.compose.foundation.layout.FlowRow(
                                modifier = Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 4.dp).clip(RoundedCornerShape(18.dp)).background(QiblyTheme.soft).padding(vertical = 10.dp),
                                horizontalArrangement = Arrangement.SpaceEvenly, maxItemsInEachRow = 3
                            ) {
                                attachOptions.forEach { (label, icon, color) ->
                                    Column(Modifier.fillMaxWidth(0.3f).padding(vertical = 6.dp).clip(RoundedCornerShape(12.dp)).clickable { showAttach = false; onCAttach(label) },
                                        horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(5.dp)) {
                                        Box(Modifier.size(50.dp).clip(CircleShape).background(color), contentAlignment = Alignment.Center) { Icon(icon, contentDescription = label, tint = Color.White, modifier = Modifier.size(25.dp)) }
                                        Text(label, color = QiblyTheme.text, fontSize = 12.sp, fontWeight = FontWeight.Medium, maxLines = 1)
                                    }
                                }
                            }
                        }
                        if (recordingVoiceC) {
                            QinblyVoiceBar(
                                accent = QinblyBrand.Accent, textColor = QiblyTheme.text, barColor = QiblyTheme.soft,
                                onCancel = { recordingVoiceC = false },
                                onTooShort = { recordingVoiceC = false; onNotice("Segure um pouco mais para gravar a mensagem.") },
                                onFailed = { recordingVoiceC = false; onNotice("Não foi possível gravar o áudio neste aparelho.") },
                                onSend = { file, secs ->
                                    recordingVoiceC = false
                                    sendCWith { token, cid ->
                                        try { QinblyApi.sendCommunityVoice(context, token, cid, file, secs) } finally { file.delete() }
                                    }
                                },
                                modifier = Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 8.dp)
                            )
                        } else {
                        Row(Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            androidx.compose.material3.TextField(
                                value = text, onValueChange = { text = it.take(2000) }, modifier = Modifier.weight(1f).onFocusChanged { if (it.isFocused) showEmoji = false },
                                placeholder = { Text("Mensagem…", maxLines = 1) }, shape = RoundedCornerShape(26.dp),
                                colors = androidx.compose.material3.TextFieldDefaults.colors(
                                    focusedContainerColor = QiblyTheme.soft, unfocusedContainerColor = QiblyTheme.soft,
                                    focusedIndicatorColor = Color.Transparent, unfocusedIndicatorColor = Color.Transparent, disabledIndicatorColor = Color.Transparent,
                                    cursorColor = QinblyBrand.Accent
                                ),
                                maxLines = 4,
                                leadingIcon = {
                                    IconButton(onClick = { showAttach = false; showEmoji = !showEmoji; if (showEmoji) { cKb?.hide(); cFocus.clearFocus() } else cKb?.show() }, modifier = Modifier.size(44.dp)) {
                                        Icon(QinblyCreateIcons.sticker, contentDescription = "Emojis e figurinhas", tint = if (showEmoji) QinblyBrand.Accent else Muted, modifier = Modifier.size(30.dp))
                                    }
                                },
                                trailingIcon = {
                                    Row(Modifier.padding(end = 10.dp), verticalAlignment = Alignment.CenterVertically) {
                                        IconButton(onClick = { showEmoji = false; showAttach = !showAttach }, modifier = Modifier.size(42.dp)) {
                                            Icon(Icons.Outlined.AttachFile, contentDescription = "Anexar", tint = if (showAttach) QinblyBrand.Accent else Muted, modifier = Modifier.size(28.dp))
                                        }
                                        IconButton(onClick = { cCameraShot() }, modifier = Modifier.size(42.dp)) {
                                            Icon(Icons.Outlined.CameraAlt, contentDescription = "Câmera", tint = Muted, modifier = Modifier.size(28.dp))
                                        }
                                    }
                                }
                            )
                            IconButton(
                                onClick = { if (text.isBlank()) startCVoice() else sendPost(c) },
                                modifier = Modifier.size(50.dp).background(qinblyAccentBrush(), CircleShape), enabled = !sending
                            ) {
                                if (text.isBlank()) Icon(Icons.Outlined.Mic, contentDescription = "Gravar áudio", tint = Color.White, modifier = Modifier.size(26.dp))
                                else Icon(Icons.Default.Send, contentDescription = "Enviar mensagem", tint = Color.White, modifier = Modifier.size(25.dp))
                            }
                        }
                        }
                        if (showEmoji) {
                            QinblyStickerGrid(QinblyBrand.Accent, QiblyTheme.soft, QiblyTheme.text, cStickerRefresh,
                                onCreate = { showCStickerCreator = true },
                                onPick = { sticker ->
                                    sendCWith { token, cid -> QinblyApi.sendCommunitySticker(token, cid, sticker) }
                                }, onNotice = onNotice,
                                modifier = Modifier.fillMaxWidth().height(300.dp).background(QiblyTheme.background).padding(10.dp))
                        }
                    } else if (c.joined || c.isOwner) {
                        Text("Só admins podem escrever nesta comunidade.", color = QiblyTheme.secondary, fontSize = 13.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center, modifier = Modifier.fillMaxWidth().padding(16.dp))
                    } else if (c.pending) {
                        Text("Pedido enviado. Quando o dono aprovar, você já pode conversar.", color = QiblyTheme.secondary, fontSize = 13.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center, modifier = Modifier.fillMaxWidth().padding(16.dp))
                    } else {
                        QinblyGradientButton(onClick = { toggleJoin(c) }, shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent), modifier = Modifier.fillMaxWidth().padding(12.dp).height(50.dp)) {
                            Text(if (c.joinMode == "approval") "Pedir para entrar" else "Entrar na comunidade", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 16.sp)
                        }
                    }
                }
            }
            if (showRules && c != null) {
                AlertDialog(
                    onDismissRequest = { showRules = false },
                    title = { Text("Regras da comunidade") },
                    text = { Text(c.rules.ifBlank { "O dono ainda não escreveu as regras." }, modifier = Modifier.verticalScroll(rememberScrollState())) },
                    confirmButton = { TextButton(onClick = { showRules = false }) { Text("Fechar") } }
                )
            }
            if (confirmDelete && c != null) {
                AlertDialog(
                    shape = RoundedCornerShape(28.dp), containerColor = QiblyTheme.dialog,
                    onDismissRequest = { confirmDelete = false },
                    title = { Text("Excluir comunidade?") },
                    text = { Text("Todas as publicações e membros serão removidos. Não dá para desfazer.") },
                    confirmButton = {
                        TextButton(onClick = {
                            confirmDelete = false
                            val token = prefs.getString("token", null) ?: return@TextButton
                            Thread {
                                try {
                                    QinblyApi.deleteCommunity(token, c.id)
                                    mainHandler.post { onChanged(); onNotice("Comunidade excluída."); onDismiss() }
                                } catch (e: Exception) { mainHandler.post { onNotice(e.message ?: "Não foi possível excluir.") } }
                            }.start()
                        }) { Text("Excluir", color = Color(0xFFD33B3B)) }
                    },
                    dismissButton = { TextButton(onClick = { confirmDelete = false }) { Text("Cancelar") } }
                )
            }
            if (confirmLeave && c != null) {
                AlertDialog(
                    shape = RoundedCornerShape(28.dp), containerColor = QiblyTheme.dialog,
                    onDismissRequest = { confirmLeave = false },
                    title = { Text("Sair da comunidade?") },
                    text = { Text("Você deixa de ver e enviar mensagens em ${c.name}. Dá para entrar de novo depois.") },
                    confirmButton = { TextButton(onClick = { confirmLeave = false; showInfo = false; toggleJoin(c) }) { Text("Sair", color = Color(0xFFD33B3B)) } },
                    dismissButton = { TextButton(onClick = { confirmLeave = false }) { Text("Cancelar") } }
                )
            }
            if (confirmClear) {
                AlertDialog(
                    shape = RoundedCornerShape(28.dp), containerColor = QiblyTheme.dialog,
                    onDismissRequest = { confirmClear = false },
                    title = { Text("Limpar conversa?") },
                    text = { Text("Isso apaga as mensagens só da sua tela. Para os outros membros, nada muda.") },
                    confirmButton = { TextButton(onClick = { confirmClear = false; val nowIso = java.time.Instant.now().toString(); clearedAt = nowIso; prefs.edit().putString("community_cleared_$communityId", nowIso).apply() }) { Text("Limpar", color = QinblyBrand.Accent) } },
                    dismissButton = { TextButton(onClick = { confirmClear = false }) { Text("Cancelar") } }
                )
            }
            if (showReport && c != null) {
                ReportReasonDialog(title = "Denunciar comunidade: qual o motivo?", onDismiss = { showReport = false }) { reason ->
                    showReport = false
                    val token = prefs.getString("token", null)
                    if (token.isNullOrBlank()) onNotice("Entre na sua conta para denunciar.")
                    else Thread {
                        try { QinblyApi.reportContent(token, "community", c.id, reason); mainHandler.post { onNotice("Denúncia enviada. Obrigado por avisar.") } }
                        catch (e: Exception) { mainHandler.post { onNotice(e.message ?: "Não foi possível enviar a denúncia.") } }
                    }.start()
                }
            }
        }
    }
}

// ---- Comunidade: denúncia e contas bloqueadas ----
private val reportReasons = listOf(
    "Spam" to "spam",
    "Assédio ou bullying" to "harassment",
    "Discurso de ódio" to "hate",
    "Violência" to "violence",
    "Conteúdo sexual" to "sexual",
    "Risco para menores" to "minor_safety",
    "Automutilação ou suicídio" to "self_harm",
    "Atividade ilegal" to "illegal",
    "Outro motivo" to "other"
)

@Composable
internal fun ReportReasonDialog(title: String, onDismiss: () -> Unit, onSelect: (String) -> Unit) {
    AlertDialog(
        shape = RoundedCornerShape(28.dp),
        onDismissRequest = onDismiss,
        title = { Text(title) },
        text = {
            Column(Modifier.verticalScroll(rememberScrollState())) {
                reportReasons.forEach { (label, code) ->
                    TextButton(onClick = { onSelect(code) }, modifier = Modifier.fillMaxWidth()) { Text(label, color = QiblyTheme.text) }
                }
            }
        },
        confirmButton = {},
        dismissButton = { TextButton(onClick = onDismiss) { Text("Cancelar", color = Pink) } },
        containerColor = QiblyTheme.dialog, titleContentColor = QiblyTheme.text, textContentColor = QiblyTheme.text
    )
}

@Composable
private fun BlockedAccountsDialog(prefs: android.content.SharedPreferences, onDismiss: () -> Unit, onNotice: (String) -> Unit, muted: Boolean = false) {
    var blocked by remember { mutableStateOf<List<QinblyApi.BlockedUser>>(emptyList()) }
    var loading by remember { mutableStateOf(true) }
    LaunchedEffect(Unit) {
        val token = prefs.getString("token", null)
        if (token.isNullOrBlank()) loading = false
        else Thread {
            try {
                val result = (if (muted) QinblyApi.getMutedUsers(token) else QinblyApi.getBlockedUsers(token))
                android.os.Handler(android.os.Looper.getMainLooper()).post { blocked = result; loading = false }
            } catch (e: Exception) {
                android.os.Handler(android.os.Looper.getMainLooper()).post { loading = false; onNotice(e.message ?: (if (muted) "Não foi possível carregar as contas silenciadas." else "Não foi possível carregar as contas bloqueadas.")) }
            }
        }.start()
    }
    AlertDialog(
        shape = RoundedCornerShape(28.dp),
        onDismissRequest = onDismiss,
        title = { Text(if (muted) "Contas silenciadas" else "Contas bloqueadas") },
        text = {
            Column(Modifier.verticalScroll(rememberScrollState())) {
                if (loading) Text("Carregando…")
                else if (blocked.isEmpty()) Text(if (muted) "Você não silenciou ninguém." else "Você não bloqueou ninguém.")
                else blocked.forEach { user ->
                    Row(Modifier.fillMaxWidth().padding(vertical = 4.dp), verticalAlignment = Alignment.CenterVertically) {
                        Column(Modifier.weight(1f)) {
                            Text(user.displayName.ifBlank { user.username }, fontWeight = FontWeight.SemiBold)
                        }
                        TextButton(onClick = {
                            val token = prefs.getString("token", null)
                            if (token.isNullOrBlank()) onNotice("Entre na sua conta para continuar.")
                            else Thread {
                                try {
                                    if (muted) QinblyApi.toggleMute(token, user.id) else QinblyApi.toggleBlock(token, user.id)
                                    android.os.Handler(android.os.Looper.getMainLooper()).post { blocked = blocked.filterNot { it.id == user.id }; onNotice(if (muted) "Pessoa não está mais silenciada." else "Usuário desbloqueado.") }
                                } catch (e: Exception) {
                                    android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível concluir agora.") }
                                }
                            }.start()
                        }) { Text(if (muted) "Reativar" else "Desbloquear", color = Pink) }
                    }
                }
            }
        },
        confirmButton = { TextButton(onClick = onDismiss) { Text("Fechar", color = Pink) } },
        containerColor = QiblyTheme.dialog, titleContentColor = QiblyTheme.text, textContentColor = QiblyTheme.text
    )
}

@Composable
private fun MessagesPage(scrollToTopRequest: Int, recipientUsername: String, onSearch: () -> Unit, onOpenConversation: (String) -> Unit, onOpenProfile: (String) -> Unit, onNotice: (String) -> Unit, onConversationRead: (Int) -> Unit = {}, onAddStory: () -> Unit = {}) {
    val readLocally = remember { mutableStateListOf<String>() }
    var inboxMenu by remember { mutableStateOf<QinblyApi.InboxSummary?>(null) }
    var inboxAnchor by remember { mutableStateOf<androidx.compose.ui.geometry.Rect?>(null) }
    var inboxPrefsTick by remember { mutableStateOf(0) }
    var confirmDeleteConv by remember { mutableStateOf<QinblyApi.InboxSummary?>(null) }
    var confirmBlockConv by remember { mutableStateOf<String?>(null) }
    var reportConvUser by remember { mutableStateOf<String?>(null) }
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    val inboxListState = rememberKeptListState("msg.list")
    LaunchedEffect(scrollToTopRequest) { if (scrollToTopRequest > 0) inboxListState.animateScrollToItem(0) }
    var draft by remember { mutableStateOf("") }
    var showEmojiPicker by remember { mutableStateOf(false) }
    BackHandler(enabled = showEmojiPicker) { showEmojiPicker = false }
    val stickerKb = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current
    val stickerFocus = androidx.compose.ui.platform.LocalFocusManager.current
    var showAttachPanel by remember { mutableStateOf(false) }
    var recordingVoice by remember { mutableStateOf(false) }
    val micPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) recordingVoice = true else onNotice("Permita o microfone para enviar mensagens de voz.")
    }
    var messages by remember { mutableStateOf<List<QinblyApi.MessageSummary>>(emptyList()) }
    var inbox by remember { mutableStateOf(QinblyCache.inbox) }
    var loadingInbox by remember { mutableStateOf(false) }
    var loading by remember { mutableStateOf(false) }
    var sending by remember { mutableStateOf(false) }
    var selectedFilter by remember { mutableStateOf("Todas") }
    var inboxSearch by remember { mutableStateOf("") }
    var showConversationMenu by remember { mutableStateOf(false) }
    var conversationSearch by remember { mutableStateOf(false) }
    var messageSearch by remember { mutableStateOf("") }
    var showClearConfirm by remember { mutableStateOf(false) }
    var menuMessage by remember { mutableStateOf<QinblyApi.MessageSummary?>(null) }
    var hiddenMsgIds by remember { mutableStateOf(context.getSharedPreferences(qinblyAccountFile(context, "qinbly_hidden"), android.content.Context.MODE_PRIVATE).getStringSet("ids", emptySet()) ?: emptySet()) }
    var reportingMessageId by remember { mutableStateOf<String?>(null) }
    var replyingTo by remember { mutableStateOf<QinblyApi.MessageSummary?>(null) }
    var menuAnchor by remember { mutableStateOf<androidx.compose.ui.geometry.Rect?>(null) }
    var showSharedMedia by remember { mutableStateOf(false) }
    var chatPhotoUrl by remember { mutableStateOf<String?>(null) }
    var reactions by remember { mutableStateOf<Map<String, List<Pair<String, String>>>>(emptyMap()) }
    var reactionsNonce by remember { mutableStateOf(0) }
    LaunchedEffect(messages.size, reactionsNonce) {
        val token = prefs.getString("token", null)
        if (!token.isNullOrBlank() && messages.isNotEmpty()) {
            try { reactions = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getReactions(token, messages.takeLast(100).map { it.id }) } } catch (_: Exception) { }
        }
    }
    var pinnedId by remember(recipientUsername) { mutableStateOf(context.getSharedPreferences(qinblyAccountFile(context, "qinbly_pins"), android.content.Context.MODE_PRIVATE).getString("pin_" + recipientUsername, "") ?: "") }
    var showBlockConfirm by remember { mutableStateOf(false) }
    var showReportConfirm by remember { mutableStateOf(false) }
    // Envia algo na conversa (foto, local, contato) e recarrega as mensagens.
    fun sendWith(action: (String) -> Unit) {
        val token = prefs.getString("token", null)
        if (token.isNullOrBlank()) { onNotice("Entre na sua conta para enviar mensagens."); return }
        if (sending) return
        sending = true
        Thread {
            try {
                action(token)
                val loaded = QinblyApi.getMessages(token, recipientUsername)
                android.os.Handler(android.os.Looper.getMainLooper()).post { messages = loaded; sending = false }
            } catch (e: Exception) {
                android.os.Handler(android.os.Looper.getMainLooper()).post { sending = false; onNotice(e.message ?: "Não foi possível enviar.") }
            }
        }.start()
    }
    var showChatPoll by remember { mutableStateOf(false) }
    var showStickerCreator by remember { mutableStateOf(false) }
    var stickerRefresh by remember { mutableIntStateOf(0) }
    val chatDocPicker = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        if (uri != null) sendWith { token -> QinblyApi.sendFileMessage(context, token, recipientUsername, uri) }
    }
    // Câmera padrão do app (a mesma do Criar), em vez da câmera do celular.
    var showChatAppCamera by remember { mutableStateOf(false) }
    // Foto da galeria passa pelo MESMO editor da câmera (padrão do app) antes de enviar.
    val chatGalleryPicker = rememberQinblyPhotoLauncher(onCamera = { showChatAppCamera = true }) { uri ->
        if (uri != null) { qinblySetPickedMedia(uri, false); showChatAppCamera = true }
    }
    var pendingChatPhoto by remember { mutableStateOf<java.io.File?>(null) }
    fun launchChatCamera() { showChatAppCamera = true }
    if (showChatAppCamera) QinblyCameraCapture(
        onResult = { u ->
            showChatAppCamera = false
            sendWith { token -> try { QinblyApi.sendImageMessage(context, token, recipientUsername, u) } finally { u.path?.let { java.io.File(it).delete() } } }
        },
        onDismiss = { showChatAppCamera = false }
    )
    val chatCameraPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) launchChatCamera() else onNotice("Permita a câmera para tirar a foto.")
    }
    fun chatCameraShot() {
        if (androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.CAMERA) == android.content.pm.PackageManager.PERMISSION_GRANTED) launchChatCamera()
        else chatCameraPermission.launch(android.Manifest.permission.CAMERA)
    }
    val chatContactPicker = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        val data = result.data?.data ?: return@rememberLauncherForActivityResult
        try {
            context.contentResolver.query(data, arrayOf(android.provider.ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME, android.provider.ContactsContract.CommonDataKinds.Phone.NUMBER), null, null, null)?.use { c ->
                if (c.moveToFirst()) {
                    val who = c.getString(0).orEmpty()
                    val number = c.getString(1).orEmpty()
                    sendWith { token -> QinblyApi.sendMessage(token, recipientUsername, "Contato: $who\n$number") }
                }
            }
        } catch (_: Exception) { onNotice("Não foi possível ler o contato escolhido.") }
    }
    fun sendMyLocation() {
        try {
            val lm = context.getSystemService(android.content.Context.LOCATION_SERVICE) as android.location.LocationManager
            val best = lm.getProviders(true).mapNotNull { try { lm.getLastKnownLocation(it) } catch (_: SecurityException) { null } }.maxByOrNull { it.time }
            if (best == null) onNotice("Não consegui pegar sua localização. Ligue o GPS e tente de novo.")
            else sendWith { token -> QinblyApi.sendMessage(token, recipientUsername, "Minha localização:\nhttps://maps.google.com/?q=" + best.latitude + "," + best.longitude) }
        } catch (_: SecurityException) { onNotice("Permita a localização para enviar onde você está.") }
    }
    val chatLocationPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { res ->
        if (res.values.any { it }) sendMyLocation() else onNotice("Permita a localização para enviar onde você está.")
    }
    fun onChatAttach(label: String) {
        when (label) {
            "Galeria" -> chatGalleryPicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))
            "Contato" -> chatContactPicker.launch(android.content.Intent(android.content.Intent.ACTION_PICK, android.provider.ContactsContract.CommonDataKinds.Phone.CONTENT_URI))
            "Localização" -> {
                val granted = androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.ACCESS_COARSE_LOCATION) == android.content.pm.PackageManager.PERMISSION_GRANTED ||
                    androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.ACCESS_FINE_LOCATION) == android.content.pm.PackageManager.PERMISSION_GRANTED
                if (granted) sendMyLocation() else chatLocationPermission.launch(arrayOf(android.Manifest.permission.ACCESS_COARSE_LOCATION, android.Manifest.permission.ACCESS_FINE_LOCATION))
            }
            "Áudio" -> { recordingVoice = true }
            "Documento" -> chatDocPicker.launch(arrayOf("application/pdf", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/vnd.ms-excel", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/vnd.ms-powerpoint", "application/vnd.openxmlformats-officedocument.presentationml.presentation", "text/plain", "text/csv", "application/zip"))
            "Enquete" -> showChatPoll = true
            else -> onNotice("$label: ainda não está disponível.")
        }
    }
    if (showStickerCreator) {
        QinblyStickerCreateDialog(QinblyBrand.Accent, onNotice, onDismiss = { showStickerCreator = false }, onCreated = { stickerRefresh++ })
    }
    if (showChatPoll) {
        QinblyPollCreateDialog(QinblyBrand.Accent, onDismiss = { showChatPoll = false }) { question, options ->
            showChatPoll = false
            sendWith { token -> QinblyApi.sendPollMessage(token, recipientUsername, question, options) }
        }
    }
    fun voteDm(poll: QinblyApi.ChatPoll, index: Int) {
        val token = prefs.getString("token", null) ?: return
        Thread {
            try {
                val r = QinblyApi.voteChatPoll(token, poll.id, index)
                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    messages = messages.map { m -> if (m.poll?.id == poll.id) m.copy(poll = m.poll?.copy(votes = r.votes, myVote = r.myVote)) else m }
                }
            } catch (e: Exception) { android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível votar.") } }
        }.start()
    }
    var isMuted by remember(recipientUsername) { mutableStateOf(prefs.getBoolean("muted_$recipientUsername", false)) }
    var isPinned by remember(recipientUsername) { mutableStateOf(prefs.getBoolean("pinned_$recipientUsername", false)) }
    var ownUserId by remember { mutableStateOf(prefs.getString("user_id", "") ?: "") }
    var recipientAvatarUrl by remember(recipientUsername) { mutableStateOf("") }
    val visibleMessages = messages.filter { it.id !in hiddenMsgIds }.let { base -> if (messageSearch.isBlank()) base else base.filter { it.body.contains(messageSearch, ignoreCase = true) } }
    val filteredInbox = inbox.filter { inboxSearch.isBlank() || it.displayName.contains(inboxSearch, ignoreCase = true) || it.username.contains(inboxSearch, ignoreCase = true) || it.body.contains(inboxSearch, ignoreCase = true) }
    val visibleInbox = when (selectedFilter) {
        "Não lidas" -> filteredInbox.filter { it.unreadCount > 0 }
        // A API atual só retorna conversas individuais; ainda não classifica grupos nem solicitações.
        "Solicitações" -> emptyList()
        else -> filteredInbox
    }.filter { c -> inboxPrefsTick >= 0 && (prefs.getString("inbox_hidden_" + c.username, "") ?: "").let { h -> h.isEmpty() || c.createdAt > h } }
        .sortedByDescending { c -> if (inboxPrefsTick >= 0 && prefs.getBoolean("pinned_" + c.username, false)) 1 else 0 }

    inboxMenu?.let { cv ->
        val cvUnread = cv.unreadCount > 0 && cv.username !in readLocally
        QinblyInboxMenu(inboxAnchor, cvUnread, prefs.getBoolean("pinned_" + cv.username, false), prefs.getBoolean("muted_" + cv.username, false), QiblyTheme.text, QinblyBrand.Accent,
            onDismiss = { inboxMenu = null },
            onProfile = { onOpenProfile(cv.username) },
            onMarkRead = {
                readLocally.add(cv.username); onConversationRead(cv.unreadCount)
                val token = prefs.getString("token", null)
                if (!token.isNullOrBlank()) Thread { try { QinblyApi.getMessages(token, cv.username) } catch (_: Exception) { } }.start()
            },
            onTogglePin = { prefs.edit().putBoolean("pinned_" + cv.username, !prefs.getBoolean("pinned_" + cv.username, false)).apply(); inboxPrefsTick++ },
            onToggleMute = { val nv = !prefs.getBoolean("muted_" + cv.username, false); prefs.edit().putBoolean("muted_" + cv.username, nv).apply(); inboxPrefsTick++; onNotice(if (nv) "Notificações silenciadas." else "Notificações reativadas.") },
            onDelete = { confirmDeleteConv = cv },
            onBlock = { confirmBlockConv = cv.username },
            onReport = { reportConvUser = cv.username })
    }
    confirmDeleteConv?.let { cv ->
        AlertDialog(
            onDismissRequest = { confirmDeleteConv = null },
            title = { Text("Apagar conversa?") },
            text = { Text("A conversa e as mensagens somem só para você, em todos os aparelhos, e não voltam. A outra pessoa continua vendo.") },
            confirmButton = { TextButton(onClick = {
                prefs.edit().putString("inbox_hidden_" + cv.username, cv.createdAt).apply(); inboxPrefsTick++; confirmDeleteConv = null
                val delToken = prefs.getString("token", null)
                if (!delToken.isNullOrBlank()) Thread { try { QinblyApi.hideConversation(delToken, cv.username) } catch (_: Exception) { } }.start()
            }) { Text("Apagar", color = Color(0xFFE5484D)) } },
            dismissButton = { TextButton(onClick = { confirmDeleteConv = null }) { Text("Cancelar") } }
        )
    }
    confirmBlockConv?.let { who ->
        AlertDialog(
            onDismissRequest = { confirmBlockConv = null },
            title = { Text("Bloquear @$who?") },
            text = { Text("Vocês não verão mais as publicações um do outro nem poderão trocar mensagens. Dá para desbloquear em Configurações > Contas bloqueadas.") },
            confirmButton = {
                TextButton(onClick = {
                    confirmBlockConv = null
                    val token = prefs.getString("token", null)
                    if (token.isNullOrBlank()) onNotice("Entre na sua conta para bloquear.")
                    else Thread {
                        try { QinblyApi.blockByUsername(token, who); android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice("@$who bloqueado.") } }
                        catch (e: Exception) { android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível bloquear.") } }
                    }.start()
                }) { Text("Bloquear", color = Color(0xFFE5484D)) }
            },
            dismissButton = { TextButton(onClick = { confirmBlockConv = null }) { Text("Cancelar") } }
        )
    }
    reportConvUser?.let { who ->
        ReportReasonDialog(title = "Denunciar @$who: qual o motivo?", onDismiss = { reportConvUser = null }) { reason ->
            reportConvUser = null
            val token = prefs.getString("token", null)
            if (token.isNullOrBlank()) onNotice("Entre na sua conta para denunciar.")
            else Thread {
                try { QinblyApi.reportUserByUsername(token, who, reason); android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice("Denúncia enviada. Obrigado por ajudar.") } }
                catch (e: Exception) { android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível enviar a denúncia.") } }
            }.start()
        }
    }

    chatPhotoUrl?.let { u ->
        QinblyDialog(onDismissRequest = { chatPhotoUrl = null }, properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)) {
            Box(Modifier.fillMaxSize().background(Color.Black).clickable { chatPhotoUrl = null }, contentAlignment = Alignment.Center) {
                AsyncImage(model = u, contentDescription = "Foto", modifier = Modifier.fillMaxWidth(), contentScale = androidx.compose.ui.layout.ContentScale.Fit)
            }
        }
    }
    if (showSharedMedia) QinblyChatSharedMedia(recipientUsername, messages, QiblyTheme.background, QiblyTheme.text, QiblyTheme.secondary, QinblyBrand.Accent) { showSharedMedia = false }

    // Pessoas para seguir: autores do feed que a pessoa ainda não segue (lista fixada ao abrir, para o botão virar "Seguindo" sem sumir).
    var suggestionSource by remember { mutableStateOf(QinblyCache.feed) }
    var moreSuggestions by remember { mutableStateOf(false) }
    LaunchedEffect(Unit) {
        if (suggestionSource.isEmpty()) {
            try { suggestionSource = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getPosts(prefs.getString("token", null)) } } catch (_: Exception) { }
        }
    }
    val ownHandle = prefs.getString("username", "").orEmpty().removePrefix("@")
    val suggestedPeople = remember(suggestionSource) {
        suggestionSource.filter { it.username.isNotBlank() && !it.username.equals(ownHandle, ignoreCase = true) && !it.username.endsWith(".demo") && !QinblyEngagement.isFollowing(prefs, it.username, it.isFollowing) }
            .distinctBy { it.username.lowercase() }
    }
    fun androidx.compose.foundation.lazy.LazyListScope.suggestionItems() {
        if (suggestedPeople.isEmpty()) return
        item(key = "suggestions-header") {
            Column(Modifier.fillMaxWidth().padding(top = 10.dp)) {
                Box(Modifier.fillMaxWidth().padding(top = 6.dp).height(1.dp).background(RemoteAppearance.feedDividerColor.copy(alpha = 0.45f)))
                Row(Modifier.fillMaxWidth().padding(top = 14.dp, bottom = 4.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text("Pessoas para seguir", color = RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold, fontSize = 16.sp, modifier = Modifier.weight(1f))
                    if (suggestedPeople.size > 5) QinblyAccentText(if (moreSuggestions) "Ver menos" else "Ver mais", fontWeight = FontWeight.SemiBold, modifier = Modifier.clickable { moreSuggestions = !moreSuggestions }.padding(6.dp))
                }
            }
        }
        items(if (moreSuggestions) suggestedPeople.take(20) else suggestedPeople.take(5), key = { "sug-" + it.username }) { person ->
            Row(Modifier.fillMaxWidth().padding(vertical = 6.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                QiblyAccountAvatar(person.username, person.avatarUrl, 46.dp) { onOpenProfile(person.username) }
                Column(Modifier.weight(1f).clickable { onOpenProfile(person.username) }) {
                    Row(verticalAlignment = Alignment.CenterVertically) { Text(person.displayName.ifBlank { person.username }, color = RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold, maxLines = 1); if (person.verified) { Spacer(Modifier.width(5.dp)); QinblyVerifiedBadge(15.dp) } }
                }
                QinblyFollowButton(
                    following = QinblyEngagement.isFollowing(prefs, person.username, person.isFollowing),
                    busy = QinblyEngagement.isFollowBusy(person.username),
                    onClick = { QinblyEngagement.toggleFollow(prefs, person.username, person.authorId, person.displayName, onNotice) }
                )
            }
        }
    }

    LaunchedEffect(prefs.getString("token", null)) {
        val profileToken = prefs.getString("token", null)
        if (!profileToken.isNullOrBlank()) {
            try {
                val profileResponse = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getMyProfile(profileToken) }
                val currentUser = profileResponse.optJSONObject("user")
                if (currentUser != null) {
                    val id = currentUser.optString("id", currentUser.optString("userId", currentUser.optString("user_id")))
                    if (id.isNotBlank()) {
                        ownUserId = id
                        prefs.edit().putString("user_id", id).apply()
                    }
                }
            } catch (_: Exception) { }
        }
    }

    LaunchedEffect(recipientUsername) {
        recipientAvatarUrl = ""
        if (recipientUsername.isNotBlank()) {
            try {
                val publicProfile = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getPublicProfile(recipientUsername) }
                val profileUser = publicProfile.optJSONObject("user") ?: publicProfile.optJSONObject("profile") ?: publicProfile
                recipientAvatarUrl = profileUser.optString("avatarUrl").ifBlank { profileUser.optString("avatar_url") }
            } catch (_: Exception) { }
        }
        messages = emptyList()
        if (recipientUsername.isBlank()) {
            val token = prefs.getString("token", null)
            if (!token.isNullOrBlank()) {
                loadingInbox = inbox.isEmpty()
                var firstInboxLoad = true
                while (true) {
                    try {
                        val loadedInbox = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getInbox(token) }
                        inbox = loadedInbox.distinctBy { it.username }
                        QinblyCache.inbox = inbox
                    } catch (e: Exception) {
                        if (firstInboxLoad) onNotice(e.message ?: "Não foi possível carregar suas conversas.")
                    } finally {
                        loadingInbox = false
                    }
                    firstInboxLoad = false
                    kotlinx.coroutines.delay(15_000)
                }
            } else {
                inbox = emptyList()
                loadingInbox = false
            }
        }
        if (recipientUsername.isNotBlank()) {
            val token = prefs.getString("token", null)
            if (token.isNullOrBlank()) {
                onNotice("Entre na sua conta para abrir mensagens.")
            } else {
                loading = true
                var firstLoad = true
                while (true) {
                    try {
                        val loaded = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                            QinblyApi.getMessages(token, recipientUsername)
                        }
                        val demoMessages = if (recipientUsername.endsWith(".demo")) listOf(
                            QinblyApi.MessageSummary("demo-msg-01", "Oi! Vi suas fotos no ${QinblyBrand.Name} 😊", "demo-user", "Hoje"),
                            QinblyApi.MessageSummary("demo-msg-02", "Obrigada! Estou testando as mensagens por aqui ✨", ownUserId, "Hoje"),
                            QinblyApi.MessageSummary("demo-msg-03", "Ficou ótimo! Depois me manda outra publicação ❤️", "demo-user", "Agora")
                        ) else emptyList()
                        messages = if (loaded.isEmpty()) demoMessages else loaded
                        loading = false
                    } catch (e: Exception) {
                        loading = false
                        if (firstLoad) onNotice(e.message ?: "Não foi possível carregar a conversa.")
                    }
                    firstLoad = false
                    kotlinx.coroutines.delay(5000)
                }
            }
        }
    }

    Column(Modifier.fillMaxSize().padding(start = 16.dp, end = 16.dp, top = 10.dp, bottom = if (WindowInsets.ime.getBottom(androidx.compose.ui.platform.LocalDensity.current) > 0) 0.dp else 10.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        if (recipientUsername.isBlank()) {
            // Faixa de cima: "Criar" (story ou nota), quem você segue com story/nota e atalhos para quem você conversa.
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
                listOf("Todas", "Não lidas").forEach { label ->
                    val selected = selectedFilter == label
                    val unreadTotal = if (label == "Não lidas") inbox.count { it.unreadCount > 0 } else 0
                    Surface(
                        modifier = Modifier.clickable { selectedFilter = label },
                        color = if (selected) QinblyBrand.Accent else QinblyBrand.Accent.copy(alpha = 0.10f),
                        shape = RoundedCornerShape(22.dp)
                    ) {
                        Row(Modifier.padding(horizontal = 16.dp, vertical = 9.dp), verticalAlignment = Alignment.CenterVertically) {
                            Text(label, color = if (selected) Color.White else RemoteAppearance.screenTextColor, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.SemiBold, maxLines = 1)
                            if (unreadTotal > 0) {
                                Spacer(Modifier.width(6.dp))
                                Box(Modifier.size(20.dp).clip(CircleShape).background(if (selected) Color.White else QinblyBrand.Accent), contentAlignment = Alignment.Center) {
                                    Text(if (unreadTotal > 9) "9+" else unreadTotal.toString(), color = if (selected) QinblyBrand.Accent else Color.White, fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                                }
                            }
                        }
                    }
                }
            }
            when {
                loadingInbox -> Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = Pink) }
                selectedFilter == "Solicitações" -> Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        Icon(Icons.Default.ChatBubbleOutline, contentDescription = null, tint = Pink, modifier = Modifier.size(36.dp))
                        Text("Nenhuma solicitação", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold)
                        Text(
                            "Mensagens de pessoas que você não segue aparecerão aqui.",
                            color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodyMedium, textAlign = androidx.compose.ui.text.style.TextAlign.Center
                        )
                    }
                }
                visibleInbox.isNotEmpty() -> LazyColumn(Modifier.fillMaxSize(), state = inboxListState, verticalArrangement = Arrangement.spacedBy(0.dp), contentPadding = PaddingValues(vertical = 4.dp)) {
                    items(visibleInbox, key = { it.username }) { conversation ->
                        val unread = conversation.unreadCount > 0 && conversation.username !in readLocally
                        val inboxRowRect = remember { arrayOfNulls<androidx.compose.ui.geometry.Rect>(1) }
                        Row(
                            Modifier.fillMaxWidth().padding(vertical = 3.dp)
                                .clip(RoundedCornerShape(18.dp))
                                .background(if (unread) QinblyBrand.Accent.copy(alpha = 0.12f) else Color.Transparent)
                                .onGloballyPositioned { inboxRowRect[0] = it.boundsInWindow() }.combinedClickable(onClick = { if (unread) { readLocally.add(conversation.username); onConversationRead(conversation.unreadCount) }; onOpenConversation(conversation.username) }, onLongClick = { inboxAnchor = inboxRowRect[0]; inboxMenu = conversation }).padding(horizontal = 10.dp, vertical = 7.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(14.dp)
                        ) {
                            QiblyAccountAvatar(conversation.username, conversation.avatarUrl, 50.dp) { onOpenProfile(conversation.username) }
                            Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                                Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                                    Box(Modifier.weight(1f)) {
                                        Text(conversation.displayName.ifBlank { conversation.username }, color = RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold, style = MaterialTheme.typography.bodyLarge, maxLines = 1)
                                    }
                                    Spacer(Modifier.width(8.dp))
                                    Text(if (conversation.createdAt.isBlank()) "Agora" else postRelativeTime(conversation.createdAt, System.currentTimeMillis()), color = if (unread) QinblyBrand.Accent else RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelSmall, fontWeight = if (unread) FontWeight.SemiBold else FontWeight.Normal)
                                }
                                Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                                    Box(Modifier.weight(1f)) {
                                        Text((if (QinblyStickers.idOf(conversation.body) != null) "Figurinha" else conversation.body).ifBlank { "@${conversation.username}" }, color = if (unread) RemoteAppearance.screenTextColor else RemoteAppearance.screenSecondaryTextColor, fontWeight = if (unread) FontWeight.SemiBold else FontWeight.Normal, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, style = MaterialTheme.typography.bodyMedium)
                                    }
                                    if (inboxPrefsTick >= 0 && prefs.getBoolean("muted_" + conversation.username, false)) Icon(Icons.Outlined.NotificationsOff, contentDescription = "Silenciada", tint = RemoteAppearance.screenSecondaryTextColor, modifier = Modifier.padding(start = 8.dp).size(18.dp))
                                    if (inboxPrefsTick >= 0 && prefs.getBoolean("pinned_" + conversation.username, false)) Icon(Icons.Outlined.PushPin, contentDescription = "Fixada", tint = RemoteAppearance.screenSecondaryTextColor, modifier = Modifier.padding(start = 8.dp).size(18.dp))
                                    if (unread) Box(
                                        Modifier.padding(start = 8.dp).sizeIn(minWidth = 20.dp, minHeight = 20.dp)
                                            .clip(CircleShape)
                                            .background(qinblyAccentBrush())
                                            .padding(horizontal = 6.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(if (conversation.unreadCount > 99) "99+" else conversation.unreadCount.toString(), color = Color.White, style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.SemiBold, maxLines = 1)
                                    }
                                }
                            }
                        }
                    }
                    if (selectedFilter == "Todas" && inboxSearch.isBlank()) suggestionItems()
                }
                else -> LazyColumn(Modifier.fillMaxSize(), state = inboxListState) { item { Box(Modifier.fillMaxWidth().padding(vertical = 24.dp), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        Box(Modifier.size(74.dp).clip(CircleShape).background(qinblyAccentBrush(0.12f)), contentAlignment = Alignment.Center) {
                            QinblyAccentIcon(Icons.Default.ChatBubbleOutline, contentDescription = null, modifier = Modifier.size(34.dp))
                        }
                        Text(if (selectedFilter == "Não lidas") "Tudo em dia!" else "Suas conversas", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold)
                        Text(if (selectedFilter == "Não lidas") "Você não tem mensagens não lidas." else "Pesquise pessoas e descubra contas para iniciar uma conversa.", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodyMedium, textAlign = androidx.compose.ui.text.style.TextAlign.Center)
                        if (selectedFilter != "Não lidas") QinblyGradientButton(onClick = onSearch, colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent), shape = RoundedCornerShape(14.dp)) {
                            Icon(Icons.Default.Search, contentDescription = null)
                            Spacer(Modifier.width(8.dp))
                            Text("Encontrar pessoas")
                        }
                    }
                } }
                    if (selectedFilter == "Todas" && inboxSearch.isBlank()) suggestionItems()
                }
            }
        } else {
            Row(Modifier.fillMaxWidth().padding(top = 6.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(2.dp)) {
                IconButton(onClick = { onOpenConversation("") }, modifier = Modifier.size(40.dp)) {
                    Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = RemoteAppearance.screenTextColor)
                }
                IconButton(onClick = { onOpenProfile(recipientUsername) }, modifier = Modifier.size(48.dp)) {
                    Box(
                        Modifier.size(42.dp).clip(CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        if (recipientAvatarUrl.isNotBlank()) {
                            AsyncImage(
                                model = recipientAvatarUrl,
                                contentDescription = "Foto de perfil de $recipientUsername",
                                modifier = Modifier.fillMaxSize().clip(CircleShape),
                                contentScale = androidx.compose.ui.layout.ContentScale.Crop
                            )
                        } else {
                            Box(Modifier.fillMaxSize().clip(CircleShape).background(RemoteAppearance.screenBackgroundColor), contentAlignment = Alignment.Center) {
                                Text(recipientUsername.take(1).uppercase(), color = Color.White, fontWeight = FontWeight.SemiBold)
                            }
                        }
                    }
                }
                Column(Modifier.weight(1f).clickable { onOpenProfile(recipientUsername) }, verticalArrangement = Arrangement.Center) {
                    Text(recipientUsername.removePrefix("@"), style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                }
                IconButton(onClick = { conversationSearch = !conversationSearch; if (!conversationSearch) messageSearch = "" }) {
                    Icon(Icons.Default.Search, contentDescription = "Pesquisar nesta conversa", tint = RemoteAppearance.screenSecondaryTextColor)
                }
                Box {
                    IconButton(onClick = { showConversationMenu = true }) {
                        Icon(Icons.Default.MoreVert, contentDescription = "Opções da conversa", tint = RemoteAppearance.screenTextColor)
                    }
                    DropdownMenu(expanded = showConversationMenu, onDismissRequest = { showConversationMenu = false }, modifier = Modifier.background(RemoteAppearance.screenBackgroundColor)) {
                        DropdownMenuItem(
                            text = { Text("Mídia, links e documentos") },
                            leadingIcon = { Icon(Icons.Default.PhotoLibrary, null, tint = Pink) },
                            onClick = { showConversationMenu = false; showSharedMedia = true }
                        )
                        DropdownMenuItem(
                            text = { Text(if (isMuted) "Ativar notificações" else "Silenciar notificações") },
                            leadingIcon = { Icon(Icons.Default.NotificationsOff, null, tint = Pink) },
                            onClick = {
                                isMuted = !isMuted
                                prefs.edit().putBoolean("muted_$recipientUsername", isMuted).apply()
                                showConversationMenu = false
                                onNotice(if (isMuted) "Notificações silenciadas neste dispositivo." else "Notificações reativadas.")
                            }
                        )
                        DropdownMenuItem(
                            text = { Text(if (isPinned) "Desafixar conversa" else "Fixar conversa") },
                            leadingIcon = { Icon(Icons.Default.PushPin, null, tint = Pink) },
                            onClick = {
                                isPinned = !isPinned
                                prefs.edit().putBoolean("pinned_$recipientUsername", isPinned).apply()
                                showConversationMenu = false
                                onNotice(if (isPinned) "Conversa marcada como fixada neste dispositivo." else "Conversa desafixada.")
                            }
                        )
                        DropdownMenuItem(
                            text = { Text("Limpar conversa") },
                            leadingIcon = { Icon(Icons.Default.DeleteForever, null, tint = Pink) },                            onClick = { showConversationMenu = false; showClearConfirm = true }
                        )
                        DropdownMenuItem(                            text = { Text("Bloquear usuário") },
                            leadingIcon = { Icon(Icons.Default.Block, null, tint = Pink) },
                            onClick = { showConversationMenu = false; showBlockConfirm = true }                        )
                        DropdownMenuItem(
                            text = { Text("Denunciar usuário") },
                            leadingIcon = { Icon(Icons.Default.Warning, null, tint = Pink) },
                            onClick = { showConversationMenu = false; showReportConfirm = true }
                        )
                        DropdownMenuItem(
                            text = { Text("Configurações da conversa") },
                            leadingIcon = { Icon(Icons.Default.Settings, null, tint = Pink) },
                            onClick = { showConversationMenu = false; onNotice("As preferências locais desta conversa estão disponíveis neste menu.") }
                        )
                    }
                }
            }
            if (conversationSearch) {
                OutlinedTextField(
                    value = messageSearch,
                    onValueChange = { messageSearch = it },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    placeholder = { Text("Pesquisar mensagens...") },
                    leadingIcon = { Icon(Icons.Default.Search, null, tint = Pink) },
                    trailingIcon = { IconButton(onClick = { messageSearch = ""; conversationSearch = false }) { Icon(Icons.Default.Close, contentDescription = "Fechar pesquisa") } },
                    shape = RoundedCornerShape(18.dp)
                )
            }


            messages.firstOrNull { it.id == pinnedId }?.let { pm ->
                Row(Modifier.fillMaxWidth().padding(vertical = 4.dp).clip(RoundedCornerShape(12.dp)).background(QiblyTheme.soft).padding(horizontal = 12.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text("Fixada: " + qinblyMessageSnippet(pm), color = QiblyTheme.text, fontSize = 14.sp, maxLines = 1, modifier = Modifier.weight(1f))
                    QinblyCloseIcon(QiblyTheme.secondary, 16.dp, modifier = Modifier.clickable {
                        pinnedId = ""
                        context.getSharedPreferences(qinblyAccountFile(context, "qinbly_pins"), android.content.Context.MODE_PRIVATE).edit().putString("pin_" + recipientUsername, "").apply()
                    }.padding(start = 10.dp))
                }
            }
            val chatListState = androidx.compose.foundation.lazy.rememberLazyListState()
            LaunchedEffect(visibleMessages.size) { if (visibleMessages.isNotEmpty()) chatListState.scrollToItem(visibleMessages.lastIndex) }
            QinblyKeepChatAtBottom(chatListState, visibleMessages.lastIndex)
            LazyColumn(Modifier.weight(1f).fillMaxWidth(), state = chatListState, verticalArrangement = Arrangement.spacedBy(6.dp), contentPadding = PaddingValues(horizontal = 4.dp, vertical = 14.dp)) {
                items(visibleMessages.size, key = { visibleMessages[it].id }) { index ->
                    val message = visibleMessages[index]
                    Column(Modifier.fillMaxWidth()) {
                    val zone = java.time.ZoneId.systemDefault()
                    fun dayOf(m: QinblyApi.MessageSummary) = try { java.time.Instant.parse(m.createdAt).atZone(zone).toLocalDate() } catch (_: Exception) { null }
                    val day = dayOf(message)
                    if (day != null && (index == 0 || dayOf(visibleMessages[index - 1]) != day)) {
                        val today = java.time.LocalDate.now(zone)
                        val label = when (day) {
                            today -> "Hoje"
                            today.minusDays(1) -> "Ontem"
                            else -> day.format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy"))
                        }
                        Box(Modifier.fillMaxWidth().padding(vertical = 8.dp), contentAlignment = Alignment.Center) {
                            Text(label, color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium,
                                modifier = Modifier.clip(RoundedCornerShape(12.dp)).background(qinblyAccentBrush(0.10f)).padding(horizontal = 12.dp, vertical = 4.dp))
                        }
                    }
                    val isOwn = (ownUserId.isNotBlank() && message.senderId == ownUserId) ||
                        message.senderId.equals(prefs.getString("username", "") ?: "", ignoreCase = true)
                    val sameSenderAsPrev = index > 0 && visibleMessages[index - 1].senderId == message.senderId && (day == null || dayOf(visibleMessages[index - 1]) == day)
                    Row(Modifier.fillMaxWidth().padding(top = if (sameSenderAsPrev) 0.dp else 6.dp), horizontalArrangement = if (isOwn) Arrangement.End else Arrangement.Start) {
                        val bubbleRect = remember { arrayOfNulls<androidx.compose.ui.geometry.Rect>(1) }
                        val bubbleShape = RoundedCornerShape(topStart = 18.dp, topEnd = 18.dp, bottomStart = if (isOwn) 18.dp else 4.dp, bottomEnd = if (isOwn) 4.dp else 18.dp)
                        val sharedPostForPad = remember(message.body) { Regex("post/([0-9a-fA-F-]{36})").find(message.body)?.groupValues?.get(1) }
                        // Publicação compartilhada (só mídia/texto): sem balão em volta; hora e check ficam do lado de fora.
                        val sharedBare = sharedPostForPad != null && message.poll == null && message.fileUrl.isBlank() && message.stickerUrl.isBlank() && message.imageUrl.isBlank() && message.audioUrl.isBlank() && QinblyStickers.idOf(message.body) == null
                        val bubbleColor = if (isOwn) QinblyBrand.Accent else if (QiblyTheme.dark) QiblyTheme.soft else Color(0xFFE9ECF1)
                        val textColor = if (sharedBare) QiblyTheme.text else if (isOwn) Color.White else if (QiblyTheme.dark) Color.White else Color(0xFF111827)
                        Surface(color = if (sharedBare || message.stickerUrl.isNotBlank() || QinblyStickers.idOf(message.body) != null) Color.Transparent else bubbleColor, shape = bubbleShape, modifier = Modifier.widthIn(max = 300.dp).onGloballyPositioned { bubbleRect[0] = it.boundsInWindow() }.clip(bubbleShape).combinedClickable(onClick = { if (message.stickerUrl.isNotBlank() || QinblyStickers.idOf(message.body) != null) { menuAnchor = bubbleRect[0]; menuMessage = message } else if (message.poll == null && message.fileUrl.isBlank() && message.imageUrl.isNotBlank()) { chatPhotoUrl = message.imageUrl } }, onLongClick = { menuAnchor = bubbleRect[0]; menuMessage = message })) {
                            Column(Modifier.padding(horizontal = if (sharedBare) 0.dp else if (message.imageUrl.isNotBlank() && message.poll == null && message.fileUrl.isBlank() && message.stickerUrl.isBlank()) 3.dp else 12.dp, vertical = if (sharedBare) 0.dp else if (message.imageUrl.isNotBlank() && message.poll == null && message.fileUrl.isBlank() && message.stickerUrl.isBlank()) 3.dp else 6.dp)) {
                                val sharedPostId = remember(message.body) { Regex("post/([0-9a-fA-F-]{36})").find(message.body)?.groupValues?.get(1) }
                                val stickerId = remember(message.body) { QinblyStickers.idOf(message.body) }
                                if (message.poll != null) {
                                    QinblyChatPollBubble(message.poll, QinblyBrand.Accent, textColor) { index -> voteDm(message.poll, index) }
                                } else if (message.stickerUrl.isNotBlank()) {
                                    AsyncImage(model = message.stickerUrl, contentDescription = "Figurinha", modifier = Modifier.size(120.dp))
                                } else if (message.fileUrl.isNotBlank()) {
                                    QinblyFileBubble(message.fileUrl, message.fileName, QinblyBrand.Accent, textColor)
                                } else if (message.imageUrl.isNotBlank()) {
                                    coil.compose.AsyncImage(model = message.imageUrl, contentDescription = "Foto enviada", modifier = Modifier.width(294.dp).heightIn(min = 160.dp, max = 400.dp).clip(RoundedCornerShape(15.dp)), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
                                } else if (message.audioUrl.isNotBlank()) {
                                    QinblyAudioBubble(message.audioUrl, message.audioSeconds, QinblyBrand.Accent, isOwn, textColor)
                                } else if (stickerId != null) {
                                    QinblyStickerView(stickerId)
                                } else if (sharedPostId == null) {
                                    if (message.body.startsWith("> ") && message.body.contains("\n")) {
                                        Column(Modifier.padding(bottom = 6.dp).clip(RoundedCornerShape(8.dp)).background(Color.Black.copy(alpha = 0.18f)).padding(horizontal = 8.dp, vertical = 5.dp)) {
                                            Text(message.body.substringBefore("\n").removePrefix("> "), color = textColor.copy(alpha = 0.75f), fontSize = 14.sp, maxLines = 2)
                                        }
                                        Text(message.body.substringAfter("\n"), color = textColor, style = MaterialTheme.typography.bodyLarge.copy(fontSize = 16.sp, lineHeight = 22.sp))
                                    } else
                                    Text(message.body, color = textColor, style = MaterialTheme.typography.bodyLarge.copy(fontSize = 16.sp, lineHeight = 22.sp))
                                } else {
                                    // Publicação compartilhada: aparece a própria mídia (foto ou vídeo) na conversa, sem cartão e sem link.
                                    val lines = message.body.split("\n").filter { it.isNotBlank() && !it.contains("/post/") }
                                    val intro = Regex("^Confira esta publicação no [^:]*: ?(.*)$")
                                    val introIndex = lines.indexOfFirst { intro.containsMatchIn(it) }
                                    val note = if (introIndex > 0) lines.take(introIndex).joinToString("\n") else ""
                                    val sharedCaption = if (introIndex >= 0) intro.find(lines[introIndex])?.groupValues?.get(1).orEmpty() else ""
                                    val sharedPost by produceState<QinblyApi.PostSummary?>(QinblyCache.feed.firstOrNull { it.id == sharedPostId }, sharedPostId) {
                                        if (value == null && sharedPostId != null) {
                                            value = try { kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyApi.getPost(sharedPostId) } } catch (_: Exception) { null }
                                        }
                                    }
                                    val sp = sharedPost
                                    val openShared = { QinblyDeepLink.postId = sharedPostId }
                                    val cap = sp?.caption?.ifBlank { sharedCaption } ?: sharedCaption
                                    val hasMedia = sp != null && sp.mediaUrl.isNotBlank()
                                    Column(Modifier.width(250.dp)) {
                                        if (sp != null && hasMedia && sp.mediaType == "video") {
                                            InlineVideoPlayer(url = sp.mediaUrl, modifier = Modifier.fillMaxWidth().aspectRatio(0.8f).clip(RoundedCornerShape(26.dp)), autoplay = false)
                                        } else if (sp != null && hasMedia) {
                                            AsyncImage(model = sp.mediaUrl, contentDescription = "Publicação compartilhada", modifier = Modifier.fillMaxWidth().heightIn(min = 160.dp, max = 340.dp).clip(RoundedCornerShape(26.dp)).clickable(onClick = openShared), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
                                        } else {
                                            Box(Modifier.fillMaxWidth().clip(RoundedCornerShape(20.dp)).background(QiblyTheme.soft).clickable(onClick = openShared).padding(14.dp)) {
                                                Text(cap.ifBlank { "Publicação" }, color = QiblyTheme.text, style = MaterialTheme.typography.bodyLarge)
                                            }
                                        }
                                        if (sp != null) {
                                            Row(Modifier.padding(top = 8.dp, start = 4.dp).clickable(onClick = openShared), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(7.dp)) {
                                                Box(Modifier.size(26.dp).clip(CircleShape).background(QiblyTheme.soft), contentAlignment = Alignment.Center) {
                                                    if (sp.avatarUrl.isNotBlank()) AsyncImage(model = sp.avatarUrl, contentDescription = null, modifier = Modifier.fillMaxSize(), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
                                                    else Text(sp.displayName.ifBlank { sp.username }.take(1).uppercase(), color = QiblyTheme.text, style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.SemiBold)
                                                }
                                                Text(sp.displayName.ifBlank { sp.username }, color = QiblyTheme.text, style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, modifier = Modifier.weight(1f, fill = false))
                                                if (sp.verified) QinblyVerifiedBadge(14.dp)
                                            }
                                            if (hasMedia && cap.isNotBlank()) Text(cap, color = QiblyTheme.secondary, style = MaterialTheme.typography.bodySmall, maxLines = 3, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, modifier = Modifier.padding(start = 37.dp, top = 2.dp))
                                        }
                                        // Recado escrito junto com a publicação: aparece embaixo dela, para ficar claro a que publicação ele se refere.
                                        if (note.isNotBlank()) Text(note, color = textColor, style = MaterialTheme.typography.bodyLarge, modifier = Modifier.padding(start = 4.dp, top = 8.dp))
                                    }
                                }
                                if (reactions[message.id].orEmpty().isNotEmpty()) Row(Modifier.align(Alignment.End).padding(top = 3.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                    val reacts = reactions[message.id].orEmpty()
                                    val reactChip: @Composable () -> Unit = {
                                        if (reacts.isNotEmpty()) Row(Modifier.padding(horizontal = 2.dp).clip(RoundedCornerShape(12.dp)).background(Color.Black.copy(alpha = 0.22f)).padding(horizontal = 6.dp, vertical = 1.dp), horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
                                            reacts.groupBy { it.second }.forEach { (emoji, list) ->
                                                Text(if (list.size > 1) emoji + " " + list.size else emoji, fontSize = 14.sp, color = textColor)
                                            }
                                        }
                                    }
                                    if (isOwn) reactChip()
                                    if (!isOwn) reactChip()
                                }
                            }
                        }
                    }
                    val nextMessage = visibleMessages.getOrNull(index + 1)
                    val lastOfSequence = nextMessage == null || nextMessage.senderId != message.senderId || dayOf(nextMessage) != day
                    if (lastOfSequence) {
                        val timeOutside = try {
                            java.time.Instant.parse(message.createdAt).atZone(zone).format(java.time.format.DateTimeFormatter.ofPattern("HH:mm"))
                        } catch (_: Exception) { message.createdAt.take(16).replace("T", " ") }
                        Row(Modifier.fillMaxWidth().padding(top = 2.dp, start = 6.dp, end = 6.dp), horizontalArrangement = if (isOwn) Arrangement.End else Arrangement.Start, verticalAlignment = Alignment.CenterVertically) {
                            Text(timeOutside, color = RemoteAppearance.screenSecondaryTextColor, fontSize = 11.sp)
                            if (isOwn) {
                                Spacer(Modifier.width(4.dp))
                                Icon(Icons.Default.CheckCircle, contentDescription = "Enviada", tint = RemoteAppearance.screenSecondaryTextColor, modifier = Modifier.size(12.dp))
                            }
                        }
                    }
                    }
                }
            }
            if (showAttachPanel) {
                val attachOptions = listOf(
                    Triple("Documento", Icons.Outlined.Description, Color(0xFF5B6CF0)),
                    Triple("Galeria", Icons.Outlined.Image, QinblyBrand.Accent),
                    Triple("Áudio", Icons.Outlined.Headphones, Color(0xFFF97316)),
                    Triple("Localização", Icons.Outlined.LocationOn, Color(0xFF16A34A)),
                    Triple("Contato", Icons.Outlined.PersonOutline, Color(0xFF0EA5E9)),
                    Triple("Enquete", QinblyCreateIcons.poll, Color(0xFFEAB308))
                )
                androidx.compose.foundation.layout.FlowRow(
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp).clip(RoundedCornerShape(18.dp)).background(QiblyTheme.soft).padding(vertical = 14.dp),
                    horizontalArrangement = Arrangement.SpaceEvenly,
                    maxItemsInEachRow = 3
                ) {
                    attachOptions.forEach { (label, icon, color) ->
                        Column(
                            Modifier.fillMaxWidth(0.3f).padding(vertical = 8.dp).clip(RoundedCornerShape(12.dp)).clickable { showAttachPanel = false; onChatAttach(label) },
                            horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(5.dp)
                        ) {
                            Box(Modifier.size(52.dp).clip(CircleShape).background(color), contentAlignment = Alignment.Center) { Icon(icon, contentDescription = label, tint = Color.White, modifier = Modifier.size(26.dp)) }
                            Text(label, color = QiblyTheme.text, fontSize = 12.sp, fontWeight = FontWeight.Medium, maxLines = 1)
                        }
                    }
                }
            }
            replyingTo?.let { rt ->
                Row(Modifier.fillMaxWidth().padding(top = 6.dp).clip(RoundedCornerShape(12.dp)).background(QiblyTheme.soft).padding(horizontal = 12.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text("Respondendo: " + qinblyMessageSnippet(rt), color = QiblyTheme.text, fontSize = 14.sp, maxLines = 1, modifier = Modifier.weight(1f))
                    QinblyCloseIcon(QiblyTheme.secondary, 16.dp, modifier = Modifier.clickable { replyingTo = null }.padding(start = 10.dp))
                }
            }
            if (recordingVoice) {
                QinblyVoiceBar(
                    accent = QinblyBrand.Accent, textColor = QiblyTheme.text, barColor = QiblyTheme.soft,
                    onCancel = { recordingVoice = false },
                    onTooShort = { recordingVoice = false; onNotice("Segure um pouco mais para gravar a mensagem.") },
                    onFailed = { recordingVoice = false; onNotice("Não foi possível gravar o áudio neste aparelho.") },
                    onSend = { file, secs ->
                        recordingVoice = false
                        val token = prefs.getString("token", null)
                        if (token.isNullOrBlank()) onNotice("Entre na sua conta para enviar mensagens.")
                        else if (!sending) {
                            sending = true
                            Thread {
                                try {
                                    QinblyApi.sendVoiceMessage(context, token, recipientUsername, file, secs)
                                    val loaded = QinblyApi.getMessages(token, recipientUsername)
                                    android.os.Handler(android.os.Looper.getMainLooper()).post { messages = loaded; sending = false }
                                } catch (e: Exception) {
                                    android.os.Handler(android.os.Looper.getMainLooper()).post { sending = false; onNotice(e.message ?: "Não foi possível enviar a mensagem de voz.") }
                                } finally { file.delete() }
                            }.start()
                        }
                    },
                    modifier = Modifier.padding(bottom = if (WindowInsets.ime.getBottom(androidx.compose.ui.platform.LocalDensity.current) > 0) QinblyKeyboardGap else 2.dp, top = 8.dp)
                )
            } else
            Row(Modifier.fillMaxWidth().padding(bottom = if (showEmojiPicker) 0.dp else if (WindowInsets.ime.getBottom(androidx.compose.ui.platform.LocalDensity.current) > 0) QinblyKeyboardGap else 2.dp, top = 8.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                androidx.compose.material3.TextField(
                    value = draft,
                    onValueChange = { draft = it.take(2000) },
                    modifier = Modifier.weight(1f).onFocusChanged { if (it.isFocused) showEmojiPicker = false },
                    placeholder = { Text("Mensagem…", maxLines = 1) },
                    shape = RoundedCornerShape(26.dp),
                    colors = androidx.compose.material3.TextFieldDefaults.colors(
                        focusedContainerColor = QiblyTheme.soft,
                        unfocusedContainerColor = QiblyTheme.soft,
                        focusedIndicatorColor = Color.Transparent,
                        unfocusedIndicatorColor = Color.Transparent,
                        disabledIndicatorColor = Color.Transparent,
                        cursorColor = QinblyBrand.Accent
                    ),
                    maxLines = 4,
                    leadingIcon = {
                        IconButton(onClick = { showAttachPanel = false; showEmojiPicker = !showEmojiPicker; if (showEmojiPicker) { stickerKb?.hide(); stickerFocus.clearFocus() } else stickerKb?.show() }, modifier = Modifier.size(44.dp)) {
                            Icon(QinblyCreateIcons.sticker, contentDescription = "Emojis e figurinhas", tint = if (showEmojiPicker) QinblyBrand.Accent else Muted, modifier = Modifier.size(30.dp))
                        }
                    },
                    trailingIcon = {
                        Row(Modifier.padding(end = 10.dp), verticalAlignment = Alignment.CenterVertically) {
                            IconButton(onClick = { showEmojiPicker = false; showAttachPanel = !showAttachPanel }, modifier = Modifier.size(42.dp)) {
                                Icon(Icons.Outlined.AttachFile, contentDescription = "Anexar", tint = if (showAttachPanel) QinblyBrand.Accent else Muted, modifier = Modifier.size(28.dp))
                            }
                            IconButton(onClick = { chatCameraShot() }, modifier = Modifier.size(42.dp)) {
                                Icon(Icons.Outlined.CameraAlt, contentDescription = "Câmera", tint = Muted, modifier = Modifier.size(28.dp))
                            }
                        }
                    }
                )
                IconButton(
                    onClick = {
                        if (draft.isBlank()) {
                            if (androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.RECORD_AUDIO) == android.content.pm.PackageManager.PERMISSION_GRANTED) recordingVoice = true
                            else micPermission.launch(android.Manifest.permission.RECORD_AUDIO)
                        }
                        else if (!sending) {
                            val token = prefs.getString("token", null)
                            if (token.isNullOrBlank()) onNotice("Entre na sua conta para enviar mensagens.")
                            else {
                                // A mensagem aparece na hora; o envio acontece por trás e não recarrega a conversa inteira.
                                val body = (replyingTo?.let { "> " + qinblyMessageSnippet(it) + "\n" } ?: "") + draft.trim()
                                val typed = draft
                                val localId = "local:" + System.nanoTime()
                                messages = messages + QinblyApi.MessageSummary(localId, body, ownUserId.ifBlank { prefs.getString("username", "").orEmpty() }, java.time.Instant.now().toString())
                                draft = ""; replyingTo = null
                                Thread {
                                    try {
                                        val sentJson = QinblyApi.sendMessage(token, recipientUsername, body)
                                        val real = sentJson.optJSONObject("message")
                                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                                            if (real == null || real.optString("id").isBlank()) return@post
                                            val realMsg = QinblyApi.MessageSummary(real.optString("id"), real.optString("body", body), real.optString("senderId", ownUserId), real.optString("createdAt"))
                                            messages = when {
                                                messages.any { it.id == localId } -> messages.map { if (it.id == localId) realMsg else it }
                                                messages.any { it.id == realMsg.id } -> messages
                                                else -> messages + realMsg
                                            }
                                        }
                                    } catch (e: Exception) {
                                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                                            messages = messages.filterNot { it.id == localId }
                                            if (draft.isBlank()) draft = typed
                                            onNotice(e.message ?: "Não foi possível enviar a mensagem.")
                                        }
                                    }
                                }.start()
                            }
                        }
                    },
                    modifier = Modifier.size(50.dp).background(qinblyAccentBrush(), CircleShape),
                    enabled = !sending
                ) {
                    if (draft.isBlank()) Icon(Icons.Outlined.Mic, contentDescription = "Gravar áudio", tint = Color.White, modifier = Modifier.size(26.dp))
                    else Icon(Icons.Default.Send, contentDescription = "Enviar mensagem", tint = Color.White, modifier = Modifier.size(25.dp))
                }
            }
            if (showEmojiPicker) {
                QinblyStickerGrid(QinblyBrand.Accent, QiblyTheme.soft, QiblyTheme.text, stickerRefresh,
                    onCreate = { showStickerCreator = true },
                    onPick = { sticker ->
                        sendWith { token -> QinblyApi.sendStickerMessage(token, recipientUsername, sticker) }
                    }, onNotice = onNotice,
                    modifier = Modifier.fillMaxWidth().height(300.dp).background(QiblyTheme.background).padding(10.dp), bleed = 16.dp)
            }
            menuMessage?.let { mm ->
                val own = (ownUserId.isNotBlank() && mm.senderId == ownUserId) || mm.senderId.equals(prefs.getString("username", "") ?: "", ignoreCase = true)
                QinblyMessageSheet(mm, menuAnchor, own, pinnedId == mm.id,
                    reactions[mm.id]?.firstOrNull { it.first == ownUserId }?.second ?: "",
                    { emoji ->
                        val token = prefs.getString("token", null)
                        if (!token.isNullOrBlank()) Thread {
                            try { QinblyApi.setReaction(token, mm.id, emoji); android.os.Handler(android.os.Looper.getMainLooper()).post { reactionsNonce++ } }
                            catch (e: Exception) { android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível reagir.") } }
                        }.start()
                    }, QinblyBrand.Accent, QiblyTheme.card, QiblyTheme.text,
                    onDismiss = { menuMessage = null },
                    onCanceled = { id -> messages = messages.filterNot { it.id == id } },
                    onHide = { id -> hiddenMsgIds = hiddenMsgIds + id; context.getSharedPreferences(qinblyAccountFile(context, "qinbly_hidden"), android.content.Context.MODE_PRIVATE).edit().putStringSet("ids", hiddenMsgIds).apply(); val hideToken = prefs.getString("token", null); if (!hideToken.isNullOrBlank()) Thread { try { QinblyApi.hideMessages(hideToken, listOf(id)) } catch (_: Exception) { } }.start() },
                    onReport = { id -> menuMessage = null; reportingMessageId = id },
                    onReply = { replyingTo = it },
                    onTogglePin = { id ->
                        pinnedId = if (pinnedId == id) "" else id
                        context.getSharedPreferences(qinblyAccountFile(context, "qinbly_pins"), android.content.Context.MODE_PRIVATE).edit().putString("pin_" + recipientUsername, pinnedId).apply()
                    },
                    onSavedSticker = { stickerRefresh++ },
                    onNotice = onNotice)
            }
            reportingMessageId?.let { rid ->
                ReportReasonDialog(title = "Denunciar mensagem: qual o motivo?", onDismiss = { reportingMessageId = null }) { reason ->
                    reportingMessageId = null
                    val token = prefs.getString("token", null)
                    if (token.isNullOrBlank()) onNotice("Entre na sua conta para denunciar.")
                    else Thread {
                        try { QinblyApi.reportContent(token, "message", rid, reason); android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice("Denúncia enviada. Obrigado por ajudar.") } }
                        catch (e: Exception) { android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível enviar a denúncia.") } }
                    }.start()
                }
            }
            if (showClearConfirm) {
                AlertDialog(
        shape = RoundedCornerShape(28.dp),
                    onDismissRequest = { showClearConfirm = false },
                    title = { Text("Limpar conversa?") },
                    text = { Text("As mensagens somem só para você, em todos os aparelhos, e não voltam. A outra pessoa continua vendo.") },
                    confirmButton = {
                        TextButton(onClick = {
                            messages = emptyList()
                            showClearConfirm = false
                            val clearToken = prefs.getString("token", null)
                            if (!clearToken.isNullOrBlank()) Thread {
                                try { QinblyApi.hideConversation(clearToken, recipientUsername); android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice("Conversa limpa.") } }
                                catch (e: Exception) { android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice("Não consegui limpar no servidor agora. Tente de novo.") } }
                            }.start() else onNotice("Entre na sua conta para limpar a conversa.")
                        }) { Text("Limpar conversa", color = Pink) }
                    },
                    dismissButton = { TextButton(onClick = { showClearConfirm = false }) { Text("Cancelar") } },
                    containerColor = Panel, titleContentColor = QiblyTheme.text, textContentColor = Muted
                )
            }
            if (showBlockConfirm) {
                AlertDialog(
        shape = RoundedCornerShape(28.dp),
                    onDismissRequest = { showBlockConfirm = false },
                    title = { Text("Bloquear usuário?") },
                    text = { Text("Vocês não verão mais as publicações um do outro nem poderão se seguir ou trocar mensagens. Você pode desbloquear em Configurações > Contas bloqueadas.") },
                    confirmButton = {
                        TextButton(onClick = {
                            showBlockConfirm = false
                            val token = prefs.getString("token", null)
                            if (token.isNullOrBlank()) onNotice("Entre na sua conta para bloquear.")
                            else Thread {
                                try {
                                    QinblyApi.blockByUsername(token, recipientUsername)
                                    android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice("Usuário bloqueado.") }
                                } catch (e: Exception) {
                                    android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível bloquear agora.") }
                                }
                            }.start()
                        }) { Text("Bloquear", color = Color.Red) }
                    },
                    dismissButton = { TextButton(onClick = { showBlockConfirm = false }) { Text("Cancelar", color = Pink) } },
                    containerColor = QiblyTheme.dialog, titleContentColor = QiblyTheme.text, textContentColor = QiblyTheme.text
                )
            }
            if (showReportConfirm) {
                ReportReasonDialog(title = "Denunciar usuário: qual o motivo?", onDismiss = { showReportConfirm = false }) { reason ->
                    showReportConfirm = false
                    val token = prefs.getString("token", null)
                    if (token.isNullOrBlank()) onNotice("Entre na sua conta para denunciar.")
                    else Thread {
                        try {
                            QinblyApi.reportUserByUsername(token, recipientUsername, reason)
                            android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice("Denúncia enviada. Obrigado por ajudar a manter a comunidade segura.") }
                        } catch (e: Exception) {
                            android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(e.message ?: "Não foi possível enviar a denúncia agora.") }
                        }
                    }.start()
                }
            }
        }
    }
}

private val qiblyAvatarRefreshVersion = androidx.compose.runtime.mutableIntStateOf(0)

/**
 * Cache único de fotos de perfil, usado por TODAS as telas (feed, listas, busca, comentários, mensagens).
 * Fica em memória (reativo: todas as fotos atualizam juntas) e no aparelho (já abre com a foto certa ao reabrir o app).
 */
private object QinblyAvatarCache {
    private class Entry(val url: String, val frame: Int, val at: Long, val fetched: Boolean)
    private val entries = mutableStateMapOf<String, Entry>()
    private val fetching = HashSet<String>()
    private var prefs: android.content.SharedPreferences? = null
    private var version = 0
    private const val FRESH_MS = 10 * 60 * 1000L

    fun init(context: android.content.Context) {
        if (prefs != null) return
        val sp = context.applicationContext.getSharedPreferences("qinbly_avatar_cache_v2", android.content.Context.MODE_PRIVATE)
        prefs = sp
        for ((key, value) in sp.all) {
            val raw = value as? String ?: continue
            val parts = raw.split("|", limit = 3)
            if (parts.size == 3) entries[key] = Entry(parts[2], parts[0].toIntOrNull() ?: -1, parts[1].toLongOrNull() ?: 0L, true)
        }
    }

    fun url(key: String): String? = entries[key]?.url?.takeIf { it.isNotBlank() }
    fun frame(key: String): Int = entries[key]?.frame ?: -1
    private fun isFresh(key: String): Boolean = entries[key]?.let { it.fetched && System.currentTimeMillis() - it.at < FRESH_MS } == true

    /** A foto trocou (versão mudou): descarta tudo para buscar de novo. */
    fun checkVersion(v: Int) {
        if (v == version) return
        version = v
        if (v > 0) { entries.clear(); prefs?.edit()?.clear()?.apply() }
    }

    /** Usa a foto que já veio na publicação/lista enquanto o perfil completo não chega. */
    fun seed(key: String, url: String) {
        if (url.isBlank() || entries[key] != null) return
        entries[key] = Entry(url, -1, 0L, false)
    }

    fun needsFetch(key: String): Boolean = !isFresh(key) && fetching.add(key)
    fun endFetch(key: String) { fetching.remove(key) }

    fun put(key: String, url: String, frame: Int) {
        val finalUrl = url.ifBlank { entries[key]?.url.orEmpty() }
        entries[key] = Entry(finalUrl, frame, System.currentTimeMillis(), true)
        prefs?.edit()?.putString(key, "$frame|${System.currentTimeMillis()}|$finalUrl")?.apply()
    }

    fun clear() { entries.clear(); fetching.clear(); prefs?.edit()?.clear()?.apply() }
}

