/**
 * Padrão do app: voltar SEMPRE volta para a tela anterior, do jeito que a pessoa deixou (busca com o texto e os resultados,
 * lista rolada, comunidade aberta...), nunca fecha tudo e joga no início.
 * QinblyKeep guarda "onde a pessoa estava" fora da tela, para sobreviver quando a tela sai da composição.
 */
private object QinblyKeep {
    private val map = HashMap<String, Any>()
    @Suppress("UNCHECKED_CAST")
    fun <T : Any> obtain(key: String, create: () -> T): T = synchronized(map) { map.getOrPut(key, create) } as T
    fun <T> state(key: String, initial: T): androidx.compose.runtime.MutableState<T> =
        obtain<androidx.compose.runtime.MutableState<T>>(key) { androidx.compose.runtime.mutableStateOf(initial) }
    fun clearPrefix(prefix: String) { synchronized(map) { map.keys.removeAll { it.startsWith(prefix) } } }
    fun clear() { synchronized(map) { map.clear() } }
}

@Composable
private fun <T> rememberKept(key: String, initial: T): androidx.compose.runtime.MutableState<T> = remember(key) { QinblyKeep.state(key, initial) }

@Composable
private fun rememberKeptListState(key: String): androidx.compose.foundation.lazy.LazyListState =
    remember(key) { QinblyKeep.obtain(key) { androidx.compose.foundation.lazy.LazyListState() } }

/**
 * Quando uma janela por cima (busca, lista de seguidores, hashtag, clipes, conversa da comunidade) abre um perfil,
 * ela se fecha para o perfil aparecer. Antes de fechar, ela deixa aqui como se reabre: ao voltar do perfil pelo botão
 * de voltar (do celular ou da tela), a janela volta como estava.
 */
/** Voltar de "Ver original"/"Ver perfil" para o story de onde a pessoa saiu (no mesmo story). */
/** Chave por conta: histórico de busca, hashtags usadas e stories vistos são de cada perfil, não do aparelho. */
internal fun qinblyAccountKey(prefs: android.content.SharedPreferences): String =
    prefs.getString("username", "").orEmpty().removePrefix("@").trim().lowercase().ifBlank { "anon" }

/** Quem tem story novo (ainda não visto por você): o anel azul na foto das publicações e do perfil acende e apaga a partir daqui. */
internal object QinblyStoryRings {
    val unseen = androidx.compose.runtime.mutableStateMapOf<String, Boolean>()
    val entries = HashMap<String, QinblyApi.TrayEntry>()
    /** Pedido para abrir o story de alguém (toque na foto de uma publicação); quem mostra o visualizador atende. */
    var openRequest by mutableStateOf<QinblyApi.TrayEntry?>(null)
    var version by mutableIntStateOf(0)
    private fun key(username: String) = username.removePrefix("@").trim().lowercase()
    private fun seenIds(prefs: android.content.SharedPreferences): Set<String> = prefs.getStringSet("seen_story_ids:" + qinblyAccountKey(prefs), emptySet()).orEmpty()
    fun hasUnseen(username: String): Boolean = unseen[key(username)] == true
    /** Trocou ou saiu da conta: o que era da conta anterior não pode aparecer na nova. */
    fun clear() { unseen.clear(); entries.clear(); openRequest = null; version++ }
    /** Tem story que você ainda não viu? Vale o que o servidor diz e também o que você já abriu neste aparelho. */
    fun entryUnseen(prefs: android.content.SharedPreferences, e: QinblyApi.TrayEntry): Boolean {
        version
        val seen = seenIds(prefs)
        return e.stories.any { it.page == "story" && !it.seen && it.id !in seen }
    }
    fun update(prefs: android.content.SharedPreferences, tray: List<QinblyApi.TrayEntry>) {
        tray.forEach { e ->
            entries[key(e.username)] = e
            unseen[key(e.username)] = e.stories.isNotEmpty() && !QinblyStoryMute.isMuted(prefs, e.username) && entryUnseen(prefs, e)
        }
    }
    /** Chamado quando um story aparece na tela do visualizador: guarda que foi visto e apaga o anel na hora. */
    fun markViewed(prefs: android.content.SharedPreferences, entry: QinblyApi.TrayEntry, storyId: String) {
        val all = seenIds(prefs)
        if (storyId in all) return
        prefs.edit().putStringSet("seen_story_ids:" + qinblyAccountKey(prefs), (if (all.size > 800) all.toList().takeLast(600).toSet() else all) + storyId).apply()
        version++
        entries[key(entry.username)] = entry
        unseen[key(entry.username)] = !QinblyStoryMute.isMuted(prefs, entry.username) && entryUnseen(prefs, entry)
    }
}

private object QinblyStoryReturn {
    var entry by mutableStateOf<QinblyApi.TrayEntry?>(null)
    var index = 0
}

/** "Ver original" de um vídeo: abre a aba Vídeos do Início já no vídeo. `returnEntry` guarda o story para o voltar. */
private object QinblyFeedJump {
    var postId by mutableStateOf<String?>(null)
    var returnEntry by mutableStateOf<QinblyApi.TrayEntry?>(null)
    var returnIndex = 0
}

private object QinblyResume {
    private class Entry(val at: QinblyNavState, val action: () -> Unit)
    private val stack = ArrayList<Entry>()
    var stateProvider: () -> QinblyNavState = { QinblyNavState(0, false, false, false, "", "") }
    /** Se preenchido, fechar a janela de publicação (aberta por um aviso) executa um "voltar" para o aviso. */
    var backOnClose: (() -> Unit)? = null
    fun push(action: () -> Unit) { stack.add(Entry(stateProvider(), action)) }
    fun arrive(now: QinblyNavState): (() -> Unit)? {
        val last = stack.indexOfLast { it.at == now }
        if (last < 0) return null
        // Tudo que foi guardado no mesmo toque (ex.: o vídeo da busca e a própria busca) volta junto, na ordem em que foi guardado.
        var first = last
        while (first > 0 && stack[first - 1].at == now) first--
        val actions = stack.subList(first, last + 1).map { it.action }
        while (stack.size > first) stack.removeAt(stack.lastIndex)
        return { actions.forEach { it() } }
    }
    fun clear() { stack.clear(); backOnClose = null; QinblyKeep.clearPrefix("search."); QinblyKeep.clearPrefix("comm.") }
}

/** Faixa de stories e notas (cartões grandes) no topo do Descobrir, com menu Criar, visualizador e nota completa. */
@Composable
private fun QinblyStoriesRow(onNotice: (String) -> Unit, onOpenProfile: (String) -> Unit, onOpenConversation: (String) -> Unit, onAddStory: () -> Unit, hostOnly: Boolean = false) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    var storyTray by remember { mutableStateOf<List<QinblyApi.TrayEntry>>(emptyList()) }
    var storyRefresh by remember { mutableIntStateOf(0) }
    var showStoryMenu by remember { mutableStateOf(false) }
    var viewingStory by remember { mutableStateOf<QinblyApi.TrayEntry?>(null) }
    LaunchedEffect(storyRefresh) {
        val token = prefs.getString("token", null)
        if (!token.isNullOrBlank()) {
            storyTray = try { kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                try { QinblyApi.syncMyCity(prefs, token) } catch (_: Exception) { }
                QinblyApi.getStoryTray(token)
            } } catch (_: Exception) { storyTray }
            QinblyStoryRings.update(prefs, storyTray)
        }
    }
    LaunchedEffect(Unit) { kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { QinblyStoryMute.sync(prefs) } }
    val myStoryEntry = storyTray.firstOrNull { it.mine }
    val trayOthers = storyTray.filter { !it.mine && it.stories.isNotEmpty() }.sortedBy { QinblyStoryMute.isMuted(prefs, it.username) }
    if (!hostOnly) androidx.compose.foundation.lazy.LazyRow(horizontalArrangement = Arrangement.spacedBy(4.dp), contentPadding = PaddingValues(horizontal = 8.dp, vertical = 10.dp)) {
        item(key = "story-create") {
            val mine = myStoryEntry
            val myName = prefs.getString("username", "").orEmpty()
            QinblyStoryBubble(
                username = myName, avatarUrl = mine?.avatarUrl.orEmpty(), label = "Seu story",
                // Igual aos outros: azul enquanto há story seu que você ainda não viu; apaga depois que você abre; cinza se não tem story.
                ring = if (mine?.stories?.isNotEmpty() != true) Color(0xFF55555C) else if (QinblyStoryRings.entryUnseen(prefs, mine)) QinblyBrand.Accent else Color(0xFF4A4066), plus = true,
                onPlus = { showStoryMenu = true },
                onClick = { if (mine?.stories?.isNotEmpty() == true) viewingStory = mine else showStoryMenu = true }
            )
        }
        items(trayOthers, key = { "tray-" + it.username }) { person ->
            QinblyStoryBubble(
                username = person.username, avatarUrl = person.avatarUrl, label = person.displayName.ifBlank { person.username },
                ring = if (QinblyStoryMute.isMuted(prefs, person.username)) Color(0xFF55555C) else if (person.stories.isEmpty() || QinblyStoryRings.entryUnseen(prefs, person)) QinblyBrand.Accent else Color(0xFF4A4066),
                plus = false, onClick = { viewingStory = person }
            )
        }
    }
    if (showStoryMenu) {
        QinblyStoryMenu(
            QinblyBrand.Accent, hasStory = myStoryEntry?.stories?.isNotEmpty() == true, hasNote = false,
            onDismiss = { showStoryMenu = false }, onNotice = onNotice, onChanged = { storyRefresh++ },
            onViewMine = { viewingStory = myStoryEntry }, onAddStory = onAddStory
        )
    }
    var viewingIndex by remember { mutableIntStateOf(0) }
    // Toque na foto de uma publicação (com anel): abre o story dessa pessoa.
    LaunchedEffect(QinblyStoryRings.openRequest) {
        QinblyStoryRings.openRequest?.let { viewingIndex = 0; viewingStory = it; QinblyStoryRings.openRequest = null }
    }
    // Voltou de "Ver original" ou do perfil: reabre o story no mesmo ponto.
    LaunchedEffect(QinblyStoryReturn.entry) {
        QinblyStoryReturn.entry?.let { viewingIndex = QinblyStoryReturn.index; viewingStory = it; QinblyStoryReturn.entry = null }
    }
    viewingStory?.let { entry ->
        // Fila de pessoas na ordem da faixa: o seu story primeiro, depois quem você segue.
        val storyQueue = listOfNotNull(myStoryEntry?.takeIf { it.stories.isNotEmpty() }) + trayOthers
        val personPos = storyQueue.indexOfFirst { it.username.equals(entry.username, ignoreCase = true) }
        QinblyStoryViewer(entry, QinblyBrand.Accent, onNotice, onDismiss = { viewingStory = null; storyRefresh++ }, onCamera = { id -> qinblyStartContribution(id); onAddStory() },
            startIndex = viewingIndex,
            hasNextPerson = personPos >= 0 && personPos < storyQueue.lastIndex,
            hasPreviousPerson = personPos > 0,
            onNextPerson = { viewingIndex = 0; viewingStory = storyQueue[personPos + 1] },
            onPreviousPerson = { viewingIndex = Int.MAX_VALUE; viewingStory = storyQueue[personPos - 1] },
            onAddStory = { viewingStory = null; storyRefresh++; onAddStory() },
            onOpenProfile = { username, idx ->
                viewingStory = null
                QinblyResume.push { QinblyStoryReturn.index = idx; QinblyStoryReturn.entry = entry }
                onOpenProfile(username)
            },
            onOpenOriginal = { origin, idx ->
                viewingStory = null
                if (origin.isVideo) {
                    QinblyFeedJump.returnEntry = entry; QinblyFeedJump.returnIndex = idx; QinblyFeedJump.postId = origin.postId
                } else {
                    QinblyResume.backOnClose = { QinblyStoryReturn.index = idx; QinblyStoryReturn.entry = entry }
                    QinblyDeepLink.postId = origin.postId
                }
            })
    }
}

/** Story em bolinha: foto de perfil com anel (azul = não visto), nome embaixo e + no próprio. */
@Composable
private fun QinblyStoryBubble(username: String, avatarUrl: String, label: String, ring: Color, plus: Boolean, onPlus: () -> Unit = {}, onClick: () -> Unit) {
    val ms = remember { androidx.compose.foundation.interaction.MutableInteractionSource() }
    Column(Modifier.width(96.dp), horizontalAlignment = Alignment.CenterHorizontally) {
        Box(Modifier.size(88.dp), contentAlignment = Alignment.Center) {
            Box(Modifier.fillMaxSize().clip(CircleShape).border(2.dp, if (ring == QinblyBrand.Accent) QinblyBrand.RingBrush else androidx.compose.ui.graphics.SolidColor(ring), CircleShape).clickable(indication = null, interactionSource = ms) { onClick() })
            QiblyAccountAvatar(username, avatarUrl, 80.dp) { onClick() }
            if (plus) Box(
                Modifier.align(Alignment.BottomCenter).offset(y = 9.dp).size(28.dp).clip(CircleShape).background(Color.White).border(2.dp, QiblyTheme.background, CircleShape).clickable { onPlus() },
                contentAlignment = Alignment.Center
            ) { Icon(Icons.Default.Add, contentDescription = "Criar story", tint = Color.Black, modifier = Modifier.size(19.dp)) }
        }
        Text(label, color = RemoteAppearance.feedTextColor, fontSize = 11.sp, fontWeight = FontWeight.Medium, maxLines = 1,
            overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, modifier = Modifier.padding(top = if (plus) 13.dp else 5.dp))
    }
}

@Composable
private fun QinblyStoryCard(imageUrl: String, isAvatar: Boolean, isVideo: Boolean, label: String, textStory: QinblyTextStory?, ring: Color, plus: Boolean, collabAvatars: List<String> = emptyList(), onPlus: () -> Unit = {}, showAvatar: Boolean = false, avatarUrl: String = "", onClick: () -> Unit) {
    val shape = RoundedCornerShape(16.dp)
    val ms = remember { androidx.compose.foundation.interaction.MutableInteractionSource() }
    Box(Modifier.width(168.dp).height(306.dp).clip(shape).background(QiblyTheme.soft).clickable(indication = null, interactionSource = ms) { onClick() }) {
        if (textStory != null) {
            Box(Modifier.fillMaxSize().background(androidx.compose.ui.graphics.Brush.verticalGradient(qinblyTextBgs[textStory.bg.coerceIn(0, qinblyTextBgs.lastIndex)])), contentAlignment = Alignment.Center) {
                Text(textStory.text, color = Color.White, fontSize = 18.sp, lineHeight = 24.sp, fontWeight = FontWeight.Medium, maxLines = 8, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center, modifier = Modifier.padding(horizontal = 14.dp))
            }
        } else if (imageUrl.isBlank()) {
            Icon(Icons.Default.Person, contentDescription = null, tint = Color.White.copy(alpha = 0.85f), modifier = Modifier.align(Alignment.Center).size(60.dp))
        } else if (imageUrl.isNotBlank()) {
            if (isVideo) QinblyVideoPoster(imageUrl, Modifier.fillMaxSize(), androidx.compose.ui.layout.ContentScale.Crop)
            else AsyncImage(model = imageUrl, contentDescription = null, modifier = Modifier.fillMaxSize(), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
        }
        Box(Modifier.align(Alignment.BottomCenter).fillMaxWidth().height(96.dp).background(androidx.compose.ui.graphics.Brush.verticalGradient(listOf(Color.Transparent, Color(0xCC000000)))))
        if (plus) Box(Modifier.align(Alignment.BottomCenter).padding(bottom = 46.dp).size(60.dp).clip(CircleShape).background(Color.White).border(1.dp, Color.Black, CircleShape).clickable(indication = null, interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() }) { onPlus() }, contentAlignment = Alignment.Center) {
            Icon(Icons.Default.Add, contentDescription = "Criar", tint = Color.Black,
                modifier = Modifier.size(32.dp)
                    .graphicsLayer(compositingStrategy = androidx.compose.ui.graphics.CompositingStrategy.Offscreen)
                    .drawWithContent {
                        drawContent()
                        drawRect(Brush.linearGradient(listOf(QinblyBrand.Logo, QinblyBrand.Pink)), blendMode = androidx.compose.ui.graphics.BlendMode.SrcIn)
                    })
        }
        if (textStory?.collab == true) {
            Row(Modifier.align(Alignment.TopEnd).padding(8.dp).clip(RoundedCornerShape(12.dp)).background(Color.White).padding(horizontal = 8.dp, vertical = 3.dp), verticalAlignment = Alignment.CenterVertically) { QinblyIconOf(QinblyIcon.Groups, Color(0xFF26215C), 14.dp); Text(" Coletivo", color = Color(0xFF26215C), fontSize = 11.sp, fontWeight = FontWeight.SemiBold) }
            if (collabAvatars.isNotEmpty()) Row(Modifier.align(Alignment.BottomStart).padding(start = 12.dp, bottom = if (showAvatar) 54.dp else 40.dp)) {
                collabAvatars.take(3).forEach { url ->
                    Box(Modifier.padding(end = 0.dp).offset(x = 0.dp).size(24.dp).clip(CircleShape).background(QiblyTheme.soft).border(1.5.dp, Color.White, CircleShape)) {
                        if (url.isNotBlank()) AsyncImage(model = url, contentDescription = null, modifier = Modifier.fillMaxSize(), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
                    }
                    Spacer(Modifier.width(2.dp))
                }
            }
        }
        if (showAvatar) Row(Modifier.align(Alignment.BottomStart).fillMaxWidth().padding(start = 10.dp, end = 10.dp, bottom = 12.dp), verticalAlignment = Alignment.CenterVertically) {
            Box(Modifier.size(34.dp).clip(CircleShape).background(QiblyTheme.soft).border(2.dp, qinblyAccentBrush(), CircleShape), contentAlignment = Alignment.Center) {
                if (avatarUrl.isNotBlank()) AsyncImage(model = avatarUrl, contentDescription = null, modifier = Modifier.fillMaxSize(), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
                else Icon(Icons.Default.Person, contentDescription = null, tint = Color.White.copy(alpha = 0.85f), modifier = Modifier.size(20.dp))
            }
            Spacer(Modifier.width(8.dp))
            Text(label, color = Color.White, fontSize = 16.sp, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, modifier = Modifier.weight(1f))
        } else Text(label, color = Color.White, fontSize = 16.sp, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
            modifier = Modifier.align(Alignment.BottomCenter).padding(start = 4.dp, end = 4.dp, bottom = 12.dp))
    }
}

@Composable
private fun QinblyNoteBubble(note: String, onClick: (() -> Unit)? = null) {
    // Reserva sempre a mesma altura para os avatares da faixa ficarem alinhados, com ou sem nota.
    // O balão pode ser mais largo que a coluna do avatar, assim a nota aparece inteira (até 3 linhas).
    Box(Modifier.height(60.dp).fillMaxWidth(), contentAlignment = Alignment.BottomCenter) {
        if (note.isNotBlank()) {
            Text(note, color = if (QiblyTheme.dark) Color.White else Color(0xFF111111), fontSize = 14.sp, lineHeight = 19.sp, fontWeight = FontWeight.Medium, maxLines = 3, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                modifier = Modifier.offset(y = 6.dp)
                    .clip(RoundedCornerShape(16.dp)).then(if (onClick != null) Modifier.clickable { onClick() } else Modifier).background(if (QiblyTheme.dark) Color(0xFF2C2C2E) else Color(0xFFF0F1F5)).border(1.dp, if (QiblyTheme.dark) Color(0x33FFFFFF) else Color(0xFFDADADD), RoundedCornerShape(16.dp)).padding(horizontal = 10.dp, vertical = 5.dp))
        }
    }
}

@Composable
private fun QiblyAccountAvatar(username: String, fallbackUrl: String, diameter: Dp, storyRing: Boolean = false, displayName: String = "", onClick: () -> Unit) {
    val avatarVersion = qiblyAvatarRefreshVersion.intValue
    val avatarContext = androidx.compose.ui.platform.LocalContext.current
    QinblyAvatarCache.init(avatarContext)
    val key = username.removePrefix("@").trim().lowercase()
    // Lê direto do cache compartilhado: a foto já aparece na primeira tela, sem silhueta nem piscada.
    val resolvedUrl = QinblyAvatarCache.url(key) ?: fallbackUrl
    LaunchedEffect(key, avatarVersion) {
        QinblyAvatarCache.checkVersion(avatarVersion)
        QinblyAvatarCache.seed(key, fallbackUrl)
        if (key.isNotBlank() && !key.contains(".demo") && QinblyAvatarCache.needsFetch(key)) {
            try {
                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                    val result = QinblyApi.getPublicProfile(username)
                    val profile = result.optJSONObject("user") ?: result.optJSONObject("profile") ?: result
                    val image = profile.optString("avatarUrl").ifBlank { profile.optString("avatar_url") }.ifBlank { profile.optString("profilePhotoUrl") }
                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) { QinblyAvatarCache.put(key, image, -1) }
                }
            } catch (_: Exception) {
            } finally {
                QinblyAvatarCache.endFetch(key)
            }
        }
    }
    QinblyStoryRings.version
    val ringUnseen = storyRing && QinblyStoryRings.hasUnseen(key)
    val ringSeen = storyRing && !ringUnseen && QinblyStoryRings.entries[key]?.stories?.isNotEmpty() == true
    val ringOn = ringUnseen || ringSeen
    // clip(CircleShape) antes do clickable: o brilho do toque fica redondo, sem o quadrado transparente em volta da foto.
    Box(Modifier.size(diameter).clip(CircleShape).clickable {
        // Com anel (story novo) a foto abre o story; o nome ao lado continua abrindo o perfil.
        val tray = if (ringOn) QinblyStoryRings.entries[key] else null
        if (tray != null) QinblyStoryRings.openRequest = tray else onClick()
    }, contentAlignment = Alignment.Center) {
        if (ringOn) Box(Modifier.size(diameter).border(2.dp, if (ringUnseen) QinblyBrand.RingBrush else androidx.compose.ui.graphics.SolidColor(Color(0xFF4A4066)), CircleShape))
        Box(Modifier.size(if (ringOn) diameter - 8.dp else diameter).clip(CircleShape).background(QiblyTheme.card)) {
            if (resolvedUrl.isNotBlank()) AsyncImage(model = coil.request.ImageRequest.Builder(avatarContext).data(resolvedUrl).memoryCacheKey("avatar:$username:$avatarVersion:$resolvedUrl").diskCacheKey("avatar:$username:$avatarVersion:$resolvedUrl").build(), contentDescription = "Foto de @$username", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
            else QinblyInitialAvatar(displayName.ifBlank { username }, username)
        }
    }
}

@Composable
private fun ProfilePage(scrollToTopRequest: Int, username: String, displayName: String, bio: String, photoRefreshKey: Int, onNotice: (String) -> Unit, onStat: (String) -> Unit, onAuth: () -> Unit, onEdit: () -> Unit, onEditProfilePhoto: () -> Unit, onSettings: () -> Unit, onSwitchAccounts: () -> Unit) {
    val profileScrollState = rememberScrollState()
    LaunchedEffect(scrollToTopRequest) { if (scrollToTopRequest > 0) profileScrollState.animateScrollTo(0) }
    val snapContext = androidx.compose.ui.platform.LocalContext.current
    // Estado inicial = último perfil carregado (memória) ou, ao abrir o app, o último salvo no aparelho. Evita foto/contadores piscando.
    val snap = remember(username) {
        QinblyCache.own?.takeIf { it.username.equals(username, ignoreCase = true) } ?: run {
            val sp = snapContext.getSharedPreferences("qinbly_profile_snapshot", android.content.Context.MODE_PRIVATE)
            if (sp.getString("username", "").orEmpty().equals(username, ignoreCase = true) && username.isNotBlank()) OwnProfileSnapshot(
                username, sp.getInt("posts", 0), sp.getInt("followers", 0), sp.getInt("following", 0),
                sp.getString("avatar", "").orEmpty(), sp.getString("photo", "").orEmpty(), sp.getString("cover", "").orEmpty(),
                sp.getInt("frame", -1), sp.getString("joined", "").orEmpty(), emptyList()
            ) else null
        }
    }
    var postsCount by remember { mutableIntStateOf(snap?.postsCount ?: 0) }
    var followersCount by remember { mutableIntStateOf(snap?.followers ?: 0) }
    var followingCount by remember { mutableIntStateOf(snap?.following ?: 0) }
    var profilePosts by remember { mutableStateOf<List<QinblyApi.PostSummary>>(snap?.posts ?: emptyList()) }
    var savedPosts by remember { mutableStateOf<List<QinblyApi.PostSummary>>(emptyList()) }
    var loadingSaved by remember { mutableStateOf(false) }
    var reloadKey by remember { mutableIntStateOf(0) }
    var profileTab by remember { mutableStateOf(QinblyProfileJump.tab.also { QinblyProfileJump.tab = null } ?: "Publicações") }
    var loadingPosts by remember { mutableStateOf(snap == null || snap.posts.isEmpty()) }
    var avatarUrl by remember { mutableStateOf(snap?.avatarUrl ?: "") }
    var profilePhotoUrl by remember { mutableStateOf(snap?.profilePhotoUrl ?: "") }
    var profileVerified by remember { mutableStateOf(false) }
    var originalCoverUrl by remember { mutableStateOf(snap?.originalCoverUrl ?: "") }
    var expandedImage by remember { mutableStateOf("") }
    var photoMenuOpen by remember { mutableStateOf(false) }
    var viewerPostId by remember { mutableStateOf<String?>(null) }
    var selectedPublicationCaption by remember { mutableStateOf("") }
    var selectedPublication by remember { mutableStateOf<QinblyApi.PostSummary?>(null) }
    var commentsOpen by remember { mutableStateOf(false) }
    var sharePost by remember { mutableStateOf<QinblyApi.PostSummary?>(null) }

    var publicationComment by remember { mutableStateOf("") }
    var joinedMonthYear by remember { mutableStateOf(snap?.joined ?: "") }

    val shownName = displayName.ifBlank { username }
    val shownBio = bio.lineSequence().filterNot { it.startsWith("🌍 ") }.joinToString("\n").trim()
    val shownCountry = bio.lineSequence().firstOrNull { it.startsWith("🌍 ") }?.removePrefix("🌍 ").orEmpty()
    val profileContext = androidx.compose.ui.platform.LocalContext.current
    val profilePrefs = remember { profileContext.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    LaunchedEffect(profileTab, reloadKey) {
        if (profileTab == "Salvos") {
            val token = profilePrefs.getString("token", null)
            if (token.isNullOrBlank()) { savedPosts = emptyList() } else {
                loadingSaved = true
                Thread {
                    try {
                        val loaded = QinblyApi.getSavedPosts(token)
                        android.os.Handler(android.os.Looper.getMainLooper()).post { QinblyEngagement.learnFromPosts(profilePrefs, loaded); savedPosts = loaded; loadingSaved = false }
                    } catch (e: Exception) {
                        android.os.Handler(android.os.Looper.getMainLooper()).post { loadingSaved = false; onNotice(e.message ?: "Não foi possível carregar seus salvos.") }
                    }
                }.start()
            }
        }
    }
    val openProfileComments: (QinblyApi.PostSummary) -> Unit = { target ->
        selectedPublication = target
        commentsOpen = true
    }

    LaunchedEffect(username, photoRefreshKey, reloadKey) {
        loadingPosts = profilePosts.isEmpty()
        if (username.isNotBlank()) {
            Thread {
                try {
                    val token = profilePrefs.getString("token", "") ?: ""
                    val response = QinblyApi.getPublicProfile(username, token.takeIf { it.isNotBlank() })
                    val user = response.optJSONObject("user") ?: response.optJSONObject("profile") ?: response
                    // Falha no feed de publicações não pode impedir o carregamento da capa do perfil.
                    val loadedPosts = QinblyApi.parsePosts(response.optJSONArray("posts"), user).ifEmpty {
                        // Servidor antigo (sem publicações no perfil): mantém o caminho anterior.
                        try {
                            QinblyApi.getPosts(profilePrefs.getString("token", null)).filter { it.username.equals(username, ignoreCase = true) }
                        } catch (_: Exception) { emptyList() }
                    }
                    android.os.Handler(android.os.Looper.getMainLooper()).post {
                        if (user != null) {
                            val created = listOf("created_at", "createdAt", "joined_at").map { user.optString(it) }.firstOrNull { it.matches(Regex("\\d{4}-\\d{2}.*")) }.orEmpty()
                            joinedMonthYear = if (created.length >= 7) {
                                val month = created.substring(5, 7).toIntOrNull() ?: 0
                                val months = listOf("janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro")
                                if (month in 1..12) "${months[month - 1]} de ${created.substring(0, 4)}" else ""
                            } else ""
                            profileVerified = user.optBoolean("verified")
                            postsCount = user.optInt("posts_count")
                            followersCount = user.optInt("followers")
                            followingCount = user.optInt("following")
                            fun cleanImageValue(value: String): String =
                                value.trim().takeUnless { it.isBlank() || it.equals("null", true) || it.equals("undefined", true) }.orEmpty()
                            val coverPath = cleanImageValue(user.optString("cover_path"))
                            val savedCover = cleanImageValue(user.optString("coverUrl"))
                                .ifBlank { cleanImageValue(user.optString("cover_url")) }
                                .ifBlank {
                                    if (coverPath.startsWith("http")) coverPath else if (coverPath.isNotBlank()) "https://qinbly.pages.dev/storage/v1/object/public/post-media/$coverPath" else ""
                                }
                            avatarUrl = cleanImageValue(user.optString("avatarUrl"))
                                .ifBlank { cleanImageValue(user.optString("avatar_url")) }
                                .ifBlank {
                                    val avatarPath = cleanImageValue(user.optString("avatar_path"))
                                    if (avatarPath.startsWith("http")) avatarPath else if (avatarPath.isNotBlank()) "https://qinbly.pages.dev/storage/v1/object/public/post-media/$avatarPath" else ""
                                }
                            profilePhotoUrl = savedCover.ifBlank {
                                cleanImageValue(user.optString("profilePhotoUrl")).ifBlank { avatarUrl }
                            }
                            val originalPath = cleanImageValue(user.optString("cover_original_path"))
                            originalCoverUrl = cleanImageValue(user.optString("originalCoverUrl")).ifBlank {
                                if (originalPath.startsWith("http")) originalPath else if (originalPath.isNotBlank()) "https://qinbly.pages.dev/storage/v1/object/public/post-media/$originalPath" else ""
                            }
                        }
                        profilePosts = loadedPosts
                        loadingPosts = false
                        val fresh = OwnProfileSnapshot(username, postsCount, followersCount, followingCount, avatarUrl, profilePhotoUrl, originalCoverUrl, -1, joinedMonthYear, loadedPosts)
                        QinblyCache.own = fresh
                        snapContext.getSharedPreferences("qinbly_profile_snapshot", android.content.Context.MODE_PRIVATE).edit()
                            .putString("username", username).putInt("posts", postsCount).putInt("followers", followersCount).putInt("following", followingCount)
                            .putString("avatar", avatarUrl).putString("photo", profilePhotoUrl).putString("cover", originalCoverUrl)
                            .putInt("frame", -1).putString("joined", joinedMonthYear).apply()
                    }
                } catch (_: Exception) {
                    android.os.Handler(android.os.Looper.getMainLooper()).post { loadingPosts = false }
                }
            }.start()
        } else {
            postsCount = 0
            followersCount = 0
            followingCount = 0
            avatarUrl = ""
            profilePosts = emptyList()
            loadingPosts = false
        }
    }

    val profileAccent = QinblyBrand.Accent
    Column(Modifier.fillMaxSize().background(RemoteAppearance.screenBackgroundColor).verticalScroll(profileScrollState), horizontalAlignment = Alignment.CenterHorizontally) {
        Box(Modifier.fillMaxWidth().height(48.dp)) {
            IconButton(onClick = onSettings, modifier = Modifier.align(Alignment.TopEnd).padding(top = 4.dp, end = 12.dp)) {
                Icon(Icons.Default.Menu, contentDescription = "Configurações do perfil", tint = RemoteAppearance.screenTextColor)
            }
        }
        // Cabeçalho: foto à esquerda; ao lado nome, @ · país e os números.
        val ownParts = qinblyBioParts(bio)
        var showTopPosts by remember { mutableStateOf(false) }
        QinblyProfileTop(
            avatar = {
                Box(Modifier.size(92.dp), contentAlignment = Alignment.Center) {
                    if (QinblyStoryRings.hasUnseen(username)) Box(Modifier.size(92.dp).border(3.dp, QinblyBrand.RingBrush, CircleShape))
                    Box(Modifier.size(82.dp).clip(CircleShape).background(QiblyTheme.card).clickable {
                        val image = originalCoverUrl.ifBlank { profilePhotoUrl.ifBlank { avatarUrl } }
                        if (image.isNotBlank()) { expandedImage = image } else if (username.isBlank()) onAuth() else onEditProfilePhoto()
                    }) {
                        val image = profilePhotoUrl.ifBlank { avatarUrl }
                        if (image.isNotBlank()) AsyncImage(model = image, contentDescription = "Foto do perfil", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
                        else if (username.isBlank()) Icon(Icons.Default.Person, contentDescription = "Foto do perfil", tint = RemoteAppearance.screenSecondaryTextColor, modifier = Modifier.fillMaxSize().padding(18.dp))
                        else QinblyInitialAvatar(shownName.ifBlank { username }, username)
                    }
                }
            },
            name = shownName.ifBlank { if (username.isBlank()) "Seu nome" else username },
            verified = profileVerified,
            onHandle = { if (username.isBlank()) onAuth() else onSwitchAccounts() },
            arrow = username.isNotBlank(),
            onAbout = null,
            below = { QinblyProfileStatsInline(likes = profilePosts.sumOf { it.likes }, following = followingCount, followers = followersCount, onFollowing = { onStat("Seguindo") }, onFollowers = { onStat("Seguidores") }, onLikes = if (username.isBlank()) null else ({ showTopPosts = true })) }
        )
        if (showTopPosts) QinblyTopPostsSheet(username.removePrefix("@"), onOpenPost = { id -> QinblyDeepLink.postId = id }) { showTopPosts = false }
        if (username.isBlank()) {
            // Sem conta: só um botão grande de Entrar (leva para entrar ou criar conta).
            QinblyGradientButton(
                onClick = onAuth,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 22.dp).height(52.dp),
                shape = RoundedCornerShape(26.dp),
                colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)
            ) { Text("Entrar", fontSize = 17.sp, fontWeight = FontWeight.SemiBold) }
            Column(Modifier.fillMaxWidth().padding(horizontal = 24.dp, vertical = 36.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                QinblyAccentIcon(Icons.Default.Person, contentDescription = null, modifier = Modifier.size(40.dp))
                Text("Entre para ver seu perfil", Modifier.padding(top = 8.dp), color = RemoteAppearance.screenTextColor, fontSize = 17.sp, fontWeight = FontWeight.SemiBold)
                Text("Publique, salve e converse com a comunidade.", Modifier.padding(top = 4.dp), color = RemoteAppearance.screenSecondaryTextColor, fontSize = 14.sp)
            }
            return@Column
        }
        QinblyProfileBioLeft(ownParts.description, placeholder = "Adicione uma descrição ao seu perfil")
        QinblyProfileLinks(ownParts.links)
        Row(Modifier.fillMaxWidth().padding(start = 16.dp, end = 16.dp, top = 8.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            QinblyGrayButton("Editar perfil", Modifier.weight(1f)) { if (username.isBlank()) onAuth() else onEdit() }
            QinblyGrayButton("Compartilhar perfil", Modifier.weight(1f)) {
                if (username.isBlank()) onAuth() else try {
                    val share = Intent(Intent.ACTION_SEND).apply { type = "text/plain"; putExtra(Intent.EXTRA_TEXT, "Conheça meu perfil no ${QinblyBrand.Name}: @${username.removePrefix("@")}") }
                    snapContext.startActivity(Intent.createChooser(share, "Compartilhar perfil"))
                } catch (_: Exception) { onNotice("Não foi possível abrir o compartilhamento neste aparelho.") }
            }
        }
        QinblyHighlightsRow(username.removePrefix("@"), profilePrefs, mine = true, onNotice = onNotice)
        Spacer(Modifier.height(12.dp))
        // Abas em superfície limpa, separadas por um divisor sutil.
        Row(
            Modifier.fillMaxWidth()
                .background(RemoteAppearance.screenBackgroundColor)
                .padding(top = 4.dp),
            horizontalArrangement = Arrangement.SpaceEvenly
        ) {
            listOf("Publicações", "Vídeos", "Fotos", "Salvos").forEach { item ->
                Column(Modifier.weight(1f).clickable { profileTab = item }.padding(top = 9.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                    // Aba selecionada: ícone preenchido e sublinhado fino na cor do texto.
                    val tabOn = profileTab == item
                    Icon(when(item) {
                        "Vídeos" -> if (tabOn) Icons.Filled.OndemandVideo else Icons.Outlined.OndemandVideo
                        "Fotos" -> if (tabOn) Icons.Default.Image else Icons.Outlined.Image
                        "Salvos" -> if (tabOn) Icons.Default.Bookmark else Icons.Default.BookmarkBorder
                        else -> if (tabOn) Icons.Default.GridView else Icons.Outlined.GridView
                    }, contentDescription = item, tint = RemoteAppearance.screenTextColor, modifier = Modifier.size(27.dp))
                    Spacer(Modifier.height(8.dp))
                    Box(Modifier.fillMaxWidth().height(2.dp).background(if (tabOn) RemoteAppearance.screenTextColor else Color.Transparent))
                }
            }
        }
        Box(Modifier.fillMaxWidth().height(0.5.dp).background(QiblyTheme.border))
        if (profileTab == "Salvos") {
            val shownSaved = savedPosts.filter { QinblyEngagement.isSaved(it) }
            if (loadingSaved && savedPosts.isEmpty()) {
                Box(Modifier.fillMaxWidth().padding(22.dp), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = Pink) }
            } else if (shownSaved.isEmpty()) {
                Box(Modifier.fillMaxWidth().padding(22.dp), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Icon(Icons.Default.BookmarkBorder, contentDescription = null, tint = Violet, modifier = Modifier.size(38.dp))
                        Text("Nenhuma publicação salva", fontWeight = FontWeight.SemiBold, color = RemoteAppearance.screenTextColor)
                        Text("Toque no marcador de uma publicação para guardá-la aqui. Só você vê os seus salvos.", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodySmall)
                    }
                }
            } else {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                    verticalArrangement = Arrangement.spacedBy(0.dp)
                ) {
                    shownSaved.forEach { post ->
                        QinblyPostCard(
                            post = post,
                            prefs = profilePrefs,
                            nameFontStyle = "",
                            onNotice = onNotice,
                            onOpenProfile = { },
                            onOpenViewer = { viewerPostId = it.id },
                            onComment = { openProfileComments(it) },
                            onShare = { sharePost = it },
                            onPostsTransform = { change -> savedPosts = change(savedPosts) },
                            onRefresh = { reloadKey++ }
                        )
                    }
                }
            }
        } else if (loadingPosts) {
            Box(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = Pink) }
        } else if (profilePosts.isEmpty()) {
            Box(Modifier.fillMaxWidth().padding(22.dp), contentAlignment = Alignment.Center) {
                Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Icon(Icons.Default.GridView, contentDescription = null, tint = Violet, modifier = Modifier.size(38.dp))
                    Text("Você ainda não publicou nada", fontWeight = FontWeight.SemiBold, color = RemoteAppearance.screenTextColor)
                    Text("Compartilhe sua primeira publicação com a comunidade.", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodySmall)
                }
            }
        } else {
            val visiblePosts = profilePosts
                .filter { profileTab != "Vídeos" || it.mediaType == "video" }
                .filter { profileTab != "Fotos" || it.mediaType == "image" }
                .sortedByDescending { it.pinned }
            if (profileTab == "Publicações" || profileTab == "Vídeos") {
                // Lista vertical de publicações mistas; "Vídeos" usa o mesmo cartão/player da tela de início, sem modificar o cabeçalho ou as demais abas.
                Column(
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                    verticalArrangement = Arrangement.spacedBy(0.dp)
                ) {
                    visiblePosts.forEach { post ->
                        QinblyPostCard(
                            post = post,
                            prefs = profilePrefs,
                            nameFontStyle = "",
                            onNotice = onNotice,
                            onOpenProfile = { },
                            onOpenViewer = { viewerPostId = it.id },
                            onComment = { openProfileComments(it) },
                            onShare = { sharePost = it },
                            onPostsTransform = { change -> profilePosts = change(profilePosts); postsCount = profilePosts.size },
                            onRefresh = { reloadKey++ }
                        )
                    }
                }
            } else {
                LazyVerticalGrid(columns = GridCells.Fixed(3), modifier = Modifier.fillMaxWidth().heightIn(max = 560.dp), contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp), horizontalArrangement = Arrangement.spacedBy(4.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    items(visiblePosts.size) { index ->
                        val post = visiblePosts[index]
                        Box(Modifier.fillMaxWidth().height(145.dp).clip(RoundedCornerShape(8.dp)).background(qinblyPlaceholderColor).clickable { if (post.mediaUrl.isNotBlank()) viewerPostId = post.id }) {
                            if (post.mediaUrl.isNotBlank() && post.mediaType != "video") QinblyFaceThumb(post.mediaUrl, Modifier.fillMaxSize(), 0.75f, "Publicação")
                            else if (post.mediaUrl.isNotBlank()) AsyncImage(model = post.mediaUrl, contentDescription = "Publicação", modifier = Modifier.fillMaxSize(), contentScale = androidx.compose.ui.layout.ContentScale.Crop)
                            else {
                                val tileBg = if (post.mediaType == "text") qinblyTextBgBrush(post.textBg) else null
                                if (tileBg != null) Box(Modifier.fillMaxSize().background(tileBg), contentAlignment = Alignment.Center) {
                                    Text(qinblySplitCaption(post.caption).first.ifBlank { post.caption }, color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 12.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center, modifier = Modifier.padding(8.dp), maxLines = 5, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                                }
                                else Text(post.caption.ifBlank { QinblyBrand.Name }, color = RemoteAppearance.screenTextColor, modifier = Modifier.align(Alignment.Center).padding(8.dp), maxLines = 4)
                            }
                            if (post.mediaType == "video") Icon(Icons.Default.PlayCircle, contentDescription = "Vídeo", tint = RemoteAppearance.screenTextColor, modifier = Modifier.align(Alignment.TopEnd).padding(5.dp))
                        }
                    }
                }
            }
        }
    }

    if (expandedImage.isNotBlank()) QinblyPhotoViewer(expandedImage, onNotice, onDismiss = { expandedImage = "" })

    viewerPostId?.let { startId ->
        val viewable = qinblyViewerList((if (profileTab == "Salvos") savedPosts else profilePosts).filter { it.mediaType != "poll" && (it.mediaUrl.isNotBlank() || it.mediaUrls.isNotEmpty()) }, startId)
        if (viewable.any { it.id == startId }) {
            QinblyPostViewer(
                posts = viewable,
                startPostId = startId,
                prefs = profilePrefs,
                currentUsername = username,
                onNotice = onNotice,
                onDismiss = { viewerPostId = null },
                onComment = { openProfileComments(it) },
                onShare = { sharePost = it },
                onOpenProfile = { viewerPostId = null }
            )
        }
    }
    sharePost?.let { target ->
        QiblyShareDialog(post = target, prefs = profilePrefs, onDismiss = { sharePost = null }, onNotice = onNotice)
    }
    if (commentsOpen) {
        selectedPublication?.let { target ->
            QinblyCommentsDialog(
                post = target,
                prefs = profilePrefs,
                currentUsername = username,
                onNotice = onNotice,
                onDismiss = { commentsOpen = false },
                onCountChanged = { postId, count ->
                    profilePosts = profilePosts.map { if (it.id == postId && it.comments != count) it.copy(comments = count) else it }
                    savedPosts = savedPosts.map { if (it.id == postId && it.comments != count) it.copy(comments = count) else it }
                    if (selectedPublication?.id == postId) selectedPublication = selectedPublication?.copy(comments = count)
                }
            )
        }
    }

}
@Composable
private fun AuthPage(onSuccess: (String) -> Unit, onCancel: () -> Unit) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    var createAccount by remember { mutableStateOf(false) }
    var showForgot by remember { mutableStateOf(false) }
    // Voltar do celular: da tela de criar conta volta para o login (não fecha tudo).
    BackHandler(enabled = createAccount && !showForgot) { createAccount = false }
    var forgotInput by remember { mutableStateOf("") }
    var forgotBusy by remember { mutableStateOf(false) }
    var forgotSent by remember { mutableStateOf(false) }
    var forgotError by remember { mutableStateOf("") }
    var forgotCooldown by remember { mutableStateOf(0) }
    // Voltar do celular na tela de esqueci a senha volta para o login.
    BackHandler(enabled = showForgot && !forgotBusy) { showForgot = false; forgotSent = false; forgotError = "" }
    androidx.compose.runtime.LaunchedEffect(forgotSent, forgotCooldown) {
        if (forgotSent && forgotCooldown > 0) { kotlinx.coroutines.delay(1000); forgotCooldown -= 1 }
    }
    val sendForgot: () -> Unit = {
        val typed = forgotInput.trim().lowercase()
        val valid = if (typed.contains("@")) typed.substringAfter("@", "").contains(".") && typed.substringBefore("@").isNotEmpty()
            else typed.removePrefix("@").matches(Regex("[a-z0-9_.]{3,30}"))
        if (typed.isBlank()) forgotError = "Digite seu e-mail ou nome de usuário."
        else if (!valid) forgotError = "Confira o e-mail ou nome de usuário digitado."
        else {
            forgotBusy = true
            forgotError = ""
            Thread {
                try {
                    QinblyApi.forgotPassword(typed)
                    android.os.Handler(android.os.Looper.getMainLooper()).post { forgotBusy = false; forgotSent = true; forgotCooldown = 60 }
                } catch (e: Exception) {
                    android.os.Handler(android.os.Looper.getMainLooper()).post { forgotBusy = false; forgotError = e.message ?: "Não foi possível enviar agora." }
                }
            }.start()
        }
    }
    var username by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var error by remember { mutableStateOf("") }
    var googleError by remember { mutableStateOf("") }
    var loading by remember { mutableStateOf(false) }
    // Clear stale profile-photo errors when opening authentication.
    androidx.compose.runtime.LaunchedEffect(Unit) { error = ""; googleError = "" }
    val googleSignInLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.StartActivityForResult()
    ) { result ->
        val activity = context as? android.app.Activity
        if (activity == null) {
            loading = false
            googleError = "Não foi possível concluir o login Google."
        } else {
            kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main).launch {
                try {
                    val idToken = GoogleSignIn.idTokenFromResult(result.data)
                    val auth = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                        QinblyApi.authenticateWithGoogle(idToken)
                    }
                    prefs.edit().putString("token", auth.token).putString("refresh_token", auth.refreshToken).putString("username", auth.username).apply()
                    rememberQinblyAccount(prefs, auth.username, auth.token, prefs.getString("display_name", "") ?: "", prefs.getString("bio", "") ?: "")
                    loading = false
                    onSuccess(auth.username)
                } catch (e: Exception) {
                    loading = false
                    val authMessage = e.message?.takeIf { it.isNotBlank() } ?: "Erro de autenticação sem detalhes retornados."
                    googleError = authMessage
                    error = ""
                }
            }
        }
    }

    // Erro do Google vira um aviso curto que some sozinho (nada de quadro fixo na tela).
    androidx.compose.runtime.LaunchedEffect(googleError) {
        if (googleError.isNotBlank()) {
            android.widget.Toast.makeText(context, googleError, android.widget.Toast.LENGTH_LONG).show()
            googleError = ""
        }
    }
    val startGoogle: () -> Unit = {
        val activity = context as? android.app.Activity
        if (activity == null) {
            googleError = "Não foi possível abrir a seleção da conta Google."
        } else {
            loading = true
            error = ""
            googleError = ""
            GoogleSignIn.signOut(activity) {
                try {
                    googleSignInLauncher.launch(GoogleSignIn.signInIntent(activity))
                } catch (e: Exception) {
                    loading = false
                    googleError = e.message ?: "Não foi possível abrir o login Google."
                }
            }
        }
    }
    val submit: () -> Unit = {
        // Entrar aceita e-mail OU nome de usuário; criar conta pede e-mail e nome de usuário.
        val typed = email.trim().lowercase()
        val looksLikeEmail = typed.contains("@") && typed.substringAfter("@", "").contains(".")
        when {
            typed.isBlank() -> error = if (createAccount) "Digite seu e-mail." else "Digite seu e-mail ou nome de usuário."
            createAccount && !looksLikeEmail -> error = "Digite um e-mail válido."
            !createAccount && typed.contains("@") && !looksLikeEmail -> error = "Digite um e-mail válido."
            !createAccount && !typed.contains("@") && !typed.removePrefix("@").matches(Regex("[A-Za-z0-9_.]{3,30}")) -> error = "Nome de usuário inválido. Use letras, números, ponto ou sublinhado."
            password.length < 8 && createAccount -> error = "A senha precisa ter pelo menos 8 caracteres."
            password.isBlank() -> error = "Digite sua senha."
            createAccount && username.trim().length < 3 -> error = "O nome de usuário precisa ter 3 caracteres ou mais."
            createAccount && !username.matches(Regex("[A-Za-z0-9_.]{3,24}")) -> error = "Use 3–24 caracteres: letras, números, ponto ou sublinhado."
            else -> {
                loading = true
                error = ""
                Thread {
                    try {
                        val result = QinblyApi.authenticate(createAccount, username, typed, password)
                        prefs.edit().putString("token", result.token).putString("refresh_token", result.refreshToken).putString("username", result.username).apply()
                        rememberQinblyAccount(prefs, result.username, result.token, prefs.getString("display_name", "") ?: "", prefs.getString("bio", "") ?: "")
                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                            loading = false
                            onSuccess(result.username)
                        }
                    } catch (e: Exception) {
                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                            loading = false
                            error = e.message ?: "Não foi possível autenticar."
                        }
                    }
                }.start()
            }
        }
    }

    if (showForgot) QinblyForgotScreen(
        input = forgotInput, onInput = { forgotInput = it.trim().take(120); forgotError = "" }, busy = forgotBusy, sent = forgotSent,
        error = forgotError, cooldown = forgotCooldown, onSend = sendForgot,
        onBack = { showForgot = false; forgotSent = false; forgotError = "" }
    ) else Column(Modifier.fillMaxSize().background(Night)) {
        Column(
            Modifier.weight(1f).verticalScroll(rememberScrollState()).padding(horizontal = 24.dp).padding(top = 8.dp, bottom = 12.dp)
        ) {
            IconButton(onClick = onCancel, enabled = !loading) {
                Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text)
            }
            Column(Modifier.fillMaxWidth().padding(top = 4.dp, bottom = 22.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                QinblyAuthLogo()
                Text(if (createAccount) "Crie sua conta" else "Bem-vindo", color = QiblyTheme.text, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Medium)
                Spacer(Modifier.height(6.dp))
                Text(if (createAccount) "Leva menos de um minuto." else "Entre para continuar", color = QiblyTheme.secondary, style = MaterialTheme.typography.bodyMedium)
            }

            val emailOk = email.contains("@") && email.substringAfter("@", "").contains(".")
            val userLenBad = username.isNotEmpty() && username.length !in 3..24
            val userCharsBad = username.isNotEmpty() && !userLenBad && !username.matches(Regex("[A-Za-z0-9_.]+"))
            val passTooShort = createAccount && password.isNotEmpty() && password.length < 8
            QinblyAuthField(
                value = email,
                onValueChange = { email = it.trim() },
                hint = if (createAccount) "E-mail" else "E-mail ou nome de usuário",
                icon = if (createAccount) Icons.Outlined.Email else Icons.Outlined.PersonOutline,
                enabled = !loading,
                keyboardType = androidx.compose.ui.text.input.KeyboardType.Email,
                valid = createAccount && emailOk
            )
            if (createAccount) {
                Spacer(Modifier.height(10.dp))
                QinblyAuthField(
                    value = username,
                    onValueChange = { username = it.trim().replace(" ", "") },
                    hint = "Nome de usuário",
                    icon = Icons.Outlined.AlternateEmail,
                    enabled = !loading,
                    invalid = userLenBad || userCharsBad,
                    valid = username.isNotEmpty() && !userLenBad && !userCharsBad
                )
                if (userLenBad) QinblyAuthWarning("Use de 3 a 24 caracteres.")
                else if (userCharsBad) QinblyAuthWarning("Use só letras, números, ponto ou sublinhado.")
            }
            Spacer(Modifier.height(10.dp))
            QinblyAuthField(
                value = password,
                onValueChange = { password = it },
                hint = "Senha",
                icon = Icons.Outlined.Lock,
                enabled = !loading,
                password = true,
                invalid = passTooShort
            )
            if (passTooShort) QinblyAuthWarning("Mínimo de 8 caracteres.")

            if (error.isNotBlank()) Text(error, color = Color(0xFFF09595), style = MaterialTheme.typography.bodySmall, modifier = Modifier.fillMaxWidth().padding(start = 6.dp, top = 10.dp))
            Spacer(Modifier.height(14.dp))
            QinblyAuthButton(if (createAccount) "Criar conta" else "Entrar", onClick = submit, enabled = !loading, loading = loading, fill = QinblyBrand.Accent)
            if (!createAccount) TextButton(
                onClick = { forgotInput = email.trim(); forgotSent = false; forgotError = ""; forgotCooldown = 0; showForgot = true },
                modifier = Modifier.fillMaxWidth(),
                enabled = !loading
            ) { Text("Esqueceu a senha?", color = QiblyTheme.text, style = MaterialTheme.typography.bodyMedium) }

            Row(Modifier.fillMaxWidth().padding(top = if (createAccount) 18.dp else 8.dp, bottom = 14.dp), verticalAlignment = Alignment.CenterVertically) {
                androidx.compose.material3.HorizontalDivider(Modifier.weight(1f), color = QiblyTheme.border)
                Text("  OU  ", color = QiblyTheme.secondary, style = MaterialTheme.typography.labelMedium)
                androidx.compose.material3.HorizontalDivider(Modifier.weight(1f), color = QiblyTheme.border)
            }
            QinblyAuthButton(
                if (createAccount) "Cadastrar com Google" else "Continuar com Google",
                onClick = startGoogle, enabled = !loading, fill = Color.White, contentColor = Color(0xFF1B1B1F),
                leading = { QinblyGoogleMark() }
            )
            if (createAccount) Text(
                "Ao criar a conta, você concorda com os Termos de uso e a Política de privacidade (em Configurações, Ajuda e suporte).",
                color = QiblyTheme.secondary, style = MaterialTheme.typography.labelMedium, textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                modifier = Modifier.fillMaxWidth().padding(top = 18.dp)
            )
        }
        QinblyAuthButton(
            if (createAccount) "Já tenho uma conta" else "Criar nova conta",
            onClick = { createAccount = !createAccount; error = "" },
            enabled = !loading, outline = QinblyBrand.Accent, contentColor = QinblyBrand.AccentLight,
            modifier = Modifier.padding(horizontal = 24.dp).padding(top = 8.dp, bottom = 16.dp).navigationBarsPadding()
        )
    }
}

@OptIn(androidx.compose.foundation.layout.ExperimentalLayoutApi::class)
@Composable
private fun EditProfilePage(initialUsername: String, initialName: String, initialBio: String, photoRefreshKey: Int, onEditProfilePhoto: () -> Unit, onBack: () -> Unit, onSaved: (String, String, String) -> Unit, onNotice: (String) -> Unit) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    var editPhotoUrl by remember { mutableStateOf("") }
    // Ao ir escolher a foto, o que a pessoa já digitou fica guardado; ao sair da edição de verdade, limpa.
    androidx.compose.runtime.LaunchedEffect(Unit) { QinblyKeep.state("editphoto.flag", false).value = false }
    androidx.compose.runtime.DisposableEffect(Unit) {
        onDispose { if (!QinblyKeep.state("editphoto.flag", false).value) QinblyKeep.clearPrefix("editprofile.") }
    }
    LaunchedEffect(initialUsername, photoRefreshKey) {
        if (initialUsername.isNotBlank()) {
            Thread {
                try {
                    val token = prefs.getString("token", "").orEmpty()
                    val response = if (token.isNotBlank()) {
                        try { QinblyApi.getMyProfile(token) } catch (_: Exception) { QinblyApi.getPublicProfile(initialUsername) }
                    } else QinblyApi.getPublicProfile(initialUsername)
                    val user = response.optJSONObject("user") ?: response.optJSONObject("profile") ?: response
                    fun clean(value: String): String = value.trim().takeUnless { it.isBlank() || it.equals("null", true) || it.equals("undefined", true) }.orEmpty()
                    fun resolve(value: String): String {
                        val v = clean(value)
                        return if (v.startsWith("http")) v else if (v.isNotBlank()) "https://qinbly.pages.dev/storage/v1/object/public/post-media/${v.removePrefix("post-media/")}" else ""
                    }
                    val photo = listOf(
                        clean(user.optString("coverUrl")), clean(user.optString("cover_url")),
                        clean(user.optString("profilePhotoUrl")), clean(user.optString("profile_photo_url")),
                        resolve(user.optString("cover_path")),
                        clean(user.optString("avatarUrl")), clean(user.optString("avatar_url")),
                        resolve(user.optString("avatar_path"))
                    ).firstOrNull { it.startsWith("http") }.orEmpty()
                    android.os.Handler(android.os.Looper.getMainLooper()).post { editPhotoUrl = photo }
                } catch (_: Exception) {
                    try {
                        val user = QinblyApi.getPublicProfile(initialUsername).let { it.optJSONObject("user") ?: it.optJSONObject("profile") ?: it }
                        val image = listOf("coverUrl", "cover_url", "avatarUrl", "avatar_url").map { user.optString(it) }.firstOrNull { it.startsWith("http") }.orEmpty()
                        android.os.Handler(android.os.Looper.getMainLooper()).post { editPhotoUrl = image }
                    } catch (_: Exception) { }
                }
            }.start()
        }
    }
    val countryOptions = listOf("Brasil", "Portugal", "Estados Unidos", "Argentina", "Chile", "Colômbia", "México", "Espanha", "França", "Alemanha", "Itália", "Reino Unido", "Canadá", "Japão", "Angola", "Moçambique", "Outro")
    val initialParts = qinblyBioParts(initialBio)
    val initialCountry = initialParts.country
    var selectedCountry by rememberKept("editprofile.country", initialCountry)
    var countryMenuExpanded by remember { mutableStateOf(false) }
    var username by rememberKept("editprofile.username", initialUsername)
    var name by rememberKept("editprofile.name", initialName)
    var bio by rememberKept("editprofile.bio", initialParts.description)
    var links by rememberKept("editprofile.links", initialParts.links)
    var loading by remember { mutableStateOf(false) }
    var error by remember { mutableStateOf("") }
    var adjustingImage by remember { mutableStateOf("") }
    var cropRatio by remember { mutableStateOf("16:10") }
    var imageFilter by remember { mutableStateOf("Original") }

    val effectOptions = listOf("Original", "Vivo", "Neon", "Quente", "Frio", "Preto e branco", "Cinema", "Retrô", "Brilho", "Contraste", "Saturação", "Fade", "Glow", "Desfoque", "VHS", "Granulado", "Vinheta")
    val saveProfile: () -> Unit = {
                    if (name.isBlank()) error = "Informe seu nome."
                    else if (links.map { qinblyCleanLink(it) }.filter { it.isNotBlank() }.any { !it.contains('.') || it.startsWith('.') || it.endsWith('.') }) error = "Um dos links não parece certo. Use algo como meusite.com."
                    else {
                        loading = true; error = ""
                        val token = prefs.getString("token", null)
                        Thread {
                            try {
                                if (token.isNullOrBlank()) {
                                    android.os.Handler(android.os.Looper.getMainLooper()).post {
                                        loading = false
                                        error = "Entre na sua conta para salvar as alterações."
                                    }
                                    return@Thread
                                }
                                val composedBio = qinblyComposeBio(bio, "", links.map { qinblyCleanLink(it) }.filter { it.isNotBlank() }.take(3))
                                QinblyApi.updateProfile(token, username.trim(), name.trim(), composedBio)
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    loading = false
                                    onSaved(username.trim(), name.trim(), composedBio)
                                    onNotice("Informações do perfil atualizadas.")
                                }
                            } catch (e: Exception) {
                                android.os.Handler(android.os.Looper.getMainLooper()).post { loading = false; error = e.message ?: "Não foi possível salvar no servidor." }
                            }
                        }.start()
                    }
    }
    Column(Modifier.fillMaxSize().background(Night).padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Row(Modifier.fillMaxWidth().padding(top = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            IconButton(onClick = onBack, enabled = !loading) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text) }
            Text("Editar perfil", modifier = Modifier.weight(1f), style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold, color = QiblyTheme.text)
            QinblyGradientButton(
                onClick = saveProfile,
                enabled = !loading,
                shape = RoundedCornerShape(24.dp),
                colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White),
                contentPadding = PaddingValues(horizontal = 20.dp, vertical = 9.dp)
            ) {
                if (loading) CircularProgressIndicator(Modifier.size(18.dp), color = Color.White, strokeWidth = 2.dp) else Text("Salvar", color = Color.White, fontWeight = FontWeight.SemiBold)
            }
        }

        Column(Modifier.fillMaxWidth().weight(1f).verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            Box(Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 4.dp), contentAlignment = Alignment.Center) {
                Box(Modifier.size(116.dp).clip(CircleShape).background(QiblyTheme.card).clickable { QinblyKeep.state("editphoto.flag", false).value = true; onEditProfilePhoto() }, contentAlignment = Alignment.Center) {
                    if (editPhotoUrl.isNotBlank()) {
                        AsyncImage(model = editPhotoUrl, contentDescription = "Alterar foto de perfil", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
                    } else {
                        Icon(Icons.Default.Person, contentDescription = "Foto de perfil", tint = RemoteAppearance.screenSecondaryTextColor, modifier = Modifier.size(54.dp))
                    }
                    Box(Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.12f)), contentAlignment = Alignment.Center) {
                        Icon(Icons.Default.CameraAlt, contentDescription = "Trocar foto de perfil", tint = Color.White.copy(alpha = 0.58f), modifier = Modifier.size(27.dp))
                    }
                }
            }
            QinblyAccentText("Alterar foto", fontWeight = FontWeight.Medium, fontSize = 14.sp,
                modifier = Modifier.fillMaxWidth().clickable { QinblyKeep.state("editphoto.flag", false).value = true; onEditProfilePhoto() }, textAlign = androidx.compose.ui.text.style.TextAlign.Center)

            Text("SOBRE VOCÊ", color = Muted, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.SemiBold)

            @Composable
            fun editCard(icon: androidx.compose.ui.graphics.vector.ImageVector, label: String, value: String, hint: String, onValue: (String) -> Unit, singleLine: Boolean = true, max: Int = 80, centered: Boolean = false, sanitize: (String) -> String = { it }) {
                var field by remember { mutableStateOf(androidx.compose.ui.text.input.TextFieldValue(value, androidx.compose.ui.text.TextRange(value.length))) }
                if (field.text != value) field = androidx.compose.ui.text.input.TextFieldValue(value, androidx.compose.ui.text.TextRange(minOf(field.selection.end, value.length)))
                Row(
                    Modifier.fillMaxWidth().clip(RoundedCornerShape(14.dp))
                        .border(BorderStroke(1.dp, QiblyTheme.border), RoundedCornerShape(14.dp))
                        .padding(horizontal = 14.dp, vertical = if (singleLine) 10.dp else 12.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        Text(label, color = Muted, style = MaterialTheme.typography.labelMedium)
                        androidx.compose.foundation.text.BasicTextField(
                            value = field,
                            onValueChange = { typed ->
                                val clean = qinblySanitized(typed) { sanitize(it).take(max) }
                                field = clean
                                onValue(clean.text)
                            },
                            enabled = !loading,
                            singleLine = singleLine,
                            textStyle = androidx.compose.ui.text.TextStyle(color = RemoteAppearance.screenTextColor, fontSize = 16.sp, textAlign = if (centered) androidx.compose.ui.text.style.TextAlign.Center else androidx.compose.ui.text.style.TextAlign.Start),
                            cursorBrush = androidx.compose.ui.graphics.SolidColor(QinblyBrand.Accent),
                            modifier = Modifier.fillMaxWidth(),
                            decorationBox = { inner ->
                                Box {
                                    if (value.isEmpty()) Text(hint, color = Muted.copy(alpha = 0.8f), style = MaterialTheme.typography.bodyMedium)
                                    inner()
                                }
                            }
                        )
                        if (!singleLine) Text("${value.length}/300", color = Muted, style = MaterialTheme.typography.labelSmall, modifier = Modifier.align(Alignment.End))
                    }
                }
            }

            editCard(Icons.Default.Person, "Nome", name, "Seu nome", { name = it }, max = 80)
            editCard(Icons.Default.Description, "Bio", bio, "Escreva uma breve descrição sobre você", { bio = it }, singleLine = false, max = 150)
            // Links (até 3).
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text("Links", color = RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold, fontSize = 14.sp, modifier = Modifier.weight(1f))
                QinblyAccentText("${links.size} de 3", fontWeight = FontWeight.Medium, style = MaterialTheme.typography.labelMedium)
            }
            links.forEachIndexed { i, link ->
                Row(
                    Modifier.fillMaxWidth().clip(RoundedCornerShape(14.dp))
                        .border(BorderStroke(1.dp, QiblyTheme.border), RoundedCornerShape(14.dp))
                        .padding(start = 14.dp, end = 6.dp, top = 4.dp, bottom = 4.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    QinblyAccentIcon(Icons.Default.Link, contentDescription = null, modifier = Modifier.size(20.dp))
                    androidx.compose.foundation.text.BasicTextField(
                        value = link,
                        onValueChange = { typed -> links = links.toMutableList().also { it[i] = qinblyCleanLink(typed) } },
                        enabled = !loading,
                        singleLine = true,
                        textStyle = androidx.compose.ui.text.TextStyle(color = QinblyBrand.Accent, fontSize = 16.sp),
                        cursorBrush = androidx.compose.ui.graphics.SolidColor(QinblyBrand.Accent),
                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(keyboardType = androidx.compose.ui.text.input.KeyboardType.Uri),
                        modifier = Modifier.weight(1f).padding(horizontal = 10.dp, vertical = 10.dp),
                        decorationBox = { inner ->
                            Box {
                                if (link.isEmpty()) Text("meusite.com", color = Muted.copy(alpha = 0.8f), fontSize = 16.sp)
                                inner()
                            }
                        }
                    )
                    IconButton(onClick = { links = links.filterIndexed { idx, _ -> idx != i } }, enabled = !loading) {
                        Icon(Icons.Default.Close, contentDescription = "Remover link", tint = Muted)
                    }
                }
            }
            if (links.size < 3) Row(
                Modifier.fillMaxWidth().clip(RoundedCornerShape(14.dp)).clickable(enabled = !loading) { links = links + "" }.padding(vertical = 8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                QinblyAccentIcon(Icons.Default.Add, contentDescription = null, modifier = Modifier.size(20.dp))
                QinblyAccentText("Adicionar link", fontWeight = FontWeight.Medium, fontSize = 15.sp, modifier = Modifier.padding(start = 8.dp))
            }
            if (error.isNotBlank()) Text(error, color = Pink, style = MaterialTheme.typography.bodySmall)
        }
    }
}

@Composable
private fun EditProfilePhotoPage(onBack: () -> Unit, onSaved: () -> Unit, onNotice: (String) -> Unit) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember { context.getSharedPreferences("qinbly_session", android.content.Context.MODE_PRIVATE).byAccount() }
    var selectedProfilePhoto by remember { mutableStateOf<Uri?>(null) }
    var loading by remember { mutableStateOf(false) }
    var error by remember { mutableStateOf("") }
    var dragX by remember { mutableFloatStateOf(0f) }
    var dragY by remember { mutableFloatStateOf(0f) }
    var profilePhotoScale by remember { mutableFloatStateOf(1f) }
    val density = androidx.compose.ui.platform.LocalDensity.current
    val screenWidthDp = androidx.compose.ui.platform.LocalConfiguration.current.screenWidthDp
    val previewWidthPx = with(density) { (screenWidthDp - 16).coerceAtLeast(1).dp.toPx() }
    val previewHeightPx = previewWidthPx
    val profilePhotoPicker = rememberQinblyPhotoLauncher { uri ->
        if (uri != null) {
            selectedProfilePhoto = uri
            dragX = 0f
            dragY = 0f
            profilePhotoScale = 1f
            error = ""
        } else if (selectedProfilePhoto == null) {
            // Fechou a galeria sem escolher nada: volta direto para a tela anterior (sem tela vazia no meio).
            onBack()
        }
    }

    LaunchedEffect(Unit) { profilePhotoPicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)) }

    // Enquadramento automático: a foto já abre preenchendo o círculo e centrada no rosto, sem passar do zoom em que ainda fica nítida.
    LaunchedEffect(selectedProfilePhoto) {
        val uri = selectedProfilePhoto ?: return@LaunchedEffect
        val info = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { qinblyPhotoInfo(context, uri) } ?: return@LaunchedEffect
        val w = previewWidthPx
        val iw = info.width.toFloat(); val ih = info.height.toFloat()
        val fit = minOf(w / iw, w / ih)
        val cover = maxOf(w / iw, w / ih) / fit
        // Nitidez: a parte da foto que aparece no círculo precisa ter pelo menos 1080 px (tamanho da imagem salva).
        val sharpMax = maxOf(cover, minOf(4f, w / (fit * 1080f)))
        val scale = if (info.hasFace && info.faceW > 0.01f) (0.45f * w / (info.faceW * iw * fit)).coerceIn(cover, sharpMax) else cover
        val fgW = iw * fit * scale; val fgH = ih * fit * scale
        val maxX = maxOf(0f, (fgW - w) / 2f); val maxY = maxOf(0f, (fgH - w) / 2f)
        profilePhotoScale = scale
        dragX = (-(info.faceCx - 0.5f) * fgW).coerceIn(-maxX, maxX)
        dragY = (-(info.faceCy - 0.5f) * fgH).coerceIn(-maxY, maxY)
    }

    Column(Modifier.fillMaxSize().background(Color.Black)) {
        Row(
            Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack, enabled = !loading) {
                Icon(Icons.Default.ArrowBack, contentDescription = "Cancelar e voltar", tint = QiblyTheme.text)
            }
            Text(
                "Arraste para ajustar",
                modifier = Modifier.weight(1f),
                color = QiblyTheme.text,
                fontWeight = FontWeight.SemiBold,
                style = MaterialTheme.typography.titleMedium,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center
            )
            IconButton(
                onClick = { if (selectedProfilePhoto != null && !loading) {
                    // O botão superior confirma a mesma ação do botão Salvar inferior.
                    error = ""
                } },
                enabled = selectedProfilePhoto != null && !loading
            ) {
                Icon(Icons.Default.CheckCircle, contentDescription = "Confirmar ajuste", tint = QiblyTheme.text)
            }
        }

        Box(
            Modifier.fillMaxWidth().weight(1f),
            contentAlignment = Alignment.Center
        ) {
            if (selectedProfilePhoto != null) {
                Box(
                    Modifier.fillMaxWidth().padding(horizontal = 8.dp).aspectRatio(1f)
                        .clip(CircleShape)
                        .background(Color(0xFF101010))
                        .pointerInput(selectedProfilePhoto) {
                            detectTransformGestures { centroid, pan, zoom, _ ->
                                // Permite arrastar e ampliar/reduzir a foto para ajustar o enquadramento 16:9.
                                // Sem limite de zoom: a pessoa amplia até onde quiser (só o enquadramento automático inicial respeita a nitidez).
                                profilePhotoScale = (profilePhotoScale * zoom).coerceIn(0.5f, 100f)
                                dragX += pan.x
                                dragY += pan.y
                            }
                        },
                    contentAlignment = Alignment.Center
                ) {
                    // Fundo de preenchimento: ocupa a foto inteira, sem faixas pretas.
                    AsyncImage(
                        model = selectedProfilePhoto,
                        contentDescription = null,
                        modifier = Modifier.fillMaxSize(),
                        contentScale = ContentScale.Crop
                    )
                    Box(Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.28f)))
                    // Foto completa por cima: preserva toda a imagem e permite movê-la livremente.
                    AsyncImage(
                        model = selectedProfilePhoto,
                        contentDescription = "Foto completa sobre a foto do perfil em formato amplo; arraste livremente",
                        modifier = Modifier.fillMaxSize().graphicsLayer {
                            translationX = dragX
                            translationY = dragY
                            scaleX = profilePhotoScale
                            scaleY = profilePhotoScale
                        },
                        contentScale = ContentScale.Fit
                    )
                    Box(Modifier.fillMaxSize().border(2.dp, Color.White.copy(alpha = 0.75f), CircleShape))
                }
            } else {
                Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Icon(Icons.Default.CameraAlt, contentDescription = null, tint = Color.White, modifier = Modifier.size(36.dp))
                    Text("Escolha uma foto para ajustar", color = QiblyTheme.text, fontWeight = FontWeight.Medium)
                    OutlinedButton(onClick = { profilePhotoPicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)) }) {
                        Text("Escolher imagem", color = QiblyTheme.text)
                    }
                }
            }
        }

        if (error.isNotBlank()) {
            Text(error, Modifier.fillMaxWidth().padding(horizontal = 20.dp, vertical = 4.dp), color = Pink, style = MaterialTheme.typography.bodySmall)
        }

        Row(
            Modifier.fillMaxWidth().padding(start = 20.dp, end = 20.dp, top = 12.dp, bottom = 24.dp),
            horizontalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            OutlinedButton(
                onClick = onBack,
                enabled = !loading,
                modifier = Modifier.weight(1f).height(54.dp),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, Color.White),
                colors = ButtonDefaults.outlinedButtonColors(contentColor = Color.White)
            ) {
                Text("Cancelar", fontWeight = FontWeight.SemiBold)
            }
            QinblyGradientButton(
                onClick = {
                    val uri = selectedProfilePhoto
                    val token = prefs.getString("token", null)
                    if (uri == null) {
                        error = "Escolha uma imagem para ajustar."
                    } else if (token.isNullOrBlank()) {
                        error = "Entre na sua conta para alterar a foto."
                    } else {
                        loading = true
                        error = ""
                        val x = dragX
                        val y = dragY
                        val scale = profilePhotoScale
                        val previewW = previewWidthPx
                        val previewH = previewHeightPx
                        Thread {
                            var source: Bitmap? = null
                            var output: Bitmap? = null
                            try {
                                // Salva exatamente o enquadramento mostrado no editor, na mesma proporção 16:9 da capa.
                                source = context.contentResolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it) }
                                    ?: throw IllegalStateException("Não foi possível abrir a imagem.")
                                source = qinblyUpright(context, uri, source!!)
                                val outW = 1080
                                val outH = 1080
                                output = Bitmap.createBitmap(outW, outH, Bitmap.Config.ARGB_8888)
                                val canvas = Canvas(output!!)
                                val paint = Paint(Paint.ANTI_ALIAS_FLAG or Paint.FILTER_BITMAP_FLAG)
                                // Camada de fundo: mesmo comportamento ContentScale.Crop da prévia.
                                val bgScale = maxOf(outW.toFloat() / source!!.width, outH.toFloat() / source!!.height)
                                val bgW = source!!.width * bgScale
                                val bgH = source!!.height * bgScale
                                canvas.drawBitmap(source!!, null, android.graphics.RectF((outW-bgW)/2f, (outH-bgH)/2f, (outW+bgW)/2f, (outH+bgH)/2f), paint)
                                canvas.drawColor(android.graphics.Color.argb(71, 0, 0, 0))
                                // Camada principal: mesmo ContentScale.Fit, zoom e arrasto escolhidos pela pessoa.
                                val fitScale = minOf(outW.toFloat() / source!!.width, outH.toFloat() / source!!.height) * scale
                                val fgW = source!!.width * fitScale
                                val fgH = source!!.height * fitScale
                                val left = (outW - fgW) / 2f + x * outW / previewW
                                val top = (outH - fgH) / 2f + y * outH / previewH
                                canvas.drawBitmap(source!!, null, android.graphics.RectF(left, top, left + fgW, top + fgH), paint)
                                val outFile = File(context.cacheDir, "qinbly-profile-square.jpg")
                                FileOutputStream(outFile).use { stream -> output!!.compress(Bitmap.CompressFormat.JPEG, 94, stream) }
                                // Guarda a foto original separadamente para que tocar na capa abra a imagem completa.
                                QinblyApi.uploadProfileImage(context, token, uri, "cover_original")
                                // A capa visível no perfil continua usando exatamente o enquadramento escolhido.
                                QinblyApi.uploadProfileImage(context, token, Uri.fromFile(outFile), "cover")
                                // Existe UMA só foto de perfil: o servidor usa esta mesma imagem em todas as telas e publicações.
                                outFile.delete()
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    loading = false
                                    onSaved()
                                }
                            } catch (e: Exception) {
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    loading = false
                                    error = e.message?.takeIf { it.isNotBlank() } ?: "Falha ao salvar a imagem da capa."
                                }
                            } finally {
                                source?.recycle()
                                output?.recycle()
                            }
                        }.start()
                    }
                },
                enabled = !loading && selectedProfilePhoto != null,
                modifier = Modifier.weight(1f).height(54.dp),
                shape = RoundedCornerShape(16.dp),
                colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)
            ) {
                if (loading) CircularProgressIndicator(Modifier.size(18.dp), color = QiblyTheme.text, strokeWidth = 2.dp)
                else Text("Salvar", fontWeight = FontWeight.SemiBold)
            }
        }
    }
}

private fun nameFontFamily(style: String): androidx.compose.ui.text.font.FontFamily = when (style) {
    "Moderna" -> androidx.compose.ui.text.font.FontFamily.SansSerif
    "Elegante" -> androidx.compose.ui.text.font.FontFamily.Cursive
    "Clássica" -> androidx.compose.ui.text.font.FontFamily.Serif
    "Monoespaçada", "Tecnológica" -> androidx.compose.ui.text.font.FontFamily.Monospace
    "Minimalista", "SF Pro (similar)" -> androidx.compose.ui.text.font.FontFamily.SansSerif
    "Arredondada" -> androidx.compose.ui.text.font.FontFamily.SansSerif
    else -> androidx.compose.ui.text.font.FontFamily.SansSerif // SF Pro (similar) usa a alternativa nativa do Android.
}

@Composable
private fun SettingsPage(prefs: android.content.SharedPreferences, username: String, nameFontStyle: String, appFontStyle: String, onAppFontChange: (String) -> Unit, onNameFontChange: (String) -> Unit, onBack: () -> Unit, onNotice: (String) -> Unit, onEditProfile: () -> Unit, onAuth: () -> Unit, onSwitchAccounts: () -> Unit, onLogout: () -> Unit, onOpenConversation: (String) -> Unit = {}) {
    val context = androidx.compose.ui.platform.LocalContext.current
    var section by remember { mutableStateOf("home") }
    var fontSection by remember { mutableStateOf("names") }
    BackHandler {
        if (section == "font_names" || section == "font_app") section = "appearance" else if (section != "home") section = "home" else onBack()
    }
    var search by remember { mutableStateOf("") }
    var notifications by remember { mutableStateOf(prefs.getBoolean("setting_notifications", true)) }
    var autoplay by remember { mutableStateOf(prefs.getBoolean("setting_autoplay", true)) }
    var allowComments by remember { mutableStateOf(prefs.getBoolean("setting_comments", true)) }
    var likesNotice by remember { mutableStateOf(prefs.getBoolean("setting_notice_likes", true)) }
    var commentsNotice by remember { mutableStateOf(prefs.getBoolean("setting_notice_comments", true)) }
    var followersNotice by remember { mutableStateOf(prefs.getBoolean("setting_notice_followers", true)) }
    var mentionsNotice by remember { mutableStateOf(prefs.getBoolean("setting_notice_mentions", true)) }
    var systemNotice by remember { mutableStateOf(prefs.getBoolean("setting_notice_system", true)) }

    var cacheTick by remember { mutableIntStateOf(0) }
    val cacheSizeLabel = remember(cacheTick) { val b = runCatching { context.cacheDir.walkTopDown().filter { it.isFile }.sumOf { it.length() } }.getOrDefault(0L); if (b < 1024 * 1024) "${b / 1024} KB" else String.format(java.util.Locale.US, "%.1f MB", b / 1048576.0) }
    var showBlockedAccounts by remember { mutableStateOf(false) }
    var showMutedAccounts by remember { mutableStateOf(false) }
    var showCredential by remember { mutableStateOf("") }
    var showLegal by remember { mutableStateOf("") }
    var showClearLocation by remember { mutableStateOf(false) }
    var showHiddenWords by remember { mutableStateOf(false) }
    if (showCredential.isNotBlank()) QinblyCredentialScreen(showCredential, prefs, { showCredential = "" }, onNotice)
    if (showLegal.isNotBlank()) QinblyLegalScreen(showLegal) { showLegal = "" }
    if (showClearLocation) QinblyClearLocationScreen(prefs, { showClearLocation = false }, onNotice)
    if (showHiddenWords) QinblyHiddenWordsScreen(prefs) { showHiddenWords = false }
    var showAccountAbout by remember { mutableStateOf(false) }
    if (showAccountAbout) {
        val snap = context.getSharedPreferences("qinbly_profile_snapshot", android.content.Context.MODE_PRIVATE)
        val joinedLabel = if (snap.getString("username", "").orEmpty().removePrefix("@") == username.removePrefix("@")) snap.getString("joined", "").orEmpty() else ""
        QinblyProfileAbout(joinedLabel, qinblyBioParts(prefs.getString("bio", "").orEmpty()).country) { showAccountAbout = false }
    }
    var showDeleteAccount by remember { mutableStateOf(false) }
    var deleteConfirmText by remember { mutableStateOf("") }
    var deletingAccount by remember { mutableStateOf(false) }
    if (showBlockedAccounts) BlockedAccountsDialog(prefs = prefs, onDismiss = { showBlockedAccounts = false }, onNotice = onNotice)
    if (showMutedAccounts) BlockedAccountsDialog(prefs = prefs, onDismiss = { showMutedAccounts = false }, onNotice = onNotice, muted = true)
    if (showDeleteAccount) {
        AlertDialog(
        shape = RoundedCornerShape(28.dp),
            onDismissRequest = { if (!deletingAccount) showDeleteAccount = false },
            title = { Text("Excluir conta definitivamente?") },
            text = { QinblyClearFocusWhenKeyboardCloses();
                Column {
                    Text("Seu perfil, publicações, comentários, curtidas, mensagens e arquivos serão apagados e não poderão ser recuperados. Para confirmar, digite o seu nome de usuário: " + username.removePrefix("@"))
                    OutlinedTextField(
                        value = deleteConfirmText,
                        onValueChange = { deleteConfirmText = it },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth().padding(top = 12.dp)
                    )
                }
            },
            confirmButton = {
                TextButton(enabled = !deletingAccount && deleteConfirmText.trim().isNotEmpty(), onClick = {
                    val token = prefs.getString("token", null)
                    if (token.isNullOrBlank()) onNotice("Entre na sua conta para excluí-la.")
                    else {
                        deletingAccount = true
                        Thread {
                            try {
                                QinblyApi.deleteAccount(token, deleteConfirmText.trim())
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    deletingAccount = false
                                    showDeleteAccount = false
                                    deleteConfirmText = ""
                                    onNotice("Sua conta foi excluída.")
                                    onLogout()
                                }
                            } catch (e: Exception) {
                                android.os.Handler(android.os.Looper.getMainLooper()).post { deletingAccount = false; onNotice(e.message ?: "Não foi possível excluir a conta agora.") }
                            }
                        }.start()
                    }
                }) { Text(if (deletingAccount) "Excluindo…" else "Excluir", color = Color.Red) }
            },
            dismissButton = { TextButton(enabled = !deletingAccount, onClick = { showDeleteAccount = false }) { Text("Cancelar", color = Pink) } },
            containerColor = QiblyTheme.dialog, titleContentColor = QiblyTheme.text, textContentColor = QiblyTheme.text
        )
    }

    fun exportAccountData() {
        val token = prefs.getString("token", null)
        if (token.isNullOrBlank()) {
            onNotice("Entre na sua conta antes de exportar os dados.")
            return
        }
        onNotice("Preparando a exportação dos seus dados…")
        Thread {
            try {
                val json = QinblyApi.exportMyData(token).toString(2)
                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    try {
                        val share = Intent(Intent.ACTION_SEND).apply {
                            type = "application/json"
                            putExtra(Intent.EXTRA_SUBJECT, "Meus dados do ${QinblyBrand.Name}")
                            putExtra(Intent.EXTRA_TEXT, json)
                        }
                        context.startActivity(Intent.createChooser(share, "Salvar ou compartilhar seus dados"))
                        onNotice("Exportação preparada. Escolha um aplicativo para salvar o arquivo.")
                    } catch (_: Exception) {
                        onNotice("Os dados foram obtidos, mas não foi possível abrir o compartilhamento.")
                    }
                }
            } catch (e: Exception) {
                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    onNotice(e.message ?: "Não foi possível exportar seus dados.")
                }
            }
        }.start()
    }

    val title = when (section) {
        "account" -> "Conta"
        "privacy" -> "Privacidade"
        "location" -> "Localização"
        "appearance" -> "Tela"
        "font_names" -> "Fonte dos nomes"
        "font_app" -> "Fonte do aplicativo"
        "content" -> "Conteúdo"
        "lives" -> "Lives e transmissão"
        "storage" -> "Dados e armazenamento"
        "help" -> "Ajuda e suporte"
        "camera_settings" -> "Publicações"
        "messages_settings" -> "Mensagens"
        "friends_settings" -> "Amigos e seguidores"
        "accessibility" -> "Acessibilidade"
        "moderation" -> "Segurança e moderação"
        "activity_history" -> "Atividade e histórico"
        "account_management" -> "Gerenciamento de contas"
        else -> "Configurações"
    }
    Column(Modifier.fillMaxSize().background(QiblyTheme.background).padding(horizontal = 12.dp, vertical = 8.dp)) {
        Row(Modifier.fillMaxWidth().padding(bottom = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            IconButton(onClick = { if (section == "font_names" || section == "font_app") section = "appearance" else if (section == "home") onBack() else section = "home" }) {
                Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = RemoteAppearance.screenTextColor)
            }
            Column(Modifier.weight(1f)) {
                Text(title, fontSize = 18.sp, fontWeight = FontWeight.SemiBold, color = RemoteAppearance.screenTextColor)
                Text(if (section == "home") "Gerencie sua conta e sua experiência" else "Personalize sua experiência no ${QinblyBrand.Name}", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodySmall)
            }
        }
        if (section == "home") {
            Surface(color = QiblyTheme.card, shape = RoundedCornerShape(24.dp), modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp).border(1.dp, QiblyTheme.border, RoundedCornerShape(16.dp))) {
                Row(Modifier.padding(horizontal = 13.dp, vertical = 11.dp), verticalAlignment = Alignment.CenterVertically) {
                    QinblyAccentIcon(Icons.Default.Search, contentDescription = null)
                    Spacer(Modifier.width(10.dp))
                    androidx.compose.foundation.text.BasicTextField(
                        value = search, onValueChange = { search = it }, singleLine = true,
                        textStyle = androidx.compose.ui.text.TextStyle(color = RemoteAppearance.screenTextColor, fontSize = 16.sp),
                        cursorBrush = Brush.horizontalGradient(listOf(QinblyBrand.Accent, QinblyBrand.AccentDeep)), modifier = Modifier.fillMaxWidth(),
                        decorationBox = { inner -> Box { if (search.isBlank()) Text("Buscar configurações...", color = RemoteAppearance.screenSecondaryTextColor); inner() } }
                    )
                }
            }
        }
        LazyColumn(modifier = Modifier.fillMaxSize(), verticalArrangement = Arrangement.spacedBy(2.dp), contentPadding = PaddingValues(bottom = 24.dp)) {
            if (section == "home") {
                item { Text("CONFIGURAÇÕES", color = QiblyTheme.hint, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.SemiBold) }
                val categories = listOf(
                    Triple("account", "Conta", "Senha, e-mail, aparelhos e exclusão"),
                    Triple("privacy", "Privacidade", "Quem vê, quem fala com você e bloqueios"),
                    Triple("location", "Localização", "Usar a localização e apagar o que foi guardado"),
                    Triple("content", "Conteúdo", "Palavras ocultas e salvar no celular"),
                    Triple("appearance", "Tela", "Tema escuro e fontes"),
                    Triple("accessibility", "Acessibilidade", "Texto maior e menos animações"),
                    Triple("storage", "Dados e armazenamento", "Cache e seus dados"),
                    Triple("invite", "Convidar amigos", "Compartilhe o ${QinblyBrand.Name}"),
                    Triple("help", "Ajuda e suporte", "Termos, privacidade, sobre e atualizações")
                ).filter { it.second.contains(search, true) || it.third.contains(search, true) }
                val loggedIn = username.isNotBlank() && !prefs.getString("token", null).isNullOrBlank()
                val accountActionMatches = search.isBlank() ||
                    "Alternar entre suas contas".contains(search, true) ||
                    "Sair".contains(search, true) ||
                    "Login".contains(search, true)
                categories.forEach { category ->
                    item {
                        val icon = when (category.first) {
                            "account" -> Icons.Outlined.PersonOutline
                            "privacy" -> Icons.Outlined.Lock
                            "location" -> Icons.Outlined.LocationOn
                            "content" -> Icons.Outlined.Tune
                            "feed" -> Icons.Outlined.PlayCircleOutline
                            "appearance" -> Icons.Outlined.DarkMode
                            "accessibility" -> Icons.Outlined.Accessibility
                            "storage" -> Icons.Outlined.Storage
                            "invite" -> Icons.Outlined.PersonAddAlt1
                            else -> Icons.Outlined.HelpOutline
                        }
                        SettingsLink(category.second, category.third, icon) {
                            if (category.first == "invite") {
                                try {
                                    val share = Intent(Intent.ACTION_SEND).apply { type = "text/plain"; putExtra(Intent.EXTRA_TEXT, "Venha para o ${QinblyBrand.Name}! Baixe o app e me siga: @${username}") }
                                    context.startActivity(Intent.createChooser(share, "Convidar amigos"))
                                } catch (_: Exception) { onNotice("Não foi possível abrir o compartilhamento neste aparelho.") }
                            } else section = category.first
                        }
                    }
                }
                if (loggedIn && (search.isBlank() || "Alternar entre suas contas".contains(search, true))) {
                }
                if (loggedIn && (search.isBlank() || "Sair".contains(search, true) || "Encerrar sessão".contains(search, true))) {
                    item { SettingsLink("Sair", "Encerrar a sessão neste dispositivo", Icons.Outlined.Logout) { onLogout() } }
                }
                if (!loggedIn && accountActionMatches) {
                    item {
                        Surface(color = Panel, shape = RoundedCornerShape(18.dp), modifier = Modifier.fillMaxWidth()) {
                            Column(Modifier.padding(18.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                Icon(Icons.Default.Person, contentDescription = null, tint = Violet, modifier = Modifier.size(42.dp))
                                Text("Faça login para acessar mais opções", color = RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold)
                                Text("Entre na sua conta para personalizar sua experiência e salvar suas preferências.", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodySmall)
                                Button(onClick = onAuth, colors = ButtonDefaults.buttonColors(containerColor = Pink), modifier = Modifier.fillMaxWidth()) {
                                    Text("Login", color = RemoteAppearance.screenTextColor, fontWeight = FontWeight.SemiBold)
                                }
                            }
                        }
                    }
                }
                if (categories.isEmpty() && !accountActionMatches) item { Text("Nenhuma configuração encontrada.", color = RemoteAppearance.screenSecondaryTextColor, modifier = Modifier.padding(16.dp)) }
            } else when (section) {
                "account" -> {
                    item { Text(if (username.isBlank()) "Nenhuma conta conectada" else "Conta atual: @$username", color = RemoteAppearance.screenSecondaryTextColor, modifier = Modifier.padding(vertical = 6.dp)) }
                    item { Box(Modifier.padding(vertical = 6.dp)) { QinblyVerificationCard(prefs.getString("token", "").orEmpty(), onNotice) } }
                    item { Text("SEGURANÇA", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 8.dp, bottom = 2.dp)) }
                    item { SettingsLink("Trocar senha", "Escolher uma senha nova", Icons.Outlined.Password) { showCredential = "password" } }
                    item { SettingsLink("Trocar e-mail", "Mudar o e-mail da conta", Icons.Outlined.Email) { showCredential = "email" } }
                    item { SettingsLink("Sair de outros aparelhos", "Encerra a sessão em todos os outros aparelhos", Icons.Outlined.Devices) {
                        val tk = prefs.getString("token", null)
                        if (tk.isNullOrBlank()) onNotice("Entre na sua conta primeiro.")
                        else Thread {
                            val msg = try { QinblyApi.signOutOtherDevices(tk); "Pronto: os outros aparelhos foram desconectados." } catch (e: Exception) { e.message ?: "Não foi possível desconectar agora." }
                            android.os.Handler(android.os.Looper.getMainLooper()).post { onNotice(msg) }
                        }.start()
                    } }
                    item { Text("CONTA", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 12.dp, bottom = 2.dp)) }
                    item { SettingsLink("Sobre esta conta", "Data de entrada e país", Icons.Outlined.Info) { if (username.isBlank()) onNotice("Entre na sua conta primeiro.") else showAccountAbout = true } }
                    item { SettingsLink("Compartilhar perfil", "Convide amigos para conhecer seu perfil", Icons.Outlined.Share) {
                        try {
                            val share = Intent(Intent.ACTION_SEND).apply { type = "text/plain"; putExtra(Intent.EXTRA_TEXT, "Conheça meu perfil no ${QinblyBrand.Name}: @${username}") }
                            context.startActivity(Intent.createChooser(share, "Compartilhar perfil"))
                        } catch (_: Exception) { onNotice("Não foi possível abrir o compartilhamento neste aparelho.") }
                    } }
                    item { SettingsLink("Excluir conta", "Apagar sua conta e seus dados definitivamente", Icons.Outlined.DeleteOutline) { deleteConfirmText = ""; showDeleteAccount = true } }
                }
                "privacy" -> {
                    item { QinblyAccountPrivacyControls(prefs, onNotice) }
                    item { Text("QUEM VÊ SEUS STORIES (PADRÃO)", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 8.dp, bottom = 2.dp)) }
                    item {
                        var chosen by remember { mutableStateOf(prefs.getString("story_default_audience", "all") ?: "all") }
                        Column {
                            listOf("all" to "Todos", "friends" to "Amigos (quem você segue e te segue)", "followers" to "Seguidores", "near" to "Perto de você (sua cidade)").forEach { (key, label) ->
                                val on = chosen == key
                                Row(Modifier.fillMaxWidth().clickable { chosen = key; prefs.edit().putString("story_default_audience", key).apply() }.padding(horizontal = 8.dp, vertical = 12.dp), verticalAlignment = Alignment.CenterVertically) {
                                    Icon(if (on) Icons.Default.RadioButtonChecked else Icons.Default.RadioButtonUnchecked, contentDescription = null, tint = if (on) QinblyBrand.Accent else Muted, modifier = Modifier.size(22.dp))
                                    Spacer(Modifier.width(14.dp))
                                    Text(label, color = QiblyTheme.text, fontSize = 16.sp)
                                }
                            }
                            Text("Em cada story você ainda pode mudar isso antes de publicar.", color = Muted, fontSize = 12.sp, modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp))
                        }
                    }
                    item { Text("ATIVIDADE", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 14.dp, bottom = 2.dp)) }
                    item { VideoPrefSwitch("Mostrar que estou online", "Você aparece na lista de pessoas online", "setting_activity_status", true, prefs, Icons.Outlined.Sensors) }
                    item { SettingsLink("Contas bloqueadas", "Gerenciar quem você bloqueou", Icons.Outlined.Block) { showBlockedAccounts = true } }
                    item { SettingsLink("Contas silenciadas", "Quem você parou de ver no feed", Icons.Outlined.NotificationsOff) { showMutedAccounts = true } }
                }
                "location" -> {
                    item { VideoPrefSwitch("Usar minha localização", "Para saber sua cidade. Desligado, o app não pede sua posição", "setting_location_enabled", true, prefs, Icons.Outlined.LocationOn) }
                    item { Text("O QUE FICA GUARDADO", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 14.dp, bottom = 2.dp)) }
                    item { Text("A cidade do seu perfil e a posição de cada aviso que você publicou no Mural.", color = Muted, fontSize = 14.sp, modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)) }
                    item { SettingsLink("Apagar dados de localização", "Remove seus avisos do Mural e a cidade guardada", Icons.Outlined.DeleteOutline) { showClearLocation = true } }
                }
                "content" -> {
                    item { Text("FILTROS", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 8.dp, bottom = 2.dp)) }
                    item { SettingsLink("Palavras ocultas", "Esconde comentários que tenham estas palavras", Icons.Outlined.VisibilityOff) { showHiddenWords = true } }
                    item { Text("AO PUBLICAR", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 14.dp, bottom = 2.dp)) }
                    item { VideoPrefSwitch("Salvar no celular", "Guardar uma cópia no celular em cada publicação nova", "setting_save_default", false, prefs, Icons.Outlined.PhoneAndroid) }
                }
                "appearance" -> {
                    item { Text("TEMA", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(bottom = 2.dp)) }
                    item {
                        SettingSwitch(
                            "Modo escuro",
                            if (QiblyTheme.dark) "Tema escuro ativado" else "Tema claro ativado",
                            QiblyTheme.dark,
                            Icons.Outlined.Brightness4
                        ) { enabled ->
                            QiblyTheme.dark = enabled
                            prefs.edit().putString("setting_theme", if (enabled) "dark" else "light").apply()
                            (context as? android.app.Activity)?.let { qinblySetSplashTheme(it, enabled) }
                        }
                    }
                    item { Text("FONTES", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(top = 14.dp, bottom = 2.dp)) }
                    item { SettingsLink("Fonte dos nomes", "Personalize os nomes dos usuários", Icons.Outlined.Badge) { section = "font_names" } }
                    item { SettingsLink("Fonte do aplicativo", "Personalize os menus, títulos e botões", Icons.Outlined.FontDownload) { section = "font_app" } }
                }
                "font_names", "font_app" -> {
                    item { Text(if (section == "font_names") "Escolha como os nomes aparecem no feed." else "Altera títulos, menus e botões. Não altera mensagens, legendas ou comentários dos usuários.", color = RemoteAppearance.screenSecondaryTextColor, style = MaterialTheme.typography.bodySmall) }
                    val options = listOf("Padrão", "SF Pro (similar)", "Moderna", "Elegante", "Clássica", "Monoespaçada", "Negrito", "Minimalista", "Arredondada", "Tecnológica")
                    items(options) { option ->
                        val selected = if (section == "font_names") nameFontStyle == option else appFontStyle == option
                        Row(Modifier.fillMaxWidth().clickable { if (section == "font_names") onNameFontChange(option) else onAppFontChange(option) }.padding(vertical = 14.dp, horizontal = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                            Text(if (section == "font_names") "Ana Lima" else QinblyBrand.Name, fontFamily = nameFontFamily(option), fontSize = 18.sp, fontWeight = if (option == "Negrito") FontWeight.ExtraBold else FontWeight.Medium, color = RemoteAppearance.screenTextColor, modifier = Modifier.weight(1f))
                            Text(option, color = if (selected) QinblyBrand.Accent else RemoteAppearance.screenSecondaryTextColor, fontSize = 14.sp)
                            Spacer(Modifier.width(12.dp))
                            Icon(if (selected) Icons.Default.RadioButtonChecked else Icons.Default.RadioButtonUnchecked, contentDescription = null, tint = if (selected) QinblyBrand.Accent else Muted, modifier = Modifier.size(20.dp))
                        }
                        androidx.compose.material3.HorizontalDivider(color = QiblyTheme.border, thickness = 0.5.dp)
                    }
                }
                "accessibility" -> {
                    item {
                        var large by remember { mutableStateOf(QiblyTheme.largeText) }
                        SettingSwitch("Texto maior", "Aumenta as letras do aplicativo todo", large, Icons.Outlined.FormatSize) {
                            large = it; QiblyTheme.largeText = it; prefs.edit().putBoolean("setting_large_text", it).apply()
                        }
                    }
                    item {
                        var calm by remember { mutableStateOf(QiblyTheme.reduceMotion) }
                        SettingSwitch("Reduzir animações", "Menos efeitos, como o coração ao curtir", calm, Icons.Outlined.SlowMotionVideo) {
                            calm = it; QiblyTheme.reduceMotion = it; prefs.edit().putBoolean("setting_reduce_motion", it).apply()
                        }
                    }
                }
                "storage" -> {
                    item { SettingsLink("Limpar cache", "Apagar arquivos temporários (${cacheSizeLabel})", Icons.Outlined.CleaningServices) { Thread { val ok = runCatching { context.cacheDir.deleteRecursively(); context.codeCacheDir.deleteRecursively(); true }.getOrDefault(false); android.os.Handler(android.os.Looper.getMainLooper()).post { cacheTick++; onNotice(if (ok) "Cache temporário limpo." else "Não foi possível limpar todo o cache.") } }.start() } }
                    item { SettingsLink("Baixar seus dados", "Exportar seus dados da conta", Icons.Outlined.FileDownload) { exportAccountData() } }
                }
                else -> {
                    item { SettingsLink("Reportar um problema", "Enviar um relato por e-mail ou aplicativo", Icons.Outlined.Flag) { try { val report = Intent(Intent.ACTION_SENDTO).apply { data = android.net.Uri.parse("mailto:"); putExtra(Intent.EXTRA_SUBJECT, "Relato de problema — ${QinblyBrand.Name}"); putExtra(Intent.EXTRA_TEXT, "Descreva o problema encontrado:\n\nVersão: 0.3.0\nDispositivo: " + android.os.Build.MANUFACTURER + " " + android.os.Build.MODEL) }; context.startActivity(Intent.createChooser(report, "Reportar problema")) } catch (_: Exception) { onNotice("Não há aplicativo de e-mail disponível neste aparelho.") } } }
                    item { SettingsLink("Termos de uso", "Regras para usar o ${QinblyBrand.Name}", Icons.Outlined.Gavel) { showLegal = "terms" } }
                    item { SettingsLink("Política de privacidade", "Quais dados guardamos e por quê", Icons.Outlined.PrivacyTip) { showLegal = "privacy" } }
                    item { SettingsLink("Sobre o ${QinblyBrand.Name}", "Versão ${BuildConfig.VERSION_NAME}", Icons.Outlined.Info) { onNotice("${QinblyBrand.Name} versão ${BuildConfig.VERSION_NAME}.") } }
                    item { SettingsLink("Atualizações do aplicativo", "Verificar e baixar o APK mais recente", Icons.Outlined.SystemUpdate) { context.startActivity(Intent(context, RemoteUiActivity::class.java)) } }
                }
            }
        }
    }
}
private fun settingOptionIcon(title: String): androidx.compose.ui.graphics.vector.ImageVector = when {
    title.contains("vídeo", true) || title.contains("reprodução", true) || title.contains("áudio", true) -> Icons.Default.PlayCircle
    title.contains("foto", true) || title.contains("câmera", true) || title.contains("galeria", true) -> Icons.Default.CameraAlt
    title.contains("mensag", true) || title.contains("coment", true) || title.contains("digitação", true) -> Icons.Default.ChatBubbleOutline
    title.contains("seguidor", true) || title.contains("contato", true) || title.contains("amigo", true) -> Icons.Default.People
    title.contains("download", true) || title.contains("dados", true) || title.contains("Wi-Fi", true) -> Icons.Default.FileDownload
    title.contains("legenda", true) || title.contains("texto", true) -> Icons.Default.TextFields
    title.contains("notifica", true) || title.contains("silenci", true) -> Icons.Default.Notifications
    title.contains("privad", true) || title.contains("bloque", true) || title.contains("sensível", true) -> Icons.Default.Lock
    title.contains("compartilh", true) || title.contains("remix", true) -> Icons.Default.Share
    title.contains("movimento", true) || title.contains("efeitos", true) -> Icons.Default.Visibility
    title.contains("rascunho", true) || title.contains("salvar", true) -> Icons.Default.BookmarkBorder
    else -> Icons.Default.Settings
}

@Composable
private fun VideoPrefSwitch(title: String, subtitle: String, key: String, default: Boolean, prefs: android.content.SharedPreferences, icon: ImageVector) {
    var checked by remember(key) { mutableStateOf(prefs.getBoolean(key, default)) }
    SettingSwitch(title, subtitle, checked, icon) {
        checked = it
        prefs.edit().putBoolean(key, it).apply()
    }
}

@Composable
private fun LocalSettingSwitch(title: String, key: String, prefs: android.content.SharedPreferences) {
    var checked by remember(key) { mutableStateOf(prefs.getBoolean(key, false)) }
    SettingSwitch(title, "Preferência salva neste aparelho", checked, settingOptionIcon(title)) {
        checked = it
        prefs.edit().putBoolean(key, it).apply()
    }
}

@Composable
private fun SettingsLink(title: String, subtitle: String, icon: androidx.compose.ui.graphics.vector.ImageVector, onClick: () -> Unit) {
    Column(modifier = Modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier.fillMaxWidth().clickable(onClick = onClick)
                .padding(horizontal = 8.dp, vertical = 11.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(Modifier.size(34.dp), contentAlignment = Alignment.Center) { Icon(icon, contentDescription = null, tint = QiblyTheme.text, modifier = Modifier.size(24.dp)) }
            Column(Modifier.weight(1f).padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                Text(title, fontWeight = FontWeight.Medium, color = QiblyTheme.text, fontSize = 16.sp)
                Text(subtitle, color = Muted, fontSize = 12.sp, lineHeight = 16.sp)
            }
            QinblyIconOf(QinblyIcon.KeyboardArrowRight, Muted, 26.dp)
        }
        androidx.compose.material3.HorizontalDivider(color = QiblyTheme.border, thickness = 0.5.dp)
    }
}

@Composable
private fun InfoPanel(title: String, message: String) {
    Surface(color = QiblyTheme.card, shape = RoundedCornerShape(14.dp), modifier = Modifier.fillMaxWidth()) {
        Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            Text(title, fontWeight = FontWeight.SemiBold)
