    var narrating by remember { mutableStateOf(false) }
    val narrationPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) narrating = true else onNotice("Permita o microfone para gravar a narração.")
    }
    var speedChoice by remember { mutableFloatStateOf(1f) }
    var latestThumb by remember { mutableStateOf<Bitmap?>(null) }
    val soundPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri ->
        if (uri != null) {
            var label = "Som escolhido"
            try {
                context.contentResolver.query(uri, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null)?.use { c ->
                    if (c.moveToFirst()) label = c.getString(0)?.substringBeforeLast('.') ?: label
                }
            } catch (_: Exception) { }
            soundName = label
            soundUri = uri
            storyMusic = null
            cameraSheet = ""
            onNotice("Som escolhido. Ele será misturado ao vídeo que você gravar.")
        }
    }
    var showComposer by remember { mutableStateOf(false) }
    var publishSettings by remember { mutableStateOf(false) }
    var editorTool by remember { mutableStateOf("Filtros") }
    var swipeFilterLabel by remember { mutableStateOf("") }
    LaunchedEffect(swipeFilterLabel) { if (swipeFilterLabel.isNotBlank()) { kotlinx.coroutines.delay(900); swipeFilterLabel = "" } }
    var storyHours by remember { mutableIntStateOf(24) }
    var storyAudience by remember { mutableStateOf(prefs.getString("story_default_audience", "all") ?: "all") }
    var storyAlsoFeed by remember { mutableStateOf(false) }
