    var photoVideoPending by remember { mutableStateOf<List<Uri>>(emptyList()) }
    val photoVideoClips = remember { mutableStateListOf<PvClip>() }
    val addVideoPhotos = rememberQinblyMultiPhotoLauncher(20) { uris ->
        if (uris.isNotEmpty()) photoVideoPending = uris
    }
    val cameraPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        cameraGranted = granted
        if (!granted) cameraError = "Permita o acesso à câmera para usar a câmera do ${QinblyBrand.Name}."
    }
    val galleryPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { results ->
        val granted = results.values.any { it }
        if (granted) {
            galleryAssets = emptyList()
            galleryOpen = true
        } else {
            onNotice("Permita o acesso às fotos e vídeos para abrir a galeria do ${QinblyBrand.Name}.")
        }
    }
    // Texto direto na tela (mesmo jeito do modo TEXTO da câmera): escreve em cima da foto, com fonte e cor embaixo.
    @Composable
    fun EditorTextOverlay(onDone: () -> Unit) {
        // Sem janela (Dialog) própria: igual ao texto da câmera, que já sobe certinho com o teclado.
        // A janela separada não recebia o tamanho do teclado e a barra de cores ficava escondida atrás dele.
        BackHandler { onDone() }
        val focus = remember { FocusRequester() }
        val keyboard = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current
        LaunchedEffect(Unit) { focus.requestFocus(); keyboard?.show() }
        val noRipple = remember { androidx.compose.foundation.interaction.MutableInteractionSource() }
        val imeUp = androidx.compose.foundation.layout.WindowInsets.ime.getBottom(androidx.compose.ui.platform.LocalDensity.current) > 0
        // Teclado fechado: a barra fica ACIMA do 6h/12h/24h; teclado aberto: logo acima do teclado.
        val closedBottom = 175.dp
        Box(Modifier.fillMaxSize().zIndex(20f).background(Color(0x99000000))) {
            Column(
                Modifier.fillMaxSize().clickable(indication = null, interactionSource = noRipple) { keyboard?.hide(); onDone() }.imePadding().padding(bottom = if (imeUp) QinblyKeyboardGap else closedBottom),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Box(Modifier.weight(1f).fillMaxWidth().padding(horizontal = 24.dp), contentAlignment = Alignment.Center) {
                    androidx.compose.foundation.text.BasicTextField(
                        value = editorText,
                        onValueChange = { editorText = it.take(120) },
                        textStyle = androidx.compose.ui.text.TextStyle(
                            color = Color(editorTextColor), fontSize = 24.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                            fontFamily = androidx.compose.ui.text.font.FontFamily(qinblyTypeface(editorTextFont)),
                            letterSpacing = qinblyTextSpacingEm(editorTextFont).em,
                            shadow = androidx.compose.ui.graphics.Shadow(Color(0xCC000000), blurRadius = 10f)
                        ),
                        cursorBrush = androidx.compose.ui.graphics.SolidColor(Color.White),
                        // Chave explícita nas cores: a cor escolhida embaixo aparece NA HORA no letreiro, também com o teclado aberto.
                        visualTransformation = remember(editorTextColor, editorWordColors.toMap()) {
                            val baseColor = editorTextColor
                            val wordsMap = editorWordColors.toMap()
                            androidx.compose.ui.text.input.VisualTransformation { t ->
                                androidx.compose.ui.text.input.TransformedText(qinblyColoredText("Forte", t.text, baseColor, wordsMap), androidx.compose.ui.text.input.OffsetMapping.Identity)
                            }
                        },
                        modifier = Modifier.fillMaxWidth().focusRequester(focus),
                        decorationBox = { inner ->
                            Box(contentAlignment = Alignment.Center) {
                                if (editorText.isEmpty()) Text("Digite aqui", color = Color(0x99FFFFFF), fontSize = 24.sp, fontWeight = FontWeight.SemiBold)
                                inner()
                            }
                        }
                    )
                }
                QinblyTextStyleBar(
                    editorTextFont, editorTextColor, { editorTextFont = it },
                    { c -> if (editorSelWord in 0 until qinblyTextWords(editorText).size) editorWordColors[editorSelWord] = c else { editorTextColor = c; editorWordColors.clear() } },
                    qinblyTextWords(editorText), editorWordColors, editorSelWord, { editorSelWord = it }
                )
            }
            Text("Pronto", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 16.sp,
                modifier = Modifier.align(Alignment.TopEnd).statusBarsPadding().padding(16.dp).clickable { keyboard?.hide(); onDone() })
        }
    }
    // Câmera chamada por outra tela (cápsula, chat…): a foto passa pelo MESMO editor do Criar e, no fim, volta para a tela que chamou.
    // (editBeforeReturn = false devolveria a foto crua, sem editor.)
    val handOffMode = onCaptured != null && !editBeforeReturn
    fun handOff(u: Uri, video: Boolean = false): Boolean {
        val cb = onCaptured ?: return false
        if (video) { onNotice("Aqui só dá para enviar foto."); return true }
        if (!handOffMode) return false
        cb(u)
        return true
    }
    // Rede de segurança: no modo câmera-para-outra-tela o editor/publicação nunca aparece; a foto volta direto.
    LaunchedEffect(showComposer) {
        if (handOffMode && showComposer) {
            val u = selectedUri ?: sourceUri
            val vid = selectedType == "vídeo"
            showComposer = false; selectedUri = null; sourceUri = null
            if (vid) onNotice("Aqui só dá para enviar foto.") else if (u != null) onCaptured(u)
        }
    }
    val imagePicker = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->
        if (uri != null && handOff(uri)) return@rememberLauncherForActivityResult
        if (uri != null) { sourceUri = uri; selectedUri = uri; selectedType = "foto"; showComposer = true }
    }
    val videoPicker = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->
        if (uri != null) { sourceUri = uri; selectedUri = uri; showComposer = true; selectedType = "vídeo" }
    }
    // Seletor do Android: não depende de permissão de acesso a toda a biblioteca.
    val multiPhotoPicker = rememberQinblyMultiPhotoLauncher(10, onCamera = { onSwitchMode("camera") }) { uris ->
        if (uris.isNotEmpty() && handOff(uris.first())) return@rememberQinblyMultiPhotoLauncher
        if (uris.isNotEmpty()) {
            gallerySelection.clear()
            gallerySelection.addAll(uris.take(10))
            sourceUri = uris.first()
            selectedUri = uris.first()
            selectedType = "foto"
            galleryOpen = false
            publishSettings = false
            showComposer = true
        } else if (initialMode == "gallery" && !showComposer) {
            onCameraCancelled()
        }
    }
    val mediaPicker = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->
        if (uri != null && handOff(uri, context.contentResolver.getType(uri)?.startsWith("video/") == true)) return@rememberLauncherForActivityResult
        if (uri != null) {
            sourceUri = uri
            selectedUri = uri
            selectedType = if (context.contentResolver.getType(uri)?.startsWith("video/") == true) "vídeo" else "foto"
            galleryOpen = false
            publishSettings = false
            showComposer = true
        } else if (initialMode == "gallery" && !showComposer) {
            onCameraCancelled()
        }
    }
    fun applyPicked() {
        val u = QinblyComposeSeed.pickedUri ?: return
        QinblyComposeSeed.pickedUri = null
        sourceUri = u; selectedUri = u
        selectedType = if (QinblyComposeSeed.pickedVideo) "vídeo" else "foto"
        galleryOpen = false; publishSettings = false; showComposer = true; showCollabGallery = false
    }
    LaunchedEffect(Unit) { applyPicked() }
    fun openQinblyGallery() {
        try { multiPhotoPicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)) }
        catch (e: Exception) { onNotice("Não foi possível abrir a galeria: " + (e.localizedMessage ?: "tente novamente")) }
    }
    fun returnToGallery() {
        publishSettings = false
        showComposer = false
        editorTool = "Filtros"
        openQinblyGallery()
    }
    // O editor é o mesmo para foto da galeria e foto/vídeo da câmera; só muda para onde ele volta.
    val newEditorChrome = initialMode == "gallery" || initialMode == "camera"
    // Tela nova só para o story comum: publica direto do editor (sem "Avançar"). Story coletivo e resposta continuam como eram.
    val storyDirect = onCaptured == null && QinblyComposeSeed.story && QinblyComposeSeed.contribTo.isBlank() && !QinblyComposeSeed.collabNew
    fun leaveEditor() {
        QinblyComposeSeed.origin = ""
        if (QinblyComposeSeed.fromGallery) {
            // Veio da galeria do story coletivo: voltar leva de novo a ela, não à câmera.
            publishSettings = false
            showComposer = false
            editorTool = "Filtros"
            sourceUri = null; selectedUri = null; bakedUri = null
            editorText = ""; editorTextEditing = false; editorTextDx = 0f; editorTextDy = 0f; editorStickers.clear(); editorSelSticker = null; editorTextScale = 1f; editorTextSelected = false; editorWordColors.clear(); editorSelWord = -1
            editorStrokes.clear(); editorStrokeMeta.clear(); editorRedo.clear()
            showCollabGallery = true
        } else if (initialMode == "gallery") returnToGallery()
        else {
            publishSettings = false
            showComposer = false
            editorTool = "Filtros"
            sourceUri = null; selectedUri = null; bakedUri = null
            editorText = ""; editorTextEditing = false; editorTextDx = 0f; editorTextDy = 0f; editorStickers.clear(); editorSelSticker = null; editorTextScale = 1f; editorTextSelected = false; editorWordColors.clear(); editorSelWord = -1
            editorStrokes.clear(); editorStrokeMeta.clear(); editorRedo.clear()
            camTextMode = false; camTextEditing = false
        }
    }
    BackHandler(enabled = newEditorChrome && showComposer) {
        leaveEditor()
    }
    // Botão de voltar do celular (padrão): na tela de legenda/publicar volta para a EDIÇÃO da foto, sem fechar tudo.
    BackHandler(enabled = showComposer && publishSettings) {
        publishSettings = false
    }
    // Ferramenta aberta no editor (Formato, Stickers, Desenho, Texto): voltar fecha a ferramenta primeiro, depois sai do editor.
    // Ao gravar ou tirar a foto, uma música livre aleatória já começa a tocar sozinha (dá pra trocar ou tirar no topo).
    LaunchedEffect(showComposer) {
        if (showComposer && onCaptured == null && storyMusic == null && soundUri == null) {
            storyMusic = qinblyFreeTracks.flatMap { it.second }.random()
        }
    }
    BackHandler(enabled = showComposer && !publishSettings && (editorTool == "Ajustar" || editorTool == "Stickers" || editorTool == "Desenho" || editorTool == "Texto" || editorTool == "HDR")) {
        if (editorTextEditing) editorTextEditing = false else editorTool = "Filtros"
    }
    if (showCollabGallery) QinblyContributeFlow(
        storyId = QinblyComposeSeed.contribTo, newCollab = QinblyComposeSeed.collabNew, onNotice = onNotice,
        onCamera = { if (QinblyComposeSeed.pickedUri != null) applyPicked() else showCollabGallery = false },
        onDone = {
            showCollabGallery = false
            QinblyComposeSeed.story = false; QinblyComposeSeed.contribTo = ""; QinblyComposeSeed.collabNew = false; QinblyComposeSeed.fromGallery = false
            onCameraCancelled()
        },
        onDismiss = {
            showCollabGallery = false
            QinblyComposeSeed.story = false; QinblyComposeSeed.contribTo = ""; QinblyComposeSeed.collabNew = false; QinblyComposeSeed.fromGallery = false
            onCameraCancelled()
        }
    )
    LaunchedEffect(initialMode) {
        if (initialMode == "gallery") openQinblyGallery()
    }
    LaunchedEffect(sourceUri) {
        bakedUri = null
        editorRatio = "Original"; editorZoom = 1f; editorPanX = 0f; editorPanY = 0f
        editorBrightness = 0f; editorContrast = 0f
    }
    LaunchedEffect(selectedUri, selectedType) {
        val current = selectedUri
        if (current != null && selectedType == "foto") {
            editorImageRatio = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                try {
                    val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
                    context.contentResolver.openInputStream(current)?.use { BitmapFactory.decodeStream(it, null, bounds) }
                    val rot = qinblyExifRotation(context, current)
                    val bw = if (rot == 90 || rot == 270) bounds.outHeight else bounds.outWidth
                    val bh = if (rot == 90 || rot == 270) bounds.outWidth else bounds.outHeight
                    if (bw > 0 && bh > 0) bw.toFloat() / bh else 1f
                } catch (_: Exception) { 1f }
            }
        }
    }
    LaunchedEffect(sourceUri) {
        val media = sourceUri
        selectedMediaReady = media != null && kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
            try { context.contentResolver.openInputStream(media)?.use { it.read() >= 0 } == true } catch (_: Exception) { false }
        }
    }
    LaunchedEffect(showComposer, sourceUri, selectedType) {
        val uri = sourceUri
        if (showComposer && selectedType == "vídeo" && uri != null) {
            videoFrames = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                extractQinblyVideoFrames(context, uri)
            }
        } else {
            videoFrames = emptyList()
        }
    }
    LaunchedEffect(sourceUri, selectedType) {
        coverBitmap = null
        coverIndex = 0
        val uri = sourceUri
        videoDurationLabel = if (uri != null && selectedType == "vídeo") kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
            val retriever = android.media.MediaMetadataRetriever()
            try {
                retriever.setDataSource(context, uri)
                val ms = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION)?.toLongOrNull() ?: 0L
                val total = (ms / 1000L).toInt()
                if (total > 0) "%d:%02d".format(total / 60, total % 60) else ""
            } catch (_: Exception) { "" } finally { try { retriever.release() } catch (_: Exception) { } }
        } else ""
    }
    LaunchedEffect(galleryOpen) {
        if (galleryOpen && galleryAssets.isEmpty()) {
            galleryLoading = true
            val assets = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                val result = mutableListOf<QinblyGalleryAsset>()
                val resolver = context.contentResolver
                val collections = listOf(
                    android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI to false,
                    android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI to true
                )
                collections.forEach { (collection, isVideo) ->
                    val projection = arrayOf(
                        android.provider.MediaStore.MediaColumns._ID,
                        android.provider.MediaStore.MediaColumns.DISPLAY_NAME,
                        android.provider.MediaStore.MediaColumns.DATE_ADDED
                    )
                    resolver.query(collection, projection, null, null,
                        "${android.provider.MediaStore.MediaColumns.DATE_ADDED} DESC")?.use { cursor ->
                        val idCol = cursor.getColumnIndexOrThrow(android.provider.MediaStore.MediaColumns._ID)
                        val nameCol = cursor.getColumnIndexOrThrow(android.provider.MediaStore.MediaColumns.DISPLAY_NAME)
                        val dateCol = cursor.getColumnIndexOrThrow(android.provider.MediaStore.MediaColumns.DATE_ADDED)
                        while (cursor.moveToNext()) {
                            val id = cursor.getLong(idCol)
                            result.add(QinblyGalleryAsset(
                                android.content.ContentUris.withAppendedId(collection, id),
                                isVideo,
                                cursor.getLong(dateCol),
                                cursor.getString(nameCol) ?: ""
                            ))
                        }
                    }
                }
                result.sortedByDescending { it.dateAdded }.take(250)
            }
            galleryAssets = assets
            galleryLoading = false
        }
    }

    fun startVideoRecording() {
        val video = videoCapture
        if (video == null) { cameraError = "A câmera de vídeo ainda está iniciando. Tente novamente."; return }
        try {
            val file = File(context.cacheDir, "qinbly-video-" + System.currentTimeMillis() + ".mp4")
            val output = androidx.camera.video.FileOutputOptions.Builder(file).build()
            var pending = video.output.prepareRecording(context, output)
            val audioGranted = androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.RECORD_AUDIO) == android.content.pm.PackageManager.PERMISSION_GRANTED
            if (audioGranted) pending = pending.withAudioEnabled()
            activeRecording = pending.start(androidx.core.content.ContextCompat.getMainExecutor(context)) { event ->
                when (event) {
                    is androidx.camera.video.VideoRecordEvent.Start -> {
                        isRecording = true
                        cameraError = ""
                        if (flashEnabled) cameraControl?.cameraControl?.enableTorch(true)
                        if (stopWhenReady) { stopWhenReady = false; activeRecording?.stop() }
                    }
                    is androidx.camera.video.VideoRecordEvent.Finalize -> {
                        isRecording = false
                        holdStarted = false
                        try { cameraControl?.cameraControl?.enableTorch(false) } catch (_: Exception) { }
                        activeRecording = null
                        if (event.hasError()) cameraError = "Falha ao finalizar o vídeo (" + event.error + ")."
                        else {
                            val speedNow = speedChoice
                            val soundNow = soundUri
                            if (speedNow != 1f || soundNow != null) {
                                flashLabel = "Aplicando velocidade e som…"
                                qinblyReencodeVideo(context, Uri.fromFile(file), speedNow, soundNow) { made, error ->
                                    if (made == null && error.isNotBlank()) onNotice(error)
                                    val finalUri = made ?: Uri.fromFile(file)
                                    sourceUri = finalUri; selectedUri = finalUri; selectedType = "vídeo"; showComposer = true
                                }
                            } else { sourceUri = Uri.fromFile(file); selectedUri = sourceUri; selectedType = "vídeo"; showComposer = true }
                        }
                    }
                }
            }
        } catch (e: Exception) { cameraError = "Não foi possível gravar o vídeo: " + (e.localizedMessage ?: "erro desconhecido") }
    }

    // Ao sair da tela Criar a câmera é solta de verdade (antes ela ficava ligada no Activity).
    androidx.compose.runtime.DisposableEffect(Unit) {
        onDispose {
            try { if (isRecording) activeRecording?.stop() } catch (_: Exception) {}
            try { cameraProvider?.unbindAll() } catch (_: Exception) {}
        }
    }
    val audioPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) startVideoRecording()
        else cameraError = "Permita o microfone para gravar vídeos com áudio."
    }
    LaunchedEffect(cameraGranted, lensFacing, showComposer, previewView, selectedCameraFormat, qualityChoice, stabilizeOn, cameraBoxW, cameraBoxH) {
        if (initialMode == "camera" && cameraGranted && !showComposer && previewView != null) {
            try {
                val future = androidx.camera.lifecycle.ProcessCameraProvider.getInstance(context)
                future.addListener({
                    try {
                        val provider = future.get()
                        cameraProvider = provider
                        val view = previewView ?: return@addListener
                        // Foto na melhor qualidade que o aparelho aguentar; se a combinação (prévia + foto + vídeo) não for aceita, volta ao modo simples.
                        fun bindUseCases(hq: Boolean) {
                            val preview = androidx.camera.core.Preview.Builder().build().also { it.setSurfaceProvider(view.surfaceProvider) }
                            val capture = (if (hq) androidx.camera.core.ImageCapture.Builder()
                                .setCaptureMode(androidx.camera.core.ImageCapture.CAPTURE_MODE_MAXIMIZE_QUALITY)
                                .setJpegQuality(100)
                                .setResolutionSelector(androidx.camera.core.resolutionselector.ResolutionSelector.Builder()
                                    .setResolutionStrategy(androidx.camera.core.resolutionselector.ResolutionStrategy.HIGHEST_AVAILABLE_STRATEGY).build())
                            else androidx.camera.core.ImageCapture.Builder().setCaptureMode(androidx.camera.core.ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY)).build()
                            val quality = when (qualityChoice) { "UHD" -> androidx.camera.video.Quality.UHD; "FHD" -> androidx.camera.video.Quality.FHD; else -> androidx.camera.video.Quality.HD }
                            val recorder = androidx.camera.video.Recorder.Builder()
                                .setQualitySelector(androidx.camera.video.QualitySelector.from(quality, androidx.camera.video.FallbackStrategy.lowerQualityOrHigherThan(androidx.camera.video.Quality.SD)))
                                .build()
                            stabilizeSupported = try { androidx.camera.video.Recorder.getVideoCapabilities(provider.getCameraInfo(androidx.camera.core.CameraSelector.Builder().requireLensFacing(lensFacing).build())).isStabilizationSupported } catch (_: Exception) { false }
                            val video = androidx.camera.video.VideoCapture.Builder(recorder).setVideoStabilizationEnabled(stabilizeOn && stabilizeSupported).build()
                            val selector = androidx.camera.core.CameraSelector.Builder().requireLensFacing(lensFacing).build()
                            val frame = when (selectedCameraFormat) { "1:1" -> android.util.Rational(1, 1); "4:3" -> android.util.Rational(3, 4); else -> if (cameraBoxW > 0 && cameraBoxH > 0) android.util.Rational(cameraBoxW, cameraBoxH) else android.util.Rational(9, 16) }
                            val viewPort = androidx.camera.core.ViewPort.Builder(frame, view.display?.rotation ?: android.view.Surface.ROTATION_0).build()
                            val group = androidx.camera.core.UseCaseGroup.Builder().setViewPort(viewPort)
                                .addUseCase(preview).addUseCase(capture).addUseCase(video).build()
                            provider.unbindAll()
                            val boundCamera = provider.bindToLifecycle(lifecycleOwner, selector, group)
                            cameraControl = boundCamera
                            zoomRatio = 1f
                            capture.flashMode = if (flashEnabled) androidx.camera.core.ImageCapture.FLASH_MODE_ON else androidx.camera.core.ImageCapture.FLASH_MODE_OFF
                            imageCapture = capture
                            videoCapture = video
                        }
                        try { bindUseCases(true) } catch (e: Exception) { provider.unbindAll(); bindUseCases(false) }
                        cameraError = ""
                    } catch (e: Exception) {
                        cameraError = "Não foi possível iniciar a câmera: " + (e.localizedMessage ?: "dispositivo indisponível")
                    }
                }, androidx.core.content.ContextCompat.getMainExecutor(context))
            } catch (e: Exception) { cameraError = "Câmera indisponível neste aparelho." }
        } else {
            if (isRecording) activeRecording?.stop()
            cameraProvider?.unbindAll()
            cameraControl = null
            imageCapture = null
            videoCapture = null
        }
    }

    LaunchedEffect(exposureIndex, cameraControl, nightOn) {
        try {
            val range = cameraControl?.cameraInfo?.exposureState?.exposureCompensationRange
            val boosted = if (nightOn && range != null) maxOf(exposureIndex, (range.upper * 2 / 3).coerceAtLeast(1).coerceAtMost(range.upper)) else exposureIndex
            cameraControl?.cameraControl?.setExposureCompensationIndex(boosted)
        } catch (_: Exception) { }
    }
    LaunchedEffect(zoomRatio) {
        if (zoomRatio > 1.01f) {
            showZoomBadge = true
            kotlinx.coroutines.delay(1200)
            showZoomBadge = false
        }
    }
    LaunchedEffect(flashLabel) {
        if (flashLabel.isNotBlank()) {
            kotlinx.coroutines.delay(1400)
            flashLabel = ""
        }
    }
    LaunchedEffect(isRecording) {
        if (isRecording) {
            recElapsed = 0
            while (isRecording) {
                kotlinx.coroutines.delay(1000)
                recElapsed += 1
                val limit = if (captureMode == "Foto") 60 else when (selectedDuration) { "5 min" -> 300; "60 s" -> 60; "20 s" -> 20; else -> 15 }
                if (recElapsed >= limit) activeRecording?.stop()
            }
        } else {
            recElapsed = 0
        }
    }
    // Miniatura da última foto/vídeo da galeria (só aparece se o app já tiver permissão de leitura).
    LaunchedEffect(cameraGranted, showComposer) {
        if (initialMode != "camera" || showComposer) return@LaunchedEffect
        val perm = if (android.os.Build.VERSION.SDK_INT >= 33) android.Manifest.permission.READ_MEDIA_IMAGES else android.Manifest.permission.READ_EXTERNAL_STORAGE
        if (androidx.core.content.ContextCompat.checkSelfPermission(context, perm) != android.content.pm.PackageManager.PERMISSION_GRANTED) {
            latestThumb = null
            return@LaunchedEffect
        }
        latestThumb = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val resolver = context.contentResolver
                val files = android.provider.MediaStore.Files.getContentUri("external")
                val typeCol = android.provider.MediaStore.Files.FileColumns.MEDIA_TYPE
                val projection = arrayOf(android.provider.MediaStore.Files.FileColumns._ID, typeCol)
                val selection = "$typeCol=? OR $typeCol=?"
                val args = arrayOf(
                    android.provider.MediaStore.Files.FileColumns.MEDIA_TYPE_IMAGE.toString(),
                    android.provider.MediaStore.Files.FileColumns.MEDIA_TYPE_VIDEO.toString()
                )
                var thumb: Bitmap? = null
                resolver.query(files, projection, selection, args, android.provider.MediaStore.MediaColumns.DATE_ADDED + " DESC")?.use { c ->
                    if (c.moveToFirst()) {
                        val id = c.getLong(0)
                        val isVideo = c.getInt(1) == android.provider.MediaStore.Files.FileColumns.MEDIA_TYPE_VIDEO
                        val base = if (isVideo) android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI else android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI
                        val uri = android.content.ContentUris.withAppendedId(base, id)
                        thumb = if (android.os.Build.VERSION.SDK_INT >= 29) {
                            resolver.loadThumbnail(uri, android.util.Size(160, 160), null)
                        } else if (isVideo) {
                            android.provider.MediaStore.Video.Thumbnails.getThumbnail(resolver, id, android.provider.MediaStore.Video.Thumbnails.MICRO_KIND, null)
                        } else {
                            android.provider.MediaStore.Images.Thumbnails.getThumbnail(resolver, id, android.provider.MediaStore.Images.Thumbnails.MICRO_KIND, null)
                        }
                    }
                }
                thumb
            } catch (_: Exception) { null }
        }
    }

    fun takePhoto() {
        val capture = imageCapture
        if (capture == null) { cameraError = "A câmera ainda está iniciando. Tente novamente."; return }
        val file = File(context.cacheDir, "qinbly-camera-" + System.currentTimeMillis() + ".jpg")
        val metadata = androidx.camera.core.ImageCapture.Metadata().apply {
            // A tela mostra a câmera da frente espelhada; a foto sai igual ao que você viu (o botão Espelhar inverte isso).
            isReversedHorizontal = lensFacing == androidx.camera.core.CameraSelector.LENS_FACING_FRONT && !mirrorOn
        }
        val output = androidx.camera.core.ImageCapture.OutputFileOptions.Builder(file).setMetadata(metadata).build()
        capture.takePicture(output, androidx.core.content.ContextCompat.getMainExecutor(context), object : androidx.camera.core.ImageCapture.OnImageSavedCallback {
            override fun onImageSaved(result: androidx.camera.core.ImageCapture.OutputFileResults) {
                fun openEditor(uri: Uri) {
                    if (handOff(uri)) return
                    sourceUri = uri
                    selectedUri = uri
                    selectedType = "foto"
                    showComposer = true
                }
                fun finishPhoto(uri: Uri) {
                    if (collageCount > 0) {
                        collageShots.add(uri)
                        if (collageShots.size >= collageCount) {
                            val list = collageShots.toList()
                            collageShots.clear()
                            flashLabel = "Montando a colagem…"
                            qinblyBuildCollage(context, list) { made -> if (made != null) openEditor(made) else onNotice("Não foi possível montar a colagem.") }
                        } else flashLabel = "Colagem: " + collageShots.size + " de " + collageCount + " fotos"
                    } else openEditor(uri)
                }
                fun withEffects(uri: Uri) {
                    if (retouchOn || hdrOn) {
                        flashLabel = "Aplicando efeitos…"
                        qinblyApplyPhotoEffects(context, uri, retouchOn, hdrOn) { fx, note ->
                            if (note.isNotBlank()) onNotice(note)
                            finishPhoto(fx ?: uri)
                        }
                    } else finishPhoto(uri)
                }
                // Deixa a foto em pé antes de abrir o editor (ver qinblyMakeUpright), fora da thread principal.
                Thread {
                    qinblyMakeUpright(file)
                    android.os.Handler(android.os.Looper.getMainLooper()).post { withEffects(Uri.fromFile(file)) }
                }.start()
            }
            override fun onError(exception: androidx.camera.core.ImageCaptureException) { cameraError = "Falha ao tirar foto: " + (exception.message ?: "tente novamente") }
        })
    }
    fun requestRecording() {
        val audioGranted = androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.RECORD_AUDIO) == android.content.pm.PackageManager.PERMISSION_GRANTED
        if (audioGranted) startVideoRecording() else audioPermission.launch(android.Manifest.permission.RECORD_AUDIO)
    }
    val timerSeconds = selectedTimerSeconds.filter { it.isDigit() }.toIntOrNull() ?: 0
    fun onShutterTap() {
        if (isRecording) { activeRecording?.stop(); return }
        if (pendingAction.isNotBlank()) { pendingAction = ""; countdown = 0; return }
        val action = if (captureMode == "Vídeo" || handsFreeOn) "video" else "photo"
        if (timerSeconds > 0 || (handsFreeOn && action == "video")) pendingAction = action
        else if (action == "photo") takePhoto() else requestRecording()
    }
    // Teclas de volume (aumentar ou diminuir) tiram a foto, ou começam/param a gravação, enquanto a câmera está aberta.
    var seenKeyTicks by remember { mutableIntStateOf(QinblyCameraKeys.shutterTicks) }
    androidx.compose.runtime.DisposableEffect(initialMode, showComposer) {
        QinblyCameraKeys.active = initialMode == "camera" && !showComposer
        onDispose { QinblyCameraKeys.active = false }
    }
    LaunchedEffect(QinblyCameraKeys.shutterTicks) {
        if (QinblyCameraKeys.shutterTicks > seenKeyTicks) {
            seenKeyTicks = QinblyCameraKeys.shutterTicks
            if (QinblyCameraKeys.active) onShutterTap()
        }
    }
    LaunchedEffect(pendingAction) {
        if (pendingAction.isNotBlank()) {
            val wait = if (timerSeconds > 0) timerSeconds else 3
            for (i in wait downTo 1) {
                countdown = i
                kotlinx.coroutines.delay(1000)
            }
            countdown = 0
            val action = pendingAction
            pendingAction = ""
            if (action == "photo") takePhoto() else if (action == "video") requestRecording()
        } else {
            countdown = 0
        }
    }

    if (initialMode == "text" || initialMode == "poll") {
 QinblySplit {
        val maxChars = if (initialMode == "poll") 200 else 5000
        val ownUsername = prefs.getString("username", "").orEmpty().removePrefix("@")
        if (initialMode == "text") {
            var textBg by remember { mutableStateOf(0) }
            val capState = remember { QinblyCaptionState(caption) }
            val bgBrush = qinblyTextBgBrush(textBg)
            // Rascunho: o texto e o fundo são salvos sozinhos e voltam na próxima vez que você abrir "Nova publicação".
            var draftRestored by remember { mutableStateOf(false) }
            var scheduledAtMs by remember { mutableStateOf(0L) }
            LaunchedEffect(Unit) {
                val saved = prefs.getString("draft_text", "").orEmpty()
                if (caption.isBlank() && saved.isNotBlank()) {
                    val (l, t) = qinblySplitCaption(saved)
                    capState.legend = l
                    capState.tags.clear(); capState.tags.addAll(t)
                    caption = saved
                    draftRestored = true
                }
            }
            LaunchedEffect(caption, textBg) {
                kotlinx.coroutines.delay(600)
                if (caption.isBlank()) prefs.edit().remove("draft_text").remove("draft_text_bg").apply()
                else prefs.edit().putString("draft_text", caption).putInt("draft_text_bg", textBg).apply()
            }
            val pickSchedule: () -> Unit = {
                val now = java.util.Calendar.getInstance()
                android.app.DatePickerDialog(context, { _, y, m, d ->
                    android.app.TimePickerDialog(context, { _, hh, mm ->
                        val picked = java.util.Calendar.getInstance().apply { set(y, m, d, hh, mm, 0); set(java.util.Calendar.MILLISECOND, 0) }.timeInMillis
                        if (picked < System.currentTimeMillis() + 60_000L) onNotice("Escolha um horário no futuro.")
                        else if (picked > System.currentTimeMillis() + 90L * 86_400_000L) onNotice("Agende para no máximo 90 dias.")
                        else scheduledAtMs = picked
                        Unit
                    }, now.get(java.util.Calendar.HOUR_OF_DAY), now.get(java.util.Calendar.MINUTE), true).show()
                }, now.get(java.util.Calendar.YEAR), now.get(java.util.Calendar.MONTH), now.get(java.util.Calendar.DAY_OF_MONTH)).apply {
                    datePicker.minDate = System.currentTimeMillis() - 1000
                    datePicker.maxDate = System.currentTimeMillis() + 90L * 86_400_000L
                }.show()
            }
            Column(Modifier.fillMaxSize().background(QiblyTheme.background).imePadding()) {
                Box(Modifier.fillMaxWidth().padding(horizontal = 4.dp, vertical = 6.dp)) {
                    IconButton(onClick = onCameraCancelled, modifier = Modifier.align(Alignment.CenterStart)) {
                        Icon(Icons.Default.Close, contentDescription = "Fechar", tint = QiblyTheme.text)
                    }
                    Text("Nova publicação", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 18.sp, modifier = Modifier.align(Alignment.Center))
                }
                Column(
                    Modifier.weight(1f).fillMaxWidth().verticalScroll(rememberScrollState()).padding(horizontal = 16.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    if (draftRestored) Row(
                        Modifier.fillMaxWidth().clip(RoundedCornerShape(12.dp)).background(QinblyBrand.AccentSoft).padding(horizontal = 14.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("Rascunho recuperado", color = QiblyTheme.text, fontSize = 14.sp, modifier = Modifier.weight(1f))
                        QinblyAccentText("Descartar", fontWeight = FontWeight.SemiBold, fontSize = 14.sp,
                            modifier = Modifier.clickable {
                                capState.legend = ""; capState.tags.clear(); caption = ""; draftRestored = false
                                prefs.edit().remove("draft_text").remove("draft_text_bg").apply()
                            }.padding(4.dp))
                    }
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                        if (ownUsername.isNotBlank()) QiblyAccountAvatar(ownUsername, "", 44.dp) { }
                        else Icon(Icons.Default.Person, contentDescription = null, tint = Color.DarkGray, modifier = Modifier.size(44.dp))
                        Column {
                            Text(if (ownUsername.isBlank()) "Meu perfil" else "@$ownUsername", fontWeight = FontWeight.SemiBold, color = QiblyTheme.text)
                            Text(if (postVisibility == "Só eu") "Só eu" else "Todos podem ver", color = Muted, style = MaterialTheme.typography.labelMedium)
                        }
                    }
                    Box(
                        Modifier.fillMaxWidth().heightIn(min = 260.dp).clip(RoundedCornerShape(24.dp))
                            .then(if (bgBrush != null) Modifier.background(bgBrush) else Modifier.background(qinblyAccentBrush(0.06f)))
                            .padding(horizontal = 22.dp, vertical = 26.dp),
                        contentAlignment = if (bgBrush != null) Alignment.Center else Alignment.TopStart
                    ) {
                        QinblyLegendField(
                            capState, maxChars, "No que você está pensando?",
                            if (bgBrush != null) Color.White else QiblyTheme.text,
                            if (bgBrush != null) 24.sp else 18.sp,
                            Modifier.fillMaxWidth(),
                            placeholderColor = if (bgBrush != null) Color.White.copy(alpha = 0.65f) else Color.Gray,
                            textAlign = if (bgBrush != null) androidx.compose.ui.text.style.TextAlign.Center else androidx.compose.ui.text.style.TextAlign.Start
                        ) { caption = it }
                    }
                    Text("${caption.length} / $maxChars", modifier = Modifier.align(Alignment.End), color = Color.Gray, style = MaterialTheme.typography.labelSmall)
                    Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
                        Box(
                            Modifier.size(40.dp).clip(CircleShape).background(QiblyTheme.background)
                                .border(if (textBg == 0) 3.dp else 1.dp, if (textBg == 0) QinblyBrand.Accent else QiblyTheme.border, CircleShape)
                                .clickable { textBg = 0 },
                            contentAlignment = Alignment.Center
                        ) { Text("Aa", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 14.sp) }
                        for (i in 1..QinblyTextBgPairs.size) {
                            Box(
                                Modifier.size(40.dp).clip(CircleShape).background(qinblyTextBgBrush(i)!!)
                                    .border(if (textBg == i) 3.dp else 0.dp, if (textBg == i) QiblyTheme.text else Color.Transparent, CircleShape)
                                    .clickable { textBg = i }
                            )
                        }
                        QinblyColorWheelDot(selected = textBg >= 16777216, startColor = if (textBg >= 16777216) Color((0xFF shl 24) or (textBg and 0xFFFFFF)) else Color.hsv(330f, 0.85f, 0.8f)) { textBg = it }
                    }
                    Text(if (textBg == 0) "Sem fundo" else "Fundo colorido", color = Muted, style = MaterialTheme.typography.labelSmall)
                    QinblyHashtagField(capState) { caption = it }
                    Column(Modifier.fillMaxWidth()) {
                        Box(Modifier.fillMaxWidth().height(0.5.dp).background(QiblyTheme.border))
                        QinblyPublishRow(QinblyCameraIcons.people, "Marcar pessoas", value = if (taggedPeople.isEmpty()) "" else taggedPeople.size.toString(), onClick = { showTagDialog = true })
                        if (showTagDialog) {
                            QinblyTagPeopleDialog(prefs.getString("token", null), prefs.getString("username", "").orEmpty(), taggedPeople.toList(), QinblyBrand.Accent, onDismiss = { showTagDialog = false }) { chosen ->
                                taggedPeople.clear(); taggedPeople.addAll(chosen); showTagDialog = false
                            }
                        }
                        QinblyPublishRow(QinblyCameraIcons.globe, "Quem pode ver", value = postVisibility, onClick = {
                            postVisibility = if (postVisibility == "Todos") "Só eu" else "Todos"
                            onNotice(if (postVisibility == "Só eu") "Só você verá esta publicação, no seu perfil." else "Todos poderão ver esta publicação.")
                        })
                        QinblyPublishRow(QinblyCameraIcons.clock, "Agendar publicação",
                            value = if (scheduledAtMs > 0L) java.text.SimpleDateFormat("dd/MM HH:mm", java.util.Locale.getDefault()).format(java.util.Date(scheduledAtMs)) else "", onClick = pickSchedule)
                        if (scheduledAtMs > 0L) QinblyAccentText("Remover agendamento", fontSize = 14.sp,
                            modifier = Modifier.clickable { scheduledAtMs = 0L }.padding(start = 34.dp, bottom = 8.dp))
                    }
                    Spacer(Modifier.height(8.dp))
                }
                Box(Modifier.fillMaxWidth().background(QiblyTheme.background).navigationBarsPadding().padding(horizontal = 16.dp, vertical = 10.dp)) {
                    QinblyGradientButton(
                        onClick = {
                            val token = prefs.getString("token", null)
                            if (token.isNullOrBlank()) {
                                onNotice("Entre na sua conta antes de publicar.")
                            } else if (!publishing) {
                                publishing = true
                                QinblyHashtagStore.record(context, caption)
                                val scheduledIso = if (scheduledAtMs > 0L) java.time.Instant.ofEpochMilli(scheduledAtMs).toString() else ""
                                Thread {
                                    try {
                                        QinblyApi.createTextPost(token, caption.trim(), if (postVisibility == "Só eu") "private" else "public", taggedPeople.toList(), textBg, scheduledIso)
                                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                                            publishing = false
                                            prefs.edit().remove("draft_text").remove("draft_text_bg").apply()
                                            onNotice(if (scheduledIso.isNotBlank()) "Publicação agendada!" else "Texto publicado com sucesso!")
                                            onCameraCancelled()
                                        }
                                    } catch (e: Exception) {
                                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                                            publishing = false
                                            onNotice(e.message ?: "Falha ao publicar.")
                                        }
                                    }
                                }.start()
                            }
                        },
                        enabled = !publishing && caption.isNotBlank(),
                        modifier = Modifier.fillMaxWidth().height(52.dp),
                        shape = RoundedCornerShape(28.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)
                    ) { Text(if (publishing) "Publicando…" else if (scheduledAtMs > 0L) "Agendar" else "Publicar", fontWeight = FontWeight.SemiBold) }
                }
            }
            return@QinblySplit
        }
        Column(
            Modifier.fillMaxSize().background(QiblyTheme.background).verticalScroll(rememberScrollState()).padding(horizontal = 16.dp, vertical = 12.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp)
        ) {
 QinblySplit {
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                IconButton(onClick = onCameraCancelled) { Icon(Icons.Default.ArrowBack, contentDescription = "Voltar", tint = QiblyTheme.text) }
                Text(if (initialMode == "poll") "Criar enquete" else "Nova publicação",
                    color = QiblyTheme.text, fontWeight = FontWeight.SemiBold, fontSize = 20.sp, modifier = Modifier.weight(1f))
            }
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                if (ownUsername.isNotBlank()) QiblyAccountAvatar(ownUsername, "", 46.dp) { }
                else Icon(Icons.Default.Person, contentDescription = null, tint = Color.DarkGray, modifier = Modifier.size(46.dp))
                Column {
                    Text(if (ownUsername.isBlank()) "Meu perfil" else "@$ownUsername", fontWeight = FontWeight.SemiBold, color = QiblyTheme.text)
                    Text("Todos podem ver", color = Color.DarkGray, style = MaterialTheme.typography.labelMedium)
                }
            }
            val capState = remember { QinblyCaptionState(caption) }
            Column(Modifier.fillMaxWidth().clip(RoundedCornerShape(20.dp)).background(qinblyAccentBrush(0.06f)).padding(16.dp)) {
                QinblyLegendField(
                    capState, maxChars, if (initialMode == "poll") "Qual é a sua pergunta?" else "No que você está pensando?", QiblyTheme.text,
                    if (initialMode == "poll") 20.sp else 18.sp,
                    Modifier.fillMaxWidth().heightIn(min = if (initialMode == "text") 200.dp else 70.dp)
                ) { caption = it }
                Text("${caption.length} / $maxChars", modifier = Modifier.align(Alignment.End), color = Color.Gray, style = MaterialTheme.typography.labelSmall)
            }
            QinblyHashtagField(capState) { caption = it }
            if (initialMode == "poll") {
 QinblySplit {
                Text("Opções", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold)
                pollOptions.forEachIndexed { index, option ->
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        Box(Modifier.size(28.dp).clip(CircleShape).background(qinblyAccentBrush(0.14f)), contentAlignment = Alignment.Center) {
                            QinblyAccentText("${index + 1}", fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
                        }
                        OutlinedTextField(value = option,
                            onValueChange = { value -> pollOptions = pollOptions.toMutableList().also { it[index] = value.take(60) } },
                            placeholder = { Text("Opção ${index + 1}") }, modifier = Modifier.weight(1f), singleLine = true,
                            shape = RoundedCornerShape(16.dp))
                        if (pollOptions.size > 2) IconButton(onClick = { pollOptions = pollOptions.filterIndexed { i, _ -> i != index } }) {
                            Icon(Icons.Default.Close, contentDescription = "Remover opção", tint = Color.Gray)
                        }
                    }
                }
                if (pollOptions.size < 6) Row(
                    Modifier.clip(RoundedCornerShape(20.dp)).clickable { pollOptions = pollOptions + "" }.padding(horizontal = 6.dp, vertical = 8.dp),
                    verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    QinblyAccentIcon(Icons.Default.Add, contentDescription = null)
                    QinblyAccentText("Adicionar opção", fontWeight = FontWeight.SemiBold)
                }
                Text("Duração", color = QiblyTheme.text, fontWeight = FontWeight.SemiBold)
                val pollDurations = listOf(1 to "1 h", 6 to "6 h", 24 to "24 h", 72 to "3 dias", 168 to "7 dias")
                Row(Modifier.horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    pollDurations.forEach { (hours, label) ->
                        val on = pollDurationHours == hours
                        Text(label, color = if (on) Color.White else QiblyTheme.text, fontWeight = FontWeight.SemiBold,
                            modifier = Modifier.clip(RoundedCornerShape(20.dp)).background(if (on) QinblyBrand.Accent else QinblyBrand.Accent.copy(alpha = 0.10f))
                                .clickable { pollDurationHours = hours }.padding(horizontal = 16.dp, vertical = 9.dp))
                    }
                }
                Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                    Text("Permitir múltiplas respostas", modifier = Modifier.weight(1f), color = QiblyTheme.text)
                    Switch(checked = pollMultipleAnswers, onCheckedChange = { pollMultipleAnswers = it })
                }
                Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                    Text("Mostrar resultados ao votar", modifier = Modifier.weight(1f), color = QiblyTheme.text)
                    Switch(checked = pollShowResults, onCheckedChange = { pollShowResults = it })
                }
                Text("Os votos são anônimos. A enquete continua no feed depois de encerrar.", color = Color.Gray, style = MaterialTheme.typography.labelSmall)
             }
} else {
                Text("Dica: use #hashtags para ser encontrado e @nome para marcar alguém.", color = Color.Gray, style = MaterialTheme.typography.bodySmall)
            }
            QinblyGradientButton(
                onClick = {
                    val token = prefs.getString("token", null)
                    if (token.isNullOrBlank()) {
                        onNotice("Entre na sua conta antes de publicar.")
                    } else if (!publishing) {
                        publishing = true
                        QinblyHashtagStore.record(context, caption)
                        Thread {
                            try {
                                if (initialMode == "poll") {
                                    // A API atual não expõe votação; preserva pergunta e opções como publicação textual.
                                    val options = pollOptions.filter { it.isNotBlank() }
                                    QinblyApi.createPollPost(token, caption.trim(), options, pollDurationHours, pollMultipleAnswers, pollShowResults)
                                } else {
                                    QinblyApi.createTextPost(token, caption.trim(), if (postVisibility == "Só eu") "private" else "public", taggedPeople.toList())
                                }
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    publishing = false
                                    onNotice(if (initialMode == "poll") "Enquete publicada!" else "Texto publicado com sucesso!")
                                    onCameraCancelled()
                                }
                            } catch (e: Exception) {
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    publishing = false
                                    onNotice(e.message ?: "Falha ao publicar.")
                                }
                            }
                        }.start()
                    }
                },
                enabled = !publishing && caption.isNotBlank() && (initialMode != "poll" || pollOptions.count { it.isNotBlank() } >= 2),
                modifier = Modifier.fillMaxWidth().height(54.dp),
                shape = RoundedCornerShape(28.dp),
                colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)
            ) { Text(if (publishing) "Publicando…" else "Publicar", fontWeight = FontWeight.SemiBold) }
         }
}
        return@QinblySplit
     }
}

    // A tela intermediária foi removida. Se o seletor do Android for cancelado,
    // voltamos ao início em vez de deixar uma página vazia.
    if (initialMode == "gallery" && !showComposer && !galleryOpen) {
        Box(Modifier.fillMaxSize().background(QiblyTheme.background))
        return
    }

    if (initialMode == "camera" && !cameraGranted && !showComposer) {
        Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.spacedBy(16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
            Spacer(Modifier.height(60.dp))
            Text("Câmera ${QinblyBrand.Name}", style = MaterialTheme.typography.headlineLarge, fontWeight = FontWeight.SemiBold)
            Text("Câmera integrada ao aplicativo, com prévia e filtros.", color = Muted)
            Button(onClick = { cameraPermission.launch(android.Manifest.permission.CAMERA) }) { Text("Permitir câmera") }
            OutlinedButton(onClick = { imagePicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)) }) { Text("Escolher foto da galeria") }
            OutlinedButton(onClick = { videoPicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.VideoOnly)) }) { Text("Escolher vídeo da galeria") }
            TextButton(onClick = onCameraCancelled) { Text("Voltar ao início") }
        }
        return
    }

    if (handOffMode && showComposer) { Box(Modifier.fillMaxSize().background(Color.Black)); return }
    if (initialMode == "camera" && !showComposer) {
 QinblySplit {
        val frameRatio = when (selectedCameraFormat) { "1:1" -> 1f; "4:3" -> 3f / 4f; else -> 9f / 16f }
        val sideScroll = rememberScrollState()
        BackHandler(enabled = cameraSheet.isNotBlank()) { cameraSheet = "" }
        Box(Modifier.fillMaxSize().background(Color(0xFF080808))) {
 QinblySplit {
            Box((if (selectedCameraFormat == "9:16") Modifier.fillMaxSize() else Modifier.align(Alignment.Center).fillMaxWidth().aspectRatio(frameRatio)).clipToBounds().onSizeChanged { cameraBoxW = it.width; cameraBoxH = it.height }) {
 QinblySplit {
                androidx.compose.ui.viewinterop.AndroidView(
                    factory = { ctx -> androidx.camera.view.PreviewView(ctx).also {
                        it.scaleType = androidx.camera.view.PreviewView.ScaleType.FILL_CENTER
                        it.implementationMode = androidx.camera.view.PreviewView.ImplementationMode.COMPATIBLE
                        previewView = it
                    } },
                    modifier = Modifier.fillMaxSize().qinblySwipeFilters { dir ->
                        // Passar o dedo para o lado troca o filtro de cor (sem abrir a faixa de filtros).
                        val names = QinblyColorFilterNames
                        val next = names[(names.indexOf(selectedFilter).coerceAtLeast(0) + dir + names.size) % names.size]
                        selectedFilter = next; filterIntensity = 1f; flashLabel = next
                    }.pointerInput(cameraControl) {
                        detectTransformGestures { _, _, zoomChange, _ ->
                            val camera = cameraControl ?: return@detectTransformGestures
                            val maxZoom = camera.cameraInfo.zoomState.value?.maxZoomRatio ?: 1f
                            val minZoom = camera.cameraInfo.zoomState.value?.minZoomRatio ?: 1f
                            val nextZoom = (zoomRatio * zoomChange).coerceIn(minZoom, maxZoom)
                            camera.cameraControl.setZoomRatio(nextZoom)
                            zoomRatio = nextZoom
                        }
                    },
                    update = { v ->
                        val name = selectedFilter
                        val amount = filterIntensity
                        QinblyFilterIntensity.value = amount
                        try {
                            if (name == "Original") v.setLayerType(android.view.View.LAYER_TYPE_NONE, null)
                            else v.setLayerType(android.view.View.LAYER_TYPE_HARDWARE, android.graphics.Paint().apply {
                                colorFilter = ColorMatrixColorFilter(qinblyFilterMatrix(name, amount))
                            })
                        } catch (_: Exception) { }
                    }
                )
                if (gridOn) {
                    androidx.compose.foundation.Canvas(Modifier.fillMaxSize()) {
                        val line = Color.White.copy(alpha = 0.35f)
                        for (i in 1..2) {
                            drawLine(line, Offset(size.width * i / 3f, 0f), Offset(size.width * i / 3f, size.height), 1.2f)
                            drawLine(line, Offset(0f, size.height * i / 3f), Offset(size.width, size.height * i / 3f), 1.2f)
                        }
                    }
                }
                if (captureMode == "Foto" && camTextMode && !camTextEditing) {
                    Text(
                        if (editorText.isBlank()) androidx.compose.ui.text.AnnotatedString("Toque para escrever") else qinblyColoredText(editorTextFont, editorText, editorTextColor, editorWordColors),
                        color = if (editorText.isBlank()) Color(0xB3FFFFFF) else Color(editorTextColor),
                        fontSize = 24.sp,
                        fontFamily = androidx.compose.ui.text.font.FontFamily(qinblyTypeface(if (editorText.isBlank()) "Forte" else editorTextFont)),
                        letterSpacing = if (editorText.isBlank()) 0.em else qinblyTextSpacingEm(editorTextFont).em,
                        textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                        style = MaterialTheme.typography.headlineMedium.copy(shadow = androidx.compose.ui.graphics.Shadow(if (editorTextColor == 0xFF111111.toInt() && editorText.isNotBlank()) Color(0xCCFFFFFF) else Color(0xCC000000), blurRadius = 10f)),
                        modifier = Modifier.align(Alignment.Center)
                            .offset { androidx.compose.ui.unit.IntOffset(editorTextDx.toInt(), editorTextDy.toInt()) }
                            .padding(horizontal = 28.dp)
                            .clip(RoundedCornerShape(12.dp))
                            // Texto móvel também na câmera (mesmo padrão do editor): arrasta para onde quiser, toca para editar.
                            .pointerInput(Unit) { detectDragGestures { change, drag -> change.consume(); editorTextDx += drag.x; editorTextDy += drag.y } }
                            .clickable { camTextEditing = true }.padding(8.dp)
                    )
                }
                if (camTextEditing) {
 QinblySplit {
                    BackHandler { camTextEditing = false }
                    val textFocus = remember { FocusRequester() }
                    val keyboard = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current
                    LaunchedEffect(Unit) { textFocus.requestFocus(); keyboard?.show() }
                    val noRippleText = remember { androidx.compose.foundation.interaction.MutableInteractionSource() }
                    Column(
                        Modifier.fillMaxSize().background(Color(0x66000000))
                            .clickable(indication = null, interactionSource = noRippleText) { camTextEditing = false; keyboard?.hide() }
                            .imePadding().padding(bottom = QinblyKeyboardGap),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
 QinblySplit {
                        Box(Modifier.weight(1f).fillMaxWidth().padding(horizontal = 24.dp), contentAlignment = Alignment.Center) {
 QinblySplit {
                            androidx.compose.foundation.text.BasicTextField(
                                value = editorText,
                                onValueChange = { editorText = it.take(120) },
                                textStyle = androidx.compose.ui.text.TextStyle(
                                    color = Color(editorTextColor), fontSize = 24.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                    fontFamily = androidx.compose.ui.text.font.FontFamily(qinblyTypeface(editorTextFont)),
                                    letterSpacing = qinblyTextSpacingEm(editorTextFont).em,
                                    shadow = androidx.compose.ui.graphics.Shadow(Color(0xCC000000), blurRadius = 10f)
                                ),
                                cursorBrush = androidx.compose.ui.graphics.SolidColor(Color.White),
                                visualTransformation = androidx.compose.ui.text.input.VisualTransformation { t ->
                                    androidx.compose.ui.text.input.TransformedText(qinblyColoredText("Forte", t.text, editorTextColor, editorWordColors), androidx.compose.ui.text.input.OffsetMapping.Identity)
                                },
                                modifier = Modifier.fillMaxWidth().focusRequester(textFocus),
                                decorationBox = { inner ->
                                    Box(contentAlignment = Alignment.Center) {
                                        if (editorText.isEmpty()) Text("Digite aqui", color = Color(0x99FFFFFF), fontSize = 24.sp, fontWeight = FontWeight.SemiBold)
                                        inner()
                                    }
                                }
                            )
                         }
}
                        QinblyTextStyleBar(
                        editorTextFont, editorTextColor, { editorTextFont = it },
                        { c -> if (editorSelWord in 0 until qinblyTextWords(editorText).size) editorWordColors[editorSelWord] = c else { editorTextColor = c; editorWordColors.clear() } },
                        qinblyTextWords(editorText), editorWordColors, editorSelWord, { editorSelWord = it }
                    )
                     }
}
                 }
}
             }
}

            Box(Modifier.fillMaxSize().padding(horizontal = 12.dp, vertical = 10.dp)) {
 QinblySplit {
                IconButton(onClick = { if (isRecording) activeRecording?.stop(); onCameraCancelled() }, modifier = Modifier.align(Alignment.TopStart).size(40.dp)) {
                    Icon(QinblyCameraIcons.close, contentDescription = "Fechar câmera", tint = Color.White, modifier = Modifier.size(26.dp))
                }

                if (!isRecording) {
                    Row(
                        Modifier.align(Alignment.TopCenter).offset(x = (-14).dp).padding(top = 4.dp)
                            .clip(CircleShape).background(Color(0x73000000)).clickable { cameraSheet = "Som" }
                            .padding(horizontal = 16.dp, vertical = 10.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Icon(QinblyCameraIcons.music, contentDescription = null, tint = Color.White, modifier = Modifier.size(19.dp))
                        Text(if (soundName.isNotBlank()) soundName else storyMusic?.title ?: "Adicionar som", color = Color.White, fontSize = 16.sp, fontWeight = FontWeight.SemiBold,
                            maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, modifier = Modifier.widthIn(max = 130.dp))
                    }
                    // Mesma folha de músicas do editor (padrão do app): as músicas livres do Qinbly.
                    if (showMusicPicker && onCaptured == null) QinblyMusicPicker(onPick = { storyMusic = it; soundName = ""; soundUri = null; showMusicPicker = false }, onDismiss = { showMusicPicker = false }, freeOnly = !QinblyComposeSeed.story)
                } else {
                    Text("%d:%02d".format(recElapsed / 60, recElapsed % 60), color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 14.sp,
                        modifier = Modifier.align(Alignment.TopCenter).padding(top = 8.dp).clip(RoundedCornerShape(14.dp))
                            .background(Color(0x73000000)).padding(horizontal = 12.dp, vertical = 4.dp))
                }

                if (!isRecording) {
 QinblySplit {
                    Column(
                        Modifier.align(Alignment.TopEnd).padding(top = 88.dp).width(140.dp)
                            .then(if (sideExpanded) Modifier.fillMaxHeight().padding(bottom = 8.dp) else Modifier)
                            .verticalScroll(sideScroll),
                        horizontalAlignment = Alignment.End,
                        verticalArrangement = Arrangement.spacedBy(11.dp)
                    ) {
 QinblySplit {
                        QinblyCameraSideItem(QinblyCameraIcons.flash, "Flash", on = flashEnabled) {
                            flashEnabled = !flashEnabled
                            imageCapture?.flashMode = if (flashEnabled) androidx.camera.core.ImageCapture.FLASH_MODE_ON else androidx.camera.core.ImageCapture.FLASH_MODE_OFF
                        }
                        QinblyCameraSideItem(QinblyCameraIcons.timer, "Temporizador", on = selectedTimerSeconds != "Desligado") {
                            selectedTimerSeconds = when (selectedTimerSeconds) { "Desligado" -> "3 s"; "3 s" -> "5 s"; "5 s" -> "10 s"; else -> "Desligado" }
                            flashLabel = if (selectedTimerSeconds == "Desligado") "Temporizador desligado" else "Temporizador: " + selectedTimerSeconds
                        }
                        QinblyCameraSideItem(QinblyCameraIcons.format, "Formato") {
                            selectedCameraFormat = when (selectedCameraFormat) { "9:16" -> "4:3"; "4:3" -> "1:1"; else -> "9:16" }
                            flashLabel = "Formato " + selectedCameraFormat
                        }
                        QinblyCameraSideItem(QinblyCameraIcons.retouch, "Retoque", on = retouchOn) {
                            retouchOn = !retouchOn
                            flashLabel = if (retouchOn) "Retoque ligado (aplicado nas fotos)" else "Retoque desligado"
                        }
                        QinblyCameraSideItem(QinblyCameraIcons.filters, "Filtros", on = filtersVisible) { filtersVisible = !filtersVisible }
                     }
}
                 }
}

                if (flashLabel.isNotBlank()) {
                    Text(flashLabel, color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.SemiBold,
                        style = MaterialTheme.typography.titleMedium.copy(shadow = androidx.compose.ui.graphics.Shadow(Color(0x99000000), blurRadius = 8f)),
                        modifier = Modifier.align(Alignment.TopCenter).padding(top = 64.dp))
                }
                if (countdown > 0) {
                    Text(countdown.toString(), color = Color.White, fontSize = 96.sp, fontWeight = FontWeight.SemiBold,
                        style = MaterialTheme.typography.displayLarge.copy(shadow = androidx.compose.ui.graphics.Shadow(Color(0x99000000), blurRadius = 16f)),
                        modifier = Modifier.align(Alignment.Center))
                }
                if (showZoomBadge) {
                    Text("${(zoomRatio * 10).toInt() / 10f}x", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.SemiBold,
                        modifier = Modifier.align(Alignment.BottomCenter).padding(bottom = 250.dp).clip(RoundedCornerShape(16.dp))
                            .background(Color(0x80000000)).padding(horizontal = 12.dp, vertical = 5.dp))
                }

                Column(
                    Modifier.align(Alignment.BottomCenter).fillMaxWidth().padding(bottom = 6.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
 QinblySplit {
                    if (cameraError.isNotBlank()) {
                        Text(cameraError, color = Color.White, style = MaterialTheme.typography.bodySmall,
                            textAlign = androidx.compose.ui.text.style.TextAlign.Center)
                    }
                    if (!isRecording) {
 QinblySplit {
                        // Tempos do vídeo: aparecem acima dos chips só no modo VÍDEO.
                        if (captureMode == "Vídeo") {
                            Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
                                listOf("15 s", "20 s", "60 s", "5 min").forEach { dur ->
                                    val chosen = dur == selectedDuration
                                    Text(dur, color = if (chosen) Color.Black else Color.White, fontWeight = FontWeight.SemiBold, fontSize = 11.sp,
                                        modifier = Modifier.clip(RoundedCornerShape(16.dp)).background(if (chosen) Color.White else Color.Transparent)
                                            .clickable { selectedDuration = dur }.padding(horizontal = 9.dp, vertical = 4.dp))
                                }
                            }
                        }
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
                            listOf("FOTO", "VÍDEO").forEach { chip ->
                                val chosen = (chip == "FOTO" && captureMode == "Foto") || (chip == "VÍDEO" && captureMode == "Vídeo")
                                Text(chip, color = if (chosen) Color.Black else Color.White, fontWeight = FontWeight.SemiBold, fontSize = 11.sp,
                                    modifier = Modifier.clip(RoundedCornerShape(16.dp)).background(if (chosen) Color.White else Color.Transparent)
                                        .clickable { captureMode = if (chip == "FOTO") "Foto" else "Vídeo"; camTextMode = false }
                                        .padding(horizontal = 10.dp, vertical = 5.dp))
                            }
                        }
                        if (filtersVisible && selectedFilter != "Original") {
 QinblySplit {
                            Row(
                                Modifier.padding(horizontal = 30.dp).fillMaxWidth().clip(RoundedCornerShape(16.dp)).background(Color(0x66000000))
                                    .padding(horizontal = 12.dp, vertical = 2.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text("Intensidade", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                                Slider(
                                    value = filterIntensity, onValueChange = { filterIntensity = it }, valueRange = 0f..1f,
                                    colors = SliderDefaults.colors(thumbColor = Color.White, activeTrackColor = Color.White, inactiveTrackColor = Color(0x55FFFFFF)),
                                    modifier = Modifier.weight(1f).height(28.dp).padding(horizontal = 8.dp)
                                )
                                Text((filterIntensity * 100).toInt().toString(), color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                            }
                         }
}
                        if (filtersVisible) {
 QinblySplit {
                            LazyRow(
                                modifier = Modifier.fillMaxWidth(),
                                contentPadding = PaddingValues(horizontal = 14.dp),
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                items(QinblyColorFilterNames) { name ->
                                    QinblyFilterBubble(name, selectedFilter == name, {
                                        selectedFilter = name
                                        filterIntensity = 1f
                                        flashLabel = name
                                    }) {
                                        QinblyFilterSample(name)
                                    }
                                }
                            }
                         }
}
                     }
}
                    Row(Modifier.fillMaxWidth().padding(horizontal = 22.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
 QinblySplit {
                        if (isRecording) {
                            Spacer(Modifier.size(44.dp))
                        } else {
 QinblySplit {
                            Box(
                                Modifier.size(44.dp).clip(RoundedCornerShape(11.dp)).background(Color(0x29FFFFFF))
                                    .border(2.dp, Color.White, RoundedCornerShape(11.dp))
                                    .clickable {
                                        try { mediaPicker.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageAndVideo)) }
                                        catch (e: Exception) { onNotice("Não foi possível abrir a galeria: " + (e.localizedMessage ?: "tente novamente")) }
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                val thumb = latestThumb
                                if (thumb != null) androidx.compose.foundation.Image(thumb.asImageBitmap(), contentDescription = "Galeria", contentScale = ContentScale.Crop, modifier = Modifier.fillMaxSize())
                                else Icon(QinblyCreateIcons.gallery, contentDescription = "Galeria", tint = Color.White, modifier = Modifier.size(26.dp))
                            }
                         }
}
                        Box(
                            Modifier.size(if (isRecording) 92.dp else 72.dp)
                                .pointerInput(Unit) {
                                    detectTapGestures(
                                        onPress = {
                                            tryAwaitRelease()
                                            if (holdStarted) {
                                                holdStarted = false
                                                val recording = activeRecording
                                                if (recording != null) recording.stop() else stopWhenReady = true
                                            }
                                        },
                                        onLongPress = {
                                            if (!isRecording && pendingAction.isBlank()) {
                                                holdStarted = true
                                                requestRecording()
                                            }
                                        },
                                        onTap = { onShutterTap() }
                                    )
                                },
                            contentAlignment = Alignment.Center
                        ) {
 QinblySplit {
                            val limit = if (captureMode == "Foto") 60 else when (selectedDuration) { "5 min" -> 300; "60 s" -> 60; "20 s" -> 20; else -> 15 }
                            androidx.compose.foundation.Canvas(Modifier.fillMaxSize()) {
                                val stroke = 4.dp.toPx()
                                drawCircle(if (isRecording) Color(0x59FFFFFF) else Color.White, radius = size.minDimension / 2f - stroke / 2f, style = androidx.compose.ui.graphics.drawscope.Stroke(width = stroke))
                                if (isRecording) {
                                    drawArc(
                                        QinblyBrand.Accent, startAngle = -90f, sweepAngle = 360f * (recElapsed.toFloat() / limit).coerceIn(0f, 1f), useCenter = false,
                                        topLeft = Offset(stroke / 2f, stroke / 2f),
                                        size = androidx.compose.ui.geometry.Size(size.width - stroke, size.height - stroke),
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(width = stroke, cap = androidx.compose.ui.graphics.StrokeCap.Round)
                                    )
                                }
                            }
                            Box(
                                Modifier.size(if (isRecording) 32.dp else 56.dp)
                                    .clip(if (isRecording) RoundedCornerShape(9.dp) else CircleShape)
                                    .background(if (!isRecording && (captureMode == "Vídeo" || handsFreeOn)) QinblyBrand.Accent else Color.White)
                            )
                         }
}
                        if (isRecording) {
                            Spacer(Modifier.size(44.dp))
                        } else {
                            Box(Modifier.size(44.dp).clip(CircleShape).background(Color(0x2EFFFFFF)).clickable {
                                lensFacing = if (lensFacing == androidx.camera.core.CameraSelector.LENS_FACING_BACK) androidx.camera.core.CameraSelector.LENS_FACING_FRONT else androidx.camera.core.CameraSelector.LENS_FACING_BACK
                            }, contentAlignment = Alignment.Center) {
                                Icon(QinblyCameraIcons.flip, contentDescription = "Virar câmera", tint = Color.White, modifier = Modifier.size(24.dp))
                            }
                        }
                     }
}
                    Text(
                        if (isRecording) (if (holdStarted) "Solte para parar" else "Toque para parar") else "Toque para foto · segure para gravar",
                        color = Color.White.copy(alpha = 0.78f), fontSize = 11.sp
                    )
                 }
}
             }
}

            if (narrating) Box(Modifier.align(Alignment.BottomCenter).fillMaxWidth().navigationBarsPadding().padding(horizontal = 16.dp, vertical = 14.dp)) {
                QinblyVoiceBar(
                    accent = QinblyBrand.Accent, textColor = Color.White, barColor = Color(0xFF161C27),
                    onCancel = { narrating = false },
                    onTooShort = { narrating = false; onNotice("A narração ficou muito curta.") },
                    onFailed = { narrating = false; onNotice("Não foi possível gravar a narração agora.") },
                    onSend = { file, _ ->
                        narrating = false
                        soundUri = Uri.fromFile(file); soundName = "Narração"; storyMusic = null
                        onNotice("Narração pronta. Ela será misturada ao vídeo que você gravar.")
                    }
                )
            }
            if (cameraSheet.isNotBlank()) {
 QinblySplit {
                Box(Modifier.fillMaxSize().background(Color(0x73000000)).pointerInput(Unit) { detectTapGestures { cameraSheet = "" } })
                Column(
                    Modifier.align(Alignment.BottomCenter).fillMaxWidth()
                        .clip(RoundedCornerShape(topStart = 22.dp, topEnd = 22.dp)).background(Color(0xFF161C27))
                        .pointerInput(Unit) { detectTapGestures { } }
                        .navigationBarsPadding().padding(horizontal = 16.dp, vertical = 12.dp)
                ) {
 QinblySplit {
                    Box(Modifier.align(Alignment.CenterHorizontally).width(36.dp).height(4.dp).clip(CircleShape).background(Color(0xFF3A4458)))
                    Spacer(Modifier.height(10.dp))
                    if (cameraSheet == "Som") {
                        Text("Escolher som", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 16.sp)
                        QinblyCameraSheetRow(QinblyCameraIcons.headphones, "Do seu celular", "Escolha uma música ou áudio seu") { soundPicker.launch("audio/*") }
                        QinblyCameraSheetRow(QinblyCameraIcons.mic, "Gravar narração", "Grave sua voz agora; ela entra no vídeo que você gravar") {
                            cameraSheet = ""
                            if (androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.RECORD_AUDIO) == android.content.pm.PackageManager.PERMISSION_GRANTED) narrating = true
                            else narrationPermission.launch(android.Manifest.permission.RECORD_AUDIO)
                        }
                        if (onCaptured == null) QinblyCameraSheetRow(QinblyCameraIcons.music, "Sons do Qinbly", "Músicas livres para usar no post") { cameraSheet = ""; showMusicPicker = true }
                        if (soundName.isNotBlank() || storyMusic != null) {
                            TextButton(onClick = { soundName = ""; soundUri = null; storyMusic = null; cameraSheet = "" }) { Text("Remover som escolhido", color = QinblyBrand.Accent) }
                        }
                    } else if (cameraSheet == "Exposição") {
                        val state = cameraControl?.cameraInfo?.exposureState
                        Text("Exposição", color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 16.sp)
                        if (state != null && state.isExposureCompensationSupported) {
                            val low = state.exposureCompensationRange.lower
                            val high = state.exposureCompensationRange.upper
                            Slider(
                                value = exposureIndex.toFloat(), onValueChange = { exposureIndex = it.toInt() },
                                valueRange = low.toFloat()..high.toFloat(), steps = (high - low - 1).coerceAtLeast(0),
                                colors = SliderDefaults.colors(thumbColor = Color.White, activeTrackColor = QinblyBrand.Accent, inactiveTrackColor = Color(0xFF3A4458))
                            )
                            Text("Escuro  ←  →  Claro", color = Color(0xFFF2F4F8), fontSize = 11.sp)
                        } else {
                            Text("Este aparelho não permite ajustar o brilho aqui.", color = Color(0xFFF2F4F8), fontSize = 12.sp)
                        }
                    }
                    Spacer(Modifier.height(6.dp))
                 }
}
             }
}
         }
}
        return@QinblySplit
     }
}

    // Câmera chamada por outra tela: só a câmera. Nada de galeria interna/editor/publicação empilhado por cima.
    if (handOffMode) return

    if (galleryOpen) {
 QinblySplit {
        Column(Modifier.fillMaxSize().background(Color(0xFF080808)).padding(horizontal = 14.dp)) {
 QinblySplit {
            Row(Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 10.dp), verticalAlignment = Alignment.CenterVertically) {
                IconButton(onClick = { galleryOpen = false; gallerySelection.clear() }) {
                    Icon(Icons.Default.Close, contentDescription = "Fechar galeria", tint = Color.White)
                }
                Column(Modifier.weight(1f)) {
                    Text("Recentes", color = Color.White, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold)
                    Text("Escolha uma foto ou vídeo", color = Color.LightGray, style = MaterialTheme.typography.bodySmall)
                }
                TextButton(onClick = { galleryFilter = "Todos" }) { Text("▾", color = Color.White) }
            }
            Row(Modifier.fillMaxWidth().padding(bottom = 12.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                listOf("Todos", "Fotos", "Vídeos").forEach { filter ->
                    val active = galleryFilter == filter
                    Surface(
                        color = if (active) Color.White else Color(0xFF202020),
                        shape = RoundedCornerShape(18.dp),
                        modifier = Modifier.clickable { galleryFilter = filter }
                    ) {
                        Text(filter, color = if (active) Color.Black else Color.White, fontWeight = FontWeight.SemiBold,
                            modifier = Modifier.padding(horizontal = 20.dp, vertical = 8.dp))
                    }
                }
            }
            val visibleAssets = galleryAssets.filter { when (galleryFilter) {
                "Fotos" -> !it.isVideo
                "Vídeos" -> it.isVideo
                else -> true
            } }
            if (galleryLoading) {
                Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = Color.White) }
            } else if (visibleAssets.isEmpty()) {
                Box(Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {
                    Text("Nenhuma mídia encontrada.", color = Color.LightGray)
                }
            } else {
                androidx.compose.foundation.lazy.grid.LazyVerticalGrid(
                    columns = androidx.compose.foundation.lazy.grid.GridCells.Fixed(3),
                    modifier = Modifier.weight(1f).fillMaxWidth(),
                    contentPadding = PaddingValues(bottom = 10.dp),
                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    items(visibleAssets.size, key = { visibleAssets[it].uri.toString() }) { index ->
                        val asset = visibleAssets[index]
                        val selectedIndex = gallerySelection.indexOf(asset.uri)
                        Box(
                            Modifier.fillMaxWidth().aspectRatio(0.76f).clip(RoundedCornerShape(4.dp))
                                .clickable {
                                    if (asset.isVideo) {
                                        gallerySelection.clear()
                                        gallerySelection.add(asset.uri)
                                    } else if (selectedIndex >= 0) {
                                        gallerySelection.remove(asset.uri)
                                    } else if (gallerySelection.size < 10) {
                                        gallerySelection.add(asset.uri)
                                    } else {
                                        onNotice("O limite é de 10 fotos por publicação.")
                                    }
                                }
                        ) {
                            AsyncImage(model = asset.uri, contentDescription = asset.name, contentScale = ContentScale.Crop, modifier = Modifier.fillMaxSize())
                            if (asset.isVideo) {
                                Row(Modifier.align(Alignment.BottomStart).fillMaxWidth().background(Color(0x66000000)).padding(5.dp),
                                    verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Default.PlayArrow, contentDescription = null, tint = Color.White, modifier = Modifier.size(15.dp))
                                    Text("VÍDEO", color = Color.White, style = MaterialTheme.typography.labelSmall)
                                }
                            }
                            Box(Modifier.align(Alignment.TopEnd).padding(6.dp).size(23.dp).border(1.5.dp, Color.White, CircleShape)
                                .background(if (selectedIndex >= 0) QinblyBrand.Accent else Color(0x55000000), CircleShape),
                                contentAlignment = Alignment.Center) {
                                if (selectedIndex >= 0) Text("${selectedIndex + 1}", color = Color.White, style = MaterialTheme.typography.labelSmall)
                            }
                        }
                    }
                }
            }
            Button(
                onClick = {
                    val asset = gallerySelection.lastOrNull()?.let { selected -> galleryAssets.firstOrNull { it.uri == selected } }
                    if (asset != null) {
                        sourceUri = asset.uri
                        selectedUri = asset.uri
                        selectedType = if (asset.isVideo) "vídeo" else "foto"
                        galleryOpen = false
                        showComposer = true
                    } else onNotice("Selecione uma foto ou vídeo.")
                },
                modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp).height(52.dp),
                shape = RoundedCornerShape(28.dp),
                colors = ButtonDefaults.buttonColors(containerColor = Color.White, contentColor = Color.Black)
            ) { Text(if (gallerySelection.isEmpty()) "Avançar" else "Avançar (${gallerySelection.size}/10)", fontWeight = FontWeight.SemiBold) }
         }
}
        return@QinblySplit
     }
}

    if (photoVideoOpen) {
 QinblySplit {
        QinblyPhotoVideoEditor(
            clips = photoVideoClips,
            pendingAdd = photoVideoPending,
            onPendingConsumed = { photoVideoPending = emptyList() },
            busy = photoVideoBusy,
            onAdd = {
                try { addVideoPhotos.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)) }
                catch (e: Exception) { onNotice("Não foi possível abrir a galeria.") }
            },
            onClose = { photoVideoOpen = false },
            onDone = {
                if (!photoVideoBusy && photoVideoClips.isNotEmpty()) {
                    photoVideoBusy = true
                    qinblyBuildPhotoVideo(context, photoVideoClips.toList()) { out, error ->
                        photoVideoBusy = false
                        if (out != null) {
                            sourceUri = out; selectedUri = out; selectedType = "vídeo"; bakedUri = null
                            gallerySelection.clear()
                            editorTool = "Filtros"
                            photoVideoOpen = false
                            showComposer = true
                        } else onNotice(error)
                    }
                }
            },
            onNotice = { msg -> onNotice(msg) }
        )
}
        return
     }

    // Aplica os efeitos ligados (retoque, HDR, fundo) UMA vez, sempre partindo da foto original. Tudo desligado = foto original de volta.
    fun runEditorFx(done: String) {
        val cur = selectedUri
        if (selectedType != "foto" || cur == null) { fxStatus = "Esse efeito só funciona em fotos."; onNotice("Esse efeito só funciona em fotos."); return }
        if (editorBusy) return
        val base = if (fxBase != null && cur == fxResult) fxBase!! else cur
        fxBase = base
        val spec = QinblyFxSpec(edRetouch, edHdr)
        if (spec.isEmpty) {
            selectedUri = base; fxResult = null; fxBase = null; bakedUri = null
            fxStatus = if (done.isNotBlank()) done else "Foto original"
            if (done.isNotBlank()) onNotice(done)
            return
        }
        editorBusy = true
        fxStatus = "Aplicando…"
        qinblyApplyPhotoFx(context, base, spec) { fx, note ->
            editorBusy = false
            if (fx != null) { selectedUri = fx; fxResult = fx; bakedUri = null }
            val msg = if (note.isNotBlank()) note else if (fx != null) done else "Não foi possível aplicar o efeito."
            fxStatus = if (msg.isNotBlank()) msg else "Pronto"
            if (msg.isNotBlank()) onNotice(msg)
        }
    }
    if (cropOpen && selectedType == "foto" && selectedUri != null) {
 QinblySplit {
        BackHandler { cropOpen = false }
        val cropUri = selectedUri!!
        val frameRatio = qinblyRatioValue(cropRatio, editorImageRatio)
        Column(Modifier.fillMaxSize().background(Color(0xFF0B0D12)).statusBarsPadding().navigationBarsPadding()) {
 QinblySplit {
            Row(Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                IconButton(onClick = { cropOpen = false }) {
                    Icon(QinblyCameraIcons.close, contentDescription = "Fechar", tint = Color.White, modifier = Modifier.size(28.dp))
                }
                Text("Recortar", color = Color.White, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold)
            }
            Box(Modifier.weight(1f).fillMaxWidth().padding(horizontal = 24.dp, vertical = 8.dp), contentAlignment = Alignment.Center) {
 QinblySplit {
                BoxWithConstraints(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    val maxW = maxWidth; val maxH = maxHeight
                    val frameW = if (maxW / maxH > frameRatio) maxH * frameRatio else maxW
                    val frameH = frameW / frameRatio
                    Box(
                        Modifier.width(frameW).height(frameH).clipToBounds()
                            .pointerInput(cropRatio, editorImageRatio) {
                                detectTransformGestures { _, pan, gestureZoom, _ ->
                                    val newZoom = (cropZoom * gestureZoom).coerceIn(1f, 4f)
                                    val limits = qinblyMaxPan(editorImageRatio, frameRatio, newZoom)
                                    cropZoom = newZoom
                                    cropPanX = (cropPanX + pan.x / size.width).coerceIn(-limits.first, limits.first)
                                    cropPanY = (cropPanY + pan.y / size.height).coerceIn(-limits.second, limits.second)
                                }
                            }
                    ) {
                        AsyncImage(
                            model = cropUri, contentDescription = "Foto", contentScale = ContentScale.Crop,
                            modifier = Modifier.fillMaxSize().graphicsLayer {
                                scaleX = cropZoom; scaleY = cropZoom
                                translationX = cropPanX * size.width; translationY = cropPanY * size.height
                            }
                        )
                        Box(Modifier.fillMaxSize().border(1.5.dp, Color.White))
                        Column(Modifier.fillMaxSize()) {
                            repeat(2) { Spacer(Modifier.weight(1f)); Box(Modifier.fillMaxWidth().height(0.5.dp).background(Color(0x80FFFFFF))) }
                            Spacer(Modifier.weight(1f))
                        }
                        Row(Modifier.fillMaxSize()) {
                            repeat(2) { Spacer(Modifier.weight(1f)); Box(Modifier.fillMaxHeight().width(0.5.dp).background(Color(0x80FFFFFF))) }
                            Spacer(Modifier.weight(1f))
                        }
                    }
                }
             }
}
            Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()).padding(vertical = 6.dp), horizontalArrangement = Arrangement.Center) {
                QINBLY_FORMATS.forEach { ratio ->
                    Text(ratio, color = if (cropRatio == ratio) Color(0xFF0B0D12) else Color.White, fontSize = 12.sp, fontWeight = FontWeight.SemiBold,
                        modifier = Modifier.padding(horizontal = 3.dp).clip(RoundedCornerShape(14.dp))
                            .background(if (cropRatio == ratio) Color.White else Color.Transparent)
                            .border(0.5.dp, Color(0x80FFFFFF), RoundedCornerShape(14.dp))
                            .clickable { cropRatio = ratio; cropZoom = 1f; cropPanX = 0f; cropPanY = 0f }
                            .padding(horizontal = 11.dp, vertical = 6.dp))
                }
            }
            Box(Modifier.fillMaxWidth().padding(vertical = 4.dp), contentAlignment = Alignment.Center) {
 QinblySplit {
                IconButton(onClick = {
                    if (!editorBusy) {
                        editorBusy = true
                        Thread {
                            try {
                                val copy = qinblyTransformCopy(context, cropUri, true, false)
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    selectedUri = copy
                                    editorImageRatio = 1f / editorImageRatio
                                    cropZoom = 1f; cropPanX = 0f; cropPanY = 0f
                                    editorBusy = false
                                }
                            } catch (e: Exception) {
                                android.os.Handler(android.os.Looper.getMainLooper()).post { editorBusy = false; onNotice("Não foi possível girar a foto.") }
                            }
                        }.start()
                    }
                }) { Icon(QinblyCameraIcons.rotate, contentDescription = "Girar", tint = Color.White, modifier = Modifier.size(26.dp)) }
             }
}
            Column(Modifier.fillMaxWidth().padding(horizontal = 18.dp, vertical = 10.dp)) {
                QinblyGradientButton(
                    onClick = { editorRatio = cropRatio; editorZoom = cropZoom; editorPanX = cropPanX; editorPanY = cropPanY; cropOpen = false },
                    modifier = Modifier.fillMaxWidth().height(54.dp),
                    shape = RoundedCornerShape(28.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = QinblyBrand.Accent, contentColor = Color.White)
                ) { Text("Usar recorte", fontWeight = FontWeight.SemiBold, color = Color.White) }
            }
         }
}
        return@QinblySplit
     }
}

    val doPublish: () -> Unit = {
                    val token = prefs.getString("token", null)
                    when {
                        token.isNullOrBlank() -> onNotice("Entre na sua conta antes de publicar.")
                        selectedUri == null && sourceUri == null -> { publishError = "Selecione uma foto ou vídeo antes de publicar."; onNotice(publishError); publishSettings = false; openQinblyGallery() }
                        !selectedMediaReady -> { publishError = "O vídeo da galeria não está acessível. Escolha-o novamente."; onNotice(publishError); publishSettings = false }
                        else -> {
                            publishError = ""
                            publishing = true
                            val musicToSend = if (onCaptured == null) storyMusic else null
                            val postCaption = qinblyAttachMusic(caption, musicToSend)
                            val directNow = storyDirect; val hoursNow = storyHours; val audienceNow = storyAudience; val feedNow = storyAlsoFeed
                            val cityNow = QinblyApi.myCity(prefs)
                            val scheduledIsoMedia = if (mediaScheduledMs > 0L && !QinblyComposeSeed.story) java.time.Instant.ofEpochMilli(mediaScheduledMs).toString() else ""
                            val wasScheduled = scheduledIsoMedia.isNotBlank()
                            QinblyHashtagStore.record(context, caption)
                            Thread {
                                try {
                                    if (selectedUri == null && sourceUri == null) throw IllegalStateException("Selecione uma foto ou vídeo antes de publicar.")
                                    else {
                                        val selectedMediaUri = bakedUri ?: selectedUri ?: sourceUri ?: throw IllegalStateException("Mídia não selecionada.")
                                        val mime = context.contentResolver.getType(selectedMediaUri)?.takeIf { it.startsWith("image/") || it.startsWith("video/") } ?: if (selectedType == "vídeo") "video/mp4" else "image/jpeg"
                                        // Copia a mídia para cache para garantir tamanho exato no upload,
                                        // inclusive para URIs de câmera, galeria e provedores de nuvem.
                                        val tempUploadFile = java.io.File.createTempFile("qinbly-upload-", if (selectedType == "vídeo") ".mp4" else ".jpg", context.cacheDir)
                                        val uploadUri = Uri.fromFile(tempUploadFile)
                                        val size = try {
                                            context.contentResolver.openInputStream(selectedMediaUri)?.use { input ->
                                                tempUploadFile.outputStream().use { output -> input.copyTo(output, 64 * 1024) }
                                            } ?: throw IllegalStateException("Não foi possível ler a foto ou vídeo selecionado.")
                                            tempUploadFile.length()
                                        } catch (e: Exception) {
                                            tempUploadFile.delete()
                                            throw e
                                        }
                                        if (saveToDevice) {
                                            val saved = qinblySaveMediaCopy(context, selectedMediaUri, selectedType == "vídeo")
                                            android.os.Handler(android.os.Looper.getMainLooper()).post {
                                                onNotice(if (saved) "Cópia salva no celular." else "Não foi possível salvar a cópia no celular.")
                                            }
                                        }
                                        try {
                                            if (size <= 0L) throw IllegalStateException("O arquivo selecionado está vazio ou não pôde ser lido.")
                                            val extension = android.webkit.MimeTypeMap.getSingleton().getExtensionFromMimeType(mime) ?: if (mime.startsWith("video/")) "mp4" else "jpg"
                                            val fileName = "qinbly-${System.currentTimeMillis()}.$extension"
                                            val storyMode = QinblyComposeSeed.story
                                            val fileId = QinblyApi.uploadPostMedia(context, token, uploadUri, fileName, mime, size, if (storyMode) "story_media" else "post_media")
                                            if (storyMode) {
                                                val contribTo = QinblyComposeSeed.contribTo
                                                if (contribTo.isNotBlank()) QinblyApi.addContribution(token, contribTo, fileId, if (mime.startsWith("video/")) "video" else "image", qinblyAttachMusic(caption, musicToSend))
                                                else if (directNow) {
                                                    QinblyApi.createStoryCustom(token, fileId, mime.startsWith("video/"), qinblyAttachMusic((if (QinblyComposeSeed.origin.isNotBlank()) QinblyComposeSeed.origin + "\n" else "") + caption, musicToSend), hoursNow, audienceNow, cityNow)
                                                    if (feedNow) {
                                                        // "+ Feed": publica também como publicação (precisa de uma cópia no lugar das publicações).
                                                        val feedFileId = QinblyApi.uploadPostMedia(context, token, uploadUri, fileName, mime, size, "post_media")
                                                        QinblyApi.createMediaPost(token, caption, feedFileId, if (mime.startsWith("video/")) "video" else "image", "public", emptyList())
                                                    }
                                                }
                                                else QinblyApi.createStoryFromFile(token, fileId, mime.startsWith("video/"), qinblyAttachMusic((if (QinblyComposeSeed.origin.isNotBlank()) QinblyComposeSeed.origin + "\n" else "") + (if (QinblyComposeSeed.collabNew) qinblyCollabCaption(caption) else caption), musicToSend))
                                            } else if (selectedType == "foto" && gallerySelection.size > 1) {
                                                val uploadedIds = mutableListOf(fileId)
                                                for ((index, extraUri) in gallerySelection.drop(1).withIndex()) {
                                                    val extraMime = context.contentResolver.getType(extraUri)?.takeIf { it.startsWith("image/") } ?: "image/jpeg"
                                                    val extraFile = java.io.File.createTempFile("qinbly-album-", ".jpg", context.cacheDir)
                                                    try {
                                                        val extraSize = context.contentResolver.openInputStream(extraUri)?.use { input ->
                                                            extraFile.outputStream().use { output -> input.copyTo(output, 64 * 1024) }
                                                            extraFile.length()
                                                        } ?: throw IllegalStateException("Não foi possível ler uma das fotos.")
                                                        val extraExt = android.webkit.MimeTypeMap.getSingleton().getExtensionFromMimeType(extraMime) ?: "jpg"
                                                        uploadedIds.add(QinblyApi.uploadPostMedia(context, token, Uri.fromFile(extraFile),
                                                            "qinbly-album-${System.currentTimeMillis()}-${index}.${extraExt}", extraMime, extraSize))
                                                    } finally { extraFile.delete() }
                                                }
                                                QinblyApi.createPhotoAlbum(token, postCaption, uploadedIds, if (postVisibility == "Só eu") "private" else "public", taggedPeople.toList(), scheduledIsoMedia)
                                            } else {
                                                QinblyApi.createMediaPost(token, postCaption, fileId, if (mime.startsWith("video/")) "video" else "image", if (postVisibility == "Só eu") "private" else "public", taggedPeople.toList(), scheduledIsoMedia)
                                            }
                                        } finally {
                                            tempUploadFile?.delete()
                                        }
                                    }
                                    android.os.Handler(android.os.Looper.getMainLooper()).post {
                                        publishing = false
                                        caption = ""
                                        storyMusic = null
                                        mediaScheduledMs = 0L
                                        selectedUri = null
                                        gallerySelection.clear()
                                        selectedType = ""
                                        publishSettings = false
                                        showComposer = false
                                        sourceUri = null
                                        coverBitmap = null
                                        onNotice(if (QinblyComposeSeed.collabNew) "Story coletivo publicado. Fica no ar por 24 horas." else if (QinblyComposeSeed.contribTo.isNotBlank()) "Resposta enviada." else if (QinblyComposeSeed.story) (if (directNow) "Story publicado. Fica no ar por $hoursNow horas." + (if (feedNow) " Também foi para o feed." else "") else "Story publicado. Fica no ar por 24 horas.") else if (wasScheduled) "Publicação agendada. Aparece no horário escolhido." else "Publicado")
                                        QinblyComposeSeed.story = false
                                        QinblyComposeSeed.origin = ""
                                        QinblyComposeSeed.contribTo = ""
                                        QinblyComposeSeed.collabNew = false
                                        QinblyComposeSeed.fromGallery = false
                                        onCameraCancelled()
                                    }
                                } catch (e: Exception) {
                                    android.os.Handler(android.os.Looper.getMainLooper()).post {
                                        publishing = false
                                        publishError = e.message?.takeIf { it.isNotBlank() } ?: "Não foi possível publicar. Verifique a conexão e tente novamente."
                                        onNotice(publishError)
                                    }
                                }
                            }.start()
                        }
                    }
    }

    val afterEdit: () -> Unit = {
        val back = onCaptured
        if (back != null) {
            // Câmera chamada por outra tela: entrega a foto já editada.
            val done = bakedUri ?: selectedUri ?: sourceUri
            showComposer = false; selectedUri = null; sourceUri = null; bakedUri = null
            if (done != null) back(done)
        } else if (storyDirect) doPublish() else publishSettings = true
    }
    val advance: () -> Unit = advance@{
        if (publishing || editorBusy) return@advance
        if (storyDirect && storyAudience == "near" && QinblyApi.myCity(prefs).isBlank()) {
            onNotice("O app ainda não sabe sua cidade.")
            return@advance
        }
                            if (selectedUri == null && sourceUri == null) {
                                publishError = "Escolha um vídeo ou uma foto antes de continuar."
                                onNotice(publishError)
                            } else if (!selectedMediaReady) {
                                publishError = "Não foi possível ler a mídia da galeria. Selecione o arquivo novamente."
                                onNotice(publishError)
                            } else if (selectedType == "foto" && gallerySelection.size <= 1 && selectedUri != null) {
                                publishError = ""
                                if (!editorBusy) {
                                    editorBusy = true
                                    val src = selectedUri!!
                                    val ratioNow = editorRatio; val z = editorZoom; val px = editorPanX; val py = editorPanY
                                    val matrixNow = qinblyEditMatrix(selectedFilter, filterIntensity, editorBrightness, editorContrast); val finishNow = qinblyFinishOf(selectedFilter, filterIntensity)
                                    val blurNow = editorBlur; val dxNow = if (editorFrame.w > 0f) editorTextDx / editorFrame.w else 0f; val dyNow = if (editorFrame.h > 0f) editorTextDy / editorFrame.h else 0f; val fontNow = editorTextFont; val colorNow = editorTextColor; val wordsNow = editorWordColors.toMap(); val textNow = editorText; val stickerNow = editorStickers.map { QinblyStickerSpec(it.emoji, it.nx, it.ny, it.scale, it.rot) }; val strokesNow = editorStrokes.toList(); val strokeMetaNow = editorStrokeMeta.toList()
                                    Thread {
                                        try {
                                            val done = qinblyRenderEditedPhoto(context, src, ratioNow, z, px, py, matrixNow, textNow, stickerNow, strokesNow, fontNow, colorNow, wordsNow, dxNow, dyNow, blurNow, editorTextScale, strokeMetaNow, finishNow)
                                            android.os.Handler(android.os.Looper.getMainLooper()).post { bakedUri = done; editorBusy = false; afterEdit() }
                                        } catch (e: Exception) {
                                            // Se não der para aplicar as edições, publica a foto original em vez de travar.
                                            android.os.Handler(android.os.Looper.getMainLooper()).post { bakedUri = null; editorBusy = false; afterEdit(); onNotice("Não foi possível aplicar as edições; a foto original será usada.") }
                                        }
                                    }.start()
                                }
                            } else {
                                publishError = ""
                                afterEdit()
                            }
    }
    // Etapa 1: editor visual. Etapa 2: opções e publicação.
    if (!publishSettings) {
 QinblySplit {
        Box(Modifier.fillMaxSize().background(Color.Black)) {
 QinblySplit {
            val uri = selectedUri
            if (uri != null && selectedType == "foto") {
 QinblySplit {
                val previewFrame = qinblyRatioValue(editorRatio, editorImageRatio)
                val previewMatrix = remember(selectedFilter, filterIntensity, editorBrightness, editorContrast) {
                    androidx.compose.ui.graphics.ColorFilter.colorMatrix(androidx.compose.ui.graphics.ColorMatrix(qinblyEditMatrix(selectedFilter, filterIntensity, editorBrightness, editorContrast).array))
                }
                Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
 QinblySplit {
                    if (editorTool == "Ajustar") QinblyFormatPicker(
                        uri = uri, ratio = editorRatio, imageRatio = editorImageRatio, zoom = editorZoom, panX = editorPanX, panY = editorPanY,
                        colorFilter = previewMatrix,
                        onChange = { z, x, y -> editorZoom = z; editorPanX = x; editorPanY = y },
                        modifier = Modifier.fillMaxSize()
                    ) else QinblyFormatFrame(
                        uri = uri, ratio = editorRatio, imageRatio = editorImageRatio, zoom = editorZoom, panX = editorPanX, panY = editorPanY,
                        blurBg = editorBlur, colorFilter = previewMatrix, adjusting = false,
                        onChange = { z, x, y -> editorZoom = z; editorPanX = x; editorPanY = y },
                        modifier = Modifier.fillMaxSize()
                    )
                    // Vinheta do filtro também na prévia (nitidez e granulado só aparecem na foto final).
                    val previewFinish = qinblyFinishOf(selectedFilter, filterIntensity)
                    if (previewFinish.vignette > 0.001f) androidx.compose.foundation.Canvas(Modifier.fillMaxSize()) {
                        val r = kotlin.math.hypot(size.width / 2f, size.height / 2f)
                        drawRect(Brush.radialGradient(
                            0f to Color.Transparent, 0.5f to Color.Transparent, 1f to Color.Black.copy(alpha = (previewFinish.vignette * 0.8f).coerceIn(0f, 1f)),
                            center = Offset(size.width / 2f, size.height / 2f), radius = r))
                    }
                 }
}
             }
} else if (uri != null) {
                // Mesmo player do feed (ExoPlayer, repetição e toque para pausar). Sem barra de progresso
                // para não cobrir a barra de ferramentas do editor.
                // Formato no vídeo: o quadro muda a cada toque em Formato (Original = tela inteira).
                val videoFrame = qinblyFrameRect(editorPreviewW, editorPreviewH, qinblyRatioValue(editorRatio, 9f / 16f))
                if (editorRatio == "Original" || editorPreviewW <= 0 || editorPreviewH <= 0) {
                    QinblyFullscreenVideo(url = uri.toString(), modifier = Modifier.fillMaxSize(), showProgress = false)
                } else {
                    val vDensity = androidx.compose.ui.platform.LocalDensity.current
                    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                        QinblyFullscreenVideo(
                            url = uri.toString(),
                            modifier = Modifier.size(with(vDensity) { videoFrame.w.toDp() }, with(vDensity) { videoFrame.h.toDp() }).clipToBounds(),
                            showProgress = false
                        )
                    }
                }
            }
            val editorFilterTint = when (selectedFilter) {
                in QinblyNewFilterNames -> qinblyAutoTint(selectedFilter)
                "Aurora" -> Color(0x22B9A6F0)
                "Pôr do sol" -> Color(0x33F4A261)
                "Neon" -> Color(0x22FF4FD8)
                "Filme" -> Color(0x22A7864A)
                "Pastel" -> Color(0x33FFFFFF)
                "Oceano" -> Color(0x226EC6E6)
                "Sonho" -> Color(0x22F7C5E3)
                "Dourado" -> Color(0x33E9C46A)
                "Quente" -> Color(0x22FF9A42)
                "Frio" -> Color(0x223F8CFF)
                "Vivo" -> Color(0x18FF45B5)
                "Cinema" -> Color(0x2230485A)
                "P&B" -> Color(0x55999999)
                "Retrô", "Vintage" -> Color(0x22C78D5A)
                "Sépia" -> Color(0x33B5834A)
                "Vívido" -> Color(0x18FF45B5)
                "Suave" -> Color(0x22FFFFFF)
                "Desbotado" -> Color(0x33AAAAAA)
                "Noir" -> Color(0x66222222)
                "Rosado" -> Color(0x22FF6FAF)
                else -> Color.Transparent
            }
            if (editorFilterTint != Color.Transparent && selectedType == "vídeo") {
                Box(Modifier.fillMaxSize().alpha(filterIntensity).background(editorFilterTint))
            }
            if (editorTool == "Desenho") {
 QinblySplit {
                androidx.compose.foundation.Canvas(
                    modifier = Modifier.offset { androidx.compose.ui.unit.IntOffset(editorFrame.left.toInt(), editorFrame.top.toInt()) }
                        .size(with(androidx.compose.ui.platform.LocalDensity.current) { editorFrame.w.toDp() }, with(androidx.compose.ui.platform.LocalDensity.current) { editorFrame.h.toDp() })
                        .pointerInput(editorEraser) { detectTapGestures { pos -> if (editorEraser) qinblyEraseAt(editorStrokes, editorStrokeMeta, pos, size.width.toFloat(), size.height.toFloat(), 18.dp.toPx()) } }
                        .pointerInput(editorTool, editorEraser, editorDrawColor, editorDrawWidth) {
                        // Borracha: apaga só o pedaço por onde o dedo passa. Caneta: cria um traço novo com a cor e a espessura escolhidas.
                        val reach = 18.dp.toPx()
                        fun eraseAt(pos: Offset) = qinblyEraseAt(editorStrokes, editorStrokeMeta, pos, size.width.toFloat(), size.height.toFloat(), reach)
                        fun eraseLine(a: Offset, b: Offset) {
                            val steps = (kotlin.math.hypot(b.x - a.x, b.y - a.y) / (reach / 2f)).toInt().coerceAtLeast(1)
                            for (st in 0..steps) { val t = st / steps.toFloat(); eraseAt(Offset(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t)) }
                        }
                        detectDragGestures(
                            onDragStart = { start ->
                                if (editorEraser) eraseAt(start)
                                else { editorRedo.clear(); editorStrokes.add(listOf(Offset(start.x / size.width, start.y / size.height))); editorStrokeMeta.add(editorDrawColor to editorDrawWidth) }
                            },
                            onDrag = { change, _ ->
                                change.consume()
                                if (editorEraser) eraseLine(change.previousPosition, change.position)
                                else if (editorStrokes.isNotEmpty()) {
                                    val last = editorStrokes.last()
                                    editorStrokes[editorStrokes.lastIndex] = last + Offset(
                                        (change.position.x / size.width).coerceIn(0f, 1f),
                                        (change.position.y / size.height).coerceIn(0f, 1f)
                                    )
                                }
                            }
                        )
                    }
                ) {
                    editorStrokes.forEachIndexed { idx, points ->
                        if (points.size > 1) {
                            val meta = editorStrokeMeta.getOrNull(idx)
                            val path = androidx.compose.ui.graphics.Path()
                            path.moveTo(points.first().x * size.width, points.first().y * size.height)
                            points.drop(1).forEach { path.lineTo(it.x * size.width, it.y * size.height) }
                            drawPath(path, Color(meta?.first ?: 0xFFFF2A9D.toInt()), style = androidx.compose.ui.graphics.drawscope.Stroke(width = ((meta?.second ?: 0.012f) * size.width).coerceAtLeast(2f), cap = androidx.compose.ui.graphics.StrokeCap.Round, join = androidx.compose.ui.graphics.StrokeJoin.Round))
                        }
                    }
                }
             }
}
            // Camada transparente de cima: mede a tela, troca filtro passando o dedo e recebe o gesto de mover/dar zoom na foto.
            // (O gesto da foto fica AQUI, nesta camada de cima, porque uma camada com gesto bloqueia o que está embaixo dela.)
            Box(Modifier.fillMaxSize().onSizeChanged { editorPreviewW = it.width; editorPreviewH = it.height }
                // Desenhando: esta camada de gestos sai da frente, senão ela engole o toque e o lápis não risca.
                .then(if (editorTool == "Desenho") Modifier else Modifier
                .pointerInput(Unit) { detectTapGestures { editorSelSticker = null; editorTextSelected = false } }
                .qinblySwipeFilters(enabled = editorTool == "Filtros" && selectedType == "foto" && editorZoom <= 1.01f) { dir ->
                    // Igual à câmera: passar o dedo para o lado troca o filtro de cor.
                    val names = QinblyColorFilterNames
                    val next = names[(names.indexOf(selectedFilter).coerceAtLeast(0) + dir + names.size) % names.size]
                    selectedFilter = next; filterIntensity = 1f; swipeFilterLabel = next
                }
                .then(if (selectedType == "foto") Modifier.qinblyFormatGestures(
                    picker = editorTool == "Ajustar", ratio = editorRatio, imageRatio = editorImageRatio, areaW = editorPreviewW, areaH = editorPreviewH,
                    zoom = { editorZoom }, panX = { editorPanX }, panY = { editorPanY },
                    ignoreSinglePan = { editorTool == "Filtros" && editorZoom <= 1.01f },
                    // Enquanto um emote ou o texto está selecionado, a pinça vale SÓ nele; a foto só dá zoom quando nada está selecionado.
                    selectedActive = { editorSelSticker != null || editorTextSelected },
                    onSelectedTransform = { gz, rot ->
                        val st = editorSelSticker
                        if (st != null) { st.scale = (st.scale * gz).coerceIn(0.3f, 8f); st.rot += rot }
                        else if (editorTextSelected) editorTextScale = (editorTextScale * gz).coerceIn(0.4f, 4f)
                    },
                    onChange = { z, x, y -> editorZoom = z; editorPanX = x; editorPanY = y }
                ) else Modifier)))
            if (fxStatus.isNotBlank()) {
                Row(
                    Modifier.align(Alignment.TopCenter).padding(top = 80.dp, start = 24.dp, end = 24.dp).zIndex(30f)
                        .clip(RoundedCornerShape(22.dp)).background(Color(0xDD000000)).padding(horizontal = 18.dp, vertical = 12.dp),
                    verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    if (fxStatus == "Aplicando…") CircularProgressIndicator(Modifier.size(18.dp), color = Color.White, strokeWidth = 2.dp)
                    Text(fxStatus, color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                }
            }
            if (swipeFilterLabel.isNotBlank()) {
                Text(swipeFilterLabel, modifier = Modifier.align(Alignment.Center).clip(RoundedCornerShape(16.dp)).background(Color(0x99000000)).padding(horizontal = 16.dp, vertical = 8.dp),
                    color = Color.White, fontSize = 16.sp, fontWeight = FontWeight.SemiBold)
            }
            if (editorText.isBlank() && editorTool == "Texto" && !editorTextEditing) {
                Text("Toque para escrever", color = Color(0xB3FFFFFF), fontSize = 24.sp, fontWeight = FontWeight.SemiBold, textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                    modifier = Modifier.align(Alignment.Center).clip(RoundedCornerShape(12.dp)).clickable { editorTextEditing = true }.padding(horizontal = 28.dp, vertical = 16.dp))
            }
            if (editorTool == "Texto" && editorTextEditing) EditorTextOverlay { editorTextEditing = false }
            if (editorText.isNotBlank() && !(editorTool == "Texto" && editorTextEditing) && editorTool != "Ajustar") {
                Text(qinblyColoredText(editorTextFont, editorText, editorTextColor, editorWordColors), modifier = Modifier.align(Alignment.Center).offset { androidx.compose.ui.unit.IntOffset(editorTextDx.toInt(), editorTextDy.toInt()) }
                        .clip(RoundedCornerShape(12.dp))
                        .then(if (editorTextSelected) Modifier.border(1.5.dp, Color.White, RoundedCornerShape(12.dp)) else Modifier)
                        .pointerInput(Unit) { detectDragGestures(onDragStart = { editorTextSelected = true; editorSelSticker = null }) { change, drag -> change.consume(); editorTextDx += drag.x; editorTextDy += drag.y } }
                        // 1º toque seleciona (moldura; a pinça passa a valer só no texto); toque no texto já selecionado abre a edição.
                        .clickable { if (editorTextSelected) { editorTool = "Texto"; editorTextEditing = true } else { editorTextSelected = true; editorSelSticker = null } }
                        .padding(horizontal = 28.dp, vertical = 16.dp),
                    color = Color(editorTextColor), fontSize = (28f * editorTextScale).sp,
                    fontFamily = androidx.compose.ui.text.font.FontFamily(qinblyTypeface(editorTextFont)),
                    letterSpacing = qinblyTextSpacingEm(editorTextFont).em,
                    style = MaterialTheme.typography.headlineMedium.copy(shadow = androidx.compose.ui.graphics.Shadow(if (editorTextColor == android.graphics.Color.BLACK || editorTextColor == 0xFF111111.toInt()) Color(0xCCFFFFFF) else Color(0xCC000000), blurRadius = 8f)),
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center)
            }
            // Adesivos/emotes: toque seleciona (moldura + X para remover), arraste move, dois dedos ampliam e giram, toque duas vezes apaga.
            if (editorTool != "Ajustar") editorStickers.forEach { st ->
                val half = with(androidx.compose.ui.platform.LocalDensity.current) { 60.dp.roundToPx() }
                val selected = editorSelSticker === st
                Box(
                    Modifier.size(120.dp)
                        .offset { androidx.compose.ui.unit.IntOffset((editorFrame.left + st.nx * editorFrame.w).toInt() - half, (editorFrame.top + st.ny * editorFrame.h).toInt() - half) }
                        .pointerInput(st) { detectTapGestures(onTap = { editorSelSticker = if (editorSelSticker === st) null else st; editorTextSelected = false }, onDoubleTap = { editorStickers.remove(st); if (editorSelSticker === st) editorSelSticker = null }) }
                        .pointerInput(st) {
                            detectTransformGestures { _, pan, zoom, rotation ->
                                editorSelSticker = st; editorTextSelected = false
                                if (editorFrame.w > 0f && editorFrame.h > 0f) {
                                    st.nx = (st.nx + pan.x / editorFrame.w).coerceIn(0f, 1f)
                                    st.ny = (st.ny + pan.y / editorFrame.h).coerceIn(0f, 1f)
                                }
                                st.scale = (st.scale * zoom).coerceIn(0.3f, 8f)
                                st.rot += rotation
                            }
                        }
                        .graphicsLayer { scaleX = st.scale; scaleY = st.scale; rotationZ = st.rot },
                    contentAlignment = Alignment.Center
                ) {
                    if (selected) Box(Modifier.size(88.dp).border((1.5f / st.scale).dp, Color.White, RoundedCornerShape(6.dp)))
                    Text(st.emoji, fontSize = 64.sp, color = Color.Black)
                }
                if (selected) {
                    // X no canto da moldura, sempre do mesmo tamanho, acompanha ampliação e giro do emote.
                    val dens = androidx.compose.ui.platform.LocalDensity.current
                    val corner = with(dens) { 44.dp.toPx() } * st.scale
                    val rad = Math.toRadians(st.rot.toDouble())
                    val cx = editorFrame.left + st.nx * editorFrame.w + (corner * Math.cos(rad) + corner * Math.sin(rad)).toFloat()
                    val cy = editorFrame.top + st.ny * editorFrame.h + (corner * Math.sin(rad) - corner * Math.cos(rad)).toFloat()
                    val xHalf = with(dens) { 13.dp.roundToPx() }
                    Box(
                        Modifier.offset { androidx.compose.ui.unit.IntOffset(cx.toInt() - xHalf, cy.toInt() - xHalf) }
                            .size(26.dp).clip(CircleShape).background(Color(0xCC000000)).border(1.dp, Color.White, CircleShape)
                            .clickable { editorStickers.remove(st); editorSelSticker = null },
                        contentAlignment = Alignment.Center
                    ) { Icon(Icons.Default.Close, contentDescription = "Remover emote", tint = Color.White, modifier = Modifier.size(15.dp)) }
                }
            }
            Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color(0x99000000), Color.Transparent, Color.Transparent, Color(0xEE000000)))))
            if (newEditorChrome) {
 QinblySplit {
            // Mesmo visual da câmera: X no canto e ferramentas de edição de foto na lateral (ícone de linha fina + nome).
            var editorSideExpanded by remember { mutableStateOf(false) }
