                onClick = { leaveEditor() },
                modifier = Modifier.align(Alignment.TopStart).padding(start = 8.dp, top = 8.dp)
            ) {
                Icon(QinblyCameraIcons.close, contentDescription = "Voltar", tint = Color.White, modifier = Modifier.size(28.dp))
            }
