                ) {
                    Icon(QinblyCameraIcons.music, contentDescription = null, tint = Color.White, modifier = Modifier.size(19.dp))
                    Text(sm0?.title ?: "Adicionar som", color = Color.White, fontSize = 16.sp, fontWeight = FontWeight.SemiBold,
                        maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis, modifier = Modifier.widthIn(max = 130.dp))
                    if (sm0 != null) QinblyCloseIcon(Color.White, 16.dp, modifier = Modifier.clickable { storyMusic = null })
                }
                if (showMusicPicker) QinblyMusicPicker(onPick = { storyMusic = it; showMusicPicker = false }, onDismiss = { showMusicPicker = false }, freeOnly = !QinblyComposeSeed.story)
                if (sm0 != null && selectedUri != null) QinblyMusicPlayer(sm0.url, muted = false, paused = showMusicPicker)
            }
            Column(
                modifier = Modifier.align(Alignment.TopEnd).padding(end = 12.dp, top = 92.dp).width(140.dp)
                    .then(if (editorSideExpanded) Modifier.fillMaxHeight().padding(bottom = 8.dp) else Modifier)
                    .verticalScroll(rememberScrollState()),
                horizontalAlignment = Alignment.End,
                verticalArrangement = Arrangement.spacedBy(11.dp)
            ) {
 QinblySplit {
                QinblyCameraSideItem(QinblyCameraIcons.editor, "Editar") {
                    photoVideoClips.clear()
                    if (selectedType == "foto") {
                        val seed = if (gallerySelection.isNotEmpty()) gallerySelection.toList() else listOfNotNull(sourceUri ?: selectedUri)
                        photoVideoClips.addAll(seed.map { PvClip(it) })
                    } else {
                        val v = selectedUri
                        if (v != null) photoVideoClips.add(PvClip(v, secs = qinblyVideoSecs(context, v), video = true))
                    }
                    photoVideoPending = emptyList()
                    photoVideoOpen = true
                }
                QinblyCameraSideItem(QinblyCreateIcons.text, "Texto", on = editorTool == "Texto", glyph = true) { editorTool = if (editorTool == "Texto") "Filtros" else "Texto"; editorTextEditing = editorTool == "Texto" }
                QinblyCameraSideItem(QinblyCameraIcons.pen, "Desenho", on = editorTool == "Desenho") {
                    editorTool = if (editorTool == "Desenho") "Filtros" else "Desenho"
                }
                QinblyCameraSideItem(QinblyCreateIcons.sticker, "Stickers", on = editorTool == "Stickers") { editorTool = if (editorTool == "Stickers") "Filtros" else "Stickers" }
                QinblyCameraSideItem(QinblyCameraIcons.format, "Formato") {
                    editorTool = "Ajustar"
                    // Vídeo: só 2 formatos, como no TikTok (9:16 tela cheia e 3:4). Foto continua com todos.
                    val ratioList = if (selectedType == "foto") QINBLY_FORMATS else listOf("9:16", "3:4")
                    val nextRatio = ratioList[(ratioList.indexOf(editorRatio) + 1) % ratioList.size]
                    editorRatio = nextRatio; editorZoom = 1f; editorPanX = 0f; editorPanY = 0f
                    val u = selectedUri
                    if (u != null && selectedType == "foto") formatScope.launch { editorPanY = qinblyFacePanY(context, u, editorImageRatio, qinblyRatioValue(nextRatio, editorImageRatio)) }
                }
                if (selectedType == "foto") QinblyCameraSideItem(QinblyCameraIcons.mirror, "Espelhar") {
                    val current = selectedUri
                    if (current != null && !editorBusy) {
                        editorBusy = true
                        Thread {
                            try {
                                val copy = qinblyTransformCopy(context, current, false, true)
                                android.os.Handler(android.os.Looper.getMainLooper()).post { selectedUri = copy; editorBusy = false }
                            } catch (e: Exception) {
                                android.os.Handler(android.os.Looper.getMainLooper()).post { editorBusy = false; onNotice("Não foi possível espelhar a foto.") }
                            }
